function normalizeAuthUsername(value){
  return String(value || '').trim().toLowerCase().replace(/\s+/g, '.');
}

function normalizeAuthUser(user){
  const role = String(user?.role || 'farmer') === 'institution' ? 'institution' : 'farmer';
  const institutionRole = role === 'institution'
    ? (String(user?.institutionRole || '').trim().toLowerCase() === 'analyst' ? 'analyst' : 'admin')
    : '';
  const displayName = String(user?.displayName || user?.username || '').trim();
  const username = normalizeAuthUsername(user?.username || displayName);
  const rawStatus = String(user?.accountStatus || (user?.onboardingCompleted ? 'active' : 'pending_setup')).trim().toLowerCase();
  const accountStatus = rawStatus === 'passive'
    ? 'passive'
    : (rawStatus === 'active' ? 'active' : 'pending_setup');
  const normalized = {
    username,
    password: String(user?.password || ''),
    role,
    institutionRole,
    displayName: displayName || username,
    accountStatus,
    onboardingCompleted: !!user?.onboardingCompleted || accountStatus === 'active',
    temporaryPassword: !!user?.temporaryPassword || (accountStatus !== 'active' && !!user?.password),
    phone: String(user?.phone || '').trim(),
    village: String(user?.village || '').trim(),
    district: String(user?.district || '').trim(),
    notes: String(user?.notes || '').trim(),
    createdBy: String(user?.createdBy || '').trim() || (role === 'institution' ? 'system' : 'institution'),
    createdAt: String(user?.createdAt || '').trim(),
    updatedAt: String(user?.updatedAt || '').trim(),
    lastPasswordResetAt: String(user?.lastPasswordResetAt || '').trim(),
    demoShowOnboardingEachLogin: !!user?.demoShowOnboardingEachLogin,
    demoRequiresInstitutionReviewAfterSetup: !!user?.demoRequiresInstitutionReviewAfterSetup,
    profileReviewStatus: String(user?.profileReviewStatus || '').trim().toLowerCase() || (role === 'farmer' ? 'not_required' : ''),
    profileReviewNote: String(user?.profileReviewNote || '').trim(),
    onboardingLastSubmittedAt: String(user?.onboardingLastSubmittedAt || '').trim()
  };
  if(role === 'farmer'){
    normalized.allowedParcelIds = Array.from(new Set((Array.isArray(user?.allowedParcelIds) ? user.allowedParcelIds : []).map(x => String(x || '').trim()).filter(Boolean)));
    normalized.customParcelIds = Array.from(new Set((Array.isArray(user?.customParcelIds) ? user.customParcelIds : []).map(x => String(x || '').trim()).filter(Boolean)));
  }
  if(accountStatus === 'active') normalized.onboardingCompleted = true;
  if(accountStatus === 'passive') normalized.temporaryPassword = !!user?.temporaryPassword;

  // v46 demo guard:
  // Older localStorage records could overwrite Ayşe demo flags with false.
  // Force the replayable onboarding behavior for the dedicated demo farmer.
  if(normalized.username === 'ciftci.ayse'){
    normalized.demoShowOnboardingEachLogin = true;
    normalized.demoRequiresInstitutionReviewAfterSetup = true;
    if(!String(normalized.profileReviewStatus || '').trim()){
      normalized.profileReviewStatus = 'pending_review';
    }
  }
  return normalized;
}

function mergeDefaultUsers(users){
  const map = new Map();
  DEFAULT_AUTH_USERS.map(normalizeAuthUser).forEach(u => map.set(u.username, u));
  (Array.isArray(users) ? users : []).map(normalizeAuthUser).forEach(u => map.set(u.username, { ...(map.get(u.username) || {}), ...u }));
  return Array.from(map.values());
}

function getAllAuthUsers(){
  try{
    const raw = localStorage.getItem(AUTH_STORAGE_KEY);
    const parsed = raw ? JSON.parse(raw) : [];
    const merged = mergeDefaultUsers(parsed);
    localStorage.setItem(AUTH_STORAGE_KEY, JSON.stringify(merged));
    return merged;
  }catch(_e){
    return mergeDefaultUsers([]);
  }
}

function persistAuthUsers(users){
  try{ localStorage.setItem(AUTH_STORAGE_KEY, JSON.stringify(mergeDefaultUsers(users))); }catch(_e){}
}

function saveAuthUser(user){
  const users = getAllAuthUsers();
  const normalized = normalizeAuthUser(user);
  const idx = users.findIndex(x => x.username === normalized.username);
  if(idx >= 0) users[idx] = normalized;
  else users.push(normalized);
  persistAuthUsers(users);
  return normalized;
}

function userNeedsOnboardingLock(user){
  return !!(user && user.role === 'farmer' && (user.accountStatus !== 'active' || !user.onboardingCompleted));
}

function userNeedsOnboarding(user){
  return userNeedsOnboardingLock(user);
}

function userAwaitingInstitutionProfileReview(user){
  return !!(user && user.role === 'farmer' && String(user.profileReviewStatus || '').trim().toLowerCase() === 'pending_review');
}

function shouldShowOnboardingPanel(user){
  if(userNeedsOnboardingLock(user)) return true;
  if(!(user && user.role === 'farmer' && user.demoShowOnboardingEachLogin)) return false;
  const dismissed = !!(STATE?.onboardingReplayDismissedForSession && STATE.onboardingReplayDismissedForSession[user.username]);
  return !dismissed;
}

function getInstitutionRole(user=STATE?.currentUser){
  if(!user || user.role !== 'institution') return '';
  return String(user.institutionRole || '').trim().toLowerCase() === 'analyst' ? 'analyst' : 'admin';
}

function canManageUsers(user=STATE?.currentUser){
  return !!(user && user.role === 'institution' && getInstitutionRole(user) === 'admin');
}

function roleLabelForUser(user){
  if(!user) return 'Giriş bekleniyor';
  if(user.role === 'farmer') return 'Çiftçi paneli';
  return getInstitutionRole(user) === 'analyst' ? 'Kurumsal analiz paneli' : 'Kurumsal yönetim paneli';
}

function defaultTabForUser(user){
  if(shouldUsePresentationDefaults()) return 'parcel';
  if(!user) return 'parcel';
  if(user.role === 'farmer') return 'parcel';
  return 'district';
}


function managedUserStatusMeta(user){
  const isPassive = user?.accountStatus === 'passive';
  const onboardingPending = !isPassive && userNeedsOnboardingLock(user);
  const profilePending = !isPassive && userAwaitingInstitutionProfileReview(user);
  const accountText = isPassive ? 'Pasif' : 'Aktif';
  const accountClass = isPassive ? 'passive' : ((onboardingPending || profilePending) ? 'pending' : 'active');
  const setupText = onboardingPending ? 'Bekliyor' : (user?.onboardingCompleted ? 'Tamamlandı' : 'Bekliyor');
  const summaryText = isPassive ? 'Pasif hesap' : (onboardingPending ? 'İlk kurulum bekliyor' : (profilePending ? 'Kurulum sonrası kontrol bekliyor' : 'Aktif'));
  const detailText = onboardingPending
    ? 'İlk doğrulama açık'
    : (profilePending ? 'Yönetici teyidi / demo onayı bekliyor' : 'Hazır');
  return {
    accountText,
    accountClass,
    setupText,
    summaryText,
    detailText,
    onboardingPending,
    profilePending,
    isPassive
  };
}

function generateManagedTemporaryPassword(user){
  const base = normalizeAuthUsername(user?.displayName || user?.username || 'ciftci').replace(/[^a-z0-9]/g, '').slice(0, 6) || 'ciftci';
  const code = String(Math.floor(1000 + Math.random() * 9000));
  return `${base}${code}`;
}

function setManagedUserStatusMessage(message='', type='info'){
  const el = document.getElementById('managedUserCreateStatus');
  if(!el) return;
  if(type === 'error') el.innerHTML = `<span style="color:#c92a2a;font-weight:700;">${escapeHtml(message || '')}</span>`;
  else if(type === 'success') el.innerHTML = `<span style="color:#2b8a3e;font-weight:700;">${message || ''}</span>`;
  else el.textContent = message || 'Hazır';
}

function formatManagedUserTimestamp(value){
  if(!value) return '-';
  try{
    const date = new Date(value);
    if(Number.isNaN(date.getTime())) return '-';
    return new Intl.DateTimeFormat('tr-TR', {
      day:'2-digit', month:'2-digit', year:'numeric', hour:'2-digit', minute:'2-digit'
    }).format(date);
  }catch(_e){
    return '-';
  }
}

function getManagedFarmers(){
  return getAllAuthUsers()
    .filter(u => u.role === 'farmer')
    .sort((a,b)=> (a.displayName || a.username).localeCompare((b.displayName || b.username), 'tr'));
}

function getManagedUserFilters(){
  return {
    query: String(document.getElementById('managedUserSearch')?.value || '').trim().toLowerCase(),
    status: String(document.getElementById('managedUserStatusFilter')?.value || 'all')
  };
}

function getFilteredManagedFarmers(){
  const { query, status } = getManagedUserFilters();
  return getManagedFarmers().filter(user => {
    const meta = managedUserStatusMeta(user);
    const haystack = [
      user.displayName,
      user.username,
      user.phone,
      user.village,
      user.district,
      user.notes,
      ...(getAllowedParcelIdsForUser(user) || []),
      ...getUserCustomParcelIds(user)
    ].join(' ').toLowerCase();
    const statusOk = status === 'all' ? true : (status === 'pending_setup'
      ? meta.onboardingPending && !meta.isPassive
      : status === 'active'
        ? (!meta.onboardingPending && !meta.isPassive)
        : meta.isPassive);
    const queryOk = !query || haystack.includes(query);
    return statusOk && queryOk;
  });
}

function renderManagedUsersOverview(){
  const box = document.getElementById('managedUsersOverview');
  if(!box) return;
  const users = getManagedFarmers();
  const activeCount = users.filter(u => u.accountStatus !== 'passive' && !userNeedsOnboarding(u)).length;
  const pendingCount = users.filter(u => u.accountStatus !== 'passive' && userNeedsOnboarding(u)).length;
  const passiveCount = users.filter(u => u.accountStatus === 'passive').length;
  box.innerHTML = [
    ['Toplam çiftçi hesabı', users.length, 'Yönetim tarafından açılan tüm kayıtlar'],
    ['Aktif hesap', activeCount, 'Panele doğrudan girebilen kullanıcılar'],
    ['İlk kurulum bekleyen', pendingCount, 'Bilgi tamamlama adımı açık hesaplar'],
    ['Pasif hesap', passiveCount, 'Geçici olarak girişe kapatılan kayıtlar']
  ].map(([label, value, note]) => `<div class="managed-user-kpi"><span class="k">${label}</span><strong>${value}</strong><span>${note}</span></div>`).join('');
}

function renderManagedUsersSidebarPreview(){
  const box = document.getElementById('managedUserSidebarPreview');
  if(!box) return;
  const users = getManagedFarmers();
  const active = users.filter(u => u.accountStatus !== 'passive' && !userNeedsOnboarding(u)).length;
  const pending = users.filter(u => u.accountStatus !== 'passive' && userNeedsOnboarding(u)).length;
  box.innerHTML = [
    ['Toplam', users.length, 'Kayıtlı çiftçi hesabı'],
    ['Aktif', active, 'Panele doğrudan girebilenler'],
    ['Bekleyen', pending, 'İlk kurulum adımı açık olanlar']
  ].map(([label, value, note]) => `<div class="preview-box"><span class="k">${label}</span><strong>${value}</strong><span>${note}</span></div>`).join('');
}

function updateManagedUserFormBadges(user){
  const accountBadge = document.getElementById('managedUserAccountStatusBadge');
  const setupBadge = document.getElementById('managedUserSetupBadge');
  const setupState = document.getElementById('managedUserSetupState');
  const statusSel = document.getElementById('managedUserAccountStatus');
  const current = user || {
    accountStatus: String(statusSel?.value || 'pending_setup'),
    onboardingCompleted: String(statusSel?.value || 'pending_setup') === 'active',
    role: 'farmer'
  };
  const meta = managedUserStatusMeta(current);
  if(accountBadge){
    accountBadge.className = `managed-user-status ${meta.accountClass}`;
    accountBadge.textContent = meta.summaryText;
  }
  if(setupBadge) setupBadge.textContent = `İlk kurulum: ${meta.setupText}`;
  if(setupState) setupState.textContent = meta.setupText;
}

