// ------------------------------------------------------------
// Boot safety shims
// If any of these are referenced before the main UI functions
// are defined (e.g., due to cache or partial reload), we avoid
// hard crashes and keep the app usable.
function cleanFarmerDisplayNameV54(value){
  const raw = String(value || '').trim();
  if(!raw) return '';
  if(raw.includes('•')){
    const parts = raw.split('•');
    const last = parts.pop();
    const cleanedLast = String(last || '').replace(/\s+\d{1,4}\s*$/u, '').trim();
    return [...parts.map(x=>String(x).trim()), cleanedLast].filter(Boolean).join(' • ');
  }
  return raw.replace(/\s+\d{1,4}\s*$/u, '').trim();
}

