function parseDelimited(text, delimiter=';'){
  const lines = text.replace(/\r/g,'').split('\n').filter(l=>l.trim().length>0);
  if(lines.length < 2) return [];
  const headers = lines[0].split(delimiter).map(h=>h.trim());
  const rows = [];
  for(let i=1;i<lines.length;i++){
    const cols = lines[i].split(delimiter);
    const obj = {};
    for(let j=0;j<headers.length;j++){
      obj[headers[j]] = (cols[j] ?? '').trim();
    }
    rows.push(obj);
  }
  return rows;
}

function toNumberTR(x){
  // "1.234,56" veya "1234.56" gelebilir
  if(x==null) return NaN;
  const s = String(x).trim();
  if(!s) return NaN;
  // Not: Eski yaklaşım tüm noktaları (.) kaldırıyordu; bu da "5.8" gibi ondalık
  // değerleri yanlışlıkla 58'e çevirip parsel alanı gibi kritik metrikleri bozuyordu.
  // Bu yüzden hem TR (1.234,56) hem EN (1234.56) formatını güvenli şekilde destekle.

  let norm = s;
  const hasComma = norm.includes(',');
  const hasDot = norm.includes('.');

  if (hasComma) {
    // TR tipi: 1.234,56  veya  1234,56
    // Binlik ayırıcı noktaları kaldır, ondalık virgülü noktaya çevir.
    norm = norm.replace(/\./g, '').replace(/,/g, '.');
  } else if (hasDot) {
    // EN tipi: 1234.56  (noktayı kaldırma!)
    // Ancak tamamen binlik ayırıcı ise (1.234.567) nokta kaldır.
    if (/^\d{1,3}(\.\d{3})+$/.test(norm)) {
      norm = norm.replace(/\./g, '');
    }
  }

  const v = Number(norm);
  return Number.isFinite(v) ? v : NaN;
}

function cropTypeFromCategory(cat){
  const c = (cat||'').toLowerCase();
  if(c.includes('meyve')) return 'meyve';
  if(c.includes('sebze')) return 'sebze';
  return 'tarla';
}

function soilSuitabilityTlPerDa(soil, cropType){
  // Basit kurallar (demo): su tutma düşükse suyu çok isteyen gruplar cezalanır,
  // erozyon yüksekse çıplak toprak bırakan/yoğun sürüm gerektiren gruplar cezalanır.
  const tex = (soil.texture||"").toLowerCase();
  const ero = (soil.erosion||"").toLowerCase();

  let score = 0; // TL/da
  const lowRetention = tex.includes("kum") || tex.includes("düşük");
  const highRetention = tex.includes("killi") || tex.includes("yüksek");
  const highErosion = ero.includes("yüksek");

  if(lowRetention){
    if(cropType==="sebze" || cropType==="meyve") score -= 650;
    if(cropType==="tahil" || cropType==="baklagil") score -= 250;
    if(cropType==="yem") score -= 150;
  }
  if(highRetention){
    if(cropType==="sebze") score += 220;
    if(cropType==="yem" || cropType==="tahil") score += 120;
  }
  if(highErosion){
    if(cropType==="sebze") score -= 420;
    if(cropType==="tahil") score -= 180;
    if(cropType==="meyve") score += 120; // çok yıllık kök sistemi (temkinli bonus)
  }
  return score;
}


function buildCropCatalogFromRows(rows){
  // CSV kolonları: urun;kategori;kc_ortalama;su_tuketimi_m3_da;beklenen_verim_kg_da;fiyat_tl_kg;degisken_maliyet_tl_da
  const list = [];
  for(const r of rows){
    const name = (r.urun || '').trim();
    if(!name) continue;
    const waterPerDa = toNumberTR(r.su_tuketimi_m3_da);
    const yieldKgDa = toNumberTR(r.beklenen_verim_kg_da);
    const priceTlKg = toNumberTR(r.fiyat_tl_kg);
    const costTlDa = toNumberTR(r.degisken_maliyet_tl_da);
    // net kâr (da) = verim* fiyat - maliyet
    const profitPerDa = (Number.isFinite(yieldKgDa) && Number.isFinite(priceTlKg) ? yieldKgDa*priceTlKg : 0) - (Number.isFinite(costTlDa) ? costTlDa : 0);
    list.push({
      name,
      type: cropTypeFromCategory(r.kategori),
      waterPerDa: Number.isFinite(waterPerDa) ? waterPerDa : 0,
      profitPerDa: Math.round(profitPerDa)
    });
  }
  // Keep dryland options (waterPerDa can be 0).
  return list.filter(c=>isFinite(c.waterPerDa) && c.waterPerDa>=0 && c.name.length>0);
}

function upsertManualCatalogFromSeasonRowsV93(rows){
  const agg = new Map();
  for(const r of rows || []){
    const crop = String(r.crop || r.urun || r.urun_adi || r.bitki || '').trim();
    if(!crop) continue;
    const key = normCropName(crop);
    const area = safeNum(r.area_da ?? r.alan_da ?? r.ekim_alani_da, 0);
    const water = safeNum(r.water_m3_calib_gross ?? r.water_m3 ?? r.su_m3 ?? r.toplam_su, 0);
    const profit = safeNum(r.profit_tl ?? r.kar_tl ?? r.net_kar_tl ?? r.toplam_kar, 0);
    if(!agg.has(key)) agg.set(key, {name: crop, area:0, water:0, profit:0});
    const a = agg.get(key);
    a.area += Math.max(0, area);
    a.water += Math.max(0, water);
    a.profit += profit;
  }
  if(!agg.size) return 0;
  const cat = STATE.cropCatalog || {};
  let n = 0;
  for(const [key,a] of agg.entries()){
    const prev = cat[key] || {name:a.name};
    const area = Math.max(1e-9, a.area);
    cat[key] = {
      ...prev,
      name: prev.name || a.name,
      waterPerDa: a.water / area,
      profitPerDa: a.profit / area,
      manualCsvSource: true
    };
    n++;
  }
  STATE.cropCatalog = cat;
  return n;
}

function applyManualParcelRowsV93(rows){
  const byId = new Map();
  for(const r of rows || []){
    const pid = normalizeManualParcelIdV92(r.parcel_id || r.parsel_id || r.id || r.parsel || '');
    if(pid) byId.set(pid, r);
  }
  let n = 0;
  for(const p of parcelData || []){
    const r = byId.get(normalizeManualParcelIdV92(p.id));
    if(!r) continue;
    const area = parseNumFlex(r.area_da ?? r.alan_da ?? r.alan ?? r.area, NaN);
    const currentCrop = String(r.current_crop || r.mevcut_urun || r.crop || r.urun || '').trim();
    const water = parseNumFlex(r.water_m3 ?? r.mevcut_su_m3 ?? r.current_water_m3 ?? r.su_m3, NaN);
    const profit = parseNumFlex(r.profit_tl ?? r.mevcut_kar_tl ?? r.current_profit_tl ?? r.kar_tl, NaN);
    if(Number.isFinite(area) && area > 0) p.area_da = area;
    if(Number.isFinite(water) && water >= 0) p.water_m3 = water;
    if(Number.isFinite(profit)) p.profit_tl = profit;
    if(currentCrop) p.current_crop = currentCrop;
    if(r.village || r.koy) p.village = String(r.village || r.koy).trim();
    if(r.district || r.ilce) p.district = String(r.district || r.ilce).trim();
    p.manualCsvOverride = true;
    n++;
  }
  return n;
}

function applyManualSeasonRowsV93(rows){
  const byParcel = new Map();
  for(const r of rows || []){
    const pid = normalizeManualParcelIdV92(r.parcel_id || r.parsel_id || r.id || '');
    const crop = String(r.crop || r.urun || r.urun_adi || r.bitki || '').trim();
    if(!pid || !crop) continue;
    if(!byParcel.has(pid)) byParcel.set(pid, []);
    byParcel.get(pid).push(r);
  }
  let n = 0;
  for(const p of parcelData || []){
    const list = byParcel.get(normalizeManualParcelIdV92(p.id));
    if(!list || !list.length) continue;
    const rowsNorm = list.map(r=>{
      const area = safeNum(r.area_da ?? r.alan_da ?? p.area_da, p.area_da || 0);
      const totalWater = safeNum(r.water_m3_calib_gross ?? r.water_m3 ?? r.su_m3 ?? r.toplam_su, 0);
      const totalProfit = safeNum(r.profit_tl ?? r.kar_tl ?? r.net_kar_tl ?? r.toplam_kar, 0);
      const crop = String(r.crop || r.urun || r.urun_adi || r.bitki || '').trim();
      const irrigationKey = irrKeyFromText(r.irrigation || r.sulama || r.irrigation_current || '') || 'sprinkler';
      return {
        name: crop,
        area,
        season: String(r.season || r.mevsim || inferSeasonFromCropName(crop) || '-'),
        irrigationCurrentKey: irrigationKey,
        irrigationCurrentText: irrigationLabel(irrigationKey),
        waterPerDa: area > 0 ? totalWater / area : 0,
        _baseWaterPerDa: area > 0 ? totalWater / area : 0,
        _officialGrossWaterPerDa: area > 0 ? totalWater / area : 0,
        profitPerDa: area > 0 ? totalProfit / area : 0,
        totalWater,
        totalProfit
      };
    });
    const totalWater = rowsNorm.reduce((a,r)=>a+safeNum(r.totalWater,0),0);
    const totalProfit = rowsNorm.reduce((a,r)=>a+safeNum(r.totalProfit,0),0);
    p.cropCurrent = rowsNorm;
    p.current_crop = rowsNorm[0]?.name || p.current_crop;
    p.area_da = rowsNorm.reduce((a,r)=>Math.max(a, safeNum(r.area,0)), safeNum(p.area_da,0));
    p.water_m3 = totalWater;
    p.profit_tl = totalProfit;
    p.manualCsvOverride = true;
    n++;
  }
  return n;
}

function applyManualIrrigationRowsV94(rows){
  const parsed = (rows || []).map(r=>{
    const method = String(r.method || r.sulama_yontemi || r.irrigation_method || r.irrigation || '').trim();
    if(!method) return null;
    const app = safeNum(r.application_efficiency ?? r.typical_application_efficiency ?? r.efficiency ?? r.randiman ?? r.randiman_orani, NaN);
    const total = safeNum(r.typical_total_efficiency ?? r.total_efficiency ?? r.toplam_randiman, app);
    return {
      method,
      application_efficiency: Number.isFinite(app) ? app : total,
      typical_total_efficiency: Number.isFinite(total) ? total : app,
      opex_tl_per_da: safeNum(r.opex_tl_per_da ?? r.isletme_tl_da ?? r.sulama_isletme_tl_da, 0),
      capex_tl_per_da: safeNum(r.capex_tl_per_da ?? r.yatirim_tl_da, 0),
      manualCsvSource: true
    };
  }).filter(Boolean);
  if(!parsed.length) return 0;
  const prev = Array.isArray(STATE.irrigMethods) ? STATE.irrigMethods : [];
  const byMethod = new Map(prev.map(r=>[String(r.method || '').trim(), r]).filter(([k])=>k));
  parsed.forEach(r=>{
    const key = String(r.method || '').trim();
    byMethod.set(key, { ...(byMethod.get(key) || {}), ...r });
    const lk = key.toLowerCase();
    const eff = clamp(safeNum(r.typical_total_efficiency, r.application_efficiency), 0.35, 1);
    if(lk.includes('drip') || lk.includes('damla')) IRR_EFF.drip = eff;
    else if(lk.includes('sprink') || lk.includes('yagmur') || lk.includes('yağmur') || lk.includes('pivot')) IRR_EFF.sprinkler = eff;
    else if(lk.includes('surface') || lk.includes('karik') || lk.includes('karık') || lk.includes('salma')) IRR_EFF.surface = eff;
  });
  STATE.irrigMethods = Array.from(byMethod.values());
  return parsed.length;
}

function applyManualReservoirRowsV94(rows){
  const parsed = (rows || []).map(r=>{
    const year = safeNum(r.year ?? r.yil ?? r['yıl'] ?? r['yıl'] ?? String(r.month || r.ay || '').slice(0,4), NaN);
    if(!Number.isFinite(year) || year <= 0) return null;
    const doluluk = safeNum(r.doluluk ?? r.doluluk_endeksi_0_100 ?? r.fullness_pct ?? r.storage_pct ?? r.capacity_pct, NaN);
    const storage = safeNum(r.storage_m3 ?? r.hacim_m3 ?? r.volume_m3 ?? r.depolama_m3, NaN);
    const pct = Number.isFinite(doluluk) ? doluluk : (Number.isFinite(storage) && STATE.maxCapacityM3 ? (storage / STATE.maxCapacityM3) * 100 : NaN);
    if(!Number.isFinite(pct)) return null;
    return {
      yil: Math.round(year),
      doluluk: pct,
      girisim_hm3: safeNum(r.girisim_hm3 ?? r.inflow_hm3, 0),
      cekis_hm3: safeNum(r.cekis_hm3 ?? r.outflow_hm3, 0),
      ortalama_pct: safeNum(r.ortalama_pct ?? r.avg_pct, NaN),
      min_pct: safeNum(r.min_pct ?? r.minimum_pct, NaN),
      manualCsvSource: true
    };
  }).filter(Boolean);
  if(!parsed.length) return 0;
  const prev = Array.isArray(STATE.barajSeries) ? STATE.barajSeries : [];
  const byYear = new Map(prev.map(r=>[String(r.yil), r]).filter(([k])=>k));
  parsed.forEach(r=>byYear.set(String(r.yil), { ...(byYear.get(String(r.yil)) || {}), ...r }));
  STATE.barajSeries = Array.from(byYear.values()).sort((a,b)=>safeNum(a.yil,0)-safeNum(b.yil,0));
  try{ updateDroughtAnalytics(); }catch(_e){}
  try{ applyWaterScenarioFromUI(true); }catch(_e){}
  return parsed.length;
}

async function applyManualCsvFilesToAnalysisV93(fileList){
  const files = Array.from(fileList || []);
  const summary = {files: files.map(f=>f.name), parcelsApplied:0, seasonParcelsApplied:0, cropsApplied:0, irrigationApplied:0, reservoirApplied:0, appliedByFile:{}};
  for(const file of files){
    const text = await file.text();
    const lower = String(file.name || '').toLowerCase();
    const parsed = (lower.endsWith('.json') || lower.endsWith('.geojson'))
      ? (()=>{ const rows = jsonToRowsV66(text); return {headers:Object.keys(rows[0] || {}), rows}; })()
      : parseCsvRobustV66(text);
    const inferred = inferManualFileKindV92(parsed.headers || [], file.name);
    const inferredKindKey = normalizeManualHeaderKeyV92(inferred.kind || '');
    const fileApplied = {kind: inferred.kind, parcelsApplied:0, seasonParcelsApplied:0, cropsApplied:0, irrigationApplied:0, reservoirApplied:0, applied:0};
    if(inferredKindKey.includes('parsel')){
      fileApplied.parcelsApplied = applyManualParcelRowsV93(parsed.rows || []);
      summary.parcelsApplied += fileApplied.parcelsApplied;
    }
    if(inferredKindKey.includes('urun') || inferredKindKey.includes('bitki') || inferredKindKey.includes('kar')){
      fileApplied.cropsApplied = upsertManualCatalogFromSeasonRowsV93(parsed.rows || []);
      fileApplied.seasonParcelsApplied = applyManualSeasonRowsV93(parsed.rows || []);
      summary.cropsApplied += fileApplied.cropsApplied;
      summary.seasonParcelsApplied += fileApplied.seasonParcelsApplied;
    }
    if(inferred.kind === 'Sulama yöntemi'){
      fileApplied.irrigationApplied = applyManualIrrigationRowsV94(parsed.rows || []);
      summary.irrigationApplied += fileApplied.irrigationApplied;
    }
    if(inferred.kind === 'Baraj su bütçesi'){
      fileApplied.reservoirApplied = applyManualReservoirRowsV94(parsed.rows || []);
      summary.reservoirApplied += fileApplied.reservoirApplied;
    }
    if(!fileApplied.irrigationApplied && (inferredKindKey.includes('sulama') || inferredKindKey.includes('irrigation'))){
      fileApplied.irrigationApplied = applyManualIrrigationRowsV94(parsed.rows || []);
      summary.irrigationApplied += fileApplied.irrigationApplied;
    }
    if(!fileApplied.reservoirApplied && (inferredKindKey.includes('baraj') || inferredKindKey.includes('reservoir') || inferredKindKey.includes('butce'))){
      fileApplied.reservoirApplied = applyManualReservoirRowsV94(parsed.rows || []);
      summary.reservoirApplied += fileApplied.reservoirApplied;
    }
    fileApplied.applied = fileApplied.parcelsApplied + fileApplied.seasonParcelsApplied + fileApplied.cropsApplied + fileApplied.irrigationApplied + fileApplied.reservoirApplied;
    summary.appliedByFile[file.name] = fileApplied;
  }
  const totalApplied = summary.parcelsApplied + summary.seasonParcelsApplied + summary.cropsApplied + summary.irrigationApplied + summary.reservoirApplied;
  STATE.manualDataActive = totalApplied > 0;
  STATE.manualDataFiles = summary.files;
  STATE.manualDataAppliedSummary = summary;
  return summary;
}

function applyParcelSummaryRows(rows){
  // CSV kolonları: parsel_id;toprak_kodu;koy;ilce;alan_da;mevcut_su_m3;mevcut_kar_tl
  const byId = new Map(rows.map(r=>[(r.parsel_id||'').trim(), r]));
  for(const p of parcelData){
    const r = byId.get(p.id);
    if(!r) continue;
    const area = toNumberTR(r.alan_da);
    const water = toNumberTR(r.mevcut_su_m3);
    const profit = toNumberTR(r.mevcut_kar_tl);

    if(Number.isFinite(area)) p.area_da = area;
    if(Number.isFinite(water)) p.water_m3 = water;
    if(Number.isFinite(profit)) p.profit_tl = profit;

    if(r.koy) p.village = r.koy;
    if(r.ilce) p.district = r.ilce;

    // isimde toprak kodunu da göster
    const soilCode = (r.toprak_kodu||'').trim();
    if(soilCode){
      p.name = `${p.id} - ${soilCode} (${p.village})`;
    }
    // toprak özeti alanına da geçir
    if(soilCode){
      p.soil = p.soil || {};
      p.soil.soilCode = soilCode;
    }
  }

  // select option label güncelle
  if(parcelSelectEl){
    for(const opt of Array.from(parcelSelectEl.options)){
      const p = parcelData.find(x=>x.id===opt.value);
      if(p) opt.textContent = p.name;
    }
  }
}

