function updateBenchmarkSweepChartsV96(items){
  const ok = (items||[]).filter(x=>x?.raw?.algorithms);
  if(!ok.length) return;
  const titles = document.querySelectorAll('.chart-grid-benchmark .chart-title');
  if(titles[0]) titles[0].textContent = '30/50/100 kâr yakınsaması - normalize skor';
  if(titles[1]) titles[1].textContent = '30/50/100 su uygunlugu - normalize skor';
  if(titles[2]) titles[2].textContent = '30/50/100 TL/m³ verimlilik yakınsaması';
  if(titles[3]) titles[3].textContent = '30/50/100 süre avantajı - normalize skor';
  const labels = ok.map(x=>String(x.repeat));
  const algNames = Array.from(new Set(ok.flatMap(x=>Object.keys(x.raw.algorithms || {}))));
  const colors = {GA:'#2563eb', ABC:'#0f766e', ACO:'#f97316'};
  const makeLine = (label, values)=>({label, data:values, type:'line', borderColor:colors[label]||'#334155', backgroundColor:'rgba(37,99,235,.08)', pointRadius:4, tension:.22, fill:false});
  const normSeries = (metric, higherBetter=true)=>{
    const byAlgo = {};
    algNames.forEach(a=> byAlgo[a] = []);
    ok.forEach(x=>{
      const vals = algNames.map(a=>{
        const r = x.raw.algorithms?.[a] || {};
        if(metric === 'profit') return +(r?.profit?.mean || 0);
        if(metric === 'water') return +(r?.water?.mean || 0);
        if(metric === 'eff') return +(r?.efficiency?.mean || 0);
        if(metric === 'runtime') return +(r?.runtime_s?.mean || 0);
        return 0;
      });
      const finite = vals.filter(v=>Number.isFinite(v) && v > 0);
      const max = finite.length ? Math.max(...finite) : 1;
      const min = finite.length ? Math.min(...finite) : 1;
      algNames.forEach((a,i)=>{
        const v = vals[i];
        let score = 0;
        if(Number.isFinite(v) && v > 0){
          score = higherBetter ? (100 * v / Math.max(1e-9, max)) : (100 * min / Math.max(1e-9, v));
        }
        byAlgo[a].push(Math.max(0, Math.min(120, score)));
      });
    });
    return byAlgo;
  };
  const profitNorm = normSeries('profit', true);
  const waterNorm = normSeries('water', false);
  const effNorm = normSeries('eff', true);
  const runtimeNorm = normSeries('runtime', false);
  if(benchmarkProfitChart){
    benchmarkProfitChart.data.labels = labels;
    benchmarkProfitChart.data.datasets = algNames.map(a=>makeLine(a, profitNorm[a] || []));
    benchmarkProfitChart.update();
  }
  if(benchmarkWaterChart){
    benchmarkWaterChart.data.labels = labels;
    benchmarkWaterChart.data.datasets = algNames.map(a=>makeLine(a, waterNorm[a] || []));
    benchmarkWaterChart.update();
  }
  if(benchmarkEffChart){
    benchmarkEffChart.data.labels = labels;
    benchmarkEffChart.data.datasets = algNames.map(a=>makeLine(a, effNorm[a] || []));
    benchmarkEffChart.update();
  }
  if(benchmarkRuntimeChart){
    benchmarkRuntimeChart.data.labels = labels;
    benchmarkRuntimeChart.data.datasets = algNames.map(a=>makeLine(a, runtimeNorm[a] || []));
    benchmarkRuntimeChart.update();
  }
}

function renderBenchmarkResultsTo(j, box, patBox, updateCharts = true){
  const kpiRoot = document.getElementById('benchmarkKpiGrid');
  if(!box) return;
  if(!j || j.status !== 'OK'){
    box.innerHTML = '<div class="badge badge-warn">Benchmark sonucu alınamadı</div>';
    if(kpiRoot) kpiRoot.innerHTML = '';
    if(patBox) patBox.innerHTML = '';
    return;
  }

  const algos = j.algorithms || {};
  const rows = Object.keys(algos);
  if(!rows.length){
    box.innerHTML = '<div class="badge badge-warn">Veri yok</div>';
    if(kpiRoot) kpiRoot.innerHTML = '';
    return;
  }

  const objectiveRaw = (j.objective || j.scenario || j.target || '').toString();
  const objective = objectiveRaw.toLowerCase();
  const isEfficiency = objective.includes('efficiency') || objective.includes('etkin') || objective.includes('verim');
  const isWater = !isEfficiency && (objective.includes('water') || objective.includes('su'));
  const isProfit = objective.includes('profit') || objective.includes('kar');
  const objectiveLabel = isEfficiency ? 'Su etkin kullanım' : (isWater && !isProfit ? 'Su tasarrufu' : (isProfit && !isWater ? 'Net kâr' : 'Su etkin kullanım'));

  const rel = (m,s)=> (Math.abs(m) > 1e-9 ? Math.abs(s)/Math.abs(m) : 0);
  const scoreRows = rows.map(a=>{
    const r = algos[a] || {};
    const p = r.profit||{}; const w = r.water||{}; const e = r.efficiency||{};
    const pm = Number(p.mean)||0, ps = Number(p.std)||0;
    const wm = Number(w.mean)||0, ws = Number(w.std)||0;
    const em = Number(e.mean)||0, es = Number(e.std)||0;
    const feasibleRate = Number(r.feasible_rate||0);
    const successRate = Number(r.success_rate||0);
    const runtime = Number(r?.runtime_s?.mean||0);
    const diversity = Number(r.unique_patterns||0);
    let base = em;
    if(isWater && !isProfit) base = (em * 1000) - (0.0002 * wm);
    else if(isProfit && !isWater) base = pm - (0.015 * wm);
    const stabilityPenalty = 0.12 * (rel(pm,ps)+rel(wm,ws)+rel(em,es));
    const feasibilityBonus = 0.25 * feasibleRate + 0.15 * successRate;
    const diversityBonus = Math.min(0.08, diversity * 0.01);
    const runtimePenalty = Math.min(0.08, runtime * 0.01);
    return { a, score: base * (1 - stabilityPenalty) + feasibilityBonus + diversityBonus - runtimePenalty };
  }).sort((x,y)=>y.score-x.score);
  const topScore = Number(scoreRows[0]?.score || 0);
  const tiedTop = scoreRows.filter(x=> Math.abs(Number(x.score||0) - topScore) <= Math.max(1e-9, Math.abs(topScore) * 0.001));
  const bestAlgo = (tiedTop.length > 1
    ? tiedTop.slice().sort((x,y)=> Number(algos[x.a]?.runtime_s?.mean||0) - Number(algos[y.a]?.runtime_s?.mean||0))[0]?.a
    : scoreRows[0]?.a) || rows[0];
  const bestRow = algos[bestAlgo] || {};
  const avgPlanDistance = rows.reduce((s,a)=> s + Number(algos[a]?.plan_distance_pct?.mean || 0), 0) / Math.max(1, rows.length);
  const benchmarkHealth = avgPlanDistance >= 5
    ? 'Algoritmalar parsel atamalarında ölçülebilir biçimde ayrışıyor.'
    : (rows.some(a=>Number(algos[a]?.unique_patterns||0) > 1)
      ? 'Toplam sonuçlar yakın olsa da algoritmalar bazı parsellerde farklı desenler üretiyor.'
      : 'Çözüm uzayı dar veya kısıtlar çok baskın; algoritmalar benzer desenlere yakınsıyor olabilir.');

  const backendInterpretation = String(j.interpretation || '').trim();
  const dynamicInterpretation = benchmarkDynamicInterpretation(bestAlgo, algos, rows);
  const leaderReason = dynamicInterpretation || backendInterpretation || (tiedTop.length > 1
    ? `${tiedTop.map(x=>x.a).join(', ')} algoritmalari ayni kalite skoruna yaklasti; karar tek algoritmaya baglanmamalidir.`
    : `${bestAlgo} metriklere dayali denge skorunda one cikti.`);

  if(updateCharts) applyBenchmarkLeaderV96(bestAlgo, objectiveLabel, leaderReason);

  if(kpiRoot){
    const requestedRepeats = Math.max(1, Number(j.repeats || 0));
    const requestedTotal = requestedRepeats * rows.length;
    const totalAttempted = rows.reduce((s,a)=> s + Number(algos[a]?.attempted_runs || algos[a]?.runs || 0), 0);
    const totalSuccessful = rows.reduce((s,a)=> s + Number(algos[a]?.successful_runs || algos[a]?.runs || 0), 0);
    const avgFeasible = rows.reduce((s,a)=> s + Math.max(0, Math.min(1, Number(algos[a]?.feasible_rate || 0))), 0) / Math.max(1, rows.length);
    const avgRuntime = rows.reduce((s,a)=> s + Number(algos[a]?.runtime_s?.mean || 0), 0) / Math.max(1, rows.length);
    kpiRoot.innerHTML = [
      {label:'Algoritma yorumu', value:(/esdeger|eşdeğer|tek algoritmaya/i.test(leaderReason) ? 'Eşdeğer bant' : bestAlgo), sub:`${objectiveLabel} hedefinde metrik temelli okuma`},
      {label:'Tekrar politikası', value:`${requestedRepeats} tekrar`, sub:`Her algoritma için hedef tekrar; seed: ${j.seed_policy?.includes('fixed') ? 'sabit kök + algoritma ofseti' : 'rastgele kök + algoritma ofseti'}`},
      {label:'Koşu kapsamı', value:`${totalSuccessful}/${requestedTotal}`, sub:`${totalAttempted} deneme başlatıldı; süre bütçesi dolarsa fiili sayı düşebilir`},
      {label:'Plan ayrışması', value:`${fmtNum(avgPlanDistance,1)}%`, sub:`Ortalama süre: ${fmtNum(avgRuntime,2)} sn • Uygulanabilirlik: ${fmtNum(avgFeasible*100,1)}%`} 
    ].map(k=>`<div class="pro-kpi"><div class="kpi-label">${escapeHtml(String(k.label))}</div><div class="kpi-value">${escapeHtml(String(k.value))}</div><div class="kpi-sub">${escapeHtml(String(k.sub))}</div></div>`).join('');
  }

  let html = '';
  const benchmarkScopeLabel = window.__lastBenchmarkScopeLabel || '';
  html += `<div class="benchmark-method-card">`+
          `<div style="display:flex;flex-wrap:wrap;gap:6px;margin-bottom:8px;">`+
          `<span class="benchmark-tag">Backend benchmark</span>`+
          `<span class="benchmark-tag">Hedef: ${escapeHtml(objectiveLabel)}</span>`+
          `<span class="benchmark-tag">İstenen tekrar: ${escapeHtml(String(Math.max(1, Number(j.repeats || 0))))}</span>`+
          `${benchmarkScopeLabel ? `<span class="benchmark-tag">Kapsam: ${escapeHtml(benchmarkScopeLabel)}</span>` : ''}`+
          `</div>`+
          `<div><b>Karşılaştırma notu:</b> ${escapeHtml(benchmarkHealth)}</div>`+
          `<div class="small muted" style="margin-top:6px;">Mevcut desen referans sütunu olarak tutulur; algoritmalar aynı veri, aynı aday ürün havuzu ve aynı su bütçesi altında kıyaslanır. Seçili parselde parsel bazlı davranış, tüm parsel görünümünde ise temsilî kurum kapsamı raporlanır.</div><div class="small muted" style="margin-top:6px;"><b>Not:</b> Buradaki başarısız koşu sayısı bir tahmin hatası değildir; yalnızca teknik olarak sonuç üretemeyen veya kısıt nedeniyle geçersiz kalan koşuları gösterir. 0 olması iyi durumdur.</div>`+
          `</div>`;
  html += `<div class="benchmark-note" style="margin-bottom:10px;"><b>Ürün çeşitliliği kontrolü:</b> Bu sürümde algoritmalar yalnızca net kâr ve su tüketimine göre değil, ürün deseninin tarımsal uygulanabilirliği açısından da değerlendirilmektedir. Ürün yoğunlaşması göstergeleri, önerilen değişiklik yapılan alanlar üzerinden hesaplanmaktadır. Bu nedenle oranlar toplam havza alanı değil, değişen öneri alanı içindeki dağılımı ifade eder. Öneri planı içinde hesaplanan alan payı ayrıca mevcutsa uyarı içinde gösterilir.</div>`;
  html += `<div class="benchmark-note" style="margin-bottom:10px;"><b>Performans notu:</b> Yüksek tekrar sayıları hesaplama süresini artırabilir. Örneğin 100 tekrar, GA/ACO/ABC için toplam 300 koşu anlamına gelir.</div>`;
  html += `<div class="benchmark-note" style="margin-bottom:10px;"><b>Benchmark yorumu:</b> ${escapeHtml(leaderReason)}</div>`;

  if(j.baseline){
    html += `<div class="benchmark-note" style="margin-bottom:10px;"><b>Baseline (mevcut desen):</b> `+
            `${fmtNum(j.baseline.total_profit_tl,0)} TL net kâr • ${fmtNum(j.baseline.total_water_m3,0)} m³ su • ${fmtNum(j.baseline.efficiency_tl_per_m3,2)} TL/m³</div>`;
  }

  if(j.baseline){
    const bProfit = Number(j.baseline.total_profit_tl || 0);
    const bWater = Number(j.baseline.total_water_m3 || 0);
    const bEff = Number(j.baseline.efficiency_tl_per_m3 || 0);
    const bestProfit = Number(bestRow?.profit?.mean || 0);
    const bestWater = Number(bestRow?.water?.mean || 0);
    const bestEff = Number(bestRow?.efficiency?.mean || 0);
    const profitDelta = bestProfit - bProfit;
    const waterDelta = bestWater - bWater;
    const effDelta = bestEff - bEff;
    const samePlanForDelta = avgPlanDistance < 0.5 && rows.every(a=>Number(algos[a]?.unique_patterns||0) <= 1);
    html += `<div class="benchmark-delta-grid-v97">
      <div><span>Mevcude gore kar</span><b>${profitDelta >= 0 ? '+' : ''}${fmtNum(profitDelta,0)} TL</b><small>Benchmark lideri: ${escapeHtml(bestAlgo)}</small></div>
      <div><span>Mevcude gore su</span><b>${waterDelta <= 0 ? '' : '+'}${fmtNum(waterDelta,0)} m3</b><small>${waterDelta <= 0 ? 'su tasarrufu yonunde' : 'daha fazla su kullaniyor'}</small></div>
      <div><span>TL/m³ farkı</span><b>${effDelta >= 0 ? '+' : ''}${fmtNum(effDelta,2)}</b><small>verimlilik yakınsaması</small></div>
      <div><span>Karar güveni</span><b>${samePlanForDelta ? 'Kısıt-kararlı' : fmtNum(avgPlanDistance,1) + '% plan farkı'}</b><small>${samePlanForDelta ? 'Aynı desen, dar çözüm uzayı' : 'Algoritmalar ayrışıyor'}</small></div>
    </div>`;
  }

  const allSamePlan = avgPlanDistance < 0.5 && rows.every(a=>Number(algos[a]?.unique_patterns||0) <= 1);
  html += `<div class="benchmark-interpretation-v97">
    <div><b>Yakınsama yorumu</b><span>${allSamePlan ? 'Algoritmalar aynı karar noktasına kilitlenmiş. Bu, algoritma hatası olarak değil; veri havuzu, su kotası, parsel uygunluğu veya tek baskın ürün kısıtının çözümü daraltması olarak okunur.' : 'Algoritmalar arasında parsel/desen farkı var; plan farkı ve CV birlikte okunarak hangi algoritmanın daha kararlı olduğu seçilir.'}</span></div>
    <div><b>Overfitting kontrolü</b><span>CV, plan farkı ve 30/50/100 tekrar eğilimi birlikte düşükse bu overfitting değil, kararlı yakınsamadır. CV yükselir veya tekrar arttıkça plan sürekli değişirse sonuç güvenilir sayılmaz.</span></div>
    <div><b>Öneri deseni</b><span>Önerilen desen benchmark lideri ile çalışır; algoritmalar aynı deseni önerirse çiftçiye farklı ürün varmış gibi gösterilmez, kısıt nedeniyle aynı sonuca gelindiği açıklanır.</span></div>
  </div>`;

  html += '<div class="benchmark-table-wrap">';
  html += '<table class="mini-table pro" style="width:100%;border-collapse:collapse;">';
  const isDoubleBenchmark = String(j?.diagnostics?.scenario_type || j?.scenario_type || '').toLowerCase() === 'double'
    || String(j?.seasonSource || j?.season_source || '').toLowerCase() === 's2';
  html += '<thead><tr>'+
    '<th style="text-align:left;">Algoritma</th>'+
    '<th style="text-align:right;">Kâr ort</th>'+
    '<th style="text-align:right;">Medyan</th>'+
    '<th style="text-align:right;">Min-Maks</th>'+
    '<th style="text-align:right;">Su ort</th>'+
    '<th style="text-align:right;">TL/m³ ort</th>'+
    '<th style="text-align:right;">Std / CV</th>'+
    '<th style="text-align:right;">Plan farkı</th>'+
    '<th style="text-align:right;">Uygulanabilirlik</th>'+
    '<th style="text-align:right;">Baskın ürün</th>'+
    '<th style="text-align:right;">İlk 3 / HHI</th>'+
    (isDoubleBenchmark ? '<th style="text-align:right;">2. ürün oranı</th><th style="text-align:right;">2. ürün alanı</th>' : '')+
    '<th style="text-align:right;">Süre</th>'+
    '<th style="text-align:right;">Desen</th>'+
    '<th style="text-align:right;">Başarısız koşu</th>'+
  '</tr></thead><tbody>';

  for(const a of rows){
    const r = algos[a] || {};
    const p = r.profit||{}; const w = r.water||{}; const e = r.efficiency||{}; const t = r.runtime_s||{}; const pd = r.plan_distance_pct||{};
    const feasibleTxt = `${fmtNum(Math.max(0, Math.min(100, (Number(r.feasible_rate||0))*100)),1)}%`;
    const successTxt = `${fmtNum(Math.max(0, Math.min(100, (Number(r.success_rate||0))*100)),1)}%`;
    const secParcelTxt = `${fmtNum((Number(r?.secondary_parcel_rate?.mean||0))*100,1)}%`;
    const secAreaTxt = `${fmtNum((Number(r?.secondary_area_da?.mean||0)),1)} da`;
    const failedRuns = Number(r.failed_runs ?? Math.max(0, Number(r.attempted_runs||0) - Number(r.successful_runs||r.runs||0)));
    const div = r.diversity || {};
    const divWarn = diversityWarningHtml(
      div,
      r.recommendation_status || div.recommendation_status,
      !!r.best?.diversity_repair_applied,
      { feasible: Number(r.feasible_rate || 0) >= 0.999, selectable: true }
    );
    const topCropTxt = div.top_crop ? `${prettyCropName(div.top_crop)} (${diversityPercentText(div.top_crop_share)})` : '-';
    const statusTxt = diversityStatusLabel(r.recommendation_status);
    html += '<tr>'+
      `<td><b>${escapeHtml(a)}</b><div class="small muted">başarılı: ${successTxt}</div></td>`+
      `<td style="text-align:right;">${fmtNum(p.mean,0)}</td>`+
      `<td style="text-align:right;">${fmtNum(p.median,0)}</td>`+
      `<td style="text-align:right;">${fmtNum(p.min,0)} - ${fmtNum(p.max,0)}</td>`+
      `<td style="text-align:right;">${fmtNum(w.mean,0)}</td>`+
      `<td style="text-align:right;">${fmtNum(e.mean,2)}</td>`+
      `<td style="text-align:right;">${fmtNum(p.std,0)} / ${fmtNum((Number(p.cv||0))*100,1)}%</td>`+
      `<td style="text-align:right;">${fmtNum(pd.mean,1)}%</td>`+
      `<td style="text-align:right;">${feasibleTxt}</td>`+
      `<td style="text-align:right;">${escapeHtml(topCropTxt)}<div class="small muted">${escapeHtml(statusTxt)}</div>${divWarn}</td>`+
      `<td style="text-align:right;">${div.top3_crop_share != null ? diversityPercentText(div.top3_crop_share) : '-'} / ${div.hhi != null ? fmtNum(div.hhi,3) : '-'}</td>`+
      (isDoubleBenchmark ? `<td style="text-align:right;">${secParcelTxt}</td><td style="text-align:right;">${secAreaTxt}</td>` : '')+
      `<td style="text-align:right;">${fmtNum(t.mean,2)} sn</td>`+
      `<td style="text-align:right;">${escapeHtml(String(r.unique_patterns ?? 0))}</td>`+
      `<td style="text-align:right;">${failedRuns > 0 ? escapeHtml(String(failedRuns)) : 'yok'}</td>`+
    '</tr>';
  }
  html += '</tbody></table></div>';
  box.innerHTML = html;

  if(patBox){
    let pHtml = '<div class="card" style="background:#fbfcff;">'+
      '<h3 class="card-subtitle" style="margin:0 0 6px;">Önerilen desen karşılaştırması (en iyi koşu)</h3>'+
      '<div class="small muted" style="margin-bottom:10px;">Her algoritma için en iyi koşuda öne çıkan ürün alanları ve parsel bazlı desen karşılaştırması gösterilir.</div>';

    pHtml += '<div class="benchmark-pattern-grid">';
    for(const a of rows){
      const best = algos[a]?.best;
      if(!best){
        pHtml += `<div class="stat benchmark-pattern-card pattern-compare-card"><div class="stat-label"><b>${escapeHtml(a)}</b></div><div class="stat-value muted">-</div></div>`;
        continue;
      }
      const prim = (best.crop_area?.primary||[]).filter(x=>safeNum(x.area_da,0)>0);
      const sec = (best.crop_area?.secondary||[]).filter(x=>safeNum(x.area_da,0)>0);
      const primList = prim.map(x=> `${escapeHtml(prettyCropName(x.crop))} (${fmtNum(x.area_da,1)} da)`).join('<br/>') || '-';
      const secList = sec.map(x=> `${escapeHtml(prettyCropName(x.crop))} (${fmtNum(x.area_da,1)} da)`).join('<br/>') || (String(best.status || '') === 'no_feasible_two_crop_plan' ? 'Uygulanabilir iki ürünlü plan bulunamadı' : 'İkinci ürün/desen yok');
      const warn = algos[a]?.identical_plan_warning ? '<div class="small muted" style="margin-top:6px;">Not: tekrarlar arasında desen çeşitliliği düşük.</div>' : '';
      const pd = algos[a]?.plan_distance_pct || {};
      const secondaryBlock = isDoubleBenchmark ? `<div class="small" style="margin-top:6px;"><b>2. ürün</b><br/>${secList}</div>` : '';
      const secondaryMeta = isDoubleBenchmark ? ` • 2. ürün alanı: ${fmtNum((algos[a]?.secondary_area_da?.mean||0),1)} da` : '';
      const bestRecommendationStatus = best.recommendation_status || algos[a]?.recommendation_status || best.diversity?.recommendation_status;
      const divBlock = diversityWarningHtml(
        best.diversity,
        bestRecommendationStatus,
        !!best.diversity_repair_applied,
        { feasible: best.feasible !== false, selectable: best.selectable !== false }
      );
      const riskBlock = agronomicRiskHtml(best.agronomic_risk || algos[a]?.agronomic_risk);
      pHtml += '<div class="stat benchmark-pattern-card pattern-compare-card" style="min-width:240px;">'+
        `<div class="stat-label"><b>${escapeHtml(a)}</b> - en iyi koşu</div>`+
        `<div class="small" style="margin-top:6px;"><b>1. ürün</b><br/>${primList}</div>`+
        secondaryBlock+
        `<div class="small" style="opacity:.88;margin-top:8px;">Kâr: <b>${fmtNum(best.total_profit_tl,0)}</b> TL • Su: <b>${fmtNum(best.total_water_m3,0)}</b> m³ • TL/m³: <b>${fmtNum(best.efficiency_tl_per_m3,2)}</b></div>`+
        `<div class="small muted" style="margin-top:4px;">Tekrar içi plan farkı: ${fmtNum(pd.mean,1)}%${secondaryMeta}</div>`+
        divBlock+
        riskBlock+
        warn+
      '</div>';
    }
    pHtml += '</div>';

    const anyBest = rows.find(a=> !!algos[a]?.best?.parcels);
    if(anyBest){
      const maps = {};
      let ids = [];
      for(const a of rows){
        const ps = algos[a]?.best?.parcels || [];
        const m = {}; ps.forEach(p=>{ m[p.id] = p; ids.push(p.id); });
        maps[a] = m;
      }
      ids = Array.from(new Set(ids)).sort(naturalParcelIdCompare);
      const differingIds = ids.filter(id=>{
        const plans = rows.map(a=> benchmarkPlanPair(maps[a]?.[id]));
        return new Set(plans).size > 1;
      });
      const shownIds = differingIds.length ? differingIds : ids.slice(0, 15);
      pHtml += `<div class="small muted" style="margin:10px 0 6px;">Parsel bazında farklılaşan desen sayısı: <b>${differingIds.length}</b> / ${ids.length}. Tabloda ${differingIds.length ? 'yalnız farklılaşan' : 'ilk 15'} parseller gösterilir. Geniş ekranda ilk sütun sabit kalır.</div>`;
      pHtml += '<div class="benchmark-table-wrap" style="margin-top:12px;">';
      pHtml += '<table class="mini-table pro" style="width:100%;border-collapse:collapse;">';
      pHtml += '<thead><tr><th>Parsel</th>'+rows.map(a=>`<th>${escapeHtml(a)}${isDoubleBenchmark ? ' (1. / 2.)' : ' (ürün)'}</th>`).join('')+'</tr></thead><tbody>';
      for(const id of shownIds){
        pHtml += `<tr><td><b>${escapeHtml(id)}</b></td>`;
        for(const a of rows){
          const p = maps[a]?.[id];
          const c1 = prettyCropName(p?.primary?.crop || '-');
          const c2raw = String(p?.secondary?.crop || '').trim();
          const c2 = c2raw ? prettyCropName(c2raw) : 'uygulanabilir ikinci ürün yok';
          pHtml += isDoubleBenchmark
            ? `<td>${escapeHtml(String(c1))}<span class="muted"> / </span>${escapeHtml(String(c2))}</td>`
            : `<td>${escapeHtml(String(c1))}</td>`;
        }
        pHtml += '</tr>';
      }
      pHtml += '</tbody></table></div>';
    }

    pHtml += '</div>';
    patBox.innerHTML = pHtml;
  }

  if(updateCharts){
    let labels = rows.slice();
    const baseIncluded = !!(j.baseline && (j.baseline.status === 'OK' || typeof j.baseline.total_profit_tl !== 'undefined'));
    if(baseIncluded) labels = ['Mevcut'].concat(labels);

    const pushBase = (arr, baseVal)=> baseIncluded ? [+(baseVal||0)].concat(arr) : arr;
    const minProfit = pushBase(rows.map(a=> +(algos[a]?.profit?.min || 0)), j.baseline?.total_profit_tl || 0);
    const meanProfit = pushBase(rows.map(a=> +(algos[a]?.profit?.mean || 0)), j.baseline?.total_profit_tl || 0);
    const maxProfit = pushBase(rows.map(a=> +(algos[a]?.profit?.max || 0)), j.baseline?.total_profit_tl || 0);
    const minWater  = pushBase(rows.map(a=> +(algos[a]?.water?.min || 0)), j.baseline?.total_water_m3 || 0);
    const meanWater = pushBase(rows.map(a=> +(algos[a]?.water?.mean || 0)), j.baseline?.total_water_m3 || 0);
    const maxWater  = pushBase(rows.map(a=> +(algos[a]?.water?.max || 0)), j.baseline?.total_water_m3 || 0);
    const runtime   = pushBase(rows.map(a=> +(algos[a]?.runtime_s?.mean || 0)), 0);
    const diversity = pushBase(rows.map(a=> +(algos[a]?.unique_patterns || 0)), 0);

    if(benchmarkProfitChart){
      benchmarkProfitChart.data.labels = labels;
      benchmarkProfitChart.data.datasets[0].data = minProfit;
      benchmarkProfitChart.data.datasets[1].data = meanProfit;
      benchmarkProfitChart.data.datasets[2].data = maxProfit;
      benchmarkProfitChart.update();
    }
    if(benchmarkWaterChart){
      benchmarkWaterChart.data.labels = labels;
      benchmarkWaterChart.data.datasets[0].data = minWater;
      benchmarkWaterChart.data.datasets[1].data = meanWater;
      benchmarkWaterChart.data.datasets[2].data = maxWater;
      benchmarkWaterChart.update();
    }
    updateBenchmarkDiagnosticChartsV96(j, rows, algos);
  }
  if(typeof window.__renderBenchmarkReport === 'function'){
    try{ window.__renderBenchmarkReport(j, box, patBox, updateCharts); }
    catch(e){ console.warn('[benchmark report]', e); }
  }
}

function renderBenchmarkResults(j){
  const box = document.getElementById('benchmarkResults');
  const patBox = document.getElementById('benchmarkPatterns');
  renderBenchmarkResultsTo(j, box, patBox, true);
}

function summarizeBenchmarkForSweepV95(j){
  const algos = j?.algorithms || {};
  const rows = Object.keys(algos);
  const out = {repeat:Number(j?.repeats||0), best:'-', avgCv:0, avgPlan:0, avgRuntime:0, feasible:0, note:''};
  if(!rows.length) return out;
  const objectiveRaw = String(j?.objective || j?.scenario || '').toLowerCase();
  const isWater = objectiveRaw.includes('water') || objectiveRaw.includes('su');
  const isProfit = objectiveRaw.includes('profit') || objectiveRaw.includes('kar');
  const rel = (m,s)=> (Math.abs(m) > 1e-9 ? Math.abs(s)/Math.abs(m) : 0);
  const scored = rows.map(a=>{
    const r = algos[a] || {};
    const pm = Number(r?.profit?.mean||0), ps = Number(r?.profit?.std||0);
    const wm = Number(r?.water?.mean||0), ws = Number(r?.water?.std||0);
    const em = Number(r?.efficiency?.mean||0), es = Number(r?.efficiency?.std||0);
    const cv = (rel(pm,ps)+rel(wm,ws)+rel(em,es))/3;
    const feasible = Number(r.feasible_rate||0);
    const runtime = Number(r?.runtime_s?.mean||0);
    const diversity = Number(r.unique_patterns||0);
    let core = em;
    if(isWater && !isProfit) core = (em * 1000) - (0.0002 * wm);
    else if(isProfit && !isWater) core = pm - (0.015 * wm);
    return {a, cv, feasible, runtime, diversity, score: core + feasible*0.25 + Math.min(0.05, diversity*0.01) - cv*0.4 - runtime*0.01};
  }).sort((x,y)=>y.score-x.score);
  const topScore = Number(scored[0]?.score || 0);
  const tied = scored.filter(x=> Math.abs(Number(x.score||0) - topScore) <= Math.max(1e-9, Math.abs(topScore) * 0.001));
  out.best = (tied.length > 1 ? tied.slice().sort((x,y)=>Number(x.runtime||0)-Number(y.runtime||0))[0]?.a : scored[0]?.a) || rows[0];
  out.avgCv = scored.reduce((s,x)=>s+x.cv,0)/Math.max(1,scored.length);
  out.avgRuntime = scored.reduce((s,x)=>s+x.runtime,0)/Math.max(1,scored.length);
  out.feasible = scored.reduce((s,x)=>s+x.feasible,0)/Math.max(1,scored.length);
  out.avgPlan = rows.reduce((s,a)=>s+Number(algos[a]?.plan_distance_pct?.mean||0),0)/Math.max(1,rows.length);
  const allSame = out.avgPlan < 0.5 && rows.every(a=>Number(algos[a]?.unique_patterns||0) <= 1);
  out.note = allSame
    ? 'Ayni optimuma yakinsiyor; veri/kisit havuzu dar oldugu icin ayni desen beklenebilir.'
    : (out.avgCv < 0.03 && out.avgPlan < 5 ? 'Stabil; tekrar artışı sonucu az değiştiriyor.' : (out.avgCv < 0.08 ? 'Kabul edilebilir; tez tablosunda raporlanabilir.' : 'Oynaklık yüksek; 100 tekrar veya veri/kısıt kontrolü önerilir.'));
  return out;
}

function renderBenchmarkSweepResultsV95(items){
  const box = document.getElementById('benchmarkSweepResults');
  if(!box) return;
  const rows = (items||[]).map(x=> x.summary).filter(Boolean);
  if(!rows.length){ box.innerHTML = ''; return; }
  const recommended = rows.find(r=> r.repeat >= 50 && r.avgCv < 0.08) || rows[rows.length-1];
  const detailRows = [];
  (items||[]).forEach(item=>{
    const repeat = Number(item?.repeat || item?.summary?.repeat || 0);
    const algos = item?.raw?.algorithms || {};
    Object.keys(algos).forEach(a=>{
      const r = algos[a] || {};
      detailRows.push({
        repeat,
        algo:a,
        profit:Number(r?.profit?.mean||0),
        water:Number(r?.water?.mean||0),
        eff:Number(r?.efficiency?.mean||0),
        cv:Number(r?.profit?.cv||0),
        plan:Number(r?.plan_distance_pct?.mean||0),
        feasible:Number(r?.feasible_rate||0),
        runtime:Number(r?.runtime_s?.mean||0),
        patterns:Number(r?.unique_patterns||0),
      });
    });
  });
  box.innerHTML = `<div class="benchmark-sweep-v95">
    <div class="matrix-title">Tekrar sayısı stabilite taraması (30/50/100)</div>
    <table><thead><tr><th>Tekrar</th><th>Önerilen algoritma</th><th>Ortalama CV</th><th>Plan farkı</th><th>Uygulanabilirlik</th><th>Ortalama süre</th><th>Akademik yorum</th></tr></thead><tbody>
      ${rows.map(r=>`<tr><td><b>${r.repeat}</b></td><td>${escapeHtml(r.best)}</td><td>${(r.avgCv*100).toFixed(2)}%</td><td>${r.avgPlan.toFixed(1)}%</td><td>${(r.feasible*100).toFixed(1)}%</td><td>${r.avgRuntime.toFixed(2)} sn</td><td>${escapeHtml(r.note)}</td></tr>`).join('')}
    </tbody></table>
    <p><b>Grafik okuma notu:</b> 30/50/100 grafiklerinde kâr, su uygunluğu, TL/m³ ve süre her tekrar içinde 0-100 normalize skor olarak çizilir. Bu nedenle farklı tekrar kapsamlarının ham büyüklükleri grafiği bozmaz; ham değerler aşağıdaki akademik tabloda okunur.</p>
    <div class="benchmark-detail-table-v97">
      <div class="matrix-title">Algoritma x tekrar ayrintili istatistik</div>
      <table><thead><tr><th>Tekrar</th><th>Algoritma</th><th>Kâr ort</th><th>Su ort</th><th>TL/m³</th><th>Kâr CV</th><th>Plan farkı</th><th>Uygulanabilir</th><th>Süre</th><th>Desen</th></tr></thead><tbody>
        ${detailRows.map(r=>`<tr><td>${r.repeat}</td><td><b>${escapeHtml(r.algo)}</b></td><td>${fmtNum(r.profit,0)}</td><td>${fmtNum(r.water,0)}</td><td>${fmtNum(r.eff,2)}</td><td>${(r.cv*100).toFixed(2)}%</td><td>${fmtNum(r.plan,1)}%</td><td>${(r.feasible*100).toFixed(1)}%</td><td>${fmtNum(r.runtime,2)} sn</td><td>${fmtNum(r.patterns,0)}</td></tr>`).join('')}
      </tbody></table>
    </div>
    <p><b>Seçilen tekrar politikası:</b> ${recommended.repeat} tekrar. CV, plan farkı ve uygulanabilirlik birlikte okunur; düşük CV + düşük plan farkı overfitting değil, kısıtlar altında kararlı yakınsama olarak yorumlanır.</p>
  </div>`;
}

async function runBenchmarkSweepV95(objective, seasonSource){
  const repeatsEl = document.getElementById('benchmarkRepeats');
  const oldVal = repeatsEl ? repeatsEl.value : '50';
  const counts = [30,50,100];
  const results = [];
  try{
    for(const count of counts){
      if(repeatsEl) repeatsEl.value = String(count);
      const j = await fetchBenchmarkPython(objective, seasonSource);
      if(benchmarkResultLooksBroken(j)) throw new Error(`${count} tekrar benchmark ciktisi bos veya hatali`);
      results.push({repeat:count, raw:j, summary:summarizeBenchmarkForSweepV95(j)});
      renderBenchmarkSweepResultsV95(results);
      updateBenchmarkSweepChartsV96(results);
    }
  }finally{
    if(repeatsEl) repeatsEl.value = oldVal;
  }
  return results;
}


// --- PYTHON BACKEND (Flask) ENTEGRASYONU ---
// Optimizasyon isteklerini /api/optimize üzerinden Python'a gönderebilir.
// Bu sayede: (1) algoritmalar gerçekten Python'da çalışır, (2) XLSX/JSON tüm desen verileri backend'de kullanılır.
function backendRecommendationRow(r, parcelRef){
  const area = safeNum(r?.area_da ?? r?.plannedAreaDa ?? r?.area, safeNum(parcelRef?.area_da, 0));
  const totalWater = safeNum(r?.totalWater ?? r?.waterTotal ?? r?.water_m3, 0);
  const totalProfit = safeNum(r?.totalProfit ?? r?.profitTotal ?? r?.profit_tl, 0);
  const waterPerDa = safeNum(r?.waterPerDa ?? r?.water_m3_da, area > 0 ? totalWater / area : 0);
  const profitPerDa = safeNum(r?.profitPerDa ?? r?.profit_tl_da, area > 0 ? totalProfit / area : 0);
  const name = prettyCropName(r?.cropName || r?.name || r?.crop || parcelRef?.current_crop || '-');
  const currentKey = r?.irrigationCurrentKey || r?.irrigationCurrent || irrigationKeysForCrop(name).currentKey;
  const suggestedKey = r?.irrigationSuggestedKey || r?.irrigationRecommended || irrigationKeysForCrop(name).suggestedKey || currentKey;
  return {
    ...r,
    name,
    area,
    waterPerDa,
    profitPerDa,
    totalWater: totalWater || area * waterPerDa,
    totalProfit: totalProfit || area * profitPerDa,
    season: r?.season || inferSeasonLabelFromCrop(name, parcelRef?.parcel_type || ''),
    irrigationCurrentKey: currentKey,
    irrigationCurrentText: r?.irrigationCurrentText || r?.irrigationCurrent || irrigationLabel(currentKey),
    irrigationSuggestedKey: suggestedKey,
    irrigationSuggestedText: r?.irrigationSuggestedText || r?.irrigationSuggested || irrigationLabel(suggestedKey),
    irrigationSuggested: r?.irrigationSuggested || r?.irrigationSuggestedText || irrigationLabel(suggestedKey),
    rankReason: r?.rankReason || r?.decisionNote || r?.reason || '',
    decisionNote: r?.decisionNote || r?.rankReason || r?.reason || '',
    cropCategory: r?.cropCategory || annualCropCategoryFromName(name),
    cropCategoryLabel: r?.cropCategoryLabel || cropCategoryLabel(r?.cropCategory || annualCropCategoryFromName(name)),
    cropCategoryMode: r?.cropCategoryMode || currentCropCategoryMode(),
    categoryFitScore: safeNum(r?.categoryFitScore, 0),
    reasonDetails: Array.isArray(r?.reasonDetails) ? r.reasonDetails : [],
    cautionDetails: Array.isArray(r?.cautionDetails) ? r.cautionDetails : [],
  };
}

function backendRecommendationPattern(item, parcelRef, currentTotals, rank=1, selected=false){
  const row = backendRecommendationRow(item, parcelRef);
  const totalWater = safeNum(row.totalWater, 0);
  const totalProfit = safeNum(row.totalProfit, 0);
  const mainCrop = prettyCropName(row.name || '-');
  return {
    rank,
    targetOrder: rank,
    selectedRecommendation: !!selected,
    backendOnly: true,
    patternName: mainCrop,
    mainCrop,
    secondaryCrop: '-',
    totalWater,
    totalProfit,
    tlPerM3: safeNum(row.tlPerM3 ?? (totalProfit / Math.max(1, totalWater)), 0),
    deltaWater: totalWater - safeNum(currentTotals?.water, 0),
    deltaProfit: totalProfit - safeNum(currentTotals?.profit, 0),
    quotaExceeded: !!row.quotaAdjusted || (safeNum(row.parcelQuotaM3, 0) > 0 && totalWater > safeNum(row.parcelQuotaM3, 0)),
    areaSplit: row.is_current_reference ? 'Mevcut desen korunuyor' : 'Backend öneri motoru çıktısı',
    irrigation: row.irrigationSuggested || row.irrigationSuggestedText || '-',
    productionWindow: row.season || 'Takvim kontrolü',
    peakMonth: 'Pik ay kontrolü',
    suitability: row.compatibilityRule || row.cropCategoryLabel || 'Uygunluk kontrolü',
    note: row.rankReason || row.decisionNote || '',
    components: [{
      role: selected ? 'Ana öneri' : 'Alternatif',
      crop: mainCrop,
      share: 1,
      area: safeNum(row.area, safeNum(parcelRef?.area_da, 0)),
      water: totalWater,
      profit: totalProfit,
      irrigation: row.irrigationSuggested || row.irrigationSuggestedText || '',
    }],
    source: item,
  };
}

function normalizeBackendRecommendationPayload(parcelResult, parcelRef, currentTotals){
  const result = parcelResult || {};
  const primaryRaw = result.primaryRecommendation || (Array.isArray(result.recommended) ? result.recommended[0] : null);
  const primaryRows = primaryRaw ? [backendRecommendationRow(primaryRaw, parcelRef)] : [];
  const alternatives = Array.isArray(result.alternativeRecommendations)
    ? result.alternativeRecommendations.map((x, idx)=>backendRecommendationPattern(x, parcelRef, currentTotals, idx + 2, false))
    : [];
  const interrowAlternatives = Array.isArray(result.interrowOrExpertAlternatives) ? result.interrowOrExpertAlternatives.slice() : [];
  const warnings = Array.isArray(result.conversionWarnings) ? result.conversionWarnings.slice() : [];
  return {
    primaryRows,
    alternatives,
    interrowAlternatives,
    warnings,
    alternativePatterns: alternatives,
    reason: primaryRows[0]?.rankReason || primaryRows[0]?.decisionNote || warnings[0] || '',
    backendResult: result,
  };
}

function diversityPercentText(v){
  return `${fmtNum(Math.max(0, safeNum(v, 0)) * 100, 1)}%`;
}

const INFEASIBLE_PLAN_WARNING_TEXT = 'Bu seçenek su/uygunluk kısıtları altında uygulanabilir değildir.';
const DIVERSITY_FEASIBLE_WARNING_TEXT = 'Bu seçenek su/uygunluk açısından uygulanabilir görünmektedir; ancak ürün yoğunlaşması nedeniyle dikkatli değerlendirilmelidir.';

function isInfeasiblePlanWarningText(text){
  const s = String(text || '').toLowerCase();
  return s.includes('su/uygunluk') && s.includes('uygulanabilir değildir');
}

function diversityStatusLabel(status){
  const s = String(status || '').toLowerCase();
  if(s === 'recommended') return 'Önerilebilir';
  if(s === 'recommended_with_diversity_warning') return 'Çeşitlilik uyarılı';
  if(s === 'not_recommended_due_to_diversity') return 'Çeşitlilik nedeniyle tartışmalı';
  if(s === 'not_feasible') return 'Uygulanabilir değil';
  return status || '-';
}

function diversityWarningHtml(diversity, status, repairApplied=false, feasibility={}){
  if(!diversity || typeof diversity !== 'object') return '';
  const statusKey = String(status || '').toLowerCase();
  const explicitFeasible = feasibility && Object.prototype.hasOwnProperty.call(feasibility, 'feasible') ? feasibility.feasible : undefined;
  const explicitSelectable = feasibility && Object.prototype.hasOwnProperty.call(feasibility, 'selectable') ? feasibility.selectable : undefined;
  const diversityOnlyStatus = statusKey === 'recommended_with_diversity_warning' || statusKey === 'not_recommended_due_to_diversity';
  const actualInfeasible = explicitFeasible === false || (explicitSelectable === false && !diversityOnlyStatus) || (
    statusKey === 'not_feasible' && explicitFeasible !== true && explicitSelectable !== true
  );
  const topShare = safeNum(diversity.top_crop_share, 0);
  const topLimit = safeNum(diversity.max_crop_share_limit, 0.25);
  const top3Share = safeNum(diversity.top3_crop_share, 0);
  const top3Limit = safeNum(diversity.max_top3_share_limit, 0.65);
  const diversityIssue = diversity.diversity_feasible === false
    || statusKey === 'recommended_with_diversity_warning'
    || statusKey === 'not_recommended_due_to_diversity'
    || topShare > topLimit
    || top3Share > top3Limit;
  const items = [];
  if(actualInfeasible){
    items.push(INFEASIBLE_PLAN_WARNING_TEXT);
  }else if(diversityIssue){
    if(statusKey === 'not_recommended_due_to_diversity'){
      items.push('Bu seçenek su/uygunluk açısından uygulanabilir olabilir; ancak ürün yoğunlaşması nedeniyle tartışmalı alternatif olarak değerlendirilmelidir.');
    }else{
      items.push(DIVERSITY_FEASIBLE_WARNING_TEXT);
    }
  }
  if(topShare > topLimit){
    items.push(`Ürün yoğunlaşması uyarısı: ${prettyCropName(diversity.top_crop || '-')}, değişen öneri alanının ${diversityPercentText(topShare)}’ını kaplamaktadır. Bu değer ${diversityPercentText(topLimit)} sınırını aşmaktadır.`);
    const totalShare = safeNum(diversity.top_crop_share_total, NaN);
    const changedArea = safeNum(diversity.changed_area_da, 0);
    const totalArea = safeNum(diversity.total_plan_area_da, 0);
    if(Number.isFinite(totalShare) && totalShare > 0 && totalArea > changedArea + 1e-6){
      items.push(`Öneri planı içinde hesaplanan alan üzerinden payı yaklaşık ${diversityPercentText(totalShare)}’dır.`);
    }
  }
  if(top3Share > top3Limit){
    items.push(`İlk 3 ürün, değişen öneri alanının ${diversityPercentText(top3Share)}’ını kaplamaktadır. Ürün deseninde çeşitlilik sınırlı olabilir.`);
    const top3TotalShare = safeNum(diversity.top3_crop_share_total, NaN);
    const changedArea = safeNum(diversity.changed_area_da, 0);
    const totalArea = safeNum(diversity.total_plan_area_da, 0);
    if(Number.isFinite(top3TotalShare) && top3TotalShare > 0 && totalArea > changedArea + 1e-6){
      items.push(`Öneri planı içinde hesaplanan alan üzerinden ilk 3 ürün payı yaklaşık ${diversityPercentText(top3TotalShare)}’dır.`);
    }
  }
  if(repairApplied){
    items.push('Ürün çeşitliliği kısıtı nedeniyle plan yeniden dengelenmiştir. Amaç, tek ürüne aşırı yığılmayı azaltarak daha uygulanabilir bir ürün deseni üretmektir.');
  }
  if(!items.length && Array.isArray(diversity.warnings) && diversity.warnings.length){
    items.push(...diversity.warnings.slice(0, 2).filter(x=>!isInfeasiblePlanWarningText(x)));
  }
  if(!items.length) return '';
  return `<div class="small" style="margin-top:8px; padding:8px 10px; border:1px solid #fde68a; border-radius:10px; background:#fffbeb;"><strong>Ürün çeşitliliği kontrolü:</strong><ul style="margin:6px 0 0 18px; padding:0;">${items.map(x=>`<li>${escapeHtml(String(x))}</li>`).join('')}</ul></div>`;
}

function agronomicRiskHtml(risk){
  if(!risk || typeof risk !== 'object') return '';
  const levelText = level => {
    const s = String(level || '').toLowerCase();
    if(s === 'high') return 'Yüksek';
    if(s === 'medium') return 'Orta';
    if(s === 'low') return 'Düşük';
    return 'Veri sınırlı';
  };
  const dataNote = part => String(part?.data_status || '').toLowerCase() === 'limited' ? ' (veri sınırlı)' : '';
  const market = risk.market_saturation_risk || {};
  const rotation = risk.rotation_risk || {};
  const labor = risk.labor_harvest_risk || {};
  const storage = risk.storage_marketing_risk || {};
  const transition = risk.transition_risk || {};
  const rows = [
    ['Pazar/fiyat baskısı riski', levelText(market.level), market.message],
    ['Münavebe/hastalık-zararlı riski', levelText(rotation.level) + dataNote(rotation), rotation.message],
    ['Hasat/işçilik yoğunluğu riski', levelText(labor.level) + dataNote(labor), labor.message],
    ['Depolama/pazarlama hassasiyeti', levelText(storage.level) + dataNote(storage), storage.message],
    ['Çiftçi geçiş/adaptasyon riski', levelText(transition.level) + dataNote(transition), transition.message],
  ].filter(r => r[2] || r[1]);
  const notes = Array.isArray(risk.notes) ? risk.notes.slice(0, 2) : [];
  if(!rows.length && !notes.length) return '';
  return `<div class="small" style="margin-top:8px; padding:8px 10px; border:1px solid #bfdbfe; border-radius:10px; background:#eff6ff;"><strong>Tarımsal uygulanabilirlik ve risk notu:</strong><div style="margin-top:4px;">Genel risk düzeyi: <b>${escapeHtml(levelText(risk.overall_level))}</b></div><ul style="margin:6px 0 0 18px; padding:0;">${rows.map(r=>`<li><b>${escapeHtml(r[0])}:</b> ${escapeHtml(r[1])}${r[2] ? ` - ${escapeHtml(String(r[2]))}` : ''}</li>`).join('')}${notes.map(x=>`<li>${escapeHtml(String(x))}</li>`).join('')}</ul></div>`;
}

function benchmarkDynamicInterpretation(bestAlgo, algos, rows){
  const best = algos?.[bestAlgo];
  if(!best || !rows?.length) return '';
  const p = safeNum(best?.profit?.mean ?? best.mean_profit, 0);
  const w = safeNum(best?.water?.mean ?? best.mean_water, 0);
  const e = safeNum(best?.efficiency?.mean ?? best.tl_per_m3, 0);
  const cv = safeNum(best?.profit?.cv ?? best.cv, 0);
  const feas = Math.max(0, Math.min(1, safeNum(best?.feasible_rate, 0)));
  const parts = [
    `${bestAlgo}, seçili koşullarda ${fmtNum(p,0)} TL ortalama kâr, ${fmtNum(w,0)} m³ ortalama su, ${fmtNum(e,2)} TL/m³, ${fmtNum(cv*100,2)}% CV ve ${fmtNum(feas*100,1)}% uygulanabilirlik dengesiyle öne çıkmıştır.`
  ];
  const ga = algos?.GA;
  if(ga && bestAlgo !== 'GA'){
    const gp = safeNum(ga?.profit?.mean ?? ga.mean_profit, 0);
    const gw = safeNum(ga?.water?.mean ?? ga.mean_water, 0);
    if(gp > p * 1.002){
      parts.push(`GA kâr bakımından güçlü bir alternatif üretmektedir; ancak su tüketimi/kararlılık dengesi ve karar skoru açısından ${bestAlgo} gerisinde kalmıştır.`);
    }else{
      parts.push(`GA benzer bir alternatif üretse de seçili metrik dengesi ${bestAlgo} lehinedir.`);
    }
    if(gw > w * 1.002){
      parts.push(`GA'nın ortalama su tüketimi ${bestAlgo} değerinden yüksektir.`);
    }
  }
  const abc = algos?.ABC;
  if(abc && bestAlgo !== 'ABC'){
    const div = abc?.diversity || {};
    const abcCv = safeNum(abc?.profit?.cv ?? abc.cv, 0);
    const concentration = div.diversity_feasible === false ? 'ürün yoğunlaşması' : 'desen değişkenliği';
    parts.push(`ABC bazı koşullarda farklı desen üretebilse de ${concentration} ve ${fmtNum(abcCv*100,2)}% CV değeri nedeniyle dikkatli yorumlanmalıdır.`);
  }
  if(bestAlgo === 'ACO' && ga){
    parts.unshift('ACO, net kâr bakımından güçlü alternatiflere yakın kalırken daha dengeli su kullanımı, TL/m³, düşük değişkenlik ve uygulanabilirlik bileşimiyle seçilmiştir.');
  }
  return parts.join(' ');
}

function backendUnavailablePlan(idsForRun, scenarioKey, algoKey, message){
  const key = basinCacheKey(scenarioKey, algoKey);
  const wanted = new Set((idsForRun || []).map(x => String(x || '').trim()).filter(Boolean));
  const targetParcels = (parcelData || []).filter(p => !wanted.size || wanted.has(String(p?.id || '').trim()));
  const plan = {};
  for(const p of targetParcels){
    plan[p.id] = {
      rows: [],
      totals: { water:0, profit:0, eff:0 },
      backendUnavailable: true,
      backendOnly: true,
      decisionReason: message || 'Backend optimizasyon sonucu alınamadı; tarayıcı içi karar üretilmedi.',
      alternativePatterns: [],
      interrowAlternatives: [],
      conversionWarnings: [message || 'Backend optimizasyon sonucu alınamadı; tarayıcı içi karar üretilmedi.']
    };
  }
  const out = {
    plan,
    budget: 0,
    totals: { water:0, profit:0, eff:0 },
    iterations: 0,
    feasible: false,
    backendUnavailable: true,
    backendOnly: true,
    diagnostics: { warnings:[message || 'Backend optimizasyon sonucu alınamadı; tarayıcı içi karar üretilmedi.'] }
  };
  basinPlanCache[key] = out;
  return out;
}

function backendStandardCropToUiRow(crop, parcelRef){
  const area = safeNum(crop?.area_da ?? crop?.area, safeNum(parcelRef?.area_da, 0));
  const totalWater = safeNum(crop?.water_m3 ?? crop?.totalWater ?? crop?.waterTotal, 0);
  const totalProfit = safeNum(crop?.profit_tl ?? crop?.totalProfit ?? crop?.profitTotal, 0);
  const waterPerDa = area > 0 ? totalWater / area : safeNum(crop?.waterPerDa ?? crop?.water_m3_da, 0);
  const profitPerDa = area > 0 ? totalProfit / area : safeNum(crop?.profitPerDa ?? crop?.profit_tl_da, 0);
  const name = prettyCropName(crop?.crop_name || crop?.name || crop?.crop || '-');
  const currentKey = crop?.irrigationCurrentKey || crop?.irrigationCurrent || irrigationKeysForCrop(name).currentKey;
  const suggestedKey = crop?.irrigation_method || crop?.irrigationSuggestedKey || crop?.irrigationRecommended || irrigationKeysForCrop(name).suggestedKey || currentKey;
  return {
    ...crop,
    name,
    area,
    season: crop?.season || crop?.period_note || inferSeasonLabelFromCrop(name, parcelRef?.parcel_type || ''),
    irrigationCurrentKey: currentKey,
    irrigationCurrentText: crop?.irrigationCurrentText || irrigationLabel(currentKey),
    irrigationSuggestedKey: suggestedKey,
    irrigationSuggestedText: crop?.irrigationSuggestedText || irrigationLabel(suggestedKey),
    irrigationSuggested: crop?.irrigationSuggested || irrigationLabel(suggestedKey),
    waterPerDa,
    profitPerDa,
    totalWater,
    totalProfit,
    tlPerM3: safeNum(crop?.tl_per_m3, totalProfit / Math.max(1, totalWater)),
    rankReason: crop?.explanation || crop?.reason || '',
    decisionNote: crop?.explanation || crop?.reason || '',
    backendOnly: true,
    feasible: crop?.feasible !== false,
    selectable: crop?.selectable !== false
  };
}

function backendChartLabelTr(label){
  const key = String(label || '').trim().toLowerCase();
  const map = {
    water_saving: 'Su tasarrufu',
    max_profit: 'Kâr odaklı',
    balanced: 'Su-kâr dengesi',
    water_efficiency: 'Su-kâr dengesi',
    current: 'Mevcut',
    mevcut: 'Mevcut'
  };
  return map[key] || String(label || '');
}

function backendStandardPlanToPattern(plan, parcelRef, baselineTotals, rank=1, selected=false){
  const crops = Array.isArray(plan?.crops) ? plan.crops : [];
  const rows = crops.map(c=>backendStandardCropToUiRow(c, parcelRef));
  const totalWater = safeNum(plan?.total_water_m3, rows.reduce((a,r)=>a+safeNum(r.totalWater,0),0));
  const totalProfit = safeNum(plan?.total_profit_tl, rows.reduce((a,r)=>a+safeNum(r.totalProfit,0),0));
  const components = rows.map((r, idx)=>({
    role: idx === 0 ? 'Ana ürün' : 'İkinci ürün / desen',
    crop: r.name,
    share: safeNum(r.area_share_pct, 0) > 0 ? safeNum(r.area_share_pct,0) / 100 : 1,
    area: safeNum(r.area, 0),
    water: safeNum(r.totalWater, 0),
    profit: safeNum(r.totalProfit, 0),
    irrigation: r.irrigationSuggested || ''
  }));
  return {
    rank,
    targetOrder: rank,
    selectedRecommendation: !!selected,
    backendOnly: true,
    patternName: rows.map(r=>r.name).filter(Boolean).join(' + ') || plan?.plan_id || 'Backend plan',
    mainCrop: rows[0]?.name || '-',
    secondaryCrop: rows[1]?.name || '-',
    totalWater,
    totalProfit,
    tlPerM3: safeNum(plan?.tl_per_m3, totalProfit / Math.max(1, totalWater)),
    deltaWater: safeNum(plan?.delta_water_m3, totalWater - safeNum(baselineTotals?.water, 0)),
    deltaProfit: safeNum(plan?.delta_profit_tl, totalProfit - safeNum(baselineTotals?.profit, 0)),
    quotaExceeded: plan?.feasible === false,
    selectable: plan?.selectable !== false && plan?.feasible !== false,
    areaSplit: plan?.pattern_type || 'Backend karar paketi',
    productionWindow: rows.map(r=>r.season).filter(Boolean).join(' / '),
    suitability: (plan?.feasibility_reasons || []).join(' • ') || 'Backend uygunluk kontrolü',
    note: plan?.explanation || (plan?.warnings || []).join(' '),
    components,
    source: plan
  };
}

function backendStandardPayloadToBasinPlan(data, scenarioKey, algoKey){
  const key = basinCacheKey(scenarioKey, algoKey);
  const selectedPlan = data?.selected_plan || {};
  const context = data?.context || {};
  const baseline = data?.baseline || {};
  const alternatives = Array.isArray(data?.alternatives) ? data.alternatives : [];
  const plan = {};
  const crops = Array.isArray(selectedPlan.crops) ? selectedPlan.crops : [];
  const byParcel = new Map();
  const noFeasibleTwoCrop = context?.scenario_type === 'double' && (
    selectedPlan?.status === 'no_feasible_two_crop_plan' || selectedPlan?.feasible === false
  );
  crops.forEach(c=>{
    const pid = String(c?.parcel_id || context?.parcel_id || selectedParcelId || '').trim();
    if(!pid) return;
    if(!byParcel.has(pid)) byParcel.set(pid, []);
    byParcel.get(pid).push(c);
  });
  byParcel.forEach((rowsRaw, pid)=>{
    const parcelRef = (parcelData || []).find(p=>String(p.id)===String(pid)) || null;
    const rows = rowsRaw.map(c=>backendStandardCropToUiRow(c, parcelRef));
    const totals = sumMetrics(rows);
    const baseRow = Array.isArray(baseline.crop_pattern) ? baseline.crop_pattern.find(b=>String(b.parcel_id)===String(pid)) : null;
    const baselineTotals = { water: safeNum(baseRow?.water_m3, safeNum(baseline.total_water_m3, 0)), profit: safeNum(baseRow?.profit_tl, safeNum(baseline.total_profit_tl, 0)) };
    const selectedPattern = backendStandardPlanToPattern(selectedPlan, parcelRef, baselineTotals, 1, true);
    const alternativePatterns = alternatives.map((a, idx)=>backendStandardPlanToPattern(a, parcelRef, baselineTotals, idx + 2, false));
    const shownAlternativePatterns = noFeasibleTwoCrop ? [selectedPattern].concat(alternativePatterns) : alternativePatterns;
    const visibleRows = noFeasibleTwoCrop ? [] : rows;
    const visibleTotals = noFeasibleTwoCrop ? {water:0, profit:0, eff:0} : totals;
    plan[pid] = {
      rows: visibleRows,
      totals: visibleTotals,
      backendOnly: true,
      backendResult: data,
      backendDecisionPackage: data,
      diversity: selectedPlan.diversity || data?.diversity || null,
      agronomicRisk: selectedPlan.agronomic_risk || data?.agronomic_risk || null,
      diversityRepairApplied: !!selectedPlan.diversity_repair_applied,
      recommendationStatus: selectedPlan.recommendation_status || data?.recommendation_status || '',
      irrigationPlan: rows.map(r=>r.irrigationSuggested || r.irrigationSuggestedText).filter(Boolean).join(' | '),
      decisionReason: selectedPlan.explanation || (selectedPlan.warnings || []).join(' '),
      alternativePatterns: shownAlternativePatterns,
      interrowAlternatives: [],
      conversionWarnings: Array.isArray(selectedPlan.warnings) ? selectedPlan.warnings : [],
      rankedCandidates: null,
      noFeasibleTwoCrop,
    };
  });
  const totalWater = safeNum(selectedPlan.total_water_m3, crops.reduce((a,c)=>a+safeNum(c?.water_m3,0),0));
  const totalProfit = safeNum(selectedPlan.total_profit_tl, crops.reduce((a,c)=>a+safeNum(c?.profit_tl,0),0));
  const out = {
    plan,
    budget: safeNum(context.water_budget_m3, data?.water_budget_m3 || 0),
    totals: { water: totalWater, profit: totalProfit, eff: totalProfit / Math.max(1, totalWater) },
    iterations: 0,
    feasible: selectedPlan.feasible !== false,
    backendOnly: true,
    server: true,
    context,
    baseline,
    selectedPlan,
    diversity: selectedPlan.diversity || data?.diversity || null,
    agronomicRisk: selectedPlan.agronomic_risk || data?.agronomic_risk || null,
    recommendationStatus: selectedPlan.recommendation_status || data?.recommendation_status || '',
    alternatives,
    optimizationRunPolicy: data?.optimization_run_policy || null,
    charts: data?.charts || {},
    tables: data?.tables || {},
    diagnostics: data?.diagnostics || {},
    pythonMeta: data?.meta || {}
  };
  basinPlanCache[key] = out;
  return out;
}

async function fetchAndCacheBasinPlanPython(scenarioKey, algoKey){
  // ✓ Bu çağrı bu fonksiyonun "tek" optimize isteği olsun

  // 1) En başta reqId al
  const reqId = ++lastOptimizeReqId;

  // 2) Önceki istekleri iptal ETME (stabilite için)
  //    Eski sürüm AbortController ile istekleri iptal ediyordu; bu Network'te (canceled) hatalarına yol açıyordu.
  //    Bu sürümde iptal yok; reqId kontrolü ile geç gelen sonuçlar yok sayılır.


  const key = basinCacheKey(scenarioKey, algoKey);
  const algoMap = { ga: 'GA', abc: 'ABC', aco: 'ACO' };
  const scenarioMap = {
    mevcut: 'current',
    current: 'current',
    su_tasarruf: 'water_saving',
    'su tasarruf': 'water_saving',
    water_saving: 'water_saving',
    maks_kar: 'max_profit',
    'maks kar': 'max_profit',
    max_profit: 'max_profit',
    su_etkin: 'water_efficiency',
    'su etkin': 'water_efficiency',
    water_efficiency: 'water_efficiency',
    onerilen: 'water_efficiency',
    recommended: 'water_efficiency',
    balanced: 'water_efficiency',
    denge: 'water_efficiency'
  };
  const selectedIdsForPayload = getSelectedParcelIdsForRun();
  const isFocusedRun = (selectedIdsForPayload || []).length <= 3;
  const runDepth = isFocusedRun
    ? { generations: 8, popSize: 12, iterations: 10, ants: 8, bees: 8, units: 10 }
    : { generations: 16, popSize: 22, iterations: 18, ants: 14, bees: 14, units: 14 };

  const payload = attachCustomParcelsToPayload({
    // v72: Run scope must match UI selection.
    // "__ALL__" -> basin totals, otherwise only the selected parcel.
    selectedParcelIds: selectedIdsForPayload,
    algorithm: algoMap[algoKey] || 'GA',
    scenario: scenarioMap[scenarioKey] || normalizeScenarioKey(scenarioKey) || 'water_efficiency',
    cropCategoryMode: currentCropCategoryMode(),
    waterBudgetRatio: budgetRatioForScenarioKey(scenarioKey),
    year: STATE.selectedWaterYear || null,
    options: {
      seasonSource: STATE.seasonSource || 's1',
      cropCategoryMode: currentCropCategoryMode(),
      allocationModel: STATE.waterAllocationModel || 'area_fair_per_da',
      scenarioType: (((STATE.seasonSource || 's1')==='s2') ? 'double' : 'single'),
      twoSeason: ((STATE.seasonSource || 's1')==='s2'),
      maxCrops: 8,
      generations: runDepth.generations,
      popSize: runDepth.popSize,
      iterations: runDepth.iterations,
      ants: runDepth.ants,
      bees: runDepth.bees,
      units: runDepth.units,
      // Deterministic seed helps reproducibility across runs.
      // Benchmark can override this.
      seed: 42,
      wWater: 1.0,
      wProfit: 1.0,
      wPattern: 0.4,
      simpleMode: false
    }
  });

  let res;
  try{
    res = await fetch("/api/optimize", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
});
  }catch(err){
    // abort ise sessiz çık
    if (err && err.name === "AbortError") return null;
    throw err;
  }

  // 3) HTTP hata kontrolü
  if(!res.ok){
    const t = await res.text().catch(()=> "");
    throw new Error("Python optimize failed: " + (t || ("HTTP " + res.status)));
  }

  // 4) JSON'u SADECE 1 KERE oku
  const data = await res.json();
  if(data && data.selected_plan && data.context){
    if (reqId !== lastOptimizeReqId) {
      console.warn("Eski optimize cevabı yok sayıldı (reqId mismatch)");
      return null;
    }
    if (data.status && data.status !== "OK") {
      alert("Optimizasyon reddedildi: " + (data.reason || data.message || "Backend sonucu OK değil"));
      return null;
    }
    return backendStandardPayloadToBasinPlan(data, scenarioKey, algoKey);
  }

  // --- Normalize backend payload shapes ---
  // Backend can return either:
  // (A) {status:"OK", parcels:[{id, result:{recommended:[...]}}], ...}
  // (B) {algorithm, objective, water_budget_m3, details:[{parcelId, chosenCrop, area_da, water_m3, profit_tl}], ...}
  // We convert (B) into (A)-like structure so the UI logic stays consistent.
  let norm = data;
  if(norm && Array.isArray(norm.details) && !Array.isArray(norm.parcels)){
    const parcelsOut = [];
    for(const d of norm.details){
      const area = +d.area_da || 0;
      const pid = (d.parcelId || d.parcel_id || d.id || "").toString();

      // Two-season payload: {primary:{crop,water_m3,profit_tl}, secondary:{...}}
      if(d.primary && d.secondary){
        const w1 = +d.primary.water_m3 || 0;
        const p1 = +d.primary.profit_tl || 0;
        const w2 = +d.secondary.water_m3 || 0;
        const p2 = +d.secondary.profit_tl || 0;

        parcelsOut.push({
          id: pid,
          result: {
            recommended: [
              {
                name: prettyCropName(d.primary.crop || "URUN"),
                area,
                waterPerDa: area>0 ? (w1/area) : 0,
                profitPerDa: area>0 ? (p1/area) : 0
              },
              {
                name: prettyCropName(d.secondary.crop || "URUN"),
                area,
                waterPerDa: area>0 ? (w2/area) : 0,
                profitPerDa: area>0 ? (p2/area) : 0
              }
            ]
          }
        });
        continue;
      }

      // Single-crop payload
      const water = +d.water_m3 || 0;
      const profit = +d.profit_tl || 0;
      const name = (d.chosenCrop || d.chosen_crop || d.crop || "URUN").toString();
      parcelsOut.push({
        id: pid,
        result: {
          recommended: [{
            name,
            area,
            waterPerDa: area>0 ? (water/area) : 0,
            profitPerDa: area>0 ? (profit/area) : 0
          }]
        }
      });
    }
    norm = {
      status: "OK",
      parcels: parcelsOut,
      droughtFactor: norm.get ? undefined : norm.droughtFactor,
      water_budget_m3: norm.water_budget_m3,
      total_water_m3: norm.total_water_m3,
      total_profit_tl: norm.total_profit_tl,
      algorithm: norm.algorithm,
      objective: norm.objective,
      year: norm.year,
      meta: norm.meta
    };
  }

  // 5) Eğer bu cevap eski isteğe aitse UI/cache güncelleme

  if (reqId !== lastOptimizeReqId) {
    console.warn("Eski optimize cevabı yok sayıldı (reqId mismatch)");
    return null;
  }

  // 6) Backend “OK değil” diyorsa cache’e yazma
  if (norm.status && norm.status !== "OK") {
    alert("Optimizasyon reddedildi: " + (norm.reason || "Bütçe aşıldı"));
    return null;
  }

  // 7) Python çıktısını UI’nin beklediği forma çevir
  const plan = {};
  let totalWater = 0;
  let totalProfit = 0;

  for(const pr of (norm.parcels||[])){
    const parcelRef = (parcelData || []).find(p=>String(p.id)===String(pr.id)) || null;
    const backend = normalizeBackendRecommendationPayload(pr.result || {}, parcelRef, null);
    let rows = backend.primaryRows;
    if(!rows.length){
      rows = [];
    }
    const totals = sumMetrics(rows);
    const backendWithTotals = normalizeBackendRecommendationPayload(pr.result || {}, parcelRef, totals);
    plan[pr.id] = {
      rows,
      totals,
      backendResult: pr.result || {},
      backendOnly: true,
      irrigationPlan: rows.map(r=>r.irrigationSuggested || r.irrigationSuggestedText).filter(Boolean).join(' | '),
      decisionReason: backendWithTotals.reason,
      alternativePatterns: backendWithTotals.alternativePatterns,
      interrowAlternatives: backendWithTotals.interrowAlternatives,
      conversionWarnings: backendWithTotals.warnings,
      rankedCandidates: null,
    };
    totalWater += totals.water;
    totalProfit += totals.profit;
  }

  // UI'da bütçe tek kaynak olsun: 2024/mevcut desen toplam su varlığı.
  // Backend bazı kapsamlı çağrılarda seçili parsel/kapsam bütçesi döndürebiliyor;
  // rozet ve uygunluk hesabında bunu "küresel bütçe" gibi göstermek hatalı olur.
  const budget = computeGlobalBudgetM3();

  const out = {
    plan,
    budget,
    totals: { water: totalWater, profit: totalProfit, eff: totalProfit/Math.max(1,totalWater) },
    iterations: 0,
    feasible: totalWater <= budget + 1e-6,
    pythonMeta: norm.dataUsed || norm.meta || {},
    deliveryReport: (norm && norm.meta && (norm.meta.delivery_report || norm.meta.deliveryReport)) ? (norm.meta.delivery_report || norm.meta.deliveryReport) : null,
    droughtFactor: norm.droughtFactor,
    projection2050vs2025: norm.projection2050vs2025
  };

  // 8) Cache’e yaz (sadece son reqId için)
  basinPlanCache[key] = out;

  return out;
}




// --- PYTHON BACKEND INTEGRATION ---
// When the Flask backend (app.py) is running, we can compute GA/ABC/ACO in Python and cache
// results into the existing basinPlanCache so the UI continues to work without rewriting.
async function fetchAndCacheBasinPlanFromServer(scenarioKey, algoKey){
  const key = basinCacheKey(scenarioKey, algoKey);
  const url = '/api/optimize';
  // Map UI keys to backend
  const algoMap = {ga:'GA', abc:'ABC', aco:'ACO'};
  const scenarioMap = {
    mevcut: 'current',
    current: 'current',
    su_tasarruf: 'water_saving',
    water_saving: 'water_saving',
    maks_kar: 'max_profit',
    max_profit: 'max_profit',
    su_etkin: 'water_efficiency',
    water_efficiency: 'water_efficiency',
    onerilen: 'water_efficiency',
    recommended: 'water_efficiency',
    balanced: 'water_efficiency',
    denge: 'water_efficiency'
  };
  const payload = attachCustomParcelsToPayload({
    selectedParcelIds: getSelectedParcelIdsForRun(),
    algorithm: algoMap[algoKey] || 'GA',
    scenario: scenarioMap[scenarioKey] || 'water_efficiency',
    cropCategoryMode: currentCropCategoryMode(),
    waterBudgetRatio: budgetRatioForScenarioKey(scenarioKey),
    options: {
      allocationModel: STATE.waterAllocationModel || 'area_fair_per_da',
      cropCategoryMode: currentCropCategoryMode(),
      maxCrops: 8,
      // weights can be tuned from UI later
      wWater: 1.0,
      wProfit: 1.0,
      wPattern: 0.4,
      simpleMode: false
    }
  });

  const res = await fetch(url, {
    method: 'POST',
    headers: {'Content-Type':'application/json'},
    body: JSON.stringify(payload)
  });
  if(!res.ok){
    throw new Error('Python optimize API failed: '+res.status);
  }
  const data = await res.json();
  if(data && data.selected_plan && data.context){
    return backendStandardPayloadToBasinPlan(data, scenarioKey, algoKey);
  }

  const plan = {};
  let totalWater = 0;
  let totalProfit = 0;

  // Normalize to expected shape
  const norm = data;
  for(const pr of (norm.parcels||[])){
    const rows = (pr.result?.recommended||[]).map(r=>({
      name: r.name,
      area: +r.area || +r.area_da || 0,
      waterPerDa: +r.waterPerDa || +r.water_m3_da || 0,
      profitPerDa: +r.profitPerDa || +r.profit_tl_da || 0,
      season: r.season || inferSeasonLabelFromCrop(r.name || '', pr.parcel_type || ''),
      decisionNote: r.decisionNote || '',
      rankReason: r.rankReason || r.decisionNote || '',
      cropCategory: r.cropCategory || annualCropCategoryFromName(r.name || ''),
      cropCategoryLabel: r.cropCategoryLabel || cropCategoryLabel(r.cropCategory || annualCropCategoryFromName(r.name || '')),
      cropCategoryMode: r.cropCategoryMode || currentCropCategoryMode(),
      categoryFitScore: safeNum(r.categoryFitScore, 0),
      reasonDetails: Array.isArray(r.reasonDetails) ? r.reasonDetails : [],
      cautionDetails: Array.isArray(r.cautionDetails) ? r.cautionDetails : [],
      compatibilityScore: safeNum(r.compatibilityScore, 0),
      totalWater: (+r.area || +r.area_da || 0) * (+r.waterPerDa || +r.water_m3_da || 0),
      totalProfit: (+r.area || +r.area_da || 0) * (+r.profitPerDa || +r.profit_tl_da || 0)
    }));
    const totals = sumMetrics(rows);
    plan[pr.id] = { rows: rows, totals: totals };
    totalWater += totals.water;
    totalProfit += totals.profit;
  }

  const out = {
    plan,
    budget: computeGlobalBudgetM3(),
    totals: { water: totalWater, profit: totalProfit, eff: totalProfit/Math.max(1,totalWater) },
    iterations: null,
    feasible: totalWater <= computeGlobalBudgetM3() + 1e-6,
    server: true,
    dataUsed: data.dataUsed
  };

  basinPlanCache[key] = out;
  return out;
}
// Global durum
let selectedParcelId = (parcelData && parcelData.length) ? parcelData[0].id : null;

// Kullanıcı tanımlı parseller (yükleme / çizim / seçili parsele ürün girme)
let customUserLayer = null;
let customDrawMode = false;
let customDrawPoints = [];
let customDrawMarkers = [];
let customDrawShape = null;
let customDrawHint = null;
let userParcelSeq = 1;

function nextUserParcelId(){
  while((parcelData||[]).some(p=>String(p.id) === `U${userParcelSeq}`)) userParcelSeq += 1;
  return `U${userParcelSeq++}`;
}

function irrigationLabelFromKey(key){
  const k = String(key||'').toLowerCase();
  if(k === 'drip') return 'Damla';
  if(k === 'sprinkler') return 'Yağmurlama';
  if(k === 'pivot') return 'Pivot / Lineer';
  if(k === 'rainfed') return 'Yağışa bağlı / Kuru';
  return 'Yüzey / Karık / Salma';
}

function cropMetaByName(name){
  const key = normCropName(name || '');
  const a = (STATE && STATE.cropCatalog && STATE.cropCatalog[key]) ? STATE.cropCatalog[key] : null;
  const b = (typeof cropCatalog !== 'undefined' && cropCatalog && cropCatalog[key]) ? cropCatalog[key] : null;
  return a || b || null;
}



function parcelTypeKeyLabel(key){
  const k = String(key||'').toLowerCase();
  if(k === 'orchard') return 'Meyve/Bağ';
  if(k === 'vegetable') return 'Sebze';
  return 'Tarla/Yem';
}

function inferParcelTypeKey(input){
  const raw = (typeof input === 'string') ? input : (input?.parcel_type || input?.land_type || input?.type || '');
  const key = String(raw || '').toLowerCase();
  if(key === 'orchard' || key === 'field' || key === 'vegetable') return key;
  const cropName = (typeof input === 'string')
    ? input
    : (input?.current_crop || input?.cropCurrent?.[0]?.name || input?.feature?.properties?.current_crop || input?.feature?.properties?.crop || '');
  const norm = normCropKey(cropName).replace(/\([^)]*\)/g, ' ');
  const orchardHints = ['ELMA','ARMUT','KIRAZ','VISNE','SEFTALI','NEKTAR','KAYISI','ERIK','CEVIZ','BAG','UZUM','BADEM','AYVA','DUT','ZERDALI','IGDE','CILEK'];
  const vegetableHints = ['DOMATES','BIBER','LAHANA','PATLICAN','ISPANAK','PIRASA','SOGAN','SARIMSAK','KABAK','KARPUZ','KAVUN','HIYAR','TURP','BAMYA','FASULYE_TAZE','BEZELYE'];
  if(orchardHints.some(k=>norm.includes(k))) return 'orchard';
  if(vegetableHints.some(k=>norm.includes(k))) return 'vegetable';
  return 'field';
}

function formatAreaDaText(areaDa){
  const v = Number(areaDa);
  if(!Number.isFinite(v) || v <= 0) return '-';
  return (Math.round(v * 10) / 10).toFixed(1);
}

function formatAreaM2TextFromDa(areaDa){
  const v = Number(areaDa);
  if(!Number.isFinite(v) || v <= 0) return '-';
  return Math.round(v * 1000).toLocaleString('tr-TR');
}

function formatAreaSummaryText(areaDa){
  const v = Number(areaDa);
  if(!Number.isFinite(v) || v <= 0) return '0.0 da';
  return `${formatAreaDaText(v)} da (${formatAreaM2TextFromDa(v)} m²)`;
}

function findCustomParcelById(pid){
  return (parcelData || []).find(p=>!!p?.frontend_custom && String(p.id) === String(pid)) || null;
}

function findCustomLayerById(pid){
  if(!customUserLayer || typeof customUserLayer.eachLayer !== 'function') return null;
  let target = null;
  customUserLayer.eachLayer(layer=>{
    if(target) return;
    const fid = layer?.feature?.properties?.id || layer?.feature?.properties?.name;
    if(String(fid) === String(pid)) target = layer;
  });
  return target;
}


function evaluateParcelDataConfidence(parcel){
  const p = parcel || {};
  const checks = [
    { key:'area', ok: safeNum(p.area_da, currentGeometryAreaDa(p)) > 0, label:'alan' },
    { key:'crop', ok: !!String(p.current_crop || (Array.isArray(p.cropCurrent) && p.cropCurrent[0] ? p.cropCurrent[0].name : '') || '').trim(), label:'ürün' },
    { key:'irrigation', ok: !!String(p.irrigation_key || '').trim(), label:'sulama' },
    { key:'village', ok: !!String(p.village || '').trim(), label:'köy/yer' },
    { key:'district', ok: !!String(p.district || '').trim(), label:'ilçe' },
    { key:'soil', ok: !!(p.soil && (String(p.soil.class || '').trim() || String(p.soil.texture || '').trim() || String(p.soil.erosion || '').trim())), label:'toprak' },
    { key:'official_link', ok: !!String(p.requested_for_parcel_id || '').trim() || !!p.frontend_override || !p.frontend_custom, label:'resmî kayıt bağı' },
    { key:'climate', ok: !!p.climate || !!STATE?.cropCatalog, label:'iklim / katalog eşleşmesi' },
  ];
  const okCount = checks.filter(c=>c.ok).length;
  let level = 'low';
  let label = 'Düşük';
  if(okCount >= 7){ level='high'; label='Yüksek'; }
  else if(okCount >= 5){ level='medium'; label='Orta'; }
  const missing = checks.filter(c=>!c.ok).map(c=>c.label);
  const note = level === 'high'
    ? 'Temel alan, ürün, sulama ve bağlamsal veriler mevcut. Yeni parsel için sonuçlar daha savunulabilir.'
    : (level === 'medium'
      ? 'Bazı kritik alanlar var; eksik başlıklar ilçe/katalog verileriyle tamamlanıyor.'
      : 'Birden fazla temel bilgi eksik. Sonuçlar yaklaşık / vekil veriyle üretilir; karar öncesi saha doğrulaması gerekir.');
  return { level, label, okCount, missing, note };
}

function parcelConfidenceBadgeHtml(parcel){
  const c = evaluateParcelDataConfidence(parcel);
  const tone = c.level === 'high' ? '#2b8a3e' : (c.level === 'medium' ? '#b08900' : '#c92a2a');
  return `<span class="pill-soft" style="border:1px solid ${tone};color:${tone};font-weight:700;">Veri güveni: ${escapeHtml(c.label)}</span>`;
}

function buildCustomParcelTooltipHtml(parcel){
  const typeKey = inferParcelTypeKey(parcel);
  const label = escapeHtml(String(parcel?.name || parcel?.id || 'Kullanıcı'));
  const approval = customParcelApprovalMeta(parcel);
  const conf = evaluateParcelDataConfidence(parcel);
  return `<span class="parcel-badge ${typeKey === 'orchard' ? 'orchard' : ''}"><span class="dot"></span><span>${label}</span><span class="hint">${escapeHtml(approval.label)} • Veri: ${escapeHtml(conf.label)}</span></span>`;
}

function ensureCustomLayerTooltip(layer, html){
  if(!layer) return;
  try{
    const hasTooltip = (typeof layer.getTooltip === 'function') && !!layer.getTooltip();
    if(hasTooltip && typeof layer.setTooltipContent === 'function') layer.setTooltipContent(html);
    else layer.bindTooltip(html, { permanent:true, direction:'center', className:'parcel-badge-wrap', opacity:1, sticky:false });
    try{ if(typeof layer.openTooltip === 'function') layer.openTooltip(); }catch(_e){}
  }catch(_e){}
}

function ensureCustomLayerPopup(layer, html){
  if(!layer) return;
  try{
    const hasPopup = (typeof layer.getPopup === 'function') && !!layer.getPopup();
    if(hasPopup && typeof layer.setPopupContent === 'function') layer.setPopupContent(html);
    else layer.bindPopup(html, {closeButton:false, autoClose:false, closeOnClick:false, autoPan:false, className:'parcel-popup'});
  }catch(_e){}
}

function buildCustomParcelPopupHtml(parcel){
  const p = parcel || {};
  const typeKey = inferParcelTypeKey(p);
  const tagText = parcelTypeKeyLabel(typeKey);
  const areaDa = safeNum(p.area_da, currentGeometryAreaDa(p));
  const areaTxt = formatAreaDaText(areaDa);
  const areaM2Txt = formatAreaM2TextFromDa(areaDa);
  const cropTxt = p.current_crop || (Array.isArray(p.cropCurrent) && p.cropCurrent[0] ? p.cropCurrent[0].name : '') || '-';
  const irrTxt = irrigationLabelFromKey(p.irrigation_key || (Array.isArray(p.cropCurrent) && p.cropCurrent[0] ? p.cropCurrent[0].irrigationCurrentKey : ''));
  const farmerTxt = p.farmer || p.owner || 'Belirtilmedi';
  const srcTxt = p.source_label || p.feature?.properties?.source_label || 'Yükleme / Çizim';
  const approval = customParcelApprovalMeta(p);
  return `
    <div class="parcel-pop">
      <div class="t">
        <span>${escapeHtml(String(p.name || p.id || 'Kullanıcı Parseli'))}</span>
        <span class="tag ${typeKey === 'orchard' ? 'orchard' : ''}">${escapeHtml(tagText)}</span>
      </div>
      <div class="s"><span class="k">Alan</span><span class="v">${escapeHtml(areaTxt)} da</span></div>
      <div class="s"><span class="k">Alan (m²)</span><span class="v">${escapeHtml(areaM2Txt)} m²</span></div>
      <div class="s"><span class="k">İlçe</span><span class="v">${escapeHtml(p.district || '-')}</span></div>
      <div class="s"><span class="k">Yer</span><span class="v">${escapeHtml(p.village || '-')}</span></div>
      <div class="s"><span class="k">Kaynak</span><span class="v right source-file">${escapeHtml(srcTxt)}</span></div>
      <div class="s"><span class="k">Onay durumu</span><span class="v">${escapeHtml(approval.label)}</span></div>
      <div class="s"><span class="k">Veri güveni</span><span class="v">${parcelConfidenceBadgeHtml(p)}</span></div>
      <div class="s"><span class="k">Ürün</span><span class="v">${escapeHtml(cropTxt)}</span></div>
      <div class="s"><span class="k">Sulama</span><span class="v">${escapeHtml(irrTxt || '-')}</span></div>
      <div class="s"><span class="k">Çiftçi</span><span class="v">${escapeHtml(farmerTxt)}</span></div>
      <div class="small muted" style="margin-top:8px;">${escapeHtml(evaluateParcelDataConfidence(p).note)}${evaluateParcelDataConfidence(p).missing.length ? ' Eksik başlıklar: ' + escapeHtml(evaluateParcelDataConfidence(p).missing.join(', ')) : ''}</div>
    </div>
  `;
}

function syncCustomParcelFeatureProperties(parcel){
  if(!parcel || !parcel.feature) return;
  const areaDa = +safeNum(currentGeometryAreaDa(parcel) || parcel.area_da, 0).toFixed(1);
  const typeKey = inferParcelTypeKey(parcel);
  parcel.area_da = areaDa > 0 ? areaDa : +safeNum(parcel.area_da, 0).toFixed(1);
  parcel.parcel_type = parcel.parcel_type && parcel.parcel_type !== 'auto' ? parcel.parcel_type : typeKey;
  parcel.source_label = parcel.source_label || parcel.feature?.properties?.source_label || 'Yükleme / Çizim';
  parcel.feature.properties = Object.assign({}, parcel.feature.properties || {}, {
    id: parcel.id,
    name: parcel.name || parcel.id,
    display_name: parcel.display_name || parcel.name || parcel.id,
    area_da: parcel.area_da,
    area_m2: Math.round(safeNum(parcel.area_da, 0) * 1000),
    village: parcel.village || '',
    district: parcel.district || '',
    current_crop: parcel.current_crop || '',
    irrigation_key: parcel.irrigation_key || '',
    irrigation_label: irrigationLabelFromKey(parcel.irrigation_key),
    farmer: parcel.farmer || '',
    parcel_type: parcel.parcel_type,
    is_orchard: parcel.parcel_type === 'orchard',
    source_label: parcel.source_label,
    owner_username: parcel.owner_username || parcel.feature?.properties?.owner_username || '',
    approval_status: String(parcel.approval_status || 'approved'),
    approval_note: String(parcel.approval_note || ''),
    reviewed_by: String(parcel.reviewed_by || ''),
    reviewed_at: String(parcel.reviewed_at || ''),
    submitted_at: String(parcel.submitted_at || ''),
    water_mode: String(parcel.irrigation_key || '').toLowerCase() === 'rainfed' ? 'kuru' : 'sulu',
    is_user_parcel: true,
  });
}

function syncCustomParcelLayerBindings(parcel){
  if(!parcel) return;
  syncCustomParcelFeatureProperties(parcel);
  const layer = findCustomLayerById(parcel.id);
  if(!layer) return;
  try{ layer.feature = parcel.feature; }catch(_e){}
  try{ if(typeof layer.setStyle === 'function' && customUserLayer?.options?.style){ layer.setStyle(customUserLayer.options.style(parcel.feature)); } }catch(_e){}
  ensureCustomLayerTooltip(layer, buildCustomParcelTooltipHtml(parcel));
  ensureCustomLayerPopup(layer, buildCustomParcelPopupHtml(parcel));
  try{ if(typeof layer.bringToFront === 'function') layer.bringToFront(); }catch(_e){}
}

function syncAllCustomParcelLayerBindings(){
  (parcelData || []).filter(p=>!!p?.frontend_custom && !!p?.feature).forEach(syncCustomParcelLayerBindings);
}

function centroidOfLatLngs(latlngs){
  const pts = (latlngs||[]).filter(p=>p && isFinite(+p.lat) && isFinite(+p.lng));
  if(!pts.length) return {lat:37.957776, lng:34.353984};
  const lat = pts.reduce((s,p)=>s+(+p.lat),0) / pts.length;
  const lng = pts.reduce((s,p)=>s+(+p.lng),0) / pts.length;
  return {lat, lng};
}

const EARTH_RADIUS_M = 6378137;

function ensureClosedLonLatRing(coords){
  const pts = (coords||[]).filter(c=>Array.isArray(c) && c.length >= 2 && isFinite(+c[0]) && isFinite(+c[1])).map(c=>[+c[0], +c[1]]);
  if(!pts.length) return [];
  const first = pts[0];
  const last = pts[pts.length - 1];
  if(first[0] !== last[0] || first[1] !== last[1]) pts.push([first[0], first[1]]);
  return pts;
}

function signedRingAreaSquareMetersLonLat(coords){
  const ring = ensureClosedLonLatRing(coords);
  if(ring.length < 4) return 0;
  let sum = 0;
  for(let i=0; i<ring.length-1; i++){
    const lon1 = ring[i][0] * Math.PI / 180;
    const lat1 = ring[i][1] * Math.PI / 180;
    const lon2 = ring[i+1][0] * Math.PI / 180;
    const lat2 = ring[i+1][1] * Math.PI / 180;
    sum += (lon2 - lon1) * (2 + Math.sin(lat1) + Math.sin(lat2));
  }
  return (sum * EARTH_RADIUS_M * EARTH_RADIUS_M) / 2;
}

function polygonAreaSquareMetersLonLat(rings){
  if(!Array.isArray(rings) || !rings.length) return 0;
  const outer = Math.abs(signedRingAreaSquareMetersLonLat(rings[0]));
  const holes = (rings.slice(1) || []).reduce((s, ring)=>s + Math.abs(signedRingAreaSquareMetersLonLat(ring)), 0);
  return Math.max(0, outer - holes);
}

function geometryAreaSquareMeters(geometry){
  const g = geometry || {};
  if(g.type === 'Polygon') return polygonAreaSquareMetersLonLat(g.coordinates || []);
  if(g.type === 'MultiPolygon') return (g.coordinates || []).reduce((s, poly)=>s + polygonAreaSquareMetersLonLat(poly || []), 0);
  return 0;
}

function featureAreaSquareMeters(feature){
  try{
    const areaM2 = geometryAreaSquareMeters(feature?.geometry);
    if(areaM2 > 0) return areaM2;
  }catch(_e){}
  try{
    const latlngs = latLngsFromFeature(feature);
    return areaSquareMetersFromLatLngs(latlngs);
  }catch(_e){}
  return 0;
}

function areaSquareMetersFromLatLngs(latlngs){
  const coords = (latlngs||[]).filter(p=>p && isFinite(+p.lat) && isFinite(+p.lng)).map(p=>[+p.lng, +p.lat]);
  return Math.max(0, polygonAreaSquareMetersLonLat([coords]));
}

function areaDaFromLatLngs(latlngs){
  const areaM2 = areaSquareMetersFromLatLngs(latlngs);
  return areaM2 > 0 ? areaM2 / 1000 : 0;
}

function currentGeometryAreaDa(parcel){
  if(!parcel) return 0;
  try{
    if(parcel.feature){
      const areaDa = featureAreaSquareMeters(parcel.feature) / 1000;
      if(areaDa > 0) return areaDa;
    }
  }catch(_e){}
  return safeNum(parcel.area_da, 0);
}

function isGeometryDrivenParcel(parcel){
  try{
    return !!(parcel && parcel.feature && currentGeometryAreaDa(parcel) > 0);
  }catch(_e){
    return false;
  }
}

function syncAreaInputMode(parcel){
  const areaEl = document.getElementById('manualParcelArea');
  const toggle = document.getElementById('manualAreaOverrideToggle');
  if(!areaEl) return;
  const geometryDriven = isGeometryDrivenParcel(parcel);
  const manualEnabled = !!(toggle && toggle.checked);
  areaEl.readOnly = geometryDriven && !manualEnabled;
  areaEl.title = geometryDriven && !manualEnabled
    ? 'Alan seçilen geometriye göre otomatik hesaplanır.'
    : '';
}

function updateAreaInputFromGeometry(parcel, force=false){
  const areaEl = document.getElementById('manualParcelArea');
  const toggle = document.getElementById('manualAreaOverrideToggle');
  if(!areaEl || !parcel) return 0;
  const areaDa = currentGeometryAreaDa(parcel);
  const manualEnabled = !!(toggle && toggle.checked);
  if(areaDa > 0){
    parcel.area_da = +areaDa.toFixed(1);
    if(force || !manualEnabled || !safeNum(areaEl.value, 0)){
      areaEl.value = parcel.area_da.toFixed(1);
    }
  }
  syncAreaInputMode(parcel);
  return areaDa;
}

function latLngsFromFeature(feature){
  try{
    const lyr = L.geoJSON(feature);
    const out = [];
    const walk = (node)=>{
      if(!node) return;
      if(Array.isArray(node)){
        node.forEach(walk);
        return;
      }
      if(isFinite(+node.lat) && isFinite(+node.lng)) out.push(node);
    };
    lyr.eachLayer(l=>{
      if(typeof l.getLatLngs === 'function') walk(l.getLatLngs());
    });
    return out;
  }catch(_e){
    return [];
  }
}

function ensureCropSuggestions(){
  const dl = document.getElementById('cropSuggestions');
  if(!dl) return;
  const names = new Set();
  try{
    Object.keys(STATE?.cropCatalog || {}).forEach(k=>{
      const nm = STATE.cropCatalog[k]?.displayName || STATE.cropCatalog[k]?.name || prettyCropName(k);
      if(nm) names.add(String(nm));
    });
  }catch(_e){}
  try{
    Object.keys((typeof cropCatalog !== 'undefined' ? cropCatalog : {}) || {}).forEach(k=>{
      const nm = cropCatalog[k]?.displayName || cropCatalog[k]?.name || prettyCropName(k);
      if(nm) names.add(String(nm));
    });
  }catch(_e){}
  dl.innerHTML = Array.from(names).sort((a,b)=>a.localeCompare(b,'tr')).map(n=>`<option value="${escapeHtml(n)}"></option>`).join('');
}

function customParcelsForApi(){
  const currentUser = STATE.currentUser;
  return (parcelData || [])
    .filter(p => !!p?.frontend_custom || !!p?.frontend_override)
    .filter(p => {
      if(p?.frontend_override && !p?.frontend_custom) return true;
      const meta = customParcelApprovalMeta(p);
      const owner = String(p.owner_username || p.feature?.properties?.owner_username || '').trim();
      if(p.requested_for_parcel_id && p.promoted_to_official) return false;
      if(meta.status !== 'approved') return false;
      if(currentUser?.role === 'institution') return true;
      return !!currentUser && owner === currentUser.username;
    })
    .map(p=>({
      id: String(p.id),
      name: String(p.name || p.id),
      village: String(p.village || ''),
      district: String(p.district || ''),
      area_da: +safeNum(p.area_da, 0).toFixed(2),
      lat: +safeNum(p.lat, 0).toFixed(6),
      lon: +safeNum(p.lon, 0).toFixed(6),
      water_m3: +safeNum(p.water_m3, 0).toFixed(2),
      profit_tl: +safeNum(p.profit_tl, 0).toFixed(2),
      current_crop: String(p.current_crop || ''),
      irrigation_key: String(p.irrigation_key || ''),
      farmer: String(p.farmer || ''),
      parcel_type: String(p.parcel_type || ''),
      source_label: String(p.source_label || ''),
      owner_username: String(p.owner_username || p.feature?.properties?.owner_username || ''),
      approval_status: String(p.approval_status || (p.frontend_override ? 'approved' : 'approved')),
      requested_for_parcel_id: String(p.requested_for_parcel_id || ''),
      soil: p.soil || {},
    }));
}

function attachCustomParcelsToPayload(payload){
  const cps = customParcelsForApi();
  if(!cps.length) return payload;
  payload.customParcels = cps;
  payload.options = payload.options || {};
  payload.options.customParcels = cps;
  return payload;
}

function setUserParcelStatus(msg, err=false){
  const el = document.getElementById('userParcelStatus');
  if(!el) return;
  el.textContent = msg || 'Hazır';
  el.style.color = err ? '#c92a2a' : '';
}

function estimateParcelBaselineFromForm(parcel, cropName, irrigationKey){
  const A = safeNum(parcel?.area_da, 0);
  const meta = cropMetaByName(cropName) || {};
  let waterPerDa = safeNum(meta.waterPerDa ?? meta.water_m3_da ?? meta.su_tuketimi_m3_da, NaN);
  let profitPerDa = safeNum(meta.profitPerDa ?? meta.net_kar_tl_da ?? meta.kar_tl_da, NaN);
  if(!isFinite(waterPerDa) || waterPerDa < 0){
    waterPerDa = (String(irrigationKey||'') === 'rainfed') ? 180 : 520;
  }
  if(!isFinite(profitPerDa) || profitPerDa < 0){
    profitPerDa = 4500;
  }
  if(String(irrigationKey||'') === 'rainfed') waterPerDa *= 0.45;
  if(String(irrigationKey||'') === 'drip') waterPerDa *= 0.85;
  if(String(irrigationKey||'') === 'pivot') waterPerDa *= 0.92;
  return {
    waterPerDa: +waterPerDa.toFixed(2),
    profitPerDa: +profitPerDa.toFixed(2),
    water_m3: +(A * waterPerDa).toFixed(1),
    profit_tl: +(A * profitPerDa).toFixed(1),
  };
}

function buildApproxFeatureForParcel(parcel){
  const lat = safeNum(parcel?.lat, 37.96);
  const lon = safeNum(parcel?.lon, 34.68);
  const d = 0.0008;
  return {
    type:'Feature',
    properties:{ id:String(parcel?.id || ''), name:String(parcel?.name || parcel?.id || '') },
    geometry:{ type:'Polygon', coordinates:[[
      [lon-d, lat-d], [lon+d, lat-d], [lon+d, lat+d], [lon-d, lat+d], [lon-d, lat-d]
    ]] }
  };
}

function updateParcelEditModeUI(parcel){
  const saveBtn = document.getElementById('saveUserParcelBtn');
  const infoEl = document.getElementById('customParcelUploadInfo');
  if(!saveBtn || !infoEl) return;
  const role = STATE.currentUser?.role || 'institution';
  const isOfficial = !!parcel && !parcel.frontend_custom;
  const isRequest = !!parcel?.requested_for_parcel_id;
  if(!parcel){
    saveBtn.textContent = 'Bildirim / güncelleme kaydet';
    return;
  }
  if(role === 'farmer' && isOfficial){
    saveBtn.textContent = 'Düzeltme talebi oluştur';
    infoEl.innerHTML = '<span class="custom-parcel-badge"><span class="dot"></span>Resmî parsel</span> <span style="margin-left:6px;">Bu kullanıcı görünümünde resmî kaydı doğrudan değiştirmezsiniz. Girdiğiniz bilgiler yönetici onayına giden düzeltme talebi olarak kaydedilir.</span>';
    return;
  }
  if(role === 'institution' && isOfficial){
    saveBtn.textContent = 'Resmî kaydı güncelle';
    infoEl.innerHTML = '<span class="custom-parcel-badge"><span class="dot"></span>Kurumsal güncelleme</span> <span style="margin-left:6px;">Bu işlem resmî parsel için yerel override oluşturur ve hesaplamalara hemen dahil edilir.</span>';
    return;
  }
  if(isRequest){
    saveBtn.textContent = 'Talep kaydını güncelle';
    const linked = parcel.requested_for_parcel_id ? ` (${escapeHtml(parcel.requested_for_parcel_id)})` : '';
    infoEl.innerHTML = `<span class="custom-parcel-badge"><span class="dot"></span>Düzeltme talebi</span> <span style="margin-left:6px;">Bu kayıt resmî parsel${linked} için oluşturulmuş bekleyen kullanıcı talebidir.</span>`;
    return;
  }
  saveBtn.textContent = parcel.frontend_custom ? 'Parsel bildirimini güncelle' : 'Bildirim / güncelleme kaydet';
  infoEl.innerHTML = parcel.frontend_custom
    ? `<span class="custom-parcel-badge"><span class="dot"></span>Kullanıcı parseli</span> <span style="margin-left:6px;">Seçili parsel doğrudan kullanıcı girdisiyle analiz edilir.</span>`
    : 'Seçili parsele mevcut ürün ve sulama bilgisi girerek karşılaştırmayı zenginleştirebilirsin.';
}

function syncUserParcelForm(){
  const p = (parcelData || []).find(x=>String(x.id) === String(selectedParcelId));
  const nameEl = document.getElementById('manualParcelName');
  const areaEl = document.getElementById('manualParcelArea');
  const vEl = document.getElementById('manualParcelVillage');
  const dEl = document.getElementById('manualParcelDistrict');
  const cropEl = document.getElementById('manualCurrentCrop');
  const irrEl = document.getElementById('manualIrrigation');
  const farmerEl = document.getElementById('manualParcelFarmer');
  const typeEl = document.getElementById('manualParcelType');
  const infoEl = document.getElementById('customParcelUploadInfo');
  if(!nameEl || !areaEl || !vEl || !dEl || !cropEl || !irrEl || !farmerEl || !typeEl) return;
  if(!p){
    nameEl.value = '';
    areaEl.value = '';
    vEl.value = '';
    dEl.value = '';
    cropEl.value = '';
    irrEl.value = 'sprinkler';
    farmerEl.value = '';
    typeEl.value = 'auto';
    return;
  }
  nameEl.value = p.name || p.id || '';
  updateAreaInputFromGeometry(p, true);
  areaEl.value = safeNum(p.area_da, 0) > 0 ? (+p.area_da).toFixed(1) : '';
  syncAreaInputMode(p);
  const pMeta = (()=>{ try{ return demoMetaForParcel(String(p.id||''), String(p?.feature?.properties?.source_file || '')); }catch(_e){ return null; } })();
  vEl.value = p.village || pMeta?.village || '';
  dEl.value = p.district || pMeta?.district || '';
  cropEl.value = p.current_crop || (Array.isArray(p.cropCurrent) && p.cropCurrent[0] ? p.cropCurrent[0].name : '') || pMeta?.crop || '';
  irrEl.value = p.irrigation_key || (Array.isArray(p.cropCurrent) && p.cropCurrent[0] ? (p.cropCurrent[0].irrigationCurrentKey || 'sprinkler') : 'sprinkler');
  farmerEl.value = p.farmer || pMeta?.farmer || '';
  typeEl.value = p.parcel_type || (pMeta ? (pMeta.orchard ? 'orchard' : 'field') : 'auto');
  updateParcelEditModeUI(p);
  if(infoEl && p){
    const conf = evaluateParcelDataConfidence(p);
    const missing = conf.missing.length ? ` Eksik: ${escapeHtml(conf.missing.join(', '))}.` : '';
    infoEl.innerHTML += `<div class="small muted" style="margin-top:8px;">${parcelConfidenceBadgeHtml(p)} <span style="margin-left:6px;">${escapeHtml(conf.note)}${missing}</span></div>`;
  }
}

function updateParcelFromUserInputs(targetParcel){
  const p = targetParcel || (parcelData || []).find(x=>String(x.id) === String(selectedParcelId));
  if(!p) throw new Error('Önce bir parsel seçin, çizin veya GeoJSON yükleyin.');
  const name = (document.getElementById('manualParcelName')?.value || p.name || p.id || '').trim();
  const village = (document.getElementById('manualParcelVillage')?.value || p.village || '').trim();
  const district = (document.getElementById('manualParcelDistrict')?.value || p.district || '').trim();
  const cropName = (document.getElementById('manualCurrentCrop')?.value || '').trim();
  const irrigationKey = (document.getElementById('manualIrrigation')?.value || 'sprinkler').trim();
  const farmerName = (document.getElementById('manualParcelFarmer')?.value || p.farmer || '').trim();
  const parcelTypeKey = (document.getElementById('manualParcelType')?.value || p.parcel_type || 'auto').trim();
  const areaEl = document.getElementById('manualParcelArea');
  const manualToggle = document.getElementById('manualAreaOverrideToggle');
  const geometryArea = currentGeometryAreaDa(p);
  const useAutoArea = geometryArea > 0 && !(manualToggle && manualToggle.checked);
  const areaInput = useAutoArea
    ? geometryArea
    : safeNum(areaEl?.value, safeNum(geometryArea, safeNum(p.area_da, 0)));
  if(areaInput <= 0) throw new Error('Alan bilgisi gerekli. GeoJSON/KML yükleyin, haritada çizin ya da alanı elle girin.');

  const role = STATE.currentUser?.role || 'institution';
  const isOfficial = !p.frontend_custom;
  const normalized = {
    name: name || p.id,
    display_name: name || p.id,
    area_da: +areaInput.toFixed(1),
    village,
    district,
    farmer: farmerName,
    parcel_type: (parcelTypeKey && parcelTypeKey !== 'auto') ? parcelTypeKey : inferParcelTypeKey(cropName || p.current_crop || p),
    current_crop: cropName || p.current_crop || 'Mevcut ürün',
    irrigation_key: irrigationKey,
  };
  const est = estimateParcelBaselineFromForm({ ...p, area_da: normalized.area_da }, normalized.current_crop, irrigationKey);
  normalized.water_m3 = est.water_m3;
  normalized.profit_tl = est.profit_tl;
  normalized.cropCurrent = [{
    name: normalized.current_crop,
    season: 'Kullanıcı / yönetici girişi',
    irrigationCurrentText: irrigationLabelFromKey(irrigationKey),
    irrigationCurrentKey: irrigationKey,
    area: +normalized.area_da.toFixed(1),
    waterPerDa: est.waterPerDa,
    profitPerDa: est.profitPerDa,
  }];

  if(role === 'farmer' && isOfficial){
    const requestId = `REQ-${p.id}-${STATE.currentUser?.username || 'user'}`;
    const feature = JSON.parse(JSON.stringify(p.feature || buildApproxFeatureForParcel(p)));
    const req = createOrUpdateCustomParcel(feature, {
      id: requestId,
      name: `Talep • ${p.id}`,
      village: normalized.village,
      district: normalized.district,
      area_da: normalized.area_da,
      current_crop: normalized.current_crop,
      irrigation_key: normalized.irrigation_key,
      farmer: normalized.farmer,
      parcel_type: normalized.parcel_type,
      water_m3: normalized.water_m3,
      profit_tl: normalized.profit_tl,
      source_label: `Resmî parsel düzeltme talebi (${p.id})`,
      requested_for_parcel_id: String(p.id),
      owner_username: String(STATE.currentUser?.username || ''),
      approval_status: 'pending_review',
      approval_note: 'Çiftçi tarafından resmî kayıt için düzeltme talebi oluşturuldu.',
      soil: p.soil || {},
      submitted_at: new Date().toISOString(),
    });
    const threadId = parcelThreadKeyFor(req, STATE.currentUser?.username || '');
    pushParcelNotification({ target_role:'institution', actor_username: STATE.currentUser?.username || '', parcel_id: String(p.id), thread_id: threadId, kind:'parcel_request', text:`${STATE.currentUser?.displayName || STATE.currentUser?.username || 'Çiftçi'} resmi parsel için düzeltme talebi oluşturdu.` });
    postParcelThreadMessage(threadId, `Düzeltme talebi bırakıldı. Ürün: ${normalized.current_crop || '-'} • Sulama: ${irrigationLabelFromKey(normalized.irrigation_key)} • Alan: ${normalized.area_da.toFixed(1)} da`, { actor_role:'farmer', actor_username: STATE.currentUser?.username || '', actor_name: STATE.currentUser?.displayName || STATE.currentUser?.username || 'Çiftçi', parcel_id: String(p.id) });
    syncUserParcelForm();
    renderUserRequestThread();
    setUserParcelStatus(`Düzeltme talebi oluşturuldu • ${req.display_name || req.name}`);
    return req;
  }

  Object.assign(p, normalized);
  p.map_only = false;
  if(p.frontend_custom){
    p.owner_username = String(p.owner_username || STATE.currentUser?.username || '').trim();
    if(role === 'farmer'){
      p.approval_status = 'pending_review';
      p.approval_note = p.approval_note || 'Çiftçi bildirimi alındı. Kurumsal inceleme bekleniyor.';
      p.reviewed_by = '';
      p.reviewed_at = '';
    }else if(role === 'institution'){
      p.approval_status = p.approval_status || 'approved';
    }
    if(role === 'farmer' && p.owner_username){
      attachCustomParcelToUser(p.owner_username, p.id);
    }
  }else if(role === 'institution'){
    p.frontend_override = true;
    persistOfficialParcelOverrides();
  }
  syncCustomParcelFeatureProperties(p);
  if(p.frontend_custom) syncCustomParcelLayerBindings(p);
  try{ persistCustomParcels(); }catch(_e){}
  try{ persistOfficialParcelOverrides(); }catch(_e){}
  refreshParcelSelect();
  try{ syncOnboardingSection(); }catch(_e){}
  try{ const sel = document.getElementById('parcelSelect'); if(sel) sel.value = p.id; }catch(_e){}
  selectedParcelId = p.id;
  updateParcelEditModeUI(p);
  refreshUI();
  const approval = p.frontend_custom ? customParcelApprovalMeta(p) : null;
  const conf = evaluateParcelDataConfidence(p);
  const msg = p.frontend_custom
    ? `Parsel bildirimi kaydedildi • ${approval ? approval.label : 'Hazır'} • Veri güveni: ${conf.label}`
    : `Resmî parsel kaydı güncellendi ve hesaplamalara dahil edildi • Veri güveni: ${conf.label}`;
  if(p.frontend_custom && role === 'farmer'){
    const threadId = parcelThreadKeyFor(p, p.owner_username || STATE.currentUser?.username || '');
    pushParcelNotification({ target_role:'institution', actor_username: STATE.currentUser?.username || '', parcel_id: String(p.requested_for_parcel_id || p.id || ''), thread_id: threadId, kind:'parcel_request', text:`${STATE.currentUser?.displayName || STATE.currentUser?.username || 'Çiftçi'} parsel bildirimi kaydetti.` });
    postParcelThreadMessage(threadId, `Parsel bildirimi güncellendi. Ürün: ${normalized.current_crop || '-'} • Sulama: ${normalized.irrigation_key || '-'} • Alan: ${normalized.area_da.toFixed(1)} da`, { actor_role:'farmer', actor_username: STATE.currentUser?.username || '', actor_name: STATE.currentUser?.displayName || STATE.currentUser?.username || 'Çiftçi', parcel_id: String(p.requested_for_parcel_id || p.id || '') });
  }
  setUserParcelStatus(msg);
  renderUserRequestThread();
  return p;
}

// -----------------------------
// Selection helpers
// -----------------------------
// UI supports "__ALL__" to view basin totals. For optimize/benchmark requests we
// must send the correct parcel list to the backend so results stay consistent.
function getSelectedParcelIdsForRun() {
  const sid = (selectedParcelId ?? '').toString();
  const usable = getVisibleUsableParcelIds();
  const isMapOnly = getVisibleParcels().some(p => String(p?.id) === String(sid) && !!p?.map_only);

  if (!sid) return usable;
  if (sid === '__ALL__') return usable;

  // Harita için eklenen (map_only) parseller optimize/benchmark'a gönderilmesin
  if (isMapOnly) return [];
  return [sid];
}

function getBenchmarkParcelIdsForRun(){
  const sid = (selectedParcelId ?? '').toString();
  const visible = getVisibleParcels().filter(p => !p?.map_only);
  const usable = visible.map(p => String(p.id));
  if(!sid || sid === '__ALL__') return usable.slice(0, Math.min(8, usable.length));
  const selectedParcel = visible.find(p => String(p?.id) === sid);
  if(!selectedParcel) return usable;
  // Benchmark sekmesi kullanıcının baktığı parsel için algoritma davranışını göstermelidir.
  // Köyün tamamını otomatik koşturmak 50+ tekrar senaryolarında arayüzü dakikalarca boş
  // bırakıyordu. Havza/köy ölçeği için resmi tablo ve ilçe/il özeti sekmeleri kullanılır.
  return [sid];
}

function getBenchmarkScopeLabel(ids){
  const arr = Array.isArray(ids) ? ids.map(String) : [];
  if(!arr.length) return 'Kapsam belirlenemedi';
  const visible = getVisibleParcels().filter(p => !p?.map_only && arr.includes(String(p.id)));
  const villages = Array.from(new Set(visible.map(p => String(p.village || p.koy || '').trim()).filter(Boolean)));
  if(arr.length === 1){
    const p = visible[0] || null;
    return `${arr[0]} parseli${p?.village ? ' • '+p.village : ''}`;
  }
  if(villages.length === 1) return `${villages[0]} köyü • ${arr.length} parsel`;
  if(villages.length > 1) return `${villages.length} köy • ${arr.length} parsel`;
  return `${arr.length} parsel`;
}

function displayIrrigationText(rawText, fallbackKey=''){
  const txt = String(rawText || '').trim();
  const low = txt.toLowerCase();
  if(!txt || txt === '-') return irrigationLabel(fallbackKey) || '-';
  if(['sprinkler','sprinkler_pivot','pivot'].includes(low)) return 'Yağmurlama';
  if(low === 'drip') return 'Damla';
  if(['surface','surface_furrow','furrow','salma','karik','karık'].includes(low)) return 'Karık / Salma';
  if(low === 'rainfed') return 'Yağışa bağlı / Kuru';
  const guessed = irrKeyFromText(txt);
  return irrigationLabel(guessed || fallbackKey) || txt;
}
let selectedAlgo = "ga";
let selectedScenario = "su_tasarruf";
const PANEL_OPEN_DEFAULTS = Object.freeze({
  parcelId: "P1",
  scenario: "su_tasarruf",
  seasonSource: "s1",
  cropCategoryMode: "mixed",
  tab: "parcel"
});

function applyPanelOpenDefaults(){
  const defaults = PANEL_OPEN_DEFAULTS;
  STATE.presentationDefaultsActive = true;
  selectedScenario = defaults.scenario;
  STATE.seasonSource = defaults.seasonSource;
  STATE.cropCategoryMode = defaults.cropCategoryMode;

  try{
    const hasP1 = (parcelData || []).some(p => String(p?.id || "").toUpperCase() === defaults.parcelId);
    const canUseP1 = !STATE.currentUser || typeof roleCanAccessParcel !== "function" || roleCanAccessParcel(defaults.parcelId, STATE.currentUser);
    if(hasP1 && canUseP1) selectedParcelId = defaults.parcelId;
  }catch(_e){}

  try{
    document.querySelectorAll('input[name="scenario"]').forEach(radio => {
      radio.checked = String(radio.value) === defaults.scenario;
    });
  }catch(_e){}

  const seasonSel = document.getElementById("seasonSourceSel");
  if(seasonSel) seasonSel.value = defaults.seasonSource;
  const cropSel = document.getElementById("cropCategoryModeSel");
  if(cropSel) cropSel.value = defaults.cropCategoryMode;
  try{ if(typeof setCropCategoryMode === "function") setCropCategoryMode(defaults.cropCategoryMode, false); }catch(_e){}
}

function focusPanelDefaultTab(){
  try{
    const btn = document.querySelector(`.tab[data-tab="${PANEL_OPEN_DEFAULTS.tab}"]`)
      || Array.from(document.querySelectorAll(".tab[data-tab]")).find(el => String(el.textContent || "").toLocaleLowerCase("tr-TR").includes("parsel düzeyi desen"));
    const key = btn?.getAttribute("data-tab") || PANEL_OPEN_DEFAULTS.tab;
    let opened = false;
    if(typeof switchTabByKey === "function") opened = !!switchTabByKey(key);
    if(!opened && btn) btn.click();
    if(getActiveTabKey() !== key && btn){
      const panel = document.getElementById(`tab-${key}`);
      document.querySelectorAll(".tab[data-tab]").forEach(el => el.classList.remove("active"));
      document.querySelectorAll(".tab-panels > .tab-panel").forEach(el => el.classList.remove("active"));
      btn.classList.add("active");
      if(panel){
        panel.classList.add("active");
        panel.classList.remove("hidden");
      }
    }
    try{
      localStorage.setItem("activeAnalysisTab", key);
      sessionStorage.setItem("activeAnalysisTab", key);
    }catch(_e){}
  }catch(_e){}
}

function isPresentationPanelRoute(){
  try{ return String(window.location.hash || "").toLowerCase() === "#panel"; }
  catch(_e){ return false; }
}

function shouldUsePresentationDefaults(){
  try{ return !!(STATE?.presentationDefaultsActive || isPresentationPanelRoute()); }
  catch(_e){ return isPresentationPanelRoute(); }
}

function getActiveTabKey(){
  try{ return document.querySelector(".tab.active")?.getAttribute("data-tab") || ""; }
  catch(_e){ return ""; }
}

function syncParcelSelectValueToParcel(parcelId, dispatchChange=false){
  const pid = String(parcelId || "").trim();
  const sel = document.getElementById("parcelSelect");
  if(!pid || !sel) return false;
  const options = Array.from(sel.options || []);
  const opt = options.find(o => String(o.value || "").trim() === pid)
    || options.find(o => String(o.value || "").trim().toUpperCase() === pid.toUpperCase())
    || options.find(o => String(o.textContent || "").trim().toUpperCase().startsWith(pid.toUpperCase()));
  if(!opt) return false;
  sel.value = opt.value;
  opt.selected = true;
  selectedParcelId = pid;
  if(dispatchChange){
    try{ sel.dispatchEvent(new Event("change", { bubbles: true })); }catch(_e){}
  }
  return String(sel.value || "").trim() === String(opt.value || "").trim();
}

function activatePanelDefaultParcel(){
  const pid = PANEL_OPEN_DEFAULTS.parcelId;
  try{
    const hasParcel = (parcelData || []).some(p => String(p?.id || "").toUpperCase() === pid);
    const canUseParcel = !STATE.currentUser || typeof roleCanAccessParcel !== "function" || roleCanAccessParcel(pid, STATE.currentUser);
    if(!hasParcel || !canUseParcel) return false;
  }catch(_e){
    return false;
  }
  if(typeof selectParcelByIdAndRefresh === "function"){
    const ok = !!selectParcelByIdAndRefresh(pid);
    syncParcelSelectValueToParcel(pid, false);
    return ok;
  }
  selectedParcelId = pid;
  try{ refreshParcelSelect(); }catch(_e){}
  syncParcelSelectValueToParcel(pid, true);
  try{ refreshUI(); }catch(_e){}
  return true;
}

function focusDefaultParcelMapWhenReady(attempt=0){
  const pid = PANEL_OPEN_DEFAULTS.parcelId;
  let result = "not-ready";
  try{
    if(typeof window._focusParcel === "function"){
      result = window._focusParcel(pid) || "not-ready";
    }
  }catch(_e){
    result = "not-ready";
  }
  if(result === "not-ready" && attempt < 5){
    requestAnimationFrame(()=> focusDefaultParcelMapWhenReady(attempt + 1));
  }
  return result;
}

function applyPresentationPanelDefaultsFinal(source="final"){
  applyPanelOpenDefaults();
  const selected = activatePanelDefaultParcel();
  focusPanelDefaultTab();
  requestAnimationFrame(()=>{
    focusPanelDefaultTab();
    syncParcelSelectValueToParcel(PANEL_OPEN_DEFAULTS.parcelId, false);
    focusDefaultParcelMapWhenReady(0);
  });
  return selected;
}

function schedulePresentationDefaultsFinal(source="scheduled-final", frames=2){
  const run = (left)=>{
    requestAnimationFrame(()=>{
      applyPresentationPanelDefaultsFinal(source);
      if(left > 1) run(left - 1);
    });
  };
  run(Math.max(1, frames));
}

// UX: while a new optimization is running, keep the last valid results visible.
// When the user changes algo/scenario without running, keep previous results but show a warning.
STATE.isOptimizing = false;
STATE.selectionDirty = false;

// Son optimizasyon çalıştırma bağlamı.
// Parsel veya senaryo/algoritma değiştiğinde öneri/opt sonuçlarının
// eski seçimden kalmaması için kullanılır.
let lastOptimizeContext = null; // { parcelId, scenario, algo }

function getAuthUserByUsername(username){
  const u = normalizeAuthUsername(username);
  return getAllAuthUsers().find(x => x.username === u) || null;
}

function getAllowedParcelIdsForUser(user){
  if(!user) return [];
  if(user.role === 'institution') return null;
  const ids = new Set((Array.isArray(user.allowedParcelIds) ? user.allowedParcelIds : []).map(String));

  // v40: Kurum bir çiftçiye yeni ürün/desen atadığında o parsel çiftçi paneline
  // otomatik düşsün. Atamalar localStorage + parcelData üzerinden okunur.
  try{
    const assignments = JSON.parse(localStorage.getItem('akkayaParcelAssignmentsV16') || '{}') || {};
    Object.values(assignments).forEach(a=>{
      if(!a) return;
      const fu = String(a.farmer_username || '').trim();
      const fn = String(a.farmer_name || '').trim().toLowerCase();
      const un = String(user.username || '').trim();
      const dn = String(user.displayName || '').trim().toLowerCase();
      if((fu && fu === un) || (fn && dn && fn === dn)){
        if(a.parcel_id) ids.add(String(a.parcel_id));
      }
    });
  }catch(_e){}

  try{
    (parcelData || []).forEach(p=>{
      const fu = String(p.assigned_farmer_username || '').trim();
      const fn = String(p.assigned_farmer_name || p.farmer || '').trim().toLowerCase();
      const un = String(user.username || '').trim();
      const dn = String(user.displayName || '').trim().toLowerCase();
      if((fu && fu === un) || (fn && dn && fn === dn)){
        if(p.id) ids.add(String(p.id));
      }
    });
  }catch(_e){}

  return Array.from(ids);
}

function userOwnsFrontendParcel(user, parcel){
  if(!user || user.role === 'institution' || !parcel?.frontend_custom) return !!(user && user.role === 'institution');
  const owner = String(parcel.owner_username || parcel?.feature?.properties?.owner_username || '').trim();
  if(owner && owner === user.username) return true;
  return getUserCustomParcelIds(user).includes(String(parcel.id || ''));
}

function roleCanAccessParcel(pid){
  const user = STATE.currentUser;
  if(!user) return false;
  const sid = String(pid || '');
  if(user.role === 'institution') return true;
  const parcel = (parcelData || []).find(p => String(p?.id) === sid);
  if(parcel?.frontend_custom) return userOwnsFrontendParcel(user, parcel);
  const allowed = getAllowedParcelIdsForUser(user) || [];
  return allowed.includes(sid);
}

function getVisibleParcels(){
  const user = STATE.currentUser;
  if(!user && shouldUsePresentationDefaults()) return [...(parcelData || [])];
  if(!user) return [];
  if(user.role === 'institution') return [...(parcelData || [])];
  return (parcelData || []).filter(p => p?.frontend_custom ? userOwnsFrontendParcel(user, p) : roleCanAccessParcel(p?.id));
}

function getVisibleUsableParcelIds(){
  return getVisibleParcels().filter(p => !p?.map_only).map(p => String(p.id));
}

function metricsTitleForCurrentRole(pid){
  const user = STATE.currentUser;
  const visibleCount = getVisibleUsableParcelIds().length;
  if(user?.role === 'farmer'){
    return pid && pid !== '__ALL__'
      ? `Kendi parsel özeti (${pid})`
      : `Kendi parsellerim (${visibleCount} parsel)`;
  }
  return pid === '__ALL__'
    ? `Senaryo Özeti (${visibleCount || 0} parsel toplamı)`
    : `Senaryo Özeti (${pid} parseli)`;
}

function syncRoleInfoBanner(){
  const banner = document.getElementById('roleInfoBanner');
  if(!banner) return;
  const user = STATE.currentUser;
  if(!user){
    banner.classList.remove('is-visible');
    banner.innerHTML = '';
    return;
  }
  if(user.role === 'farmer'){
    const count = getVisibleUsableParcelIds().length;
    if(userNeedsOnboardingLock(user)){
      banner.innerHTML = `<strong>${escapeHtml(user.displayName || user.username)}</strong> hesabı için ilk kurulum açık. Yönetim tarafından açılmış hesabınızı kullanıyorsunuz. İletişim bilgilerinizi doğrulayın, gerekirse parsel ekleyin ve ardından paneli aktif hale getirin.`;
    }else if(shouldShowOnboardingPanel(user)){
      banner.innerHTML = `<strong>${escapeHtml(user.displayName || user.username)}</strong> demo hesabında bilgi doğrulama adımı bu oturumda tekrar açıldı. Böylece ön kayıt → doğrulama → kurum teyidi akışı sunumda yeniden gösterilebilir.`;
    }else if(userAwaitingInstitutionProfileReview(user)){
      banner.innerHTML = `<strong>${escapeHtml(user.displayName || user.username)}</strong> hesabının temel bilgileri güncellendi. Şimdi yönetici tarafında kurulum sonrası teyit / onay akışı gösterilebilir.`;
    }else{
      banner.innerHTML = `<strong>${escapeHtml(user.displayName || user.username)}</strong> hesabı ile giriş yapıldı. Bu görünümde yalnızca size tanımlı <strong>${count}</strong> parsel listelenir. Odak; mevcut ürün, önerilen ürün deseni, su tasarrufu ve gelir etkisidir.`;
    }
  }else{
    const count = getVisibleUsableParcelIds().length;
    if(getInstitutionRole(user) === 'analyst'){
      banner.innerHTML = `<strong>Kurumsal analiz görünümü</strong> aktif. Bölge genelindeki <strong>${count}</strong> parsel için ilçe özeti, su bütçesi, algoritma karşılaştırmaları ve uzun vadeli etki ekranları öne çıkar. Kullanıcı açma / pasife alma gibi işlemler yönetici hesabında tutulur.`;
    }else{
      banner.innerHTML = `<strong>Kurumsal yönetim görünümü</strong> aktif. Bölge genelindeki <strong>${count}</strong> parsel için kullanıcı yönetimi, resmi özet tablolar, su bütçesi ve uzun vadeli etki ekranları birlikte kullanılabilir.`;
    }
  }
  banner.classList.add('is-visible');
}

function ensureAllowedSelectedParcel(){
  const visibleIds = getVisibleParcels().map(p => String(p.id));
  if(!visibleIds.length){
    selectedParcelId = '';
    return;
  }
  if(!visibleIds.includes(String(selectedParcelId || ''))){
    const usable = getVisibleUsableParcelIds();
    selectedParcelId = usable[0] || visibleIds[0];
  }
}

function updateSidebarStepNumbers(){
  const groups = Array.from(document.querySelectorAll('.sidebar-panel .sidebar-group'));
  let visibleIndex = 1;
  groups.forEach((group)=>{
    const isVisible = window.getComputedStyle(group).display !== 'none';
    const stepEl = group.querySelector('.sidebar-group-step');
    if(stepEl && isVisible){
      stepEl.textContent = String(visibleIndex++);
    }
  });
}

function applyRoleLayerVisibility(){
  const syncOne = (layer)=>{
    const pid = String(layer?.feature?.properties?.id || layer?.feature?.properties?.name || '');
    if(!pid) return;
    const allowed = roleCanAccessParcel(pid);
    try{
      const el = (typeof layer.getElement === 'function') ? layer.getElement() : null;
      if(el){
        el.style.display = allowed ? '' : 'none';
        el.style.pointerEvents = allowed ? '' : 'none';
      }
    }catch(_e){}
    try{
      const tt = layer.getTooltip && layer.getTooltip();
      const ttEl = tt && tt.getElement ? tt.getElement() : null;
      if(ttEl) ttEl.style.display = allowed ? '' : 'none';
    }catch(_e){}
    if(!allowed){
      try{ if(typeof layer.closePopup === 'function') layer.closePopup(); }catch(_e){}
      try{ if(typeof layer.setStyle === 'function') layer.setStyle({ opacity:0, fillOpacity:0 }); }catch(_e){}
    }
  };
  try{ if(parcelLayer) parcelLayer.eachLayer(syncOne); }catch(_e){}
  try{ if(customUserLayer) customUserLayer.eachLayer(syncOne); }catch(_e){}
}

function syncAppActionLocks(){
  const need = userNeedsOnboardingLock(STATE.currentUser);
  document.body.classList.toggle('onboarding-required', need);
  const runButtons = ['runOptBtn', 'runOptBtnSecondary']
    .map(id => document.getElementById(id))
    .filter(Boolean);
  const benchBtn = document.getElementById('runBenchmarkBtn');
  runButtons.forEach(runBtn => {
    runBtn.disabled = !!need;
    runBtn.classList.toggle('btn-disabled', !!need);
    runBtn.title = need ? 'Önce ilk kurulum adımını tamamlayın.' : '';
  });
  if(benchBtn){
    benchBtn.disabled = !!need;
    benchBtn.classList.toggle('btn-disabled', !!need);
    benchBtn.title = need ? 'Önce ilk kurulum adımını tamamlayın.' : '';
  }
}

function renderAdminParcelPicker(selectedIds=[]){
  const wrap = document.getElementById('adminParcelPicker');
  if(!wrap) return;
  const selected = new Set((selectedIds || []).map(x => String(x)));
  wrap.innerHTML = '';
  getRegisterableParcelChoices().forEach(pid => {
    const item = document.createElement('label');
    item.className = 'auth-parcel-chip';
    item.innerHTML = `<input type="checkbox" value="${escapeHtml(pid)}" ${selected.has(pid) ? 'checked' : ''}/> <span>${escapeHtml(pid)}</span>`;
    wrap.appendChild(item);
  });
}

function renderManagedUsersList(){
  const box = document.getElementById('managedUsersList');
  const metaBox = document.getElementById('managedUsersListMeta');
  if(!box) return;
  renderManagedUsersOverview();
  renderManagedUsersSidebarPreview();
  if(!canManageUsers()){
    box.innerHTML = '<tr><td colspan="6"><div class="managed-user-empty">Bu modül yalnızca kurumsal yönetici hesabında açılır. Analiz odaklı kurum kullanıcıları ilçe / su bütçesi / etki sekmelerini kullanır.</div></td></tr>';
    if(metaBox) metaBox.textContent = 'Yönetim yetkisi yok.';
    return;
  }
  const users = getFilteredManagedFarmers();
  const total = getManagedFarmers().length;
  const selectedUsername = document.getElementById('managedUserEditUsername')?.value || '';
  if(metaBox){
    metaBox.textContent = users.length === total
      ? `${total} çiftçi hesabı listeleniyor.`
      : `${users.length} kayıt gösteriliyor • toplam ${total} çiftçi hesabı var.`;
  }
  if(!users.length){
    box.innerHTML = '<tr><td colspan="6"><div class="managed-user-empty">Filtreye uyan çiftçi hesabı bulunamadı.</div></td></tr>';
    return;
  }
  box.innerHTML = users.map(user => {
    const meta = managedUserStatusMeta(user);
    const selected = selectedUsername === user.username;
    const officialIds = getAllowedParcelIdsForUser(user) || [];
    const customIds = getUserCustomParcelIds(user);
    const phoneTag = user.phone ? `<span class="mini-tag">${escapeHtml(user.phone)}</span>` : '';
    const temp = user.temporaryPassword ? '<span class="mini-tag">Geçici şifre</span>' : '';
    const noteText = user.notes ? escapeHtml(user.notes) : 'Not girilmedi';
    const lastAction = user.lastPasswordResetAt
      ? `Şifre yenileme • ${escapeHtml(formatManagedUserTimestamp(user.lastPasswordResetAt))}`
      : `Güncelleme • ${escapeHtml(formatManagedUserTimestamp(user.updatedAt || user.createdAt))}`;
    return `<tr class="managed-user-row-item ${selected ? 'is-selected' : ''}" data-managed-select="${escapeHtml(user.username)}">
      <td>
        <div class="managed-user-cell-primary">${escapeHtml(user.displayName || user.username)}</div>
        <div class="managed-user-cell-sub">@${escapeHtml(user.username)} • ${escapeHtml(user.village || '-')} / ${escapeHtml(user.district || '-')}</div>
        <div class="managed-user-cell-tags">${temp}${phoneTag}</div>
      </td>
      <td><span class="managed-user-status ${meta.accountClass}">${escapeHtml(meta.summaryText)}</span></td>
      <td>
        <div class="managed-user-parcel-count"><strong>${officialIds.length}</strong> resmi parsel</div>
        <div class="small muted">${customIds.length} kullanıcı parseli</div>
      </td>
      <td>
        <div class="managed-user-setup-line">${escapeHtml(meta.setupText)}</div>
        <div class="small muted">${escapeHtml(meta.detailText || (meta.onboardingPending ? 'İşlem bekliyor' : 'Hazır'))}</div>
      </td>
      <td>
        <div class="managed-user-note-preview">${noteText}</div>
        <div class="small muted">${lastAction}</div>
      </td>
      <td class="ta-right">
        <div class="managed-user-table-actions">
          <button class="managed-user-table-btn" type="button" data-managed-action="edit" data-username="${escapeHtml(user.username)}">Düzenle</button>
          <button class="managed-user-table-btn ${user.accountStatus === 'passive' ? '' : 'warn'}" type="button" data-managed-action="toggle-passive" data-username="${escapeHtml(user.username)}">${user.accountStatus === 'passive' ? 'Aktif et' : 'Pasif yap'}</button>
          <button class="managed-user-table-btn danger" type="button" data-managed-action="reset-password" data-username="${escapeHtml(user.username)}">Şifre yenile</button>
        </div>
      </td>
    </tr>`;
  }).join('');

  box.querySelectorAll('[data-managed-select]').forEach(row => {
    row.addEventListener('click', ()=> openManagedUserEditorByUsername(row.getAttribute('data-managed-select'), false));
  });

  box.querySelectorAll('[data-managed-action="edit"]').forEach(btn => {
    btn.addEventListener('click', (ev)=>{
      ev.stopPropagation();
      openManagedUserEditorByUsername(btn.getAttribute('data-username'));
    });
  });

  box.querySelectorAll('[data-managed-action="toggle-passive"]').forEach(btn => {
    btn.addEventListener('click', (ev)=>{
      ev.stopPropagation();
      toggleManagedUserPassiveState(btn.getAttribute('data-username'));
    });
  });

  box.querySelectorAll('[data-managed-action="reset-password"]').forEach(btn => {
    btn.addEventListener('click', (ev)=>{
      ev.stopPropagation();
      resetManagedUserPassword(btn.getAttribute('data-username'));
    });
  });
}

function renderOnboardingParcelSummary(){
  const box = document.getElementById('onboardingParcelSummary');
  if(!box) return;
  const user = STATE.currentUser;
  if(!user || user.role !== 'farmer'){
    box.innerHTML = '';
    return;
  }
  const assigned = getAllowedParcelIdsForUser(user) || [];
  const customIds = getUserCustomParcelIds(user);
  const assignedHtml = assigned.length ? assigned.map(pid => `<span class="auth-parcel-chip auth-parcel-chip--readonly">${escapeHtml(pid)}</span>`).join('') : '<span class="small muted">Yönetim tarafından henüz resmi parsel atanmadı.</span>';
  const customHtml = customIds.length ? customIds.map(pid => {
    const parcel = getCustomParcelById(pid);
    const meta = customParcelApprovalMeta(parcel);
    return `<span class="auth-parcel-chip auth-parcel-chip--readonly auth-parcel-chip--status-${escapeHtml(meta.className)}">${escapeHtml(pid)} • ${escapeHtml(meta.label)}</span>`;
  }).join('') : '<span class="small muted">Henüz kullanıcı tarafından eklenen parsel bildirimi yok.</span>';
  box.innerHTML = `
    <div class="onboarding-summary-grid">
      <div>
        <strong>Yönetim tarafından atanmış parseller</strong>
        <div class="auth-parcel-picker auth-parcel-picker--readonly">${assignedHtml}</div>
      </div>
      <div>
        <strong>Kullanıcının parsel bildirimi / düzeltme kayıtları</strong>
        <div class="auth-parcel-picker auth-parcel-picker--readonly">${customHtml}</div>
      </div>
    </div>
    <div class="small muted" style="margin-top:8px;">Eksik veya hatalı parseliniz varsa soldaki <b>Parsel bildirimi / düzeltme</b> kartından GeoJSON/KML yükleyebilir veya haritada çizim yapabilirsiniz. Çiftçi tarafından eklenen parseller kurumsal onaydan sonra analize dahil edilir.</div>`;
}

function syncOnboardingSection(){
  const section = document.getElementById('onboardingSection');
  const user = STATE.currentUser;
  const need = shouldShowOnboardingPanel(user);
  if(section) section.classList.toggle('is-visible', !!need);
  const compact = document.getElementById('onboardingCompactBanner');
  if(compact) compact.classList.toggle('is-visible', !!need);
  if(!user || user.role !== 'farmer') return;
  const nameEl = document.getElementById('onboardingDisplayName');
  const phoneEl = document.getElementById('onboardingPhone');
  const villageEl = document.getElementById('onboardingVillage');
  const districtEl = document.getElementById('onboardingDistrict');
  const notesEl = document.getElementById('onboardingNotes');
  const userLabel = document.getElementById('onboardingUsernameLabel');
  if(nameEl) nameEl.value = user.displayName || '';
  if(phoneEl) phoneEl.value = user.phone || '';
  if(villageEl) villageEl.value = user.village || '';
  if(districtEl) districtEl.value = user.district || '';
  if(notesEl) notesEl.value = user.notes || '';
  if(userLabel) userLabel.textContent = `@${user.username}`;
  renderOnboardingParcelSummary();
}

function jumpToUserParcelTools(){
  try{
    const grp = document.getElementById('parcelGroup');
    if(grp) grp.open = true;
    const card = document.getElementById('userParcelCard');
    if(card) card.scrollIntoView({ behavior:'smooth', block:'start' });
    const startBtn = document.getElementById('startDrawParcelBtn');
    if(startBtn) startBtn.focus();
  }catch(_e){}
}

function completeCurrentUserOnboarding(){
  const user = STATE.currentUser;
  if(!user || user.role !== 'farmer') return;
  const errEl = document.getElementById('onboardingError');
  const okEl = document.getElementById('onboardingSuccess');
  if(errEl) errEl.textContent = '';
  if(okEl) okEl.textContent = '';
  const displayName = String(document.getElementById('onboardingDisplayName')?.value || '').trim();
  const phone = String(document.getElementById('onboardingPhone')?.value || '').trim();
  const village = String(document.getElementById('onboardingVillage')?.value || '').trim();
  const district = String(document.getElementById('onboardingDistrict')?.value || '').trim();
  const notes = String(document.getElementById('onboardingNotes')?.value || '').trim();
  const pass1 = String(document.getElementById('onboardingPassword')?.value || '');
  const pass2 = String(document.getElementById('onboardingPassword2')?.value || '');
  const assigned = getAllowedParcelIdsForUser(user) || [];
  const customIds = getUserCustomParcelIds(user);
  if(!displayName){ if(errEl) errEl.textContent = 'Lütfen ad soyad bilgisini girin.'; return; }
  if(user.temporaryPassword || userNeedsOnboarding(user)){
    if(pass1.length < 4){ if(errEl) errEl.textContent = 'İlk kurulumda yeni şifre en az 4 karakter olmalıdır.'; return; }
    if(pass1 !== pass2){ if(errEl) errEl.textContent = 'Şifre tekrar alanı eşleşmiyor.'; return; }
  }
  if(!assigned.length && !customIds.length){
    if(errEl) errEl.textContent = 'Panele geçmeden önce en az bir parsel atanmış olmalı veya kullanıcı parseli oluşturulmalıdır.';
    return;
  }
  const reviewNeeded = !!user.demoRequiresInstitutionReviewAfterSetup;
  const saved = saveAuthUser({
    ...user,
    displayName,
    phone,
    village,
    district,
    notes,
    password: pass1.length >= 4 ? pass1 : user.password,
    accountStatus: 'active',
    onboardingCompleted: true,
    temporaryPassword: false,
    onboardingLastSubmittedAt: new Date().toISOString(),
    profileReviewStatus: reviewNeeded ? 'pending_review' : (user.profileReviewStatus || 'not_required'),
    profileReviewNote: reviewNeeded ? 'Kurulum bilgileri güncellendi. Demo akışında yönetici teyidi bekleniyor.' : (user.profileReviewNote || '')
  });
  if(document.getElementById('onboardingPassword')) document.getElementById('onboardingPassword').value = '';
  if(document.getElementById('onboardingPassword2')) document.getElementById('onboardingPassword2').value = '';
  if(!STATE.onboardingReplayDismissedForSession) STATE.onboardingReplayDismissedForSession = {};
  STATE.onboardingReplayDismissedForSession[saved.username] = true;
  if(reviewNeeded){
    const threadId = `THREAD-ONBOARDING-${saved.username}`;
    pushParcelNotification({ target_role:'institution', actor_username: saved.username, parcel_id:'', thread_id: threadId, kind:'message', text:`${saved.displayName || saved.username} ilk kurulum bilgilerini doğruladı. Yönetici teyidi / sunum onayı bekleniyor.` });
    postParcelThreadMessage(threadId, `Kurulum bilgileri güncellendi. Telefon: ${phone || '-'} • Köy: ${village || '-'} • İlçe: ${district || '-'}`, { actor_role:'farmer', actor_username: saved.username, actor_name: saved.displayName || saved.username, parcel_id:'' });
  }
  if(okEl) okEl.textContent = reviewNeeded ? 'Bilgiler kaydedildi. Bu oturum için panel açıldı; kurum tarafında da kurulum sonrası teyit akışı görünür oldu.' : 'Bilgiler kaydedildi. Çiftçi paneli kullanıma hazır.';
  renderManagedUsersList();
  setAuthenticatedUser(saved, { focus:false });
  try{ syncOnboardingSection(); syncRoleInfoBanner(); syncAppActionLocks(); }catch(_e){}
}

function initManagedUserAdmin(){
  renderAdminParcelPicker();
  renderManagedUserForm(null);
  renderManagedUsersList();

  const searchEl = document.getElementById('managedUserSearch');
  const filterEl = document.getElementById('managedUserStatusFilter');
  const newBtn = document.getElementById('managedUserNewBtn');
  const saveBtn = document.getElementById('saveManagedFarmerBtn');
  const cancelBtn = document.getElementById('cancelManagedFarmerBtn');
  const statusSel = document.getElementById('managedUserAccountStatus');
  const openPanelBtn = document.getElementById('openUserManagementTabBtn');
  const workspaceNewBtn = document.getElementById('managedUserWorkspaceNewBtn');

  if(searchEl && !searchEl.dataset.bound){
    searchEl.dataset.bound = '1';
    searchEl.addEventListener('input', renderManagedUsersList);
  }
  if(filterEl && !filterEl.dataset.bound){
    filterEl.dataset.bound = '1';
    filterEl.addEventListener('change', renderManagedUsersList);
  }
  if(newBtn && !newBtn.dataset.bound){
    newBtn.dataset.bound = '1';
    newBtn.addEventListener('click', ()=>{
      renderManagedUserForm(null);
      renderManagedUsersList();
      setManagedUserStatusMessage('Yeni kayıt formu hazır.', 'info');
    });
  }
  if(cancelBtn && !cancelBtn.dataset.bound){
    cancelBtn.dataset.bound = '1';
    cancelBtn.addEventListener('click', ()=>{
      renderManagedUserForm(null);
      renderManagedUsersList();
      setManagedUserStatusMessage('Form temizlendi.', 'info');
    });
  }
  if(openPanelBtn && !openPanelBtn.dataset.bound){
    openPanelBtn.dataset.bound = '1';
    openPanelBtn.addEventListener('click', ()=>{
      const grp = document.getElementById('userManagementGroup');
      if(grp) grp.open = true;
      const tabBtn = document.querySelector('.tab[data-tab="users"]');
      if(tabBtn) tabBtn.click();
      const panel = document.getElementById('tab-users');
      if(panel) setTimeout(()=> panel.scrollIntoView({ behavior:'smooth', block:'start' }), 60);
    });
  }
  if(workspaceNewBtn && !workspaceNewBtn.dataset.bound){
    workspaceNewBtn.dataset.bound = '1';
    workspaceNewBtn.addEventListener('click', ()=>{
      const tabBtn = document.querySelector('.tab[data-tab="users"]');
      if(tabBtn) tabBtn.click();
      renderManagedUserForm(null);
      renderManagedUsersList();
      setManagedUserStatusMessage('Yeni kayıt formu hazır.', 'info');
    });
  }
  if(statusSel && !statusSel.dataset.bound){
    statusSel.dataset.bound = '1';
    statusSel.addEventListener('change', ()=> updateManagedUserFormBadges({
      accountStatus: statusSel.value,
      onboardingCompleted: statusSel.value === 'active',
      role: 'farmer'
    }));
  }
  if(saveBtn && !saveBtn.dataset.bound){
    saveBtn.dataset.bound = '1';
    saveBtn.addEventListener('click', ()=>{
      if(!adminAllowed()) return;
      const editUsername = String(document.getElementById('managedUserEditUsername')?.value || '').trim();
      const displayName = String(document.getElementById('managedUserDisplayName')?.value || '').trim();
      const usernameRaw = String(document.getElementById('managedUserUsername')?.value || displayName).trim();
      const username = normalizeAuthUsername(usernameRaw);
      const passwordInput = String(document.getElementById('managedUserPassword')?.value || '').trim();
      const village = String(document.getElementById('managedUserVillage')?.value || '').trim();
      const district = String(document.getElementById('managedUserDistrict')?.value || '').trim();
      const phone = String(document.getElementById('managedUserPhone')?.value || '').trim();
      const notes = String(document.getElementById('managedUserNotes')?.value || '').trim();
      const accountStatus = String(document.getElementById('managedUserAccountStatus')?.value || 'pending_setup');
      const selectedIds = Array.from(document.querySelectorAll('#adminParcelPicker input:checked')).map(el => String(el.value || ''));
      if(!displayName){ setManagedUserStatusMessage('Lütfen çiftçi adını girin.', 'error'); return; }
      if(!editUsername && (!username || username.length < 3)){ setManagedUserStatusMessage('Geçerli bir kullanıcı adı girin.', 'error'); return; }
      if(!editUsername && getAuthUserByUsername(username)){ setManagedUserStatusMessage('Bu kullanıcı adı zaten kayıtlı.', 'error'); return; }

      const existing = editUsername ? getAuthUserByUsername(editUsername) : null;
      if(editUsername && !existing){ setManagedUserStatusMessage('Düzenlenecek kayıt bulunamadı.', 'error'); return; }

      const base = existing || {
        username,
        role: 'farmer',
        institutionRole: '',
        customParcelIds: [],
        createdAt: new Date().toISOString(),
        createdBy: STATE.currentUser?.username || 'institution'
      };
      const nextPassword = passwordInput || existing?.password || 'demo123';
      const saved = saveAuthUser({
        ...base,
        username: existing?.username || username,
        displayName,
        password: nextPassword,
        phone,
        village,
        district,
        notes,
        role: 'farmer',
        allowedParcelIds: selectedIds,
        accountStatus,
        onboardingCompleted: accountStatus === 'active' ? true : (accountStatus === 'pending_setup' ? false : !!existing?.onboardingCompleted),
        temporaryPassword: passwordInput ? true : (existing ? existing.temporaryPassword : true),
        createdBy: base.createdBy || STATE.currentUser?.username || 'institution',
        createdAt: base.createdAt || new Date().toISOString(),
        updatedAt: new Date().toISOString(),
        lastPasswordResetAt: passwordInput ? new Date().toISOString() : (existing?.lastPasswordResetAt || '')
      });
      renderManagedUserForm(saved);
      renderManagedUsersList();
      setManagedUserStatusMessage(editUsername
        ? `<strong>${escapeHtml(saved.displayName)}</strong> kaydı güncellendi.`
        : `<strong>${escapeHtml(saved.displayName)}</strong> hesabı açıldı. Giriş: <b>${escapeHtml(saved.username)}</b> / <b>${escapeHtml(saved.password)}</b>`, 'success');
    });
  }
}

function initOnboardingControls(){
  const completeBtn = document.getElementById('completeOnboardingBtn');
  const openBtn = document.getElementById('openOnboardingParcelToolsBtn');
  const compactOpen = document.getElementById('openOnboardingPanelBtn');
  if(completeBtn && !completeBtn.dataset.bound){
    completeBtn.dataset.bound = '1';
    completeBtn.addEventListener('click', completeCurrentUserOnboarding);
  }
  if(openBtn && !openBtn.dataset.bound){
    openBtn.dataset.bound = '1';
    openBtn.addEventListener('click', jumpToUserParcelTools);
  }
  if(compactOpen && !compactOpen.dataset.bound){
    compactOpen.dataset.bound = '1';
    compactOpen.addEventListener('click', ()=>{
      const sec = document.getElementById('onboardingSection');
      if(sec) sec.scrollIntoView({ behavior:'smooth', block:'start' });
    });
  }
}

function setAuthenticatedUser(user, opts={}){
  STATE.currentUser = user || null;
  if(user) startAppBoot();
  try{
    localStorage.removeItem(AUTH_SESSION_KEY);
    localStorage.removeItem('sazlicaDemoUser');
  }catch(_e){}
  document.body.classList.toggle('auth-pending', !user);
  document.documentElement.classList.toggle('auth-pending', !user);
  document.body.classList.toggle('is-authenticated', !!user);
  document.body.classList.toggle('role-farmer', user?.role === 'farmer');
  document.body.classList.toggle('role-institution', user?.role === 'institution');
  document.body.classList.toggle('onboarding-required', !!userNeedsOnboardingLock(user));
  document.body.dataset.institutionRole = getInstitutionRole(user) || 'none';

  const roleLabel = document.getElementById('sessionRoleLabel');
  const userLabel = document.getElementById('sessionUserLabel');
  const subtitle = document.getElementById('sessionSubtitle');
  const switchBtn = document.getElementById('switchUserBtn');
  if(roleLabel) roleLabel.textContent = roleLabelForUser(user);
  if(userLabel) userLabel.textContent = user ? (user.displayName || user.username) : '-';
  if(subtitle) subtitle.textContent = !user
    ? 'Rol bazlı prototip paneli'
    : (userNeedsOnboardingLock(user)
      ? 'İlk kurulum ve bilgi tamamlama adımı açık'
      : (shouldShowOnboardingPanel(user)
        ? 'Demo için doğrulama adımı tekrar gösteriliyor'
        : (user.role === 'farmer'
        ? 'Kendi arazisine özel sade karar ekranı'
        : (getInstitutionRole(user) === 'analyst'
          ? 'Senaryo, su bütçesi ve etki analizi odaklı kurumsal görünüm'
          : 'Kullanıcı yönetimi + bölgesel analiz görünümü'))));
  if(switchBtn) switchBtn.classList.toggle('hidden', !user);

  updateSidebarStepNumbers();
  ensureAllowedSelectedParcel();
  refreshParcelSelect();
  syncRoleInfoBanner();
  syncOnboardingSection();
  renderManagedUsersList();
  syncAppActionLocks();
  try{ updateNotificationBell(); renderNotificationCenter(); renderInstitutionRequestInbox(); }catch(_e){}
  const shouldReplayOnboarding = shouldShowOnboardingPanel(user);
  if(user){
    const defaultTab = defaultTabForUser(user);
    const currentActive = document.querySelector('.tab.active');
    const currentKey = currentActive?.getAttribute('data-tab') || '';
    if(currentKey !== defaultTab){
      const preferredBtn = document.querySelector(`.tab[data-tab="${defaultTab}"]`);
      if(preferredBtn) preferredBtn.click();
    }
  }
  if(user){
    try{
      window.location.hash = 'panel';
      requestAnimationFrame(()=>{
        const appShell = document.querySelector('.app-shell');
        if(appShell) appShell.scrollIntoView({ behavior:'smooth', block:'start' });
        else window.scrollTo({ top:0, behavior:'smooth' });
      });
    }catch(_e){}
  }else{
    try{ window.scrollTo({ top:0, behavior:'smooth' }); }catch(_e){}
  }
  try{ if(window._updateParcelStyles) window._updateParcelStyles(); }catch(_e){}
  applyRoleLayerVisibility();
  const activeHidden = document.querySelector('.tab.active[data-role="institution"]');
  if(user?.role === 'farmer' && activeHidden){
    const fallback = document.querySelector('.tab[data-tab="parcel"]');
    if(fallback) fallback.click();
  }
  if(shouldReplayOnboarding){
    try{
      const sec = document.getElementById('onboardingSection');
      if(sec) sec.scrollIntoView({ behavior:'smooth', block:'start' });
      const focusEl = document.getElementById('onboardingDisplayName');
      if(focusEl) focusEl.focus();
    }catch(_e){}
  }else if(opts.focus !== false && selectedParcelId){
    try{ if(window._focusParcel) window._focusParcel(String(selectedParcelId)); }catch(_e){}
  }
  try{ refreshUI(); }catch(_e){}
  try{ updateNotificationBell(); renderNotificationCenter(); renderInstitutionRequestInbox(); }catch(_e){}
  finishAppBoot();
}

function getRegisterableParcelChoices(){
  const ids = (parcelData || []).filter(p => !p?.map_only).map(p => String(p.id || '').trim()).filter(Boolean);
  if(ids.length) return Array.from(new Set(ids));
  return Array.from({length: 15}, (_, i) => `P${i+1}`);
}

function setAuthTab(name){
  document.querySelectorAll('[data-auth-tab]').forEach(btn => btn.classList.toggle('is-active', btn.getAttribute('data-auth-tab') === name));
  document.querySelectorAll('[data-auth-panel]').forEach(panel => panel.classList.toggle('is-active', panel.getAttribute('data-auth-panel') === name));
}

function initAuthUI(){
  const form = document.getElementById('loginForm');
  const usernameEl = document.getElementById('loginUsername');
  const passwordEl = document.getElementById('loginPassword');
  const errorEl = document.getElementById('loginError');
  const switchBtn = document.getElementById('switchUserBtn');

  updateSidebarStepNumbers();
  initManagedUserAdmin();
  initOnboardingControls();

  document.querySelectorAll('[data-auth-tab]').forEach(btn => {
    btn.addEventListener('click', ()=> setAuthTab(btn.getAttribute('data-auth-tab') || 'login'));
  });

  document.querySelectorAll('[data-demo-user]').forEach(btn => {
    btn.addEventListener('click', ()=>{
      const user = getAuthUserByUsername(btn.getAttribute('data-demo-user'));
      if(usernameEl && user) usernameEl.value = user.username;
      if(passwordEl && user) passwordEl.value = user.password;
      if(errorEl) errorEl.textContent = '';
      setAuthTab('login');
      try{ usernameEl?.focus(); }catch(_e){}
    });
  });

  if(form){
    form.addEventListener('submit', (ev)=>{
      ev.preventDefault();
      const username = usernameEl?.value || '';
      const password = passwordEl?.value || '';
      const user = getAuthUserByUsername(username);
      if(!user || user.password !== password){
        if(errorEl) errorEl.textContent = 'Kullanıcı adı veya şifre hatalı. Açık kayıt yerine yönetim tarafından açılmış hesabınızla giriş yapmalısınız.';
        return;
      }
      if(user.accountStatus === 'passive'){
        if(errorEl) errorEl.textContent = 'Bu hesap yönetim tarafından pasife alınmış. Lütfen kurum yöneticisi ile iletişime geçin.';
        return;
      }
      if(errorEl) errorEl.textContent = '';
      if(!STATE.onboardingReplayDismissedForSession) STATE.onboardingReplayDismissedForSession = {};
      delete STATE.onboardingReplayDismissedForSession[user.username];
      setAuthenticatedUser(user);
    });
  }

  if(switchBtn){
    switchBtn.addEventListener('click', ()=>{
      if(STATE.onboardingReplayDismissedForSession) STATE.onboardingReplayDismissedForSession = {};
      setAuthenticatedUser(null, { focus:false });
      if(errorEl) errorEl.textContent = '';
      if(passwordEl) passwordEl.value = '';
      const oErr = document.getElementById('onboardingError');
      const oOk = document.getElementById('onboardingSuccess');
      if(oErr) oErr.textContent = '';
      if(oOk) oOk.textContent = '';
    });
  }

  try{
    localStorage.removeItem(AUTH_SESSION_KEY);
    document.body.classList.add('auth-pending');
    document.documentElement.classList.add('auth-pending');
    document.body.classList.remove('is-authenticated','role-farmer','role-institution','onboarding-required');
    document.body.dataset.institutionRole = 'none';
    try{ updateNotificationBell(); renderNotificationCenter(); renderInstitutionRequestInbox(); }catch(_e){}
  }catch(_e){}
}

// DOM referansları// DOM referansları (DOMContentLoaded içinde atanır)
let parcelSelectEl = null;
let parcelSummaryBody = null;

 // Parsel dropdown'ını güncelle (API'den gelen parcelData ile)
function refreshParcelSelect() {
  if (!parcelSelectEl) parcelSelectEl = document.getElementById("parcelSelect");
  if (!parcelSelectEl) return;

  const current = parcelSelectEl.value;
  parcelSelectEl.innerHTML = "";

  const opt0 = document.createElement("option");
  opt0.value = "";
  opt0.textContent = "Parsel seç";
  parcelSelectEl.appendChild(opt0);

  // Natural sort: P1, P2, ... P10 (instead of P1, P10, P11...)
  // Bazı veri setlerinde id alanı "P1 - ..." gibi zengin etiket taşıyabilir.
  // Bu yüzden önce id içinden, olmazsa name/display_name içinden P\d+ yakalayıp sıralıyoruz.
  const _parcelNum = (p)=>{
    const cand = [p?.id, p?.name, p?.display_name, p?.label].filter(Boolean).map(x=>String(x));
    for(const s of cand){
      // Prefer the leading parcel code (P1, P2, ...). Avoid "grab all digits" because
      // labels like "P2 - K10.2 ..." would become 2102 and break ordering.
      const m1 = s.match(/(^|\s)P\s*(\d+)\b/i);
      if(m1) return parseInt(m1[2], 10);
      const m2 = s.match(/^P\s*(\d+)$/i);
      if(m2) return parseInt(m2[1], 10);
    }
    return Number.POSITIVE_INFINITY;
  };

  let visibleParcels = getVisibleParcels();
  const defaultPid = PANEL_OPEN_DEFAULTS?.parcelId || "P1";
  if(shouldUsePresentationDefaults()){
    const p1 = (parcelData || []).find(p => String(p?.id || "").trim().toUpperCase() === defaultPid.toUpperCase());
    if(p1 && !visibleParcels.some(p => String(p?.id || "").trim().toUpperCase() === defaultPid.toUpperCase())){
      visibleParcels = [p1, ...visibleParcels];
    }
  }
  const sorted = [...visibleParcels].sort((a, b) => {
    const an = _parcelNum(a);
    const bn = _parcelNum(b);
    if(an !== bn) return an - bn;
    const ax = String(a?.id || a?.name || "");
    const bx = String(b?.id || b?.name || "");
    return ax.localeCompare(bx, "tr");
  });

  sorted.forEach((p) => {
    const opt = document.createElement("option");
    opt.value = p.id;
    const name = (p.name || p.display_name || p.label || "").trim();
    const v = (p.village || "").trim();
    const d = (p.district || "").trim();
    const farmer = cleanFarmerDisplayNameV54(p.farmer_name || p.assigned_farmer_name || p.farmer || "");
    const currentCropRaw = String(
      p.current_crop ||
      p.main_crop_current ||
      (Array.isArray(p.cropCurrent) && p.cropCurrent[0] ? p.cropCurrent[0].name : '') ||
      ''
    ).trim();
    const currentCrop = currentCropRaw ? prettyCropName(currentCropRaw) : '';

    // Dropdown label: "P157 - Kaynarca - Yakup Doğan (BUĞDAY)"
    // Böylece parsel id, köy, çiftçi adı ve mevcut ürün aynı seçim alanında birlikte görünür.
    const prefix = p.frontend_custom ? '[Kullanıcı] ' : '';
    const place = v || d || '';
    const parts = [`${prefix}${p.id}`];
    if(place) parts.push(place);
    if(farmer) parts.push(farmer);
    opt.textContent = parts.join(' - ') + (currentCrop ? ` (${currentCrop})` : '');
        parcelSelectEl.appendChild(opt);
  });

  const wanted = String(
    current ||
    selectedParcelId ||
    (shouldUsePresentationDefaults() ? defaultPid : "")
  ).trim();
  if (wanted) {
    const wantedOpt = Array.from(parcelSelectEl.options || []).find(opt => String(opt.value || "").trim() === wanted)
      || Array.from(parcelSelectEl.options || []).find(opt => String(opt.value || "").trim().toUpperCase() === wanted.toUpperCase())
      || Array.from(parcelSelectEl.options || []).find(opt => String(opt.textContent || "").trim().toUpperCase().startsWith(wanted.toUpperCase()));
    if(wantedOpt){
      parcelSelectEl.value = wantedOpt.value;
      selectedParcelId = String(wantedOpt.value || wanted);
    }
  }
}


// Parsel özeti yaz
