// -------------------------
// Parsel özeti: toprak kodu çözümleyici (harita lejantına göre)
// Kod örneği: "B11.3 K IVes" (eğim-bünye-derinlik + büyük toprak grubu + arazi kabiliyeti)
// -------------------------

const SOIL_GROUPS = {
  // (Lejanttaki büyük toprak grupları / sık kullanılanlar)
  P: 'Kırmızı Sarı Podzolik Topraklar',
  G: 'Gri Kahverengi Podzolik Topraklar',
  M: 'Kahverengi Orman Toprakları',
  N: 'Kireçsiz Kahverengi Orman Toprakları',
  C: 'Kestanerengi Topraklar',
  D: 'Kırmızımsı Kestanerengi Topraklar',
  T: 'Kırmızı Akdeniz Toprakları',
  E: 'Kırmızı Kahverengi Akdeniz Toprakları',
  B: 'Kahverengi Topraklar',
  U: 'Kireçsiz Kahverengi Topraklar (diğer)',
  F: 'Kırmızımsı Kahverengi Topraklar',
  R: 'Rendzinalar',
  V: 'Vertisoller',
  Z: 'Sierozemler',
  L: 'Regosoller',
  X: 'Bazaltik Topraklar',
  Y: 'Yüksek Dağ Çayır Toprakları',
  // (Lejantta ayrıca geçen özel gruplar)
  H: 'Hidromorfik Alüvyal Topraklar',
  S: 'Alüvyal Sahil Bataklıkları',
  K: 'Kolüvyal Topraklar',
  'Ç': 'Tuzlu-Alkali ve Tuzlu-Alkali Karisik Topraklar',
  O: 'Organik Topraklar'
};

const SLOPE_CLASSES = {
  A: '0-2% (düz / çok az eğimli)',
  B: '2-6% (hafif eğimli)',
  C: '6-12% (orta eğimli)',
  D: '12-20% (eğimli)',
  E: '20-30% (çok eğimli)',
  F: '30%+ (dik)'
};

const DEPTH_CLASSES = {
  derin: 'Derin (90+ cm)',
  orta: 'Orta derin (50-90 cm)',
  sig: 'Sığ (20-50 cm)',
  coksig: 'Çok sığ (0-20 cm)',
  lito: 'Litozolik (anakaya çok yakın)'
};

// Eğim-bünye-derinlik kombinasyon tablosundan (lejant görselindeki numaralar)
function decodeEbdCode(n){
  const num = Number(String(n||'').replace(/[^0-9]/g,''));
  if(!Number.isFinite(num) || num<=0) return null;

  // 1-27: A/B/C eğim + (ince/orta/kaba) + (derin/orta/sığ)
  // 28-31: D eğim (%12-20) + "çeşitli" + (derin/orta/sığ/çok sığ)
  // 32-35: litozolik (A/B/C/D)
  if(num >= 1 && num <= 27){
    const block = Math.floor((num-1)/9); // 0:A, 1:B, 2:C
    const within = (num-1)%9;            // 0..8
    const texBlock = Math.floor(within/3); // 0:ince,1:orta,2:kaba
    const depthIdx = within%3;             // 0:derin,1:orta,2:sığ

    const slope = ['A','B','C'][block];
    const texture = ['İnce','Orta','Kaba'][texBlock];
    const depthKey = ['derin','orta','sig'][depthIdx];
    return {
      code: num,
      slope,
      slopeText: SLOPE_CLASSES[slope] || String(slope),
      texture,
      depthText: DEPTH_CLASSES[depthKey]
    };
  }

  if(num >= 28 && num <= 31){
    const depthKey = ['derin','orta','sig','coksig'][num-28];
    return {
      code: num,
      slope: 'D',
      slopeText: SLOPE_CLASSES.D,
      texture: 'Çeşitli',
      depthText: DEPTH_CLASSES[depthKey]
    };
  }

  if(num >= 32 && num <= 35){
    const slope = ['A','B','C','D'][num-32];
    return {
      code: num,
      slope,
      slopeText: SLOPE_CLASSES[slope] || String(slope),
      texture: '-',
      depthText: DEPTH_CLASSES.lito
    };
  }
  return { code: num, slope: '-', slopeText: '-', texture: '-', depthText: '-' };
}

const EROSION_WATER = {
  1: 'Hiç veya çok az',
  2: 'Orta',
  3: 'Şiddetli',
  4: 'Çok şiddetli'
};

const SOIL_OTHER = {
  h: 'Hafif tuzlu',
  s: 'Tuzlu',
  a: 'Alkali',
  k: 'Hafif tuzlu-alkali',
  v: 'Tuzlu-alkali',
  t: 'Taşlı',
  r: 'Kayalı',
  y: 'Yetersiz drenaj',
  f: 'Kötü drenajlı'
};

const LAND_CAP_SUB = {
  e: 'Erozyon sınırlayıcı',
  w: 'Islaklık / drenaj sınırlayıcı',
  s: 'Toprak (derinlik-bünye-taşlılık vb.) sınırlayıcı',
  c: 'İklim / iklimsel sınırlayıcı'
};

function decodeLandCapability(token){
  const raw = String(token||'').trim();
  const m = raw.match(/^([IVX]{1,4})([a-zA-Z]*)$/);
  if(!m) return null;
  const cls = m[1];
  const subs = (m[2]||'').toLowerCase().split('').filter(Boolean);
  const subText = subs.map(s=>LAND_CAP_SUB[s]).filter(Boolean);
  return { cls, subs, subText };
}

function decodeSoilCode(rawCode){
  const raw = String(rawCode||'').trim();
  if(!raw) return null;

  const tokens = raw.replace(/\s+/g,' ').split(' ').filter(Boolean);
  // 1) Eğim-bünye-derinlik + erozyon (ör: B11.3)
  let ebdTok = tokens.find(t=>/^[A-F][0-9]{1,2}(\.[0-9])?$/.test(t)) || null;
  const ebd = ebdTok ? {
    slope: ebdTok[0],
    code: Number((ebdTok.match(/^[A-F]([0-9]{1,2})/)||[])[1] || NaN),
    erosion: Number((ebdTok.match(/\.(\d)$/)||[])[1] || NaN)
  } : null;
  const ebdDetail = ebd ? decodeEbdCode(ebd.code) : null;

  // 2) Büyük toprak grubu: tek harf (ör: K)
  const groupTok = tokens.find(t=>/^[A-ZÇĞİÖŞÜ]$/.test(t) && SOIL_GROUPS[t]) || null;

  // 3) Arazi kullanma kabiliyeti: Roma rakamı + alt sınıf (örn IVes)
  const capTok = tokens.find(t=>/^[IVX]{1,4}[A-Za-z]*$/.test(t)) || null;
  const cap = capTok ? decodeLandCapability(capTok) : null;

  // 4) Diğer toprak özellikleri: kod içinde tek harflerle geçebilir (h, s, a, k, v, t, r, y, f)
  // (Örn: "M 11 t.2" gibi desenler görülebiliyor; buradan sadece harfleri yakalıyoruz.)
  const otherLetters = Array.from(new Set((raw.match(/[hsakvtryf]/gi) || []).map(x=>x.toLowerCase())));
  const other = otherLetters.map(k=>({ k, text: SOIL_OTHER[k] })).filter(x=>x.text);

  return {
    raw,
    ebdTok,
    slope: ebd?.slope || (ebdDetail?.slope),
    slopeText: SLOPE_CLASSES[ebd?.slope] || ebdDetail?.slopeText || null,
    ebdDetail,
    erosionDeg: Number.isFinite(ebd?.erosion) ? ebd.erosion : null,
    erosionText: Number.isFinite(ebd?.erosion) ? (EROSION_WATER[ebd.erosion] || String(ebd.erosion)) : null,
    groupTok,
    groupText: groupTok ? SOIL_GROUPS[groupTok] : null,
    capTok,
    cap,
    other
  };
}

function getParcelClimateDiagnostics(parcelId){
  const rows = (Array.isArray(STATE.climateMonthlyRows) ? STATE.climateMonthlyRows : []).filter(r => String(r.parcel_id || r.parsel_id || '') === String(parcelId || ''));
  if(!rows.length) return null;
  const years = Array.from(new Set(rows.map(r=>monthKeyToYear(r.month)).filter(y=>isFinite(y)))).sort((a,b)=>a-b);
  const selectedYear = isFinite(+STATE.selectedWaterYear) && years.includes(+STATE.selectedWaterYear) ? +STATE.selectedWaterYear : years[years.length-1];
  const filtered = rows.filter(r => monthKeyToYear(r.month) === selectedYear);
  if(!filtered.length) return null;
  const activeMonths = filtered.filter(r => safeNum(r.et0_mm ?? r.eto_mm ?? r.et0,0) > 80 || safeNum(r.tavg_c ?? r.tavg ?? r.t_mean_c,0) >= 10);
  const first = activeMonths[0]?.month;
  const last = activeMonths[activeMonths.length-1]?.month;
  const frostMin = Math.min(...filtered.map(r => safeNum(r.tmin_c ?? r.tmin, 99)).filter(v=>isFinite(v)));
  const frost = frostMin <= -5 ? 'Yüksek' : (frostMin <= 0 ? 'Orta' : 'Düşük');
  const label = first && last ? `${monthLabelFromKey(first)} - ${monthLabelFromKey(last)}` : 'Yıl geneli';
  return { selectedYear, frostMin, frost, seasonLabel: label };
}

function monthLabelFromKey(k){
  const d = new Date(k);
  const arr = ['Ocak','Şubat','Mart','Nisan','Mayıs','Haziran','Temmuz','Ağustos','Eylül','Ekim','Kasım','Aralık'];
  return isNaN(d) ? String(k || '-') : arr[d.getMonth()];
}

function renderParcelSummary() {
  const p = parcelData.find((x) => x.id === selectedParcelId);
  if (!p || !parcelSummaryBody) return;

  const climateRaw = p.climate || {};
  const climate = {
    rain_mm: (climateRaw.rain_mm ?? climateRaw.rain ?? climateRaw.rainfall_mm ?? '-'),
    eto_mm:  (climateRaw.eto_mm  ?? climateRaw.eto  ?? climateRaw.eto_total_mm ?? '-'),
    t_avg:   (climateRaw.t_avg   ?? climateRaw.tavg ?? climateRaw.t_mean_c),
    sourceYears: safeNum(climateRaw.source_years, 1),
    periodLabel: String(climateRaw.period_label || '').trim()
  };
  const climateDiag = getParcelClimateDiagnostics(p.id);
  const soilCode = (p.soil && (p.soil.code || p.soil.soilCode)) ? String(p.soil.code || p.soil.soilCode).trim() : '';
  const decoded = decodeSoilCode(soilCode);
  const climateSource = (STATE.weatherSource === 'openmeteo' && Array.isArray(STATE.weatherDaily) && STATE.weatherDaily.length)
    ? `Canlı meteoroloji (${STATE.weatherStart || 'başlangıç'} → ${STATE.weatherEnd || 'bitiş'})`
    : `Yüklenen iklim serisi${climate.periodLabel ? ` • ${climate.periodLabel}` : ''}`;

  const soilHighlights = [];
  if(decoded?.groupText) soilHighlights.push(`<div class="parcel-kv"><span>Toprak grubu</span><strong>${escapeHtml(decoded.groupText)}</strong></div>`);
  if(decoded?.capTok) soilHighlights.push(`<div class="parcel-kv"><span>Arazi kabiliyeti</span><strong>${escapeHtml(decoded.capTok)}</strong></div>`);
  if(decoded?.erosionText) soilHighlights.push(`<div class="parcel-kv"><span>Erozyon</span><strong>${escapeHtml(decoded.erosionText)}</strong></div>`);
  if(decoded?.ebdDetail?.texture) soilHighlights.push(`<div class="parcel-kv"><span>Bünye / derinlik</span><strong>${escapeHtml(decoded.ebdDetail.texture)} • ${escapeHtml(decoded.ebdDetail.depthText)}</strong></div>`);

  const role = STATE.currentUser?.role || 'institution';
  const statusBadge = p.frontend_custom ? `<span class="parcel-mini-badge is-custom">Kullanıcı kaydı</span>` : (p.frontend_override ? `<span class="parcel-mini-badge is-override">Yönetici güncelledi</span>` : `<span class="parcel-mini-badge">Resmî kayıt</span>`);
  parcelSummaryBody.innerHTML = `
    <div class="parcel-summary-shell ${role === 'farmer' ? 'is-farmer' : 'is-institution'}">
      <div class="parcel-summary-hero">
        <div>
          <div class="parcel-summary-kicker">Seçili parsel</div>
          <div class="parcel-summary-title-row">
            <h3>${escapeHtml(p.name || p.id)}</h3>
            ${statusBadge}
          </div>
          <div class="parcel-summary-sub">${escapeHtml(p.village || '-')} • ${escapeHtml(p.district || '-')}</div>
        </div>
        <div class="parcel-summary-area">
          <span>Toplam alan</span>
          <strong>${Number(safeNum(p.area_da,0)).toLocaleString('tr-TR',{maximumFractionDigits:1})} da</strong>
        </div>
      </div>

      <div class="parcel-summary-grid">
        <div class="parcel-summary-stat water">
          <span>Mevcut yıllık su kullanımı</span>
          <strong>${Math.round(safeNum(p.water_m3,0)).toLocaleString('tr-TR')} m³</strong>
          <small>Seçili referans desene göre</small>
        </div>
        <div class="parcel-summary-stat profit">
          <span>Mevcut yıllık net kâr</span>
          <strong>${Math.round(safeNum(p.profit_tl,0)).toLocaleString('tr-TR')} TL</strong>
          <small>Parsel referansı</small>
        </div>
        <div class="parcel-summary-stat climate">
          <span>Yıllık yağış / ETo</span>
          <strong>${isFinite(+climate.rain_mm)?Math.round(+climate.rain_mm):'-'} mm / ${isFinite(+climate.eto_mm)?Math.round(+climate.eto_mm):'-'} mm</strong>
          <small>${escapeHtml(climateSource)}</small>
        </div>
      </div>

      <div class="parcel-summary-panels">
        <section class="parcel-summary-panel">
          <div class="parcel-panel-head">
            <h4>Toprak özeti</h4>
            <span>${soilCode ? `Kod: ${escapeHtml(soilCode)}` : 'Kod yok'}</span>
          </div>
          <div class="parcel-kv-grid">${soilHighlights.length ? soilHighlights.join('') : '<div class="small muted">Toprak kodu bulunamadı. Detaylı toprak yorumu için veri setine kod eklenmelidir.</div>'}</div>
          ${decoded ? `<details class="mini-details"><summary>Kod çözümü / detay</summary><div class="small muted" style="margin-top:6px;">Kod: <code>${escapeHtml(decoded.raw)}</code></div></details>` : ''}
        </section>
        <section class="parcel-summary-panel">
          <div class="parcel-panel-head"><h4>İklim özeti</h4><span>${escapeHtml(String(climateDiag?.selectedYear || climate.periodLabel || 'Seçili dönem'))}</span></div>
          <div class="parcel-kv-grid">
            <div class="parcel-kv"><span>Ortalama sıcaklık</span><strong>${Number.isFinite(climate.t_avg)? Number(climate.t_avg).toFixed(1) : '-'} °C</strong></div>
            <div class="parcel-kv"><span>Don riski</span><strong>${escapeHtml(climateDiag?.frost || 'Bilinmiyor')}</strong></div>
            <div class="parcel-kv"><span>Büyüme sezonu</span><strong>${escapeHtml(climateDiag?.seasonLabel || 'Bilinmiyor')}</strong></div>
            <div class="parcel-kv"><span>Veri kapsamı</span><strong>${climate.sourceYears > 1 ? `${climate.sourceYears} yıl ortalaması` : 'Tek yıl / seçili dönem'}</strong></div>
          </div>
        </section>
      </div>
    </div>
  `;
}

// Mevcut / önerilen tabloları doldur

// -------------------------
// Optimizasyon motoru (GA / ABC / ACO)
// Amaç: senaryoya göre (su_tasarruf / maks_kar) parsel alanını ürünler arasında paylaştırmak
// Not: Bu demo sürümünde 8-11 ürün arasından optimizasyon yapılır. İleride gerçek ürün-çeşit veri seti ile genişletilir.
// -------------------------

function clamp(v, a, b){ return Math.max(a, Math.min(b, v)); }

// Türkçe yerel ayarlarda ondalık ayırıcı virgül olabildiği için güvenli sayı ayrıştırma
function parseNumFlex(v, fallback){
  if(v===undefined || v===null) return fallback;
  const s = String(v).trim().replace(',', '.');
  const n = Number(s);
  return Number.isFinite(n) ? n : fallback;
}

function normalizeVec(x){
  const s = x.reduce((acc,v)=>acc+Math.max(0,v),0);
  if(!s) return x.map(()=>1/x.length);
  return x.map(v=>Math.max(0,v)/s);
}

function vecToRows(areaDa, crops, x){
  // x: proportions
  const xN = normalizeVec(x);
  // area rounding
  let rows = crops.map((c,i)=>({
    name: c.name,
    area: +(areaDa * xN[i]).toFixed(1),
    waterPerDa: c.waterPerDa,
    profitPerDa: c.profitPerDa,
  }));
  // Fix rounding so sum equals areaDa
  const sumArea = rows.reduce((a,r)=>a+r.area,0);
  const diff = +(areaDa - sumArea).toFixed(1);
  if(Math.abs(diff) >= 0.1){
    // adjust largest area crop
    let j = 0;
    for(let i=1;i<rows.length;i++) if(rows[i].area > rows[j].area) j=i;
    rows[j].area = +(rows[j].area + diff).toFixed(1);
  }
  rows = rows.filter(r=>r.area > 0.0);
  rows.forEach(r=>{
    r.totalWater = r.area * r.waterPerDa;
    r.totalProfit = r.area * r.profitPerDa;
  });
  return rows;
}

function sumMetrics(rows){
  const totalArea = rows.reduce((a,r)=>a+r.area,0);
  const totalWater = rows.reduce((a,r)=>a+r.totalWater,0);
  const totalProfit = rows.reduce((a,r)=>a+r.totalProfit,0);
  return { area: totalArea, water: totalWater, profit: totalProfit, totalArea, totalWater, totalProfit };
}

// --- v54: Sulama randımanı (yöntem bazlı) ---
// Basit varsayımlar: yüzey/karık düşük, yağmurlama orta, damla yüksek.
const IRR_EFF = { surface:0.55, sprinkler:0.70, drip:0.90, pivot:0.80, rainfed:1.00 };
function deliveredWaterPerDa(baseWaterPerDa, irrKey){
  // Koruma: ölçek hatasıyla gelen aşırı büyük değerleri UI'da patlatma.
  const w = clamp(safeNum(baseWaterPerDa), 0, 3000);
  const k = irrKey || 'sprinkler';
  if(k === 'rainfed') return w * 0.20; // destek sulaması varsayımı
  const eff = IRR_EFF[k] || (STATE.irrigEfficiency ?? 0.62);
  return w / Math.max(0.35, eff);
}

// Öneri sulama yöntemi: karık/salma -> damla (sebzede), kuru tahıl -> yağmurlama (destek),
// pivot/yağmurlama -> damla (yüksek su tasarrufu hedefinde)
function recommendedIrrKeyForCrop(cropName, currentKey){
  const nm = (cropName||'').toLowerCase();
  if(currentKey === 'rainfed') return 'sprinkler';
  if(nm.includes('buğday') || nm.includes('arpa') || nm.includes('çavdar')) return currentKey === 'rainfed' ? 'sprinkler' : 'sprinkler';
  // sebze/endüstri bitkilerinde damla hedef
  if(currentKey === 'surface' || currentKey === 'sprinkler' || currentKey === 'pivot') return 'drip';
  return 'drip';
}

function irrigationLabel(key){
  if(key==='drip') return 'Damla';
  if(key==='sprinkler') return 'Yağmurlama';
  if(key==='surface') return 'Karık/Salma';
  if(key==='pivot') return 'Pivot/Lineer';
  if(key==='rainfed') return 'Yağışa bağlı';
  return String(key||'-');
}

function isBlankSeasonLabel(v){
  const s = String(v ?? '').trim().toLowerCase();
  return !s || s==='-' || s==='-' || s==='nan' || s==='undefined' || s==='null';
}

function getCropCatalogEntry(cropName){
  const key = normCropName(cropName || '');
  return (STATE.cropCatalog && STATE.cropCatalog[key]) ? STATE.cropCatalog[key] : null;
}

function irrigationMethodMeta(methodKey){
  const map = { surface:'surface_furrow', sprinkler:'sprinkler', drip:'drip', pivot:'sprinkler', rainfed:'surface_furrow' };
  const wanted = map[String(methodKey || '').trim()] || String(methodKey || '').trim();
  return (STATE.irrigMethods || []).find(r => String(r.method || '').trim() === wanted) || {
    method: wanted, capex_tl_per_da: 0, opex_tl_per_da: 0, typical_total_efficiency: IRR_EFF[methodKey] || 0.62
  };
}

function costBreakdownRuleFor(parcelType, category, cropName=''){
  const rows = Array.isArray(STATE.costBreakdownRules) ? STATE.costBreakdownRules : [];
  const pt = String(parcelType || '').trim().toLowerCase();
  const cat = String(category || '').trim().toLowerCase();
  const crop = String(cropName || '').trim().toLowerCase();
  let hit = rows.find(r => String(r.parcel_type || '').trim().toLowerCase() === pt && String(r.crop || '').trim().toLowerCase() === crop && crop);
  if(!hit) hit = rows.find(r => String(r.parcel_type || '').trim().toLowerCase() === pt && String(r.category || '').trim().toLowerCase() === cat && cat && !String(r.crop || '').trim());
  if(!hit) hit = rows.find(r => String(r.parcel_type || '').trim().toLowerCase() === pt && !String(r.category || '').trim() && !String(r.crop || '').trim());
  if(!hit) hit = rows.find(r => String(r.parcel_type || '').trim().toLowerCase() === 'default');
  return hit || null;
}

function inferParcelTypeForUi(row, parcel){
  const cat = getCropCatalogEntry(row?.name || '');
  return String(cat?.parcelType || row?.parcelType || parcel?.parcel_type || '').trim().toLowerCase() || (isPerennialCropName(row?.name || '') ? 'orchard' : 'field');
}

function computeRowEconomics(row, parcel, methodKey, baselineMethodKey){
  const cat = getCropCatalogEntry(row?.name || '') || {};
  const area = safeNum(row?.area, 0);
  const baseWaterPerDa = safeNum(row?._baseWaterPerDa, 0) || safeNum(row?.waterPerDa, 0);
  const appliedMethod = methodKey || row?.irrigationSuggestedKey || row?.irrigationCurrentKey || irrigationKeysForCrop(row?.name || '').suggestedKey || 'sprinkler';
  const baselineMethod = baselineMethodKey || row?._baselineMethodKey || row?.irrigationSuggestedKey || row?.irrigationCurrentKey || appliedMethod;
  const methodMeta = irrigationMethodMeta(appliedMethod);
  const baselineMethodMeta = irrigationMethodMeta(baselineMethod);
  const waterPerDa = deliveredWaterPerDa(baseWaterPerDa, appliedMethod);
  const totalWater = area * waterPerDa;

  const priceTlKg = safeNum(cat.price_tl_kg ?? cat.priceTlPerKg, 0);
  const yieldKgDa = safeNum(cat.yield_kg_da ?? cat.yieldKgPerDa, 0);
  const supportTlDa = safeNum(cat.support_tl_da ?? cat.supportTlPerDa, 0);
  const hasMarketBasis = yieldKgDa > 0 && priceTlKg > 0;
  const grossDa = hasMarketBasis ? (safeNum(cat.grossRevenueTlPerDa, 0) || (yieldKgDa * priceTlKg)) : 0;
  const grossRevenue = hasMarketBasis ? (area * grossDa) : NaN;
  const baselineNet = safeNum(row?.totalProfit, 0) || (area * safeNum(row?.profitPerDa, 0));
  const baselineIrrigationOpexTotal = area * safeNum(baselineMethodMeta.opex_tl_per_da, 0);
  const irrigationOpexTotal = area * safeNum(methodMeta.opex_tl_per_da, 0);
  const targetNet = baselineNet - (irrigationOpexTotal - baselineIrrigationOpexTotal);
  const catalogTotalCost = area * safeNum(cat.cost_tl_da ?? cat.costTlPerDa ?? cat.var_cost_tl_da ?? cat.varCostTlPerDa, 0);
  let totalCost = NaN;
  if(hasMarketBasis){
    totalCost = Math.max(catalogTotalCost, grossRevenue + (area * supportTlDa) - targetNet);
    if(!isFinite(totalCost)) totalCost = catalogTotalCost || 0;
  }

  const remainingCost = hasMarketBasis ? Math.max(0, totalCost - irrigationOpexTotal) : 0;
  const parcelType = inferParcelTypeForUi(row, parcel);
  const rule = costBreakdownRuleFor(parcelType, cat.category || '', row?.name || '');
  const shares = rule || {};
  const defaultParts = [
    ['Tohum / fide / fidan', 0.14],
    ['Gübre', 0.18],
    ['İlaç / bitki koruma', 0.10],
    ['Toprak işleme', 0.14],
    ['İşçilik / bakım', 0.20],
    ['Hasat / paketleme', 0.14],
    ['Diğer', 0.10],
  ];
  const rawParts = [
    ['Tohum / fide / fidan', safeNum(shares.seed_fidan_share, 0.14)],
    ['Gübre', safeNum(shares.fertilizer_share, 0.18)],
    ['İlaç / bitki koruma', safeNum(shares.pesticide_share, 0.10)],
    ['Toprak işleme', safeNum(shares.tillage_share, 0.14)],
    ['İşçilik / bakım', safeNum(shares.labor_maintenance_share, 0.20)],
    ['Hasat / paketleme', safeNum(shares.harvest_packaging_share, 0.14)],
    ['Diğer', safeNum(shares.other_share, 0.10)],
  ];
  const rawShareSum = rawParts.reduce((s, x) => s + Math.max(0, safeNum(x[1], 0)), 0);
  const parts = rawShareSum > 1e-9 ? rawParts : defaultParts;
  const sumShare = Math.max(1e-9, parts.reduce((s, x) => s + x[1], 0));
  const breakdown = hasMarketBasis
    ? parts.map(([label, share]) => ({ label, amount: remainingCost * (share / sumShare) }))
    : [{ label:'Net kâr kaydı / proxy', amount: targetNet }];
  breakdown.push({ label:'Sulama işletme', amount: irrigationOpexTotal });

  return {
    crop: prettyCropName(row?.name || '-'),
    season: !isBlankSeasonLabel(row?.season) ? row.season : inferSeasonLabelFromCrop(row?.name || '', parcel?.parcel_type || ''),
    methodKey: appliedMethod,
    methodLabel: irrigationLabel(appliedMethod),
    areaDa: area,
    priceTlKg,
    yieldKgDa,
    totalProductionKg: area * yieldKgDa,
    grossRevenueTl: grossRevenue,
    totalCostTl: totalCost,
    totalNetProfitTl: targetNet,
    supportTotalTl: area * supportTlDa,
    waterPerDa,
    totalWaterM3: totalWater,
    waterCostTlPerM3: totalWater > 0 ? (irrigationOpexTotal / totalWater) : 0,
    tlPerM3: totalWater > 0 ? (targetNet / totalWater) : 0,
    breakdown,
    operationsNote: String(rule?.operations_note || '').trim(),
    parcelType,
    category: String(cat.category || '').trim(),
    capexTlPerDa: safeNum(methodMeta.capex_tl_per_da, 0),
    opexTlPerDa: safeNum(methodMeta.opex_tl_per_da, 0),
    dataNote: String(cat.sourceNote || '').trim(),
    hasMarketBasis,
    economicsNote: hasMarketBasis
      ? String(cat.sourceNote || '2024 fiyat/verim/gider kataloğu').trim()
      : 'Bu ürün için 2024 fiyat-verim-gider satırı bulunamadı; net kâr öneri/desen satırındaki TL/da değerinden proxy olarak gösterildi.',
  };
}

function renderBusinessMetrics(currentRows, recRows, parcel, objectiveKey){
  const box = document.getElementById('businessMetricsBox');
  if(!box) return;
  const current = Array.isArray(currentRows) ? currentRows : [];
  const rec = Array.isArray(recRows) ? recRows : [];
  if(!current.length){
    box.innerHTML = '<div class="small muted">Ekonomik dayanak için önce parsel verisi yüklenmelidir.</div>';
    return;
  }

  const buildTable = (rows, title, mode)=>{
    const econRows = rows.map(r => computeRowEconomics(
      r,
      parcel,
      mode==='recommended' ? (r.irrigationSuggestedKey || irrigationKeysForCrop(r.name).suggestedKey) : (r.irrigationCurrentKey || irrigationKeysForCrop(r.name).currentKey),
      mode==='recommended' ? (r.irrigationSuggestedKey || irrigationKeysForCrop(r.name).suggestedKey) : (r.irrigationCurrentKey || irrigationKeysForCrop(r.name).currentKey)
    ));
    const totals = econRows.reduce((acc, r)=>{
      acc.area += r.areaDa;
      if(r.hasMarketBasis){
        acc.known += 1;
        acc.prod += safeNum(r.totalProductionKg, 0);
        acc.gross += safeNum(r.grossRevenueTl, 0);
        acc.cost += safeNum(r.totalCostTl, 0);
      }
      acc.net += safeNum(r.totalNetProfitTl, 0);
      acc.water += safeNum(r.totalWaterM3, 0);
      return acc;
    }, {area:0, prod:0, gross:0, cost:0, net:0, water:0, known:0});
    const lead = econRows[0] || null;
    const money = (v, known=true)=> known ? Math.round(safeNum(v,0)).toLocaleString('tr-TR') : '<span class="muted">Veri yok</span>';
    const num = (v, digits=1, known=true)=> known ? safeNum(v,0).toLocaleString('tr-TR', { maximumFractionDigits: digits }) : '<span class="muted">Veri yok</span>';
    const breakdownHtml = lead ? `<div class="business-breakdown"><strong>${escapeHtml(lead.crop)} için ${lead.hasMarketBasis ? 'gider dağılımı' : 'ekonomik kaynak notu'}</strong><table class="data-table business-table compact" style="margin-top:6px;"><thead><tr><th>Kalem</th><th>Tutar (TL)</th></tr></thead><tbody>${lead.breakdown.map(b=>`<tr><td>${escapeHtml(b.label)}</td><td>${Math.round(safeNum(b.amount,0)).toLocaleString('tr-TR')}</td></tr>`).join('')}</tbody></table><div class="muted" style="margin-top:6px;">${escapeHtml(lead.hasMarketBasis ? (lead.operationsNote || 'Toprak işleme, ekim/dikim, gübreleme, ilaçlama, sulama, bakım ve hasat işlemleri 2024 gider toplamı üzerinden oranlanmıştır.') : lead.economicsNote)}</div></div>` : '';
    return `<div class="mini-block business-metrics-card"><h4 style="margin:0 0 8px 0">${escapeHtml(title)}</h4><div class="business-table-wrap"><table class="data-table business-table"><thead><tr><th>Ürün</th><th>Alan (da)</th><th>Verim (kg/da)</th><th>2024 fiyat (TL/kg)</th><th>Toplam üretim (kg)</th><th>Brüt hasılat</th><th>Toplam gider</th><th>Net kâr</th><th>Su (m³)</th><th>TL/m³</th><th>Sulama</th></tr></thead><tbody>${econRows.map(r=>`<tr><td><strong>${escapeHtml(r.crop)}</strong><div class="small muted">${escapeHtml(r.season || '-')}</div>${!r.hasMarketBasis ? `<div class="small muted">Ekonomik dayanak: proxy net kâr</div>` : ''}</td><td>${r.areaDa.toFixed(1)}</td><td>${num(r.yieldKgDa,1,r.hasMarketBasis)}</td><td>${num(r.priceTlKg,2,r.hasMarketBasis)}</td><td>${money(r.totalProductionKg,r.hasMarketBasis)}</td><td>${money(r.grossRevenueTl,r.hasMarketBasis)}</td><td>${money(r.totalCostTl,r.hasMarketBasis)}</td><td>${Math.round(safeNum(r.totalNetProfitTl,0)).toLocaleString('tr-TR')}</td><td>${Math.round(safeNum(r.totalWaterM3,0)).toLocaleString('tr-TR')}</td><td>${r.tlPerM3.toFixed(2)}</td><td>${escapeHtml(r.methodLabel)}<div class="small muted">İşletme: ${r.opexTlPerDa.toFixed(0)} TL/da • ${r.waterCostTlPerM3.toFixed(2)} TL/m³</div></td></tr>`).join('')}</tbody><tfoot><tr><th>Toplam</th><th>${totals.area.toFixed(1)}</th><th>-</th><th>-</th><th>${totals.known ? Math.round(totals.prod).toLocaleString('tr-TR') : 'Veri yok'}</th><th>${totals.known ? Math.round(totals.gross).toLocaleString('tr-TR') : 'Veri yok'}</th><th>${totals.known ? Math.round(totals.cost).toLocaleString('tr-TR') : 'Veri yok'}</th><th>${Math.round(totals.net).toLocaleString('tr-TR')}</th><th>${Math.round(totals.water).toLocaleString('tr-TR')}</th><th>${(totals.net/Math.max(1,totals.water)).toFixed(2)}</th><th>-</th></tr></tfoot></table></div>${breakdownHtml}</div>`;
  };

  const note = `<div class="small muted" style="margin-bottom:10px;">Bu ekonomik özet 2024 ürün fiyatı, verim, parsel alanı, toplam su ve gider kalemlerini aynı yerde gösterir. Tablo küçük ekranda daralmaz; yatay kaydırma ile okunur. Detaylı hastalık/mineral laboratuvar verisi projede olmadığı için karar mantığı şu anda su kotası, mevsim, familya/rotasyon, parsel tipi, toprak sınıfı ve sulama yöntemi üzerinden açıklanır.</div>`;
  box.innerHTML = `${note}<div class="official-grid business-grid">${buildTable(current, 'Mevcut desen - ekonomik dayanak', 'current')}${rec.length ? buildTable(rec, `Önerilen desen - ekonomik dayanak (${getScenarioDisplayMeta(objectiveKey).label})`, 'recommended') : '<div class="mini-block"><div class="small muted">Öneri oluştuğunda ekonomik dayanak burada gösterilir.</div></div>'}</div>`;
}

function inferSeasonLabelFromCrop(cropName, parcelType=''){
  const nm = normCropName(cropName||'');
  const pt = String(parcelType||'').toLowerCase();
  if(pt === 'orchard' || isPerennialCropName(cropName||'')) return 'Çok yıllık / bahçe';
  if(/DOMATES|BIBER|KABAK|PATLICAN|HIYAR|KARPUZ|KAVUN|MISIR|PANCAR|PATATES|AYCICEGI|SOGAN|SARIMSAK|LAHANA|FASULYE|CILEK/.test(nm)) return 'Yazlık';
  if(/BUGDAY|ARPA|CAVDAR|YULAF|TRITIKALE|MERCIMEK|NOHUT|FIG|FIĞ|YEM_BEZELYESI/.test(nm)) return 'Kışlık / serin dönem';
  return 'Ana ürün';
}

function isMeaningfulCropRow(r){
  if(!r) return false;
  const name = String(r.name || '').trim();
  if(!name || name === '-' || name === '-' || name.toLowerCase() === 'nan' || name.toLowerCase() === 'undefined' || name.toLowerCase() === 'null') return false;
  const area = safeNum(r.area, 0);
  const water = safeNum(r.waterPerDa, 0);
  const profit = safeNum(r.profitPerDa, 0);
  return area > 0 || water > 0 || profit !== 0;
}

function sanitizePlanRows(rows, parcel){
  const seen = new Set();
  return (Array.isArray(rows) ? rows : []).filter(isMeaningfulCropRow).map(r=>{
    const key = `${normCropName(r.name||'')}|${String(r.season||'').trim()}|${safeNum(r.area,0).toFixed(2)}`;
    if(seen.has(key)) return null;
    seen.add(key);
    const season = String(r.season||'').trim() || inferSeasonLabelFromCrop(r.name, parcel?.parcel_type || '');
    const area = safeNum(r.area, safeNum(parcel?.area_da, 0));
    const waterPerDa = safeNum(r.waterPerDa, 0);
    const profitPerDa = safeNum(r.profitPerDa, 0);
    return {
      ...r,
      season,
      area,
      waterPerDa,
      profitPerDa,
      totalWater: safeNum(r.totalWater, area * waterPerDa),
      totalProfit: safeNum(r.totalProfit, area * profitPerDa),
    };
  }).filter(Boolean);
}

// Crop -> irrigation mapping (from backend meta: data/crop_irrigation_map.json)
// In the "Önerilen Ürün Deseni" table we show only the best (improved) irrigation suggestion
// compared to the current/default method. We intentionally do not expose all irrigation
// methods as a dropdown.

function _normIrrLookupKeys(cropName){
  const raw = String(cropName||'');
  const k1 = raw;
  const k2 = normCropName(raw);
  const k3 = normCropKey(raw);
  const k4 = normCropKey(raw).replace(/[()]/g,' ').replace(/\s+/g,' ').trim();
  const k5 = normCropKey(raw).replace(/[()]/g,' ').replace(/\s+/g,'_').trim();
  const k6 = normCropKey(raw).replace(/[()]/g,'_').replace(/\s+/g,'_').trim();
  // also try internal style: spaces->underscore
  const k7 = k2.replace(/\s+/g,'_');
  return [k1,k2,k3,k4,k5,k6,k7].filter(Boolean);
}

function irrigationKeysForCrop(cropName){
  const m = STATE.cropIrrigationMap || {};
  let rec = null;
  for(const k of _normIrrLookupKeys(cropName)){
    if(m && m[k]){ rec = m[k]; break; }
  }
  const currentKey = rec?.current || 'sprinkler';
  const suggestedKey = rec?.recommended || recommendedIrrKeyForCrop(cropName, currentKey);
  return { currentKey, suggestedKey };
}

function objectiveFitness(areaDa, crops, x, scenarioKey, currentTotals, parcel){
  // minimize: lower is better
  const xN = normalizeVec(x);

  const water = areaDa * xN.reduce((acc,xi,i)=>acc + xi*crops[i].waterPerDa, 0);

  // temel kâr
  let profit = areaDa * xN.reduce((acc,xi,i)=>acc + xi*crops[i].profitPerDa, 0);

  // köy/ilçe desen uyumu bonusu (TL)
  if(STATE.villagePatterns && STATE.districtPatterns && parcel){
    const bonus = areaDa * xN.reduce((acc,xi,i)=>{
      const cNorm = normCropName(crops[i].name);
      return acc + xi * contextBonusTlPerDa(parcel, cNorm);
    }, 0);
    profit += bonus;
  }

  // toprak/erozyon uygunluğu: bazı ürün tiplerine küçük ceza/bonus
  if(parcel && parcel.soil){
    const soilAdj = areaDa * xN.reduce((acc,xi,i)=>{
      const t = crops[i].type || cropTypeFromCategory(crops[i].category);
      return acc + xi * soilSuitabilityTlPerDa(parcel.soil, t);
    },0);
    profit += soilAdj;
  }

  // Constraints (soft penalties)
  let penalty = 0;

  // (A) Mutlak su bütçesi kısıtı (yaklaşık: alan oranına göre parsel bütçesi)
  const wBudget = parcelWaterBudget(areaDa, parcel);
  if(water > wBudget){
    const over = (water - wBudget) / Math.max(1, wBudget);
    penalty += over * 50.0; // güçlü ceza
  }

  // (A2) Kuraklık riski: su yoğun seçimlere ek ceza
  const r = clamp(STATE.droughtRisk ?? 0, 0, 1);
  penalty += r * (water / Math.max(1, wBudget)) * 2.5;

  // (B) Senaryo kısıtları (mevcut desene göre)
  // NOTE: UI/back-end may send scenario keys in different forms.
  // Normalize so optimization behaves consistently.
  const sk = normalizeScenarioKey(scenarioKey);
  const curW = safeNum(currentTotals?.totalWater ?? currentTotals?.water);
  const curP = safeNum(currentTotals?.totalProfit ?? currentTotals?.profit);

  if(sk === "water_saving"){
    // Farmer-first constraint: keep production profitable (allow some drop, but avoid collapse)
    const minProfit = curP * 0.85;
    if(curP > 0 && profit < minProfit) penalty += (minProfit - profit) / Math.max(1, minProfit) * 12.0;
    // Strongly discourage increasing water compared to current (drought reality)
    if(curW > 0 && water > curW) penalty += ((water - curW) / Math.max(1, curW)) * 30.0;
    // objective: reduce water
    return (water / Math.max(1, curW || wBudget)) + penalty;
  }

  if(sk === "water_efficiency"){
    const minProfit = curP * 0.78;
    if(curP > 0 && profit < minProfit) penalty += (minProfit - profit) / Math.max(1, minProfit) * 10.0;
    if(curW > 0 && water > curW * 1.03) penalty += ((water - curW * 1.03) / Math.max(1, curW)) * 18.0;
    const eff = profit / Math.max(1, water);
    const curEff = curP / Math.max(1, curW || wBudget);
    return -(eff / Math.max(0.01, curEff || 1)) + 0.35 * (water / Math.max(1, curW || wBudget)) - 0.15 * (profit / Math.max(1, curP || 1)) + penalty;
  }

  if(sk === "max_profit"){
    // Still respect water reality: don't exceed current too much
    const maxWater = curW * 1.10;
    if(curW > 0 && water > maxWater) penalty += (water - maxWater) / Math.max(1, maxWater) * 10.0;
    return (-(profit / Math.max(1, curP || 1))) + penalty;
  }

  if(sk === "balanced"){
    // Balanced: prefer less water while keeping profit reasonable
    const minProfit = curP * 0.75;
    if(curP > 0 && profit < minProfit) penalty += (minProfit - profit) / Math.max(1, minProfit) * 8.0;
    // weighted tradeoff
    return (water / Math.max(1, curW || wBudget)) - 0.25 * (profit / Math.max(1, curP || 1)) + penalty;
  }

  // current: no optimization, just feasibility penalties
  return 0 + penalty;
}

// GA: continuous proportions
function runGA(areaDa, crops, scenarioKey, currentTotals, parcel, opts={}){
  const n = crops.length;
  const popSize = opts.popSize ?? 40;
  const gens = opts.gens ?? 60;
  const elite = opts.elite ?? 4;
  const mutRate = opts.mutRate ?? 0.18;

  function randVec(){
    const x = Array.from({length:n}, ()=>Math.random());
    return normalizeVec(x);
  }

  function crossover(a,b){
    // blend crossover
    const child = a.map((v,i)=>{
      const t = Math.random();
      return t*v + (1-t)*b[i];
    });
    return normalizeVec(child);
  }

  function mutate(x){
    const y = x.slice();
    for(let i=0;i<n;i++){
      if(Math.random() < mutRate){
        y[i] = clamp(y[i] + (Math.random()-0.5)*0.35, 0, 1);
      }
    }
    return normalizeVec(y);
  }

  let pop = Array.from({length:popSize}, randVec);

  for(let g=0; g<gens; g++){
    const scored = pop.map(x=>({x, f: objectiveFitness(areaDa,crops,x,scenarioKey,currentTotals,parcel)}))
                      .sort((a,b)=>a.f-b.f);
    const next = scored.slice(0,elite).map(s=>s.x);
    while(next.length < popSize){
      // tournament selection
      const a = scored[Math.floor(Math.random()*Math.min(popSize,12))].x;
      const b = scored[Math.floor(Math.random()*Math.min(popSize,12))].x;
      let child = crossover(a,b);
      child = mutate(child);
      next.push(child);
    }
    pop = next;
  }

  const best = pop.map(x=>({x, f: objectiveFitness(areaDa,crops,x,scenarioKey,currentTotals,parcel)}))
                  .sort((a,b)=>a.f-b.f)[0].x;
  return best;
}

// ABC: Artificial Bee Colony (simplified for proportions)
function runABC(areaDa, crops, scenarioKey, currentTotals, parcel, opts={}){
  const n = crops.length;
  const foodCount = opts.foodCount ?? 25;
  const iters = opts.iters ?? 80;
  const limit = opts.limit ?? 20;

  function randVec(){ return normalizeVec(Array.from({length:n}, ()=>Math.random())); }

  let foods = Array.from({length:foodCount}, randVec);
  let trials = Array.from({length:foodCount}, ()=>0);

  function neighbor(x){
    const y = x.slice();
    const i = Math.floor(Math.random()*n);
    const k = Math.floor(Math.random()*n);
    const phi = (Math.random()*2 - 1); // [-1,1]
    y[i] = clamp(y[i] + phi*(y[i] - y[k]), 0, 1);
    return normalizeVec(y);
  }

  function fitnessVal(x){ return objectiveFitness(areaDa,crops,x,scenarioKey,currentTotals,parcel); }

  for(let t=0; t<iters; t++){
    // employed bees
    for(let j=0;j<foodCount;j++){
      const v = neighbor(foods[j]);
      if(fitnessVal(v) < fitnessVal(foods[j])){
        foods[j] = v; trials[j]=0;
      }else trials[j]++;
    }

    // onlooker selection (roulette on inverse fitness)
    const fits = foods.map(fitnessVal);
    const inv = fits.map(f=> 1/(1e-6 + Math.max(0, f + 1))); // keep positive
    const sumInv = inv.reduce((a,b)=>a+b,0);

    for(let o=0;o<foodCount;o++){
      let r = Math.random()*sumInv, pick=0;
      for(let j=0;j<foodCount;j++){ r -= inv[j]; if(r<=0){ pick=j; break; } }
      const v = neighbor(foods[pick]);
      if(fitnessVal(v) < fits[pick]){
        foods[pick] = v; trials[pick]=0;
      }else trials[pick]++;
    }

    // scout
    for(let j=0;j<foodCount;j++){
      if(trials[j] >= limit){
        foods[j] = randVec();
        trials[j] = 0;
      }
    }
  }

  let best = foods[0], bestF = fitnessVal(best);
  for(const x of foods){
    const f = fitnessVal(x);
    if(f < bestF){ best=x; bestF=f; }
  }
  return best;
}

// ACO: Ant Colony (discrete allocations with 20 units = 5% each)
function runACO(areaDa, crops, scenarioKey, currentTotals, parcel, opts={}){
  const n = crops.length;
  const ants = opts.ants ?? 30;
  const iters = opts.iters ?? 60;
  const units = opts.units ?? 20; // 5% resolution
  const evap = opts.evap ?? 0.15;

  // pheromone for each crop choice per unit position
  let tau = Array.from({length:units}, ()=>Array.from({length:n}, ()=>1.0));

  function heuristic(i){
    // scenario-dependent desirability
    if(scenarioKey === "su_tasarruf"){
      return 1/(1 + crops[i].waterPerDa); // less water better
    }
    if(normalizeScenarioKey(scenarioKey) === "water_efficiency"){
      return 1 + (crops[i].profitPerDa / Math.max(1, crops[i].waterPerDa)) / 30;
    }
    if(scenarioKey === "maks_kar"){
      return 1 + crops[i].profitPerDa/10000; // more profit better
    }
    // balanced (not used here)
    return 1;
  }
  const eta = crops.map((_,i)=>heuristic(i));

  function construct(){
    const counts = Array.from({length:n}, ()=>0);
    for(let u=0;u<units;u++){
      // probability proportional to tau^a * eta^b
      const a=1.0,b=2.0;
      const weights = tau[u].map((t,i)=>Math.pow(t,a)*Math.pow(eta[i],b));
      const sumW = weights.reduce((x,y)=>x+y,0);
      let r = Math.random()*sumW, pick=0;
      for(let i=0;i<n;i++){ r -= weights[i]; if(r<=0){ pick=i; break; } }
      counts[pick] += 1;
    }
    // proportions
    const x = counts.map(c=>c/units);
    return normalizeVec(x);
  }

  function fit(x){ return objectiveFitness(areaDa,crops,x,scenarioKey,currentTotals,parcel); }

  let globalBest = null, globalBestF = Infinity;

  for(let it=0; it<iters; it++){
    const solutions = [];
    for(let a=0;a<ants;a++){
      const x = construct();
      const f = fit(x);
      solutions.push({x,f});
      if(f < globalBestF){ globalBestF=f; globalBest=x; }
    }

    // evaporate
    for(let u=0;u<units;u++){
      for(let i=0;i<n;i++){
        tau[u][i] *= (1-evap);
        tau[u][i] = Math.max(0.01, tau[u][i]);
      }
    }

    // reinforce best few
    solutions.sort((a,b)=>a.f-b.f);
    const topK = Math.max(1, Math.floor(ants*0.15));
    for(let k=0;k<topK;k++){
      const x = solutions[k].x;
      const delta = 1/(1e-6 + Math.max(0, solutions[k].f + 1));
      for(let u=0;u<units;u++){
        for(let i=0;i<n;i++){
          tau[u][i] += delta * x[i];
        }
      }
    }
  }

  return globalBest ?? normalizeVec(Array.from({length:n}, ()=>1/n));
}


function getCandidateCropsForParcel(p){
  // Senaryo kaynağı önemlidir: Senaryo-2 seçildiğinde, sezon dosyalarında
  // bazı parsel/yıl kombinasyonları eksik olsa bile "anlaşılan ürün havuzu"
  // mutlaka adaylar içinde bulunmalıdır.
  const seasonSource = _seasonModeKey();

  // Senaryo-2: aday havuzu sadece mutabık ürünlerden oluşsun.
  // Sezon dosyası farklı ürünler içerebildiği için (domates/biber vs.)
  // bu modda "candidatesByParcel" kullanmıyoruz.
  if(seasonSource === 's2'){
    ensureScenario2Catalog();
    const catalog = STATE.cropCatalog || {};
    return (STATE.S2_PRIMARY_POOL || S2_PRIMARY_POOL || [])
      .filter(Boolean)
      .map(k=>({
        name: k,
        waterPerDa: clamp(safeNum(catalog[k]?.waterPerDa, S2_DEFAULT_PARAMS[k]?.waterPerDa || 0), 0, 3000),
        profitPerDa: clamp(safeNum(catalog[k]?.profitPerDa, S2_DEFAULT_PARAMS[k]?.profitPerDa || 0), -50000, 50000)
      }))
      .filter(c=>isFinite(c.waterPerDa) && isFinite(c.profitPerDa) && c.waterPerDa>=0);
  }

  // PRIMARY: use enhanced season candidates for this parcel *and selected year* (real data).
  // This makes parcel switching and year switching actually change recommendations.
  const pid = p?.id;
  const y = +STATE.selectedWaterYear;

  // 1) Year-specific candidates
  let m = null;
  if(STATE.candidatesByParcelYear && isFinite(y) && pid){
    const byParcel = STATE.candidatesByParcelYear.get(y);
    m = byParcel ? byParcel.get(pid) : null;
  }

  // 2) Fallback: all-years candidates
  if((!m || !m.size) && STATE.candidatesByParcel && pid){
    m = STATE.candidatesByParcel.get(pid);
  }
  if(m && m.size){
    const arr = [];
    for(const [ck,a] of m.entries()){
      const area = a.area || 1;
      const waterPerDa = a.water / area;
      const profitPerDa = a.profit / area;
      arr.push({ name: a.name || ck, waterPerDa, profitPerDa, irrigationText: a.irrigationText || '', irrigationKey: a.irrigationKey || '', parcelSpecific: true });
    }
    // Crop catalog parametreleri (Kc, ekonomi vb.)
    if(STATE.cropCatalog){
      for(const c of arr){
        const cat = STATE.cropCatalog[normCropName(c.name)];
        if(!cat) continue;

        // Su/da: eksikse katalogdan doldur
        // Only overwrite missing/invalid values. Do NOT treat 0 as invalid (dryland).
        if((!isFinite(c.waterPerDa) || c.waterPerDa<0) && isFinite(cat.waterPerDa) && cat.waterPerDa>=0){
          c.waterPerDa = cat.waterPerDa;
        }

        // Kâr/da: fiyat/teşvik yüklenmişse (override) katalogdaki kârı tercih et
        if(STATE.marketOverridesActive && cat._profit_overridden && isFinite(cat.profitPerDa)){
          c.profitPerDa = cat.profitPerDa;
        }else if((!isFinite(c.profitPerDa)) && isFinite(cat.profitPerDa)){
          c.profitPerDa = cat.profitPerDa;
        }

        // Dinamik meteoroloji aktifse: ET0/yağış + Kc ile sezonluk sulama ihtiyacını hesapla
        if(STATE.dynamicIrrigation){
          const irr = computeSeasonIrrigation(p, c.name);
          if(irr && irr.mode !== "none" && isFinite(irr.sumGross) && irr.sumGross>0){
            // sumGross (mm) ≈ m3/da
            const dyn = irr.sumGross;
            // çok sert sıçramaları azaltmak için harmanla
            const base = (isFinite(c.waterPerDa) && c.waterPerDa>0) ? c.waterPerDa : dyn;
            c.waterPerDa = 0.4*base + 0.6*dyn;
          }
        }
      }
    }
    // Senaryo-2: ürün havuzunu garanti et (meyve + tarla bitkileri)
    if(seasonSource === 's2'){
      const catalog = STATE.cropCatalog || {};
      const must = (STATE.S2_PRIMARY_POOL || []).filter(Boolean);
      const have = new Set(arr.map(x=>normCropName(x.name)));
      for(const ck of must){
        if(have.has(ck)) continue;
        const cat = catalog[ck];
        if(cat && isFinite(cat.waterPerDa) && isFinite(cat.profitPerDa)){
        arr.push({ name: ck, waterPerDa: cat.waterPerDa, profitPerDa: cat.profitPerDa, parcelSpecific: false });
        }
      }
    }

    // Allow dryland / rainfed candidates (waterPerDa can be 0).
    // Previously we filtered out waterPerDa==0 which removed cereals/legumes that can be grown
    // with minimal irrigation, leading to empty candidate sets and "0" results.
    return arr
      .map(c=>({
        ...c,
        // Aşırı uç değerleri (ölçek hataları) UI'da patlatmasın diye yumuşak tavan
        waterPerDa: clamp(safeNum(c.waterPerDa,0), 0, 3000),
        profitPerDa: clamp(safeNum(c.profitPerDa,0), -50000, 50000)
      }))
      .filter(c=>isFinite(c.waterPerDa) && isFinite(c.profitPerDa) && c.waterPerDa>=0);
  }

  // FALLBACK (should rarely happen): use global catalog
  let candidates = cropCatalog.slice();
  if(STATE.cropCatalog){
    candidates = candidates.map(c=>{
      const cat = STATE.cropCatalog[normCropName(c.name)];
      return cat ? { ...c, waterPerDa: cat.waterPerDa, profitPerDa: cat.profitPerDa } : c;
    });
  }
  return candidates.map(c=>({ ...c, parcelSpecific: false })).filter(c=>isFinite(c.waterPerDa) && isFinite(c.profitPerDa) && c.waterPerDa>=0);
}

// Senaryo-2 bahce/perennial kısıtı: meyve bahcesi olan parselde ürün değişmez;
// bunun yerine su tasarrufu senaryolarında sulama planı (kısıntılı damla) önerilir.
const PERENNIAL_SET = new Set([
  // Senaryo-2: çok yıllık ürünler (bahce + bağ + yonca)
  // Not: burada anahtarlar normCropName() çıktısı ile aynı olmalı.
  normCropName('ELMA'),
  normCropName('KİRAZ'),
  normCropName('BAĞ (ÜZÜM)'),
  normCropName('CEVİZ'),
  normCropName('ARMUT'),
  normCropName('ŞEFTALİ'),
  normCropName('NEKTARİN'),
  normCropName('KAYISI'),
  normCropName('VİŞNE'),
  normCropName('ERİK'),
  normCropName('YONCA (YEŞİLOT)')
]);

function isPerennialCropName(name){
  const k = normCropName(name);
  return PERENNIAL_SET.has(k) || /BADEM|NEKTAR|KAYSI|KAYISI|AYVA|DUT|CILEK|CILEK|IGDE|ZERDALI|KIRAZ|ELMA|ARMUT|VISNE|ERIK|BAG|UZUM|CEVIZ|SEFTALI/.test(k);
}

function isAnnualFieldCandidateName(name){
  const k = normCropName(name);
  if(!k || isPerennialCropName(name)) return false;
  if(/DOMATES|BIBER|KABAK|PATLICAN|HIYAR|KARPUZ|KAVUN|SOGAN|SARIMSAK|LAHANA|MARUL|ISPANAK|HAVUC|TURP|BAMYA|FASULYE/.test(k)) return true;
  if(/BUGDAY|ARPA|CAVDAR|YULAF|TRITIKALE|MERCIMEK|NOHUT|FIG|YEM|BEZELYE|AYCICEGI|MISIR|PANCAR|PATATES|KIMYON|NADAS/.test(k)) return true;
  return false;
}

function dominantCropNameForParcel(p){
  // currentRows üzerinden en büyük alanlı ürünü al
  let best = null;
  for(const c of (p.cropCurrent||[])){
    if(!best || (c.area||0) > (best.area||0)) best = c;
  }
  return best ? best.name : null;
}

function s2IrrigationAdjust(scenarioKey){
  const sk = normalizeScenarioKey(scenarioKey);
  if(sk === 'water_saving' || scenarioKey === 'su_tasarruf') return {
    wmul:0.82,
    pmul:0.95,
    label:'Damla sulama + kontrollü kısıntı (%18). Amaç: ana ürünü korurken suyu azaltmak ve TL/m³ verimini yükseltmek.'
  };
  if(sk === 'max_profit' || scenarioKey === 'maks_kar') return {
    wmul:0.96,
    pmul:1.06,
    label:'Tam zamanlı damla sulama + verim odaklı yönetim. Amaç: ana ürünü korurken ticari getiriyi artırmak.'
  };
  if(sk === 'water_efficiency') return {
    wmul:0.88,
    pmul:1.01,
    label:'Damla sulama + sıra arası nem yönetimi. Amaç: ana ürünü koruyup TL/m³ değerini yükseltmek.'
  };
  return {
    wmul:0.90,
    pmul:1.00,
    label:'Damla sulama + hafif kısıntı (%10). Amaç: su ve kâr dengesini birlikte korumak.'
  };
}

function orchardCropMetaForUi(name){
  const cat = STATE.cropCatalog || {};
  const raw = String(name||'').trim();
  const variants = [];
  if(raw) variants.push(raw);
  if(raw && raw.includes('_')) variants.push(raw.replace(/_/g,' '));
  const pretty = prettyCropName(raw);
  if(pretty && pretty !== raw) variants.push(pretty);
  if(pretty && pretty.includes('_')) variants.push(pretty.replace(/_/g,' '));
  for(const v of variants){
    const k = normCropName(v);
    if(cat[k]){
      let wNet = safeNum(cat[k].waterPerDa);
      let pr = safeNum(cat[k].profitPerDa);
      if(!(isFinite(wNet) && wNet>0)){
        const ws = getNetM3PerDaFromSeasons(STATE.selectedWaterYear, k);
        if(isFinite(ws) && ws>0) wNet = ws;
      }
      return { waterNet: wNet, profit: pr };
    }
  }
  const fallback = {
    'MERCIMEK': { waterNet: 210, profit: 3600 },
    'NOHUT': { waterNet: 312.36, profit: 3200 },
    'FIĞ (YEŞILOT)': { waterNet: 155.83, profit: 4500 },
    'ARPA (YEŞILOT)': { waterNet: 288.12, profit: 4200 },
    'YULAF (YEŞILOT)': { waterNet: 250, profit: 3900 },
  };
  return fallback[normCropName(raw)] || { waterNet: 0, profit: 0 };
}

function orchardAlternativeScenarioMetrics(mainCrop, parcelAreaDa, objectiveKey, currentMainRow, list){
  const rows = Array.isArray(list) && list.length ? list : orchardInterrowAlternativesForMain(mainCrop);
  const currentKey = currentMainRow?.irrigationCurrentKey || irrKeyFromText(currentMainRow?.irrigationCurrentText || '') || 'drip';
  const out = rows.map((alt, idx)=>{
    const meta = orchardCropMetaForUi(alt.name);
    const isProfit = normalizeScenarioKey(objectiveKey) === 'max_profit' || objectiveKey === 'maks_kar';
    const share = safeNum(isProfit ? (alt.shareProfit || alt.share_profit) : (alt.shareWater || alt.share_water), /baklagil/i.test(String(alt.kind||'')) ? (isProfit ? 0.32 : 0.27) : (isProfit ? 0.18 : 0.30));
    const waterMult = safeNum(isProfit ? (alt.waterMultProfit || alt.water_mult_profit) : (alt.waterMultWater || alt.water_mult_water), /baklagil/i.test(String(alt.kind||'')) ? (isProfit ? 0.84 : 0.74) : (isProfit ? 0.68 : 0.58));
    const profitMult = safeNum(isProfit ? (alt.profitMultProfit || alt.profit_mult_profit) : (alt.profitMultWater || alt.profit_mult_water), /baklagil/i.test(String(alt.kind||'')) ? (isProfit ? 0.95 : 0.88) : (isProfit ? 0.28 : 0.40));
    const area = +(safeNum(parcelAreaDa, 0) * share).toFixed(1);
    const suggestedKey = recommendedIrrKeyForCrop(alt.name, currentKey) || currentKey;
    const waterGross = deliveredWaterPerDa(meta.waterNet * waterMult, suggestedKey);
    const profitPerDa = +(meta.profit * profitMult).toFixed(2);
    const totalWater = +(area * waterGross).toFixed(2);
    const totalProfit = +(area * profitPerDa).toFixed(2);
    const tlPerM3 = totalWater > 0 ? (totalProfit / totalWater) : 0;
    const score = isProfit ? (totalProfit + tlPerM3 * 250) : (tlPerM3 * 1100 - totalWater * 0.10 + totalProfit * 0.10);
    return {
      ...alt,
      area,
      irrigationKey: suggestedKey,
      irrigationText: irrigationLabel(suggestedKey),
      waterPerDa: +waterGross.toFixed(3),
      profitPerDa,
      totalWater,
      totalProfit,
      tlPerM3: +tlPerM3.toFixed(2),
      score: +score.toFixed(2),
      rank: idx + 1,
      objectiveLabel: isProfit ? 'Kâr odaklı sıra arası senaryo' : 'Su verimliliği odaklı sıra arası senaryo'
    };
  }).filter(x=>x.area > 0 && x.waterPerDa >= 0);
  out.sort((a,b)=>safeNum(b.score)-safeNum(a.score));
  out.forEach((x,i)=>x.rank=i+1);
  return out;
}


function _seasonModeKey(){
  const farmerRaw = document.getElementById('farmerSeasonSourceSelectV102')?.value || document.getElementById('farmerSeasonSourceSelectV100')?.value || '';
  const raw = (farmerRaw || document.getElementById('seasonSourceSel')?.value || STATE.seasonSource || 's1');
  return String(raw || 's1').toLowerCase() === 's2' ? 's2' : 's1';
}

function normalizeCropCategoryMode(value){
  const raw = String(value || 'same_category').trim().toLowerCase().replace(/[-\s]+/g,'_');
  const map = {
    same:'same_category', same_category:'same_category', mevcut:'same_category',
    field:'field_cereal', field_cereal:'field_cereal', cereal:'field_cereal', tahil:'field_cereal', tarla:'field_cereal',
    forage:'forage', yem:'forage',
    legume:'legume', baklagil:'legume',
    vegetable:'vegetable', sebze:'vegetable',
    industrial:'industrial_oil', industrial_oil:'industrial_oil', oil:'industrial_oil', endustri:'industrial_oil',
    orchard:'orchard', bahce:'orchard',
    mixed:'mixed', karisik:'mixed', all:'mixed'
  };
  return map[raw] || 'same_category';
}

function currentCropCategoryMode(){
  const el = document.getElementById('cropCategoryModeSel') || document.getElementById('farmerCropCategoryModeV102') || document.getElementById('farmerCropCategoryModeV100') || document.getElementById('farmerCropCategoryModeV98');
  return setCropCategoryMode(el?.value || STATE.cropCategoryMode || 'same_category', false);
}

function setCropCategoryMode(value, shouldClearCaches = true){
  const val = normalizeCropCategoryMode(value || 'same_category');
  STATE.cropCategoryMode = val;
  ['cropCategoryModeSel', 'farmerCropCategoryModeV102', 'farmerCropCategoryModeV100', 'farmerCropCategoryModeV98'].forEach((id)=>{
    const el = document.getElementById(id);
    if(el && el.value !== val) el.value = val;
  });
  if(shouldClearCaches){
    try{ Object.keys(optimizationCache || {}).forEach(k=>delete optimizationCache[k]); }catch(_e){}
    try{ Object.keys(basinPlanCache || {}).forEach(k=>delete basinPlanCache[k]); }catch(_e){}
  }
  return val;
}

function cropCategoryModeOptionsHtml(){
  return `
    <option value="same_category">Mevcut kategoriye yakın öner</option>
    <option value="field_cereal">Tahıl / tarla ürünleri</option>
    <option value="forage">Yem bitkileri</option>
    <option value="legume">Baklagiller</option>
    <option value="vegetable">Sebze ürünleri</option>
    <option value="industrial_oil">Endüstri / yağ / özel ürünler</option>
    <option value="orchard">Bahçe / çok yıllık ürünler</option>
    <option value="mixed">Karışık mod - tüm uygun ürünler</option>`;
}

function annualCropCategoryFromName(name){
  const k = normCropName(name);
  if(isPerennialCropName(name)) return 'orchard';
  if(/SILAJ|YESILOT|YEŞILOT|YEM|FIG|FİĞ/.test(k)) return 'forage';
  if(/MERCIMEK|NOHUT|FASULYE|BAKLA|BEZELYE/.test(k)) return 'legume';
  if(/BUGDAY|ARPA|CAVDAR|YULAF|TRITIKALE/.test(k)) return 'field_cereal';
  if(/AYCICEGI|KIMYON|PATATES|PANCAR|SARIMSAK|LAVANTA|COREK|ASPIR/.test(k)) return 'industrial_oil';
  if(/DOMATES|BIBER|KABAK|PATLICAN|HIYAR|KARPUZ|KAVUN|SOGAN|LAHANA|MARUL|ISPANAK|HAVUC|TURP|BAMYA/.test(k)) return 'vegetable';
  if(/MISIR/.test(k)) return /SILAJ/.test(k) ? 'forage' : 'field_cereal';
  return 'field_cereal';
}

function cropCategoryLabel(category){
  return {
    same_category:'Mevcut kategori',
    field_cereal:'Tahıl / tarla',
    forage:'Yem bitkisi',
    legume:'Baklagil',
    vegetable:'Sebze',
    industrial_oil:'Endüstri / yağ / özel',
    orchard:'Bahçe / çok yıllık',
    mixed:'Karışık mod'
  }[String(category || '')] || 'Genel';
}

function cropCategoryFitScore(candidateCategory, mode, currentCategory=''){
  const cat = String(candidateCategory || '');
  const m = normalizeCropCategoryMode(mode);
  const cur = String(currentCategory || '');
  if(m === 'mixed') return 0.72;
  if(m === 'orchard') return cat === 'orchard' ? 1 : 0;
  if(m === 'same_category'){
    if(cat === cur) return 1;
    const near = {
      field_cereal:{ forage:0.72, legume:0.64, industrial_oil:0.55 },
      forage:{ field_cereal:0.70, legume:0.58 },
      legume:{ field_cereal:0.62, forage:0.55 },
      vegetable:{ industrial_oil:0.46, legume:0.42 },
      industrial_oil:{ field_cereal:0.58, vegetable:0.52 }
    };
    return near[cur]?.[cat] ?? 0.20;
  }
  if(cat === m) return 1;
  const nearMode = {
    field_cereal:{ forage:0.62, legume:0.52, industrial_oil:0.45 },
    forage:{ field_cereal:0.58, legume:0.46 },
    legume:{ field_cereal:0.52, forage:0.46 },
    vegetable:{ industrial_oil:0.42, legume:0.34 },
    industrial_oil:{ field_cereal:0.50, vegetable:0.42 }
  };
  return nearMode[m]?.[cat] ?? 0.08;
}

function _objectiveScorePattern(totalWater, totalProfit, scenarioKey){
  const obj = normalizeScenarioKey(scenarioKey);
  const eff = totalWater > 0 ? (totalProfit / totalWater) : 0;
  if(obj === 'water_saving' || obj === 'su_tasarruf'){
    return -totalWater * 1.00 + eff * 80 + totalProfit * 0.002;
  }
  if(obj === 'water_efficiency'){
    return eff * 1400 + totalProfit * 0.035 - totalWater * 0.060;
  }
  if(obj === 'max_profit' || obj === 'maks_kar'){
    return totalProfit - totalWater * 0.025 + eff * 120;
  }
  return eff * 1200 + totalProfit * 0.030 - totalWater * 0.050;
}

function decisionObjectiveKeyV8(scenarioKey){
  const obj = normalizeScenarioKey(scenarioKey);
  if(obj === 'water_saving' || obj === 'su_tasarruf') return 'water_saving';
  if(obj === 'max_profit' || obj === 'maks_kar') return 'max_profit';
  return 'water_efficiency';
}

function decisionNormalizeV8(value, min, max){
  const v = safeNum(value, 0);
  const lo = safeNum(min, 0);
  const hi = safeNum(max, lo);
  if(!Number.isFinite(v) || !Number.isFinite(lo) || !Number.isFinite(hi) || Math.abs(hi - lo) < 1e-9) return 0.5;
  return clamp((v - lo) / (hi - lo), 0, 1);
}

function planDecisionMetricsV8(parcel, rows, baselineTotals, scenarioKey){
  const totals = sumMetrics(Array.isArray(rows) ? rows : []);
  const water = safeNum(totals.water, 0);
  const profit = safeNum(totals.profit, 0);
  const baselineWater = safeNum(baselineTotals?.water, 0);
  const baselineProfit = safeNum(baselineTotals?.profit, 0);
  const planArea = safeNum(parcel?.area_da, 0) || safeNum(totals.area, 0);
  const quota = (typeof parcelWaterBudget === 'function') ? safeNum(parcelWaterBudget(planArea, parcel), 0) : 0;
  const suit = (typeof patternSuitabilitySummary === 'function') ? patternSuitabilitySummary(parcel, rows) : { score:0.78, label:'Proxy', basis:'' };
  const quotaGap = quota > 0 ? quota - water : 0;
  const quotaRatio = quota > 0 ? water / quota : 0;
  const quotaExceeded = quota > 0 && water > quota + 1e-6;
  const orchardReplacement = (rows || []).some(r=>!!r?.orchardConversion);
  const quotaOk = !quotaExceeded;
  return {
    ...totals,
    candidateWater: water,
    candidateProfit: profit,
    candidateWUE: water > 0 ? profit / water : 0,
    deltaWater: water - baselineWater,
    waterSaving: baselineWater - water,
    deltaProfit: profit - baselineProfit,
    quota,
    quotaGap,
    quotaRatio,
    quotaExceeded,
    quotaOk,
    quota_ok: quotaOk,
    fullFeasible: quotaOk,
    quotaLabel: quotaExceeded ? 'Kota aşımı riski' : 'Kota uygun',
    suitabilityScore: clamp(safeNum(suit?.score, 0.78), 0, 1),
    suitabilityLabel: suit?.label || 'Proxy',
    suitabilityBasis: suit?.basis || '',
    orchardReplacement,
    objectiveKey: decisionObjectiveKeyV8(scenarioKey),
  };
}

function orchardReplacementClearlyBetterV8(replacementMetrics, keepMetrics, scenarioKey){
  const obj = decisionObjectiveKeyV8(scenarioKey);
  const rw = safeNum(replacementMetrics?.candidateWater, 0);
  const rp = safeNum(replacementMetrics?.candidateProfit, 0);
  const re = safeNum(replacementMetrics?.candidateWUE, 0);
  const kw = safeNum(keepMetrics?.candidateWater, 0);
  const kp = safeNum(keepMetrics?.candidateProfit, 0);
  const ke = safeNum(keepMetrics?.candidateWUE, 0);
  if(replacementMetrics?.quotaExceeded) return false;
  if(obj === 'water_saving') return rw > 0 && kw > 0 && rw <= kw * 0.70 && rp >= kp * 0.70;
  if(obj === 'max_profit') return rp >= kp * 1.25 && rw <= kw * 1.15;
  return re >= ke * 1.20 && rp >= kp * 0.95 && rw <= kw * 1.05;
}

function candidateDominatesV8(a, b, scenarioKey){
  const am = a?.metrics || {};
  const bm = b?.metrics || {};
  if(!am || !bm) return false;
  if(am.quotaExceeded && !bm.quotaExceeded) return false;
  if(am.orchardReplacement && !bm.orchardReplacement && !orchardReplacementClearlyBetterV8(am, bm, scenarioKey)) return false;
  const aw = safeNum(am.candidateWater, Number.POSITIVE_INFINITY);
  const bw = safeNum(bm.candidateWater, Number.POSITIVE_INFINITY);
  const ap = safeNum(am.candidateProfit, 0);
  const bp = safeNum(bm.candidateProfit, 0);
  const ae = safeNum(am.candidateWUE, 0);
  const be = safeNum(bm.candidateWUE, 0);
  const waterOk = aw <= bw + Math.max(1, bw * 0.002);
  const profitOk = ap >= bp - Math.max(1, bp * 0.002);
  const wueOk = ae >= be - Math.max(0.01, be * 0.002);
  const strict = aw < bw - Math.max(1, bw * 0.005)
    || ap > bp + Math.max(1, bp * 0.005)
    || ae > be + Math.max(0.01, be * 0.005)
    || (!am.quotaExceeded && bm.quotaExceeded);
  return waterOk && profitOk && wueOk && strict;
}

function waterEfficiencyEconomicAdvantageV8(aMetrics, bMetrics){
  const aw = safeNum(aMetrics?.candidateWater ?? aMetrics?.totalWater, Number.POSITIVE_INFINITY);
  const bw = safeNum(bMetrics?.candidateWater ?? bMetrics?.totalWater, Number.POSITIVE_INFINITY);
  const ap = safeNum(aMetrics?.candidateProfit ?? aMetrics?.totalProfit, 0);
  const bp = safeNum(bMetrics?.candidateProfit ?? bMetrics?.totalProfit, 0);
  const ae = safeNum(aMetrics?.candidateWUE ?? aMetrics?.tlPerM3, 0);
  const be = safeNum(bMetrics?.candidateWUE ?? bMetrics?.tlPerM3, 0);
  const aOk = !!(aMetrics?.fullFeasible || aMetrics?.quotaOk || aMetrics?.quota_ok);
  const bOk = !!(bMetrics?.fullFeasible || bMetrics?.quotaOk || bMetrics?.quota_ok);
  if(!aOk || !bOk) return false;
  const wueBetter = ae > be + Math.max(0.10, be * 0.015);
  const profitBetter = ap > bp + Math.max(1000, bp * 0.08);
  const waterNotExplosive = aw <= bw * 2.25;
  return wueBetter && profitBetter && waterNotExplosive;
}

function validateRecommendationResultV8(rankedCandidates, scenarioKey, context={}){
  const ranked = (Array.isArray(rankedCandidates) ? rankedCandidates : []).filter(Boolean).map((c, idx)=>({
    ...c,
    targetOrder: idx + 1,
    metrics: c.metrics || planDecisionMetricsV8(context.parcel || null, c.rows || [], context.baselineTotals || {}, scenarioKey)
  }));
  if(!ranked.length) return ranked;
  const obj = decisionObjectiveKeyV8(scenarioKey);
  const first = ranked[0];
  if(obj === 'water_saving'){
    const better = ranked.find(c=>{
      if(c === first || !c.metrics?.fullFeasible || !c.metrics?.quotaOk) return false;
      if(c.metrics?.orchardReplacement && !first.metrics?.orchardReplacement && !orchardReplacementClearlyBetterV8(c.metrics, first.metrics, scenarioKey)) return false;
      const cw = safeNum(c.metrics?.candidateWater, Number.POSITIVE_INFINITY);
      const fw = safeNum(first.metrics?.candidateWater, Number.POSITIVE_INFINITY);
      if(cw < fw - 1e-6) return true;
      if(Math.abs(cw - fw) <= 1e-6){
        return safeNum(c.metrics?.candidateWUE,0) > safeNum(first.metrics?.candidateWUE,0)
          || safeNum(c.metrics?.candidateProfit,0) > safeNum(first.metrics?.candidateProfit,0);
      }
      return false;
    });
    if(better){
      console.warn('[recommendation-validation] Su tasarrufu sırası düzeltildi:', better.c1 || better.label || better.type);
      return [better, ...ranked.filter(c=>c!==better)].map((c,i)=>({...c, targetOrder:i+1}));
    }
  }
  if(obj === 'max_profit'){
    const top = ranked[0];
    const better = ranked.find(c=>{
      if(c === top || !c.metrics?.fullFeasible || !c.metrics?.quotaOk) return false;
      if(top.metrics?.orchardReplacement && !c.metrics?.orchardReplacement) return true;
      if(c.metrics?.orchardReplacement && !top.metrics?.orchardReplacement && !orchardReplacementClearlyBetterV8(c.metrics, top.metrics, scenarioKey)) return false;
      return safeNum(c.metrics?.candidateProfit,0) > safeNum(top.metrics?.candidateProfit,0) + Math.max(1, safeNum(top.metrics?.candidateProfit,0) * 0.002);
    });
    if(better){
      console.warn('[recommendation-validation] Kâr hedefi sırası düzeltildi:', better.c1 || better.label || better.type);
      return [better, ...ranked.filter(c=>c!==better)].map((c,i)=>({...c, targetOrder:i+1}));
    }
  }
  if(obj === 'water_efficiency'){
    const dominator = ranked.slice(1).find(c=>candidateDominatesV8(c, ranked[0], scenarioKey));
    if(dominator){
      console.warn('[recommendation-validation] Pareto dominance sırası düzeltildi:', dominator.c1 || dominator.label || dominator.type);
      return [dominator, ...ranked.filter(c=>c!==dominator)].map((c,i)=>({...c, targetOrder:i+1}));
    }
    const economicLeader = ranked.slice(1).find(c=>waterEfficiencyEconomicAdvantageV8(c.metrics, ranked[0].metrics));
    if(economicLeader){
      console.warn('[recommendation-validation] Su etkin kullanım ekonomik etkinlik sırası düzeltildi:', economicLeader.c1 || economicLeader.label || economicLeader.type);
      return [economicLeader, ...ranked.filter(c=>c!==economicLeader)].map((c,i)=>({...c, targetOrder:i+1}));
    }
  }
  return ranked.map((c,i)=>{
    const dominatedBy = ranked.find(other=>other !== c && candidateDominatesV8(other, c, scenarioKey));
    const rankReason = c.type === 'current_reference'
      ? (obj === 'water_efficiency'
          ? 'Mevcut desen, daha fazla su kullanmasına rağmen birim su başına gelir ve toplam kâr açısından daha güçlü olduğu için su etkin kullanım hedefinde korunmuştur.'
          : 'Mevcut desen bu hedefte alternatiflerden daha avantajlı olduğu için korunmuştur.')
      : (obj === 'water_saving'
          ? 'Bu aday uygulanabilir ve kota uygun adaylar içinde en düşük toplam su kullanımına sahip olduğu için seçilmiştir.'
          : (obj === 'max_profit'
              ? 'Bu aday uygulanabilir ve kota uygun adaylar içinde en yüksek net kârı verdiği için seçilmiştir.'
              : 'Bu aday, su tüketimini belirgin azaltırken kabul edilebilir TL/m³ ve net kâr düzeyi sağladığı için seçilmiştir.'));
    return {
      ...c,
      targetOrder:i+1,
      rankReason,
      debugRank:{
        label: c.label || c.c1 || c.rows?.[0]?.name || '',
        scenario: _seasonModeKey(),
        objective: obj,
        is_current_reference: c.type === 'current_reference',
        totalWater: safeNum(c.metrics?.candidateWater,0),
        totalProfit: safeNum(c.metrics?.candidateProfit,0),
        tlPerM3: safeNum(c.metrics?.candidateWUE,0),
        fullFeasible: !!c.metrics?.fullFeasible,
        quota_ok: !!c.metrics?.quotaOk,
        rank: i+1,
        rankReason,
        dominatedBy: dominatedBy ? (dominatedBy.label || dominatedBy.c1 || dominatedBy.rows?.[0]?.name || '') : ''
      }
    };
  });
}

function rankPlanCandidatesV8(candidates, scenarioKey, baselineTotals){
  const list = (Array.isArray(candidates) ? candidates : []).filter(c=>{
    const m = c?.metrics || {};
    return safeNum(m.candidateWater, 0) >= 0 && safeNum(m.candidateProfit, 0) > 0;
  });
  if(!list.length) return [];
  const obj = decisionObjectiveKeyV8(scenarioKey);
  const values = (key)=>list.map(c=>safeNum(c.metrics?.[key], 0));
  const minMax = (key)=>{
    const arr = values(key);
    return { min: Math.min(...arr), max: Math.max(...arr) };
  };
  const mmWaterSaving = minMax('waterSaving');
  const mmProfit = minMax('candidateProfit');
  const mmWue = minMax('candidateWUE');
  const baselineProfit = safeNum(baselineTotals?.profit, 0);
  const baselineWater = safeNum(baselineTotals?.water, 0);
  const scored = list.map(c=>{
    const m = c.metrics;
    const waterSavingNorm = decisionNormalizeV8(m.waterSaving, mmWaterSaving.min, mmWaterSaving.max);
    const profitNorm = decisionNormalizeV8(m.candidateProfit, mmProfit.min, mmProfit.max);
    const wueNorm = decisionNormalizeV8(m.candidateWUE, mmWue.min, mmWue.max);
    const fullFeasibleScore = m.fullFeasible ? 1 : 0;
    const quotaOk = m.quotaOk ? 1 : 0;
    const quotaPenalty = m.quotaExceeded ? (m.quotaRatio > 1.15 ? 0.45 : 0.25) : 0;
    const suitabilityPenalty = Math.max(0, 0.70 - safeNum(m.suitabilityScore, 0.78)) * 0.60;
    const lowProfitPenalty = baselineProfit > 0 && m.candidateProfit < baselineProfit * 0.35 ? 0.25 : 0;
    const orchardReplacementPenalty = m.orchardReplacement ? (obj === 'max_profit' ? 0.22 : 0.38) : 0;
    let objectiveScore;
    if(obj === 'water_saving'){
      objectiveScore = 0.65 * waterSavingNorm + 0.15 * fullFeasibleScore + 0.10 * quotaOk + 0.05 * wueNorm + 0.05 * profitNorm;
    }else if(obj === 'max_profit'){
      objectiveScore = 0.70 * profitNorm + 0.10 * fullFeasibleScore + 0.05 * quotaOk + 0.10 * wueNorm + 0.05 * waterSavingNorm;
    }else{
      objectiveScore = 0.50 * wueNorm + 0.25 * profitNorm + 0.20 * waterSavingNorm + 0.03 * fullFeasibleScore + 0.02 * quotaOk;
    }
    objectiveScore -= quotaPenalty + suitabilityPenalty + lowProfitPenalty + orchardReplacementPenalty;
    return { ...c, objectiveScore, score: objectiveScore };
  });
  scored.sort((a,b)=>{
    const am = a.metrics || {};
    const bm = b.metrics || {};
    const aFull = am.fullFeasible ? 1 : 0;
    const bFull = bm.fullFeasible ? 1 : 0;
    const aOk = am.quotaOk ? 1 : 0;
    const bOk = bm.quotaOk ? 1 : 0;
    const aQuota = am.quotaExceeded ? 1 : 0;
    const bQuota = bm.quotaExceeded ? 1 : 0;
    if(!!am.orchardReplacement !== !!bm.orchardReplacement){
      if(am.orchardReplacement && !orchardReplacementClearlyBetterV8(am, bm, scenarioKey)) return 1;
      if(bm.orchardReplacement && !orchardReplacementClearlyBetterV8(bm, am, scenarioKey)) return -1;
    }
    if(obj === 'water_saving'){
      if(aFull !== bFull) return bFull - aFull;
      if(aOk !== bOk) return bOk - aOk;
      if(aQuota !== bQuota) return aQuota - bQuota;
      const aw = safeNum(am.candidateWater, Number.POSITIVE_INFINITY);
      const bw = safeNum(bm.candidateWater, Number.POSITIVE_INFINITY);
      if(Math.abs(aw - bw) > 1e-6) return aw - bw;
      return safeNum(bm.candidateProfit, 0) - safeNum(am.candidateProfit, 0);
    }
    if(obj === 'max_profit'){
      if(aFull !== bFull) return bFull - aFull;
      if(aOk !== bOk) return bOk - aOk;
      if(aQuota !== bQuota) return aQuota - bQuota;
      const ap = safeNum(am.candidateProfit, 0);
      const bp = safeNum(bm.candidateProfit, 0);
      if(Math.abs(ap - bp) > 1e-6) return bp - ap;
      const ae = safeNum(am.candidateWUE,0);
      const be = safeNum(bm.candidateWUE,0);
      if(Math.abs(ae - be) > 1e-6) return be - ae;
      return safeNum(am.candidateWater, 0) - safeNum(bm.candidateWater, 0);
    }
    if(aFull !== bFull) return bFull - aFull;
    if(aOk !== bOk) return bOk - aOk;
    if(waterEfficiencyEconomicAdvantageV8(am, bm)) return -1;
    if(waterEfficiencyEconomicAdvantageV8(bm, am)) return 1;
    if(Math.abs(safeNum(b.objectiveScore,0) - safeNum(a.objectiveScore,0)) > 1e-9){
      return safeNum(b.objectiveScore,0) - safeNum(a.objectiveScore,0);
    }
    if(aQuota !== bQuota) return aQuota - bQuota;
    return safeNum(bm.candidateWUE,0) - safeNum(am.candidateWUE,0);
  });
  if(obj === 'water_saving' && baselineWater > 0){
    const lowerWater = scored.filter(c=>safeNum(c.metrics?.candidateWater,0) <= baselineWater + 1e-6);
    if(lowerWater.length) return validateRecommendationResultV8(lowerWater.concat(scored.filter(c=>!lowerWater.includes(c))), scenarioKey, { baselineTotals });
  }
  return validateRecommendationResultV8(scored, scenarioKey, { baselineTotals });
}

function decisionReasonV8(candidate, scenarioKey){
  const m = candidate?.metrics || {};
  const obj = decisionObjectiveKeyV8(scenarioKey);
  const f0 = (v)=>Math.round(safeNum(v,0)).toLocaleString('tr-TR');
  const f1 = (v)=>safeNum(v,0).toLocaleString('tr-TR', {maximumFractionDigits:1});
  const waterText = `${f0(Math.abs(safeNum(m.waterSaving,0)))} m³`;
  const profitText = `${f0(Math.abs(safeNum(m.deltaProfit,0)))} TL`;
  const quotaText = m.quotaExceeded ? 'kota aşımı riski taşıyor' : 'kota içinde kalıyor';
  if(candidate?.type === 'current_reference'){
    if(obj === 'water_efficiency'){
      return `Mevcut desen, daha fazla su kullanmasına rağmen birim su başına gelir ve toplam kâr açısından daha güçlü olduğu için su etkin kullanım hedefinde korunmuştur. Mevcut desen ${f1(safeNum(m.candidateWUE,0))} TL/m³ değerindedir ve ${quotaText}.`;
    }
    if(obj === 'max_profit'){
      return `Mevcut desen bu hedefte alternatiflerden daha yüksek veya daha güvenilir kâr sunduğu için korunmuştur. Mevcut desen ${f0(safeNum(m.candidateProfit,0))} TL net kâr üretir ve ${quotaText}.`;
    }
    return `Mevcut referans bu hedefte alternatiflerden daha avantajlı bulunduğu için korunmuştur. Mevcut desen ${f1(safeNum(m.candidateWUE,0))} TL/m³ değerindedir ve ${quotaText}.`;
  }
  const orchardWarning = (candidate?.rows || []).some(r=>r?.orchardConversion)
    ? ' Bu alternatif ana ürün değişimi/bahçe yenileme gerektirir; söküm-yeni tesis kararı uzman onayıyla değerlendirilmelidir.'
    : '';
  if(obj === 'water_saving'){
    return `Bu aday uygulanabilir ve kota uygun adaylar içinde en düşük toplam su kullanımına sahip olduğu için seçilmiştir. Mevcut desene göre ${safeNum(m.waterSaving,0) >= 0 ? waterText + ' su tasarrufu sağlar' : waterText + ' daha fazla su ister'}; kâr etkisi ${safeNum(m.deltaProfit,0) >= 0 ? '+' : '-'}${profitText} ve ${quotaText}.${orchardWarning}`;
  }
  if(obj === 'max_profit'){
    const quotaGuard = m.quotaExceeded
      ? ' Daha yüksek kâr veren adaylar su kotası/uygulanabilirlik riski nedeniyle ana öneri yapılmamıştır.'
      : '';
    return `Bu aday uygulanabilir ve kota uygun adaylar içinde en yüksek net kârı verdiği için seçilmiştir. Net kâr farkı ${safeNum(m.deltaProfit,0) >= 0 ? '+' : '-'}${profitText}, su farkı ${safeNum(m.deltaWater,0) >= 0 ? '+' : '-'}${f0(Math.abs(safeNum(m.deltaWater,0)))} m³ ve ${quotaText}.${quotaGuard}${orchardWarning}`;
  }
  const quotaGuard = m.quotaExceeded
    ? ' Daha yüksek kâr veren adaylar su kotası/uygulanabilirlik riski nedeniyle ana öneri yapılmamıştır.'
    : '';
  return `Bu aday, su tüketimini belirgin azaltırken kabul edilebilir TL/m³ ve net kâr düzeyi sağladığı için seçilmiştir. Plan ${f1(safeNum(m.candidateWUE,0))} TL/m³ değerine sahip; ${quotaText} ve uygunluk notu ${escapeHtml(m.suitabilityLabel || 'Proxy')}.${quotaGuard}${orchardWarning}`;
}

function _patternPeakMonthLabel(pattern){
  const txt = String(pattern?.seasonLabel || pattern?.season || '').toLowerCase();
  if(txt.includes('çok yıllık') || txt.includes('bahçe')) return 'Haz-Tem';
  if(txt.includes('yaz')) return 'Tem-Ağu';
  if(txt.includes('kış')) return 'Nis-May';
  if(txt.includes('rotasyon') || txt.includes('+')) return 'Haz-Tem';
  return 'Temmuz';
}

function cropSuitabilityForParcel(parcel, cropName){
  const lccRaw = String(parcel?.land_capability_class || parcel?.soil?.class || '').trim();
  const lcc = lccRaw && !/veri\s*yok/i.test(lccRaw) ? lccRaw.toUpperCase().replace(/\.?\s*s[ıi]n[ıi]f/i,'').trim() : '';
  const key = lcc ? `${lcc}|${normCropName(cropName)}` : '';
  const rec = key && STATE.cropSuitabilityByKey instanceof Map ? STATE.cropSuitabilityByKey.get(key) : null;
  if(rec){
    const score = clamp(safeNum(rec.score, 0.85), 0, 1);
    return {
      score,
      label: score >= 0.85 ? 'Yüksek' : (score >= 0.70 ? 'Orta' : (score >= 0.60 ? 'Sınırda' : 'Uygun değil')),
      basis: rec.basis || rec.status || 'LCC x ürün uygunluk tablosu'
    };
  }
  const isPerennial = isPerennialCropName(cropName);
  const parcelType = inferParcelTypeKey(parcel);
  const score = (parcelType === 'orchard' && !isPerennial) ? 0.68 : (parcelType !== 'orchard' && isPerennial ? 0.62 : 0.78);
  return {
    score,
    label: 'Proxy',
    basis: 'Parsel toprak sınıfı eksik; parsel tipi + ürün grubu proxy kullanıldı.'
  };
}

function patternSuitabilitySummary(parcel, rows){
  const list = (rows || []).filter(Boolean).map(r=>cropSuitabilityForParcel(parcel, r.name || r.mainCrop || r.crop));
  if(!list.length) return { score:0, label:'-', basis:'Ürün satırı yok' };
  const minScore = Math.min(...list.map(x=>safeNum(x.score,0)));
  const weakest = list.sort((a,b)=>safeNum(a.score)-safeNum(b.score))[0];
  return { score:minScore, label:weakest?.label || '-', basis:weakest?.basis || '' };
}

function rankedCandidatesToUiPatternsV8(parcel, currentRows, rankedCandidates, scenarioKey){
  const ranked = Array.isArray(rankedCandidates) ? rankedCandidates.filter(Boolean) : [];
  if(!ranked.length) return [];
  const areaDa = safeNum(parcel?.area_da, 0);
  const baselineTotals = sumMetrics(Array.isArray(currentRows) ? currentRows : []);
  const scenarioType = _seasonModeKey();
  const toComponent = (row, idx, share)=>{
    const crop = prettyCropName(row?.name || row?.crop || '-');
    const area = safeNum(row?.area, areaDa * share);
    const water = safeNum(row?.totalWater, area * safeNum(row?.waterPerDa, 0));
    const profit = safeNum(row?.totalProfit, area * safeNum(row?.profitPerDa, 0));
    const irrKey = row?.irrigationSuggestedKey || row?.irrigationCurrentKey || irrigationKeysForCrop(crop).suggestedKey || 'sprinkler';
    return {
      crop,
      role: row?.currentReference ? 'Mevcut referans' : (row?.orchardConversion ? 'Bahçe yenileme - ana ürün değişimi' : (idx === 0 ? 'Ana ürün' : '2. ürün / ara ürün')),
      share,
      percent: Math.round(share * 100),
      area,
      water,
      profit,
      waterPerDa: area > 0 ? water / area : safeNum(row?.waterPerDa, 0),
      profitPerDa: area > 0 ? profit / area : safeNum(row?.profitPerDa, 0),
      cropCategory: row?.cropCategory || annualCropCategoryFromName(crop),
      cropCategoryLabel: row?.cropCategoryLabel || cropCategoryLabel(row?.cropCategory || annualCropCategoryFromName(crop)),
      irrigationKey: irrKey,
      irrigation: row?.irrigationSuggestedText || row?.irrigationSuggested || row?.irrigationCurrentText || irrigationLabel(irrKey),
      season: (row?.patternPercent || row?.patternShare) ? 'Desen oranı' : (row?.season || (scenarioType === 's2' ? 'Desen oranı' : inferSeasonFromCropName(crop) || 'Tek sezon'))
    };
  };
  const splitLabel = (components)=>components.map(c=>`${c.role || 'Ürün'} %${Math.round(safeNum(c.share,0)*100)}`).join(' + ');
  return ranked.slice(0, 8).map((candidate, idx)=>{
    const rows = Array.isArray(candidate.rows) ? candidate.rows.filter(Boolean) : [];
    const metrics = candidate.metrics || planDecisionMetricsV8(parcel, rows, baselineTotals, scenarioKey);
    const rawArea = rows.reduce((a,r)=>a+safeNum(r.area,0),0);
    const sequentialLike = areaDa > 0 && rawArea > areaDa * 1.20;
    const components = rows.map((r, ridx)=>{
      const share = rows.length <= 1
        ? 1
        : (sequentialLike ? (1 / rows.length) : clamp(safeNum(r.area,0) / Math.max(1, rawArea), 0.05, 0.95));
      return toComponent(r, ridx, share);
    });
    const main = components[0]?.crop || prettyCropName(candidate.c1 || '-');
    const second = components.find((c,i)=>i>0 && normCropName(c.crop) !== normCropName(main))?.crop || '-';
    const totalWater = safeNum(metrics.candidateWater, safeNum(candidate.totals?.water, 0));
    const totalProfit = safeNum(metrics.candidateProfit, safeNum(candidate.totals?.profit, 0));
    const orchardReplacement = !!metrics.orchardReplacement || rows.some(r=>r?.orchardConversion);
    const note = candidate.type === 'current_reference'
      ? 'Mevcut referans korundu; bu hedefte ürün değişimi daha avantajlı bulunmadı.'
      : (orchardReplacement
          ? 'Bahçe yenileme - ana ürün değişimi: söküm/yeni tesis ve uzman onayı gerekir.'
          : decisionReasonV8(candidate, scenarioKey));
    return {
      rank: idx + 1,
      targetOrder: idx + 1,
      selectedRecommendation: idx === 0,
      referencePattern: candidate.type === 'current_reference',
      patternName: candidate.type === 'current_reference'
        ? `${main} mevcut referans`
        : (second !== '-' ? `${main} + ${second}` : `${main} önerilen desen`),
      mainCrop: main,
      secondaryCrop: second,
      areaSplit: components.length ? splitLabel(components) : 'Ana ürün %100',
      irrigation: components.map(c=>c.irrigation).filter(Boolean).join(' / '),
      totalWater,
      totalProfit,
      tlPerM3: totalWater > 0 ? totalProfit / totalWater : 0,
      deltaWater: safeNum(metrics.deltaWater, totalWater - safeNum(baselineTotals.water,0)),
      deltaProfit: safeNum(metrics.deltaProfit, totalProfit - safeNum(baselineTotals.profit,0)),
      quotaExceeded: !!metrics.quotaExceeded,
      quotaLabel: metrics.quotaLabel || (metrics.quotaExceeded ? 'Kota aşımı riski' : 'Kota uygun'),
      peakMonth: rows.map(r=>cropPeakMonthLabel(r.name)).filter(Boolean).join(' / ') || _patternPeakMonthLabel({season: components[0]?.season}),
      seasonLabel: candidate.type === 'current_reference'
        ? 'Mevcut referans'
        : (orchardReplacement ? 'Bahçe yenileme' : (components.length > 1 ? 'Çift ürün / desen' : (rows[0]?.season || 'Tek sezon'))),
      note,
      suitability: `${metrics.suitabilityLabel || 'Proxy'} (${Math.round(safeNum(metrics.suitabilityScore,0)*100)}%)`,
      cropCategory: candidate.cropCategory || components[0]?.cropCategory || '',
      cropCategoryLabel: candidate.cropCategoryLabel || components[0]?.cropCategoryLabel || '',
      cropCategoryMode: candidate.cropCategoryMode || currentCropCategoryMode(),
      suitabilityBasis: metrics.suitabilityBasis || '',
      growthDays: rows.map(r=>stageTotalDays(stageParamsForCrop(r.name))).filter(Boolean).join('+'),
      productionWindow: rows.map(r=>cropProductionWindowLabel(r.name)).filter(Boolean).join(' / '),
      components,
      score: safeNum(candidate.objectiveScore, 0),
      candidateType: candidate.type || (orchardReplacement ? 'orchard_replacement' : 'candidate')
    };
  });
}

function _annualCropFamily(name){
  if(typeof familyOf === 'function') return familyOf(name) || 'Genel';
  const k = normCropName(name);
  if(/DOMATES|BIBER|PATLICAN|PATATES/.test(k)) return 'Solanaceae';
  if(/LAHANA|TURP|KARNABAHAR|BROKOLI/.test(k)) return 'Brassicaceae';
  if(/MARUL|AYCICEGI/.test(k)) return 'Asteraceae';
  if(/BUGDAY|ARPA|YULAF|CAVDAR|TRITIKALE|MISIR/.test(k)) return 'Tahıl';
  if(/NOHUT|MERCIMEK|FASULYE|FIG|BEZELYE/.test(k)) return 'Baklagil';
  if(/SOGAN|SARIMSAK/.test(k)) return 'Allium';
  return 'Diğer';
}

function _annualCandidateMeta(name, fallback={}){
  const cat = STATE.cropCatalog || {};
  const key = normCropName(name);
  const hit = cat[key] || null;
  const waterPerDa = safeNum(fallback.waterPerDa, safeNum(hit?.waterPerDa, 0));
  const profitPerDa = safeNum(fallback.profitPerDa, safeNum(hit?.profitPerDa, 0));
  const keys = irrigationKeysForCrop(name);
  return {
    name: prettyCropName(fallback.name || name),
    waterPerDa,
    profitPerDa,
    irrigationKey: fallback.irrigationKey || fallback.irrigationCurrentKey || keys.suggestedKey || keys.currentKey || 'sprinkler',
    season: fallback.season || inferSeasonFromCropName(name) || 'Tek sezon',
    cropFamily: _annualCropFamily(name),
  };
}

function buildAnnualCandidateUniverse(parcel, currentRows, scenarioKey){
  const selectedVillage = normalizeVillageKey(parcel?.village || parcel?.koy || '');
  const selectedPid = String(parcel?.id || '');
  const seasonMode = _seasonModeKey();
  const categoryMode = currentCropCategoryMode();
  const currentCategory = annualCropCategoryFromName(currentRows?.[0]?.name || parcel?.current_crop || parcel?.currentCrop || '');
  const universe = new Map();
  const selectedVillageCrops = new Set();
  const otherVillageCrops = new Map();
  const add = (name, partial={})=>{
    const key = normCropName(name);
    if(!key || key === 'NADAS' || !isAnnualFieldCandidateName(name) || isPerennialCropName(name)) return;
    const meta = _annualCandidateMeta(name, partial);
    if(!(safeNum(meta.waterPerDa, 0) >= 0) || !(safeNum(meta.profitPerDa, 0) > 0)) return;
    const villageKey = normalizeVillageKey(partial.village || '');
    if(villageKey && villageKey === selectedVillage) selectedVillageCrops.add(key);
    if(villageKey && villageKey !== selectedVillage){
      if(!otherVillageCrops.has(key)) otherVillageCrops.set(key, new Set());
      otherVillageCrops.get(key).add(villageKey);
    }
    if(!universe.has(key)){
      universe.set(key, {
        ...meta,
        sourceType: partial.sourceType || 'scenario_generated',
        candidateSourceVillage: partial.village || '',
        sourceWeights: [],
        seenVillages: new Set(),
      });
    }
    const item = universe.get(key);
    item.sourceWeights.push({
      waterPerDa: safeNum(meta.waterPerDa, 0),
      profitPerDa: safeNum(meta.profitPerDa, 0),
      sourceType: partial.sourceType || item.sourceType,
      local: villageKey && villageKey === selectedVillage,
    });
    if(villageKey) item.seenVillages.add(villageKey);
    if(partial.sourceType === 'current_reference') item.sourceType = 'current_reference';
    else if(partial.sourceType === 'local_village_crop' && item.sourceType !== 'current_reference') item.sourceType = 'local_village_crop';
    else if(partial.sourceType === 'regional_5_village_crop' && !['current_reference','local_village_crop'].includes(item.sourceType)) item.sourceType = 'regional_5_village_crop';
  };

  for(const r of (currentRows || [])){
    add(r.name, { ...r, sourceType:'current_reference', village: parcel?.village || '' });
  }
  const local = (typeof getCandidateCropsForParcel === 'function') ? getCandidateCropsForParcel(parcel) : [];
  for(const c of (local || [])){
    add(c.name || c.crop, { ...c, sourceType:'local_village_crop', village: parcel?.village || '' });
  }
  const year = +STATE.selectedWaterYear;
  const maps = [];
  if(STATE.candidatesByParcelYear?.has?.(year)) maps.push(STATE.candidatesByParcelYear.get(year));
  if(STATE.candidatesByParcel) maps.push(STATE.candidatesByParcel);
  for(const byParcel of maps){
    if(!byParcel || typeof byParcel.entries !== 'function') continue;
    for(const [pid, mp] of byParcel.entries()){
      const pMeta = (parcelData || []).find(px=>String(px.id) === String(pid)) || {};
      const village = pMeta.village || pMeta.koy || '';
      const villageKey = normalizeVillageKey(village);
      if(!mp || typeof mp.entries !== 'function') continue;
      for(const [, agg] of mp.entries()){
        const area = safeNum(agg.area, 1);
        add(agg.name || agg.crop, {
          waterPerDa: area > 0 ? safeNum(agg.water, 0) / area : 0,
          profitPerDa: area > 0 ? safeNum(agg.profit, 0) / area : 0,
          irrigationKey: agg.irrigationKey,
          irrigationText: agg.irrigationText,
          sourceType: String(pid) === selectedPid || villageKey === selectedVillage ? 'local_village_crop' : 'regional_5_village_crop',
          village
        });
      }
    }
  }
  const scenarioSeeds = [
    ...Object.keys(S1_PAIRING || {}),
    ...(Array.isArray(NIGDE_TARLA_CROP_POOL) ? NIGDE_TARLA_CROP_POOL.map(x=>x.name) : []),
    ...(seasonMode === 's2' ? [...(S2_SUMMER_RAW || []), ...(S2_WINTER_RAW || [])] : [])
  ];
  for(const name of scenarioSeeds) add(name, { sourceType:'scenario_generated' });
  for(const key in (STATE.cropCatalog || {})) add(key, { sourceType:'scenario_generated' });

  let candidates = Array.from(universe.values()).map(item=>{
    const usable = item.sourceWeights.filter(x=>safeNum(x.waterPerDa,0) >= 0 && safeNum(x.profitPerDa,0) > 0);
    const localRows = usable.filter(x=>x.local);
    const chosen = localRows.length ? localRows : usable;
    const avg = (field, fallback)=> chosen.length ? chosen.reduce((a,x)=>a+safeNum(x[field],0),0) / chosen.length : fallback;
    const key = normCropName(item.name);
    const seenInSelectedVillage = selectedVillageCrops.has(key) || item.sourceType === 'current_reference';
    const seenVillages = item.seenVillages || new Set();
    const seenInOtherVillages = otherVillageCrops.has(key);
    const villageCount = seenVillages.size || (seenInSelectedVillage ? 1 : 0);
    const cropCategory = annualCropCategoryFromName(item.name);
    const categoryFitScore = cropCategoryFitScore(cropCategory, categoryMode, currentCategory);
    return {
      ...item,
      waterPerDa: avg('waterPerDa', item.waterPerDa),
      profitPerDa: avg('profitPerDa', item.profitPerDa),
      tlPerM3: avg('waterPerDa', item.waterPerDa) > 0 ? avg('profitPerDa', item.profitPerDa) / avg('waterPerDa', item.waterPerDa) : 0,
      seenInSelectedVillage,
      seenInOtherVillages,
      candidateVillageCount: villageCount,
      seenVillages: Array.from(seenVillages),
      sourceType: item.sourceType === 'scenario_generated' && seenInSelectedVillage ? 'local_village_crop' : item.sourceType,
      cropCategory,
      cropCategoryLabel: cropCategoryLabel(cropCategory),
      cropCategoryMode: categoryMode,
      currentCategory,
      categoryFitScore,
    };
  }).filter(x=>safeNum(x.profitPerDa,0) > 0);
  const hardCategoryModes = new Set(['field_cereal', 'forage', 'legume', 'vegetable', 'industrial_oil', 'orchard']);
  if(hardCategoryModes.has(categoryMode)){
    const exact = candidates.filter(c=>String(c.cropCategory || '') === categoryMode);
    if(exact.length){
      candidates = exact;
    }else{
      return [];
    }
  }else if(categoryMode !== 'mixed'){
    const exact = candidates.filter(c=>String(c.cropCategory || '') === currentCategory);
    if(exact.length){
      candidates = exact.map(c=>({ ...c, categoryFitScore: 1 }));
    }else{
      const strong = candidates.filter(c=>safeNum(c.categoryFitScore,0) >= 0.70 || (c.sourceType === 'current_reference' && c.cropCategory === currentCategory));
      const near = candidates.filter(c=>safeNum(c.categoryFitScore,0) >= 0.40 || (c.sourceType === 'current_reference' && c.cropCategory === currentCategory));
      if(strong.length >= Math.min(4, candidates.length)) candidates = strong;
      else if(near.length >= 3) candidates = near;
    }
  }
  return candidates;
}

function evaluateAnnualCandidateForParcel(parcel, candidate, currentTotals, scenarioKey, share=1, role='Ana ürün'){
  const areaDa = safeNum(parcel?.area_da || parcel?.area, 0);
  const area = +(areaDa * share).toFixed(1);
  const name = prettyCropName(candidate.name);
  const waterPerDa = safeNum(candidate.waterPerDa, 0);
  const profitPerDa = safeNum(candidate.profitPerDa, 0);
  const irrigationKey = candidate.irrigationKey || irrigationKeysForCrop(name).suggestedKey || irrigationKeysForCrop(name).currentKey || 'sprinkler';
  const row = {
    name,
    area,
    season: role === 'Ana ürün' && share >= 0.99 ? (candidate.season || inferSeasonFromCropName(name) || 'Tek sezon') : 'Desen payı',
    irrigationCurrentKey: irrigationKey,
    irrigationCurrentText: irrigationLabel(irrigationKey),
    irrigationSuggestedKey: irrigationKey,
    irrigationSuggestedText: irrigationLabel(irrigationKey),
    irrigationSuggested: irrigationLabel(irrigationKey),
    _baseWaterPerDa: waterPerDa * Math.max(0.35, IRR_EFF[irrigationKey] || STATE.irrigEfficiency || 0.62),
    waterPerDa,
    profitPerDa,
    totalWater: area * waterPerDa,
    totalProfit: area * profitPerDa,
    candidateSourceVillage: candidate.candidateSourceVillage || '',
    sourceType: candidate.sourceType,
    cropCategory: candidate.cropCategory,
    cropCategoryLabel: candidate.cropCategoryLabel,
    cropCategoryMode: candidate.cropCategoryMode,
    categoryFitScore: safeNum(candidate.categoryFitScore, 0),
    categoryFallback: !!candidate.categoryFallback,
    categoryFallbackNote: candidate.categoryFallbackNote || '',
    cropFamily: candidate.cropFamily,
    patternShare: share,
    patternPercent: Math.round(share * 100),
  };
  const metrics = planDecisionMetricsV8(parcel, [row], currentTotals, scenarioKey);
  const suit = cropSuitabilityForParcel(parcel, name);
  const quotaOk = !!metrics.quotaOk;
  const economicFloor = safeNum(currentTotals?.profit, 0) > 0 ? safeNum(metrics.candidateProfit,0) >= safeNum(currentTotals.profit,0) * 0.20 : true;
  return {
    type: candidate.sourceType === 'current_reference' ? 'current_reference' : 'candidate',
    label: candidate.sourceType === 'current_reference' ? 'Mevcut referans' : name,
    rows: [row],
    totals: sumMetrics([row]),
    metrics: { ...metrics, quotaOk, quota_ok: quotaOk, fullFeasible: quotaOk, suitabilityScore:suit.score, suitabilityLabel:suit.label, suitabilityBasis:suit.basis },
    c1: name,
    c2: null,
    sourceType: candidate.sourceType,
    candidateSourceVillage: candidate.candidateSourceVillage,
    seenInSelectedVillage: !!candidate.seenInSelectedVillage,
    seenInOtherVillages: !!candidate.seenInOtherVillages,
    candidateVillageCount: safeNum(candidate.candidateVillageCount,0),
    cropCategory: candidate.cropCategory,
    cropCategoryLabel: candidate.cropCategoryLabel,
    cropCategoryMode: candidate.cropCategoryMode,
    categoryFitScore: safeNum(candidate.categoryFitScore,0),
    categoryFallback: !!candidate.categoryFallback,
    categoryFallbackNote: candidate.categoryFallbackNote || '',
    cropFamily: candidate.cropFamily,
    season: candidate.season,
    economicFloor,
  };
}

function _normalizeAnnualScores(scored){
  const vals = (fn)=>scored.map(fn).filter(Number.isFinite);
  const range = (arr)=>({ min: Math.min(...arr, 0), max: Math.max(...arr, 1) });
  const water = range(vals(c=>safeNum(c.metrics?.candidateWater,0)));
  const profit = range(vals(c=>safeNum(c.metrics?.candidateProfit,0)));
  const wue = range(vals(c=>safeNum(c.metrics?.candidateWUE,0)));
  const saving = range(vals(c=>safeNum(c.metrics?.waterSaving,0)));
  const norm = (v,r)=> Math.abs(r.max-r.min) < 1e-9 ? 0.5 : clamp((v-r.min)/(r.max-r.min),0,1);
  return { water, profit, wue, saving, norm };
}

function scoreAnnualCandidateByObjective(candidate, objectiveKey, ranges, context={}){
  const obj = decisionObjectiveKeyV8(objectiveKey);
  const m = candidate.metrics || {};
  const n = ranges.norm;
  const currentProfit = safeNum(context.currentProfit, 0);
  const currentWUE = safeNum(context.currentWUE, 0);
  const waterScore = 1 - n(safeNum(m.candidateWater,0), ranges.water);
  const profitScore = n(safeNum(m.candidateProfit,0), ranges.profit);
  const efficiencyScore = n(safeNum(m.candidateWUE,0), ranges.wue);
  const savingScore = n(safeNum(m.waterSaving,0), ranges.saving);
  const quotaScore = (m.fullFeasible || m.quotaOk) ? 1 : 0;
  const suitabilityScore = clamp(safeNum(m.suitabilityScore,0.78),0,1);
  const categoryFitScore = clamp(safeNum(candidate.categoryFitScore,0.72),0,1);
  const currentFamily = context.currentFamily || '';
  const familyPenalty = candidate.cropFamily && currentFamily && candidate.cropFamily === currentFamily && candidate.type !== 'current_reference' ? 0.16 : 0;
  const rotationPenalty = familyPenalty;
  const fieldToVegetablePenalty = /Tahıl|Yem|Poaceae/i.test(currentFamily) && !/Tahıl|Yem|Baklagil|Poaceae/i.test(candidate.cropFamily || '') && candidate.type !== 'current_reference' ? 0.50 : 0;
  const localRegionalScore = candidate.sourceType === 'current_reference'
    ? 0.12
    : (candidate.seenInSelectedVillage ? 0.10 : (candidate.seenInOtherVillages ? 0.03 : -0.04));
  const lowEconomyPenalty = candidate.economicFloor ? 0 : 0.35;
  const waterSavingProfitFloorPenalty = (obj === 'water_saving' && currentProfit > 0 && safeNum(m.candidateProfit,0) < currentProfit * 0.35 && candidate.type !== 'current_reference') ? 0.34 : 0;
  const waterEfficiencyWeakPenalty = (obj === 'water_efficiency' && currentProfit > 0 && currentWUE > 0 && safeNum(m.candidateProfit,0) < currentProfit * 0.75 && safeNum(m.candidateWUE,0) < currentWUE * 0.95 && candidate.type !== 'current_reference') ? 0.42 : 0;
  const quotaPenalty = quotaScore ? 0 : 0.45;
  const categoryPenalty = Math.max(0, 1 - categoryFitScore) * 0.32;
  let finalScore;
  if(obj === 'water_saving'){
    finalScore = 0.42 * waterScore + 0.14 * savingScore + 0.11 * profitScore + 0.07 * efficiencyScore + 0.07 * suitabilityScore + 0.05 * quotaScore + 0.14 * categoryFitScore + localRegionalScore;
  }else if(obj === 'max_profit'){
    finalScore = 0.52 * profitScore + 0.13 * efficiencyScore + 0.07 * waterScore + 0.07 * suitabilityScore + 0.07 * quotaScore + 0.14 * categoryFitScore + localRegionalScore;
  }else{
    finalScore = 0.42 * efficiencyScore + 0.23 * profitScore + 0.15 * savingScore + 0.05 * suitabilityScore + 0.03 * quotaScore + 0.12 * categoryFitScore + localRegionalScore;
  }
  finalScore -= quotaPenalty + lowEconomyPenalty + rotationPenalty + fieldToVegetablePenalty + categoryPenalty + waterSavingProfitFloorPenalty + waterEfficiencyWeakPenalty;
  return {
    ...candidate,
    waterScore,
    profitScore,
    efficiencyScore,
    categoryFitScore,
    categoryPenalty,
    rotationPenalty,
    familyPenalty,
    fieldToVegetablePenalty,
    waterSavingProfitFloorPenalty,
    waterEfficiencyWeakPenalty,
    diversityPenalty: 0,
    localRegionalScore,
    finalScore,
    score: finalScore,
  };
}

function _annualCandidateDominates(a,b){
  const am = a.metrics || {};
  const bm = b.metrics || {};
  const aOk = !!(am.fullFeasible || am.quotaOk);
  const bOk = !!(bm.fullFeasible || bm.quotaOk);
  if(aOk && !bOk) return true;
  if(!aOk && bOk) return false;
  const aw = safeNum(am.candidateWater, Number.POSITIVE_INFINITY);
  const bw = safeNum(bm.candidateWater, Number.POSITIVE_INFINITY);
  const ap = safeNum(am.candidateProfit, 0);
  const bp = safeNum(bm.candidateProfit, 0);
  const ae = safeNum(am.candidateWUE, 0);
  const be = safeNum(bm.candidateWUE, 0);
  const apen = safeNum(a.rotationPenalty, 0) + safeNum(a.fieldToVegetablePenalty, 0) + Math.max(0, 1 - safeNum(a.categoryFitScore, 0)) * 0.35;
  const bpen = safeNum(b.rotationPenalty, 0) + safeNum(b.fieldToVegetablePenalty, 0) + Math.max(0, 1 - safeNum(b.categoryFitScore, 0)) * 0.35;
  if(apen > bpen + 1e-9) return false;
  return aw <= bw + Math.max(1,bw*0.002)
    && ap >= bp - Math.max(1,bp*0.002)
    && ae >= be - Math.max(0.01,be*0.002)
    && (aw < bw - Math.max(1,bw*0.005) || ap > bp + Math.max(1,bp*0.005) || ae > be + Math.max(0.01,be*0.005));
}

function _annualRankReason(candidate, objectiveKey, scenarioMode){
  const obj = decisionObjectiveKeyV8(objectiveKey);
  if(candidate.type === 'current_reference'){
    if(obj === 'water_efficiency') return 'Mevcut desen, birim su başına gelir ve toplam kâr açısından alternatiflerden daha güçlü olduğu için su etkin kullanım hedefinde korunmuştur.';
    if(obj === 'max_profit') return 'Mevcut desen bu hedefte alternatiflerden daha yüksek veya daha güvenilir kâr sunduğu için korunmuştur.';
    return 'Mevcut desen bu hedefte alternatiflerden daha avantajlı olduğu için korunmuştur.';
  }
  const risk = candidate.referenceRiskNote ? ` ${candidate.referenceRiskNote}` : '';
  const lowerWater = candidate.lowerWaterReason ? ` ${candidate.lowerWaterReason}` : '';
  const fallback = scenarioMode === 's2' && (!candidate.rows || candidate.rows.length <= 1) ? ' İkinci ürün uygun bulunamadığı için tek ürün önerisi gösterilmiştir.' : '';
  const cat = candidate.cropCategoryLabel || cropCategoryLabel(candidate.cropCategory || '');
  const fit = Math.round(safeNum(candidate.categoryFitScore, 0) * 100);
  const algo = String(STATE.farmerAlgoModeV7 === 'auto' ? (STATE.autoAlgoDecisionV7?.selected || 'otomatik') : (STATE.farmerAlgoModeV7 || selectedAlgo || 'ga')).toUpperCase();
  const catText = cat ? ` Ürün grubu uyumu: ${cat} (${fit}%). Algoritma: ${algo}.` : ` Algoritma: ${algo}.`;
  const catFallback = candidate.categoryFallbackNote ? ` ${candidate.categoryFallbackNote}` : '';
  if(obj === 'water_saving') return `Bu aday su kullanımını düşürürken ekonomik eşik, kota ve parsel uygunluğu birlikte sağlandığı için seçilmiştir.${catText}${catFallback}${lowerWater}${risk}${fallback}`;
  if(obj === 'max_profit') return `Bu aday uygulanabilir ve kota uygun adaylar içinde en yüksek net kârı verdiği için seçilmiştir.${catText}${catFallback}${risk}${fallback}`;
  return `Bu aday TL/m³, net kâr, su kullanımı ve kota uygunluğu birlikte değerlendirildiğinde en güçlü aday olduğu için seçilmiştir.${catText}${catFallback}${risk}${fallback}`;
}

function rankAnnualCandidates(candidates, objectiveKey, context={}){
  const list = (Array.isArray(candidates) ? candidates : []).filter(c=>safeNum(c?.metrics?.candidateProfit,0) > 0);
  if(!list.length) return [];
  const ranges = _normalizeAnnualScores(list);
  const currentFamily = context.currentRows?.[0] ? _annualCropFamily(context.currentRows[0].name) : '';
  const currentTotals = sumMetrics(context.currentRows || []);
  let scored = list.map(c=>scoreAnnualCandidateByObjective(c, objectiveKey, ranges, {
    currentFamily,
    currentProfit: safeNum(currentTotals.profit, 0),
    currentWUE: safeNum(currentTotals.water, 0) > 0 ? safeNum(currentTotals.profit, 0) / safeNum(currentTotals.water, 1) : 0,
  }));
  const obj = decisionObjectiveKeyV8(objectiveKey);
  scored.sort((a,b)=>{
    const af = a.metrics?.fullFeasible || a.metrics?.quotaOk ? 1 : 0;
    const bf = b.metrics?.fullFeasible || b.metrics?.quotaOk ? 1 : 0;
    if(af !== bf) return bf - af;
    const ac = safeNum(a.categoryFitScore,0) >= 0.70 ? 1 : 0;
    const bc = safeNum(b.categoryFitScore,0) >= 0.70 ? 1 : 0;
    if(ac !== bc) return bc - ac;
    if(obj === 'water_saving'){
      const ae = a.economicFloor ? 1 : 0;
      const be = b.economicFloor ? 1 : 0;
      if(ae !== be) return be - ae;
      const scoreDiff = safeNum(b.finalScore,0)-safeNum(a.finalScore,0);
      if(Math.abs(scoreDiff) > 0.08) return scoreDiff;
      return safeNum(a.metrics?.candidateWater,0)-safeNum(b.metrics?.candidateWater,0);
    }
    if(obj === 'max_profit'){
      if(Math.abs(safeNum(a.metrics?.candidateProfit,0)-safeNum(b.metrics?.candidateProfit,0)) > 1e-6) return safeNum(b.metrics?.candidateProfit,0)-safeNum(a.metrics?.candidateProfit,0);
      return safeNum(a.metrics?.candidateWater,0)-safeNum(b.metrics?.candidateWater,0);
    }
    if(waterEfficiencyEconomicAdvantageV8(a.metrics,b.metrics)) return -1;
    if(waterEfficiencyEconomicAdvantageV8(b.metrics,a.metrics)) return 1;
    return safeNum(b.finalScore,0)-safeNum(a.finalScore,0);
  });
  const dominator = scored.slice(1).find(c=>_annualCandidateDominates(c, scored[0]));
  if(dominator){
    scored = [dominator, ...scored.filter(c=>c!==dominator)];
  }
  scored.forEach(c=>{ delete c.lowerWaterReason; });
  if(obj === 'water_saving' && scored[0]){
    const lowerWater = scored.slice(1).find(c=>
      (c.metrics?.fullFeasible || c.metrics?.quotaOk)
      && safeNum(c.metrics?.candidateWater,0) < safeNum(scored[0].metrics?.candidateWater,0) - 1e-6
    );
    if(lowerWater){
      scored[0].lowerWaterReason = 'Daha düşük su kullanan adaylar ekonomik alt eşik / kota / uygulanabilirlik nedeniyle geriye alınmıştır.';
    }
  }
  const currentRef = scored.find(c=>c.type === 'current_reference');
  if(currentRef && scored[0] && (obj !== 'water_saving') && (_annualCandidateDominates(currentRef, scored[0]) || waterEfficiencyEconomicAdvantageV8(currentRef.metrics, scored[0].metrics))){
    scored = [currentRef, ...scored.filter(c=>c!==currentRef)];
  }
  const ref = currentRef;
  if(ref && scored[0] !== ref && safeNum(ref.metrics?.candidateProfit,0) > safeNum(scored[0]?.metrics?.candidateProfit,0) * 1.08 && !(ref.metrics?.fullFeasible || ref.metrics?.quotaOk)){
    scored[0].referenceRiskNote = 'Mevcut ürün daha kârlıdır ancak kota/uygunluk riski nedeniyle ana öneri yapılmamıştır.';
  }
  const first = scored[0];
  const rest = scored.slice(1);
  const picked = [first];
  const familyUse = new Map([[first.cropFamily || '', 1]]);
  for(const cand of rest){
    const fam = cand.cropFamily || '';
    const use = familyUse.get(fam) || 0;
    cand.diversityPenalty = use > 0 ? Math.min(0.18, use * 0.06) : 0;
    familyUse.set(fam, use+1);
  }
  rest.sort((a,b)=>safeNum(b.finalScore,0)-safeNum(b.diversityPenalty,0)-safeNum(a.finalScore,0)+safeNum(a.diversityPenalty,0));
  picked.push(...rest);
  return picked.map((c,idx)=>{
    const rankReason = _annualRankReason(c, objectiveKey, context.scenarioMode || _seasonModeKey());
    return {
      ...c,
      targetOrder: idx+1,
      rankReason,
      debugRank: {
        rank: idx+1,
        label: c.label || c.c1 || c.rows?.[0]?.name || '',
        objective: decisionObjectiveKeyV8(objectiveKey),
        scenario: context.scenarioMode || _seasonModeKey(),
        is_current_reference: c.type === 'current_reference',
        totalWater: safeNum(c.metrics?.candidateWater,0),
        totalProfit: safeNum(c.metrics?.candidateProfit,0),
        tlPerM3: safeNum(c.metrics?.candidateWUE,0),
        waterSavingPct: safeNum(c.metrics?.baselineWater,0) > 0 ? 100 * safeNum(c.metrics?.waterSaving,0) / safeNum(c.metrics?.baselineWater,1) : 0,
        profitDelta: safeNum(c.metrics?.profitDelta,0),
        quota_ok: !!c.metrics?.quotaOk,
        fullFeasible: !!c.metrics?.fullFeasible,
        sourceType: c.sourceType,
        candidateSourceVillage: c.candidateSourceVillage || '',
        seenInSelectedVillage: !!c.seenInSelectedVillage,
        seenInOtherVillages: !!c.seenInOtherVillages,
        candidateVillageCount: safeNum(c.candidateVillageCount,0),
        cropFamily: c.cropFamily,
        category: c.cropCategory,
        cropCategoryMode: c.cropCategoryMode,
        categoryFitScore: safeNum(c.categoryFitScore,0),
        season: c.season || '',
        waterScore: safeNum(c.waterScore,0),
        profitScore: safeNum(c.profitScore,0),
        efficiencyScore: safeNum(c.efficiencyScore,0),
        categoryPenalty: safeNum(c.categoryPenalty,0),
        rotationPenalty: safeNum(c.rotationPenalty,0),
        familyPenalty: safeNum(c.familyPenalty,0),
        fieldToVegetablePenalty: safeNum(c.fieldToVegetablePenalty,0),
        diversityPenalty: safeNum(c.diversityPenalty,0),
        localRegionalScore: safeNum(c.localRegionalScore,0),
        objectiveScore: safeNum(c.score,0),
        finalScore: safeNum(c.finalScore,0),
        rankReason
      }
    };
  });
}

function buildAnnualRecommendationPayload(parcel, currentRows, scenarioKey){
  const seasonMode = _seasonModeKey();
  const universe = buildAnnualCandidateUniverse(parcel, currentRows, scenarioKey);
  const currentTotals = sumMetrics(currentRows || []);
  if(!universe.length){
    const reason = 'Seçilen ürün grubunda bu parsel için güvenilir aday bulunamadı; kategori dışı ürünler ana öneri yapılmadı ve mevcut desen referans olarak korundu.';
    const rows = (currentRows || []).map(r=>({ ...r, currentReference:true }));
    const metrics = planDecisionMetricsV8(parcel, rows, currentTotals, scenarioKey);
    const selected = {
      type:'current_reference',
      label:'Mevcut referans',
      rows,
      totals: sumMetrics(rows),
      metrics,
      c1: rows[0]?.name || '',
      c2: null,
      cropCategory: annualCropCategoryFromName(rows[0]?.name || ''),
      cropCategoryLabel: cropCategoryLabel(annualCropCategoryFromName(rows[0]?.name || '')),
      cropCategoryMode: currentCropCategoryMode(),
      categoryFitScore: 0,
      rankReason: reason,
      debugRank: { rank:1, rankReason: reason, hardFilterPassed:false, is_current_reference:true }
    };
    return {
      selected,
      rankedCandidates:[selected],
      rows,
      totals: selected.totals,
      irrigationPlan: '',
      decisionMetrics: metrics,
      decisionReason: reason
    };
  }
  const evaluated = [];
  const currentKeys = new Set((currentRows || []).map(r=>normCropName(r.name)));
  for(const cand of universe){
    const evaluatedOne = evaluateAnnualCandidateForParcel(parcel, cand, currentTotals, scenarioKey, 1, 'Ana ürün');
    if(currentKeys.has(normCropName(cand.name))) evaluatedOne.type = 'current_reference';
    evaluated.push(evaluatedOne);
  }
  if(seasonMode === 's2'){
    const annual = universe.filter(c=>c.sourceType !== 'current_reference');
    const byScoreSeed = annual.slice().sort((a,b)=>safeNum(b.tlPerM3,0)-safeNum(a.tlPerM3,0)).slice(0,10);
    for(const c1 of byScoreSeed){
      const c2 = annual.find(x=>normCropName(x.name)!==normCropName(c1.name) && x.cropFamily !== c1.cropFamily);
      if(!c2) continue;
      const share2 = decisionObjectiveKeyV8(scenarioKey) === 'max_profit' ? 0.35 : 0.30;
      const e1 = evaluateAnnualCandidateForParcel(parcel, c1, currentTotals, scenarioKey, 1-share2, 'Ana ürün');
      const e2 = evaluateAnnualCandidateForParcel(parcel, c2, currentTotals, scenarioKey, share2, '2. ürün / ara ürün');
      const rows = [...e1.rows, ...e2.rows];
      const metrics = planDecisionMetricsV8(parcel, rows, currentTotals, scenarioKey);
      evaluated.push({
        type:'candidate',
        label:`${prettyCropName(c1.name)} + ${prettyCropName(c2.name)}`,
        rows,
        totals: sumMetrics(rows),
        metrics: { ...metrics, quotaOk: metrics.quotaOk, quota_ok: metrics.quotaOk, fullFeasible: metrics.quotaOk },
        c1: prettyCropName(c1.name),
        c2: prettyCropName(c2.name),
        sourceType: c1.seenInSelectedVillage || c2.seenInSelectedVillage ? 'local_village_crop' : 'regional_5_village_crop',
        seenInSelectedVillage: !!(c1.seenInSelectedVillage || c2.seenInSelectedVillage),
        seenInOtherVillages: !!(c1.seenInOtherVillages || c2.seenInOtherVillages),
        candidateVillageCount: Math.max(safeNum(c1.candidateVillageCount,0), safeNum(c2.candidateVillageCount,0)),
        cropCategory: c1.cropCategory === c2.cropCategory ? c1.cropCategory : `${c1.cropCategory}+${c2.cropCategory}`,
        cropCategoryLabel: c1.cropCategory === c2.cropCategory ? cropCategoryLabel(c1.cropCategory) : `${cropCategoryLabel(c1.cropCategory)} + ${cropCategoryLabel(c2.cropCategory)}`,
        cropCategoryMode: c1.cropCategoryMode || currentCropCategoryMode(),
        categoryFitScore: (safeNum(c1.categoryFitScore,0) + safeNum(c2.categoryFitScore,0)) / 2,
        cropFamily: `${c1.cropFamily}+${c2.cropFamily}`,
        season:'Çift ürün / desen',
        economicFloor: true
      });
    }
  }
  const rankedCandidates = rankAnnualCandidates(evaluated, scenarioKey, { currentRows, scenarioMode: seasonMode });
  const selected = rankedCandidates[0] || evaluated[0] || null;
  return {
    selected,
    rankedCandidates,
    rows: selected?.rows || currentRows || [],
    totals: selected?.totals || sumMetrics(selected?.rows || []),
    irrigationPlan: selected ? 'Sulama önerisi: ' + (selected.rows||[]).map(r=>`${r.name} → ${r.irrigationSuggested || r.irrigationSuggestedText || irrigationLabel(r.irrigationSuggestedKey)}`).join(' | ') : '',
    decisionMetrics: selected?.metrics || null,
    decisionReason: selected ? _annualRankReason(selected, scenarioKey, seasonMode) : '',
  };
}

function _fieldCandidatePool(parcel, currentRows){
  return buildAnnualCandidateUniverse(parcel, currentRows, selectedScenario).map(c=>({
    name: c.name,
    waterPerDa: c.waterPerDa,
    profitPerDa: c.profitPerDa,
    tlPerM3: c.tlPerM3,
    irrigationKey: c.irrigationKey,
    family: c.cropFamily,
    suitability: cropSuitabilityForParcel(parcel, c.name),
    sourceType: c.sourceType,
    candidateSourceVillage: c.candidateSourceVillage,
  }));
}

function buildUiAlternativePatterns(parcel, currentRows, recRows, recMeta, scenarioKey){
  const scenarioType = _seasonModeKey();
  const n = (value, fallback=0)=>{ const v = Number(value); return Number.isFinite(v) ? v : fallback; };
  const areaDa = n(parcel?.area_da, 0);
  const currentMain = Array.isArray(currentRows) && currentRows.length ? [...currentRows].sort((a,b)=>safeNum(b.area)-safeNum(a.area))[0] : null;
  const recMain = Array.isArray(recRows) && recRows.length ? recRows[0] : currentMain;
  const isOrchard = scenarioType === 's2' && !!(parcel?.parcel_type === 'orchard' || parcel?.is_orchard || (currentMain && isPerennialCropName(currentMain.name)) || recMeta?.orchardKeepMainCrop);
  const patterns = [];
  const baselineTotals = sumMetrics(Array.isArray(currentRows) ? currentRows : []);
  const quota = (typeof parcelWaterBudget === 'function') ? n(parcelWaterBudget(areaDa, parcel), 0) : 0;
  const selectedObjective = normalizeScenarioKey(scenarioKey);
  const quotaScore = (water)=> (quota > 0 && water > quota) ? -Math.abs(water - quota) * 1000 : 0;
  const component = (crop, share, source, role, totals={})=>{
    const name = prettyCropName(crop || source?.name || '-');
    const pct = clamp(n(share, 0), 0, 1);
    const area = n(totals.area, areaDa * pct);
    const waterPerDa = n(totals.waterPerDa, n(source?.waterPerDa, 0));
    const profitPerDa = n(totals.profitPerDa, n(source?.profitPerDa, 0));
    const water = n(totals.water, area * waterPerDa);
    const profit = n(totals.profit, area * profitPerDa);
    const irrKey = totals.irrigationKey || source?.irrigationKey || source?.irrigationSuggestedKey || source?.irrigationCurrentKey || irrigationKeysForCrop(name).suggestedKey || 'sprinkler';
    return {
      crop: name,
      role,
      share: pct,
      percent: Math.round(pct * 100),
      area,
      water,
      profit,
      waterPerDa: area > 0 ? water / area : waterPerDa,
      profitPerDa: area > 0 ? profit / area : profitPerDa,
      irrigationKey: irrKey,
      irrigation: totals.irrigation || source?.irrigationSuggestedText || source?.irrigationSuggested || irrigationLabel(irrKey),
      season: totals.season || source?.season || (scenarioType === 's2' ? 'Desen payı' : (inferSeasonFromCropName(name) || 'Tek sezon')),
    };
  };
  const splitLabel = (components)=> (components || [])
    .filter(c=>safeNum(c.share, 0) > 0)
    .map(c=>`${c.role || 'Ürün'} %${Math.round(safeNum(c.share,0)*100)}`)
    .join(' + ') || 'Ana ürün %100';
  const patternWithDerived = (pattern)=>{
    const water = safeNum(pattern.totalWater, 0);
    const profit = safeNum(pattern.totalProfit, 0);
    return {
      ...pattern,
      deltaWater: water - n(baselineTotals.water, 0),
      deltaProfit: profit - n(baselineTotals.profit, 0),
      quotaExceeded: quota > 0 && water > quota,
      score: safeNum(pattern.score, 0) + quotaScore(water),
    };
  };
  const rowsToComponents = (rows, forceSingle=false)=>{
    const list = Array.isArray(rows) ? rows.filter(Boolean) : [];
    const used = forceSingle ? list.slice(0,1) : list.slice(0, Math.max(1, Math.min(3, list.length)));
    if(!used.length || !(areaDa > 0)) return [];
    if(used.length === 1) return [component(used[0].name, 1, used[0], 'Ana ürün')];
    const rawArea = used.reduce((a,r)=>a+n(r.area,0),0);
    const sequentialLike = rawArea > areaDa * 1.20;
    const eq = 1 / used.length;
    return used.map((r, idx)=>{
      const share = sequentialLike ? eq : clamp(n(r.area,0) / Math.max(1, rawArea), 0.05, 0.90);
      return component(r.name, share, r, idx === 0 ? 'Ana ürün' : (idx === 1 ? '2. ürün / ara ürün' : `${idx+1}. ürün`), { season:'Desen payı' });
    });
  };
  const selectedRecommendationPattern = (() => {
    const recList = Array.isArray(recRows) ? recRows.filter(Boolean) : [];
    if(!recList.length || !areaDa) return null;
    const components = rowsToComponents(recList, scenarioType === 's1');
    const totalWater = components.reduce((a,r)=>a+safeNum(r.water,0),0);
    const totalProfit = components.reduce((a,r)=>a+safeNum(r.profit,0),0);
    const mainRow = recList[0];
    const secondRow = components.find((r,idx)=>idx>0 && normCropName(r.crop)!==normCropName(mainRow?.name));
    const suit = patternSuitabilitySummary(parcel, recList);
    const secondName = secondRow ? prettyCropName(secondRow.crop) : '-';
    return {
      selectedRecommendation: true,
      patternName: secondRow ? `${prettyCropName(mainRow.name)} + ${secondName}` : `${prettyCropName(mainRow.name)} önerilen desen`,
      mainCrop: prettyCropName(mainRow.name),
      secondaryCrop: secondName,
      areaSplit: splitLabel(components),
      irrigation: components.map(r=>r.irrigation).filter(Boolean).join(' / '),
      totalWater,
      totalProfit,
      tlPerM3: totalWater > 0 ? totalProfit / totalWater : 0,
      peakMonth: recList.map(r=>cropPeakMonthLabel(r.name)).filter(Boolean).join(' / '),
      seasonLabel: secondRow ? 'Seçili yıllık desen' : (inferSeasonFromCropName(mainRow.name) || 'Tek sezon'),
      note: 'Seçili senaryo + algoritma önerisi',
      suitability: `${suit.label || 'Proxy'} (${Math.round(safeNum(suit.score,0)*100)}%)`,
      suitabilityBasis: suit.basis || '',
      growthDays: recList.map(r=>stageTotalDays(stageParamsForCrop(r.name))).join('+'),
      productionWindow: recList.map(r=>cropProductionWindowLabel(r.name)).join(' / '),
      components,
      score: Number.POSITIVE_INFINITY
    };
  })();
  if(isOrchard && currentMain){
    const main = prettyCropName(currentMain.name);
    const baseRow = recMain || currentMain;
    const baseWater = n(baseRow.totalWater, n(currentMain.totalWater,0));
    const baseProfit = n(baseRow.totalProfit, n(currentMain.totalProfit,0));
    const baseComponent = component(main, 1, baseRow, 'Ana ürün', { water:baseWater, profit:baseProfit, season:'Bahçe (çok yıllık)' });
    patterns.push({
      rank: 1,
      patternName: `${main} + temel bahçe yönetimi`,
      mainCrop: main,
      secondaryCrop: '-',
      areaSplit: 'Ana ürün %100',
      irrigation: baseRow.irrigationSuggestedText || baseRow.irrigationSuggested || baseRow.irrigationCurrentText || 'Damla',
      totalWater: baseWater,
      totalProfit: baseProfit,
      tlPerM3: baseWater > 0 ? (baseProfit/baseWater) : 0,
      peakMonth: _patternPeakMonthLabel({season:'Bahçe (çok yıllık)'}),
      seasonLabel: 'Bahçe (çok yıllık)',
      note: 'Ana ürün korunur; öneri sulama yöntemi ve yönetim desenine dayanır.',
      components: [baseComponent],
      score: _objectiveScorePattern(baseWater, baseProfit, scenarioKey)
    });
    const altMetrics = (Array.isArray(recMeta?.orchardAlternativeMetrics) && recMeta.orchardAlternativeMetrics.length)
      ? recMeta.orchardAlternativeMetrics
      : orchardAlternativeScenarioMetrics(main, areaDa, scenarioKey, baseRow, orchardAlternativeListFallback(currentRows, recRows, recMeta));
    altMetrics.forEach((a)=>{
      const altShare = clamp(n(a.area,0) / Math.max(1, areaDa), 0.10, 0.35);
      const mainShare = 1 - altShare;
      const totalWater = baseWater * mainShare + n(a.totalWater,0);
      const totalProfit = baseProfit * mainShare + n(a.totalProfit,0);
      const components = [
        component(main, mainShare, baseRow, 'Ana ürün', { water:baseWater * mainShare, profit:baseProfit * mainShare, season:'Desen payı' }),
        component(a.name, altShare, a, 'Sıra arası / ara ürün', { water:n(a.totalWater,0), profit:n(a.totalProfit,0), irrigationKey:a.irrigationKey, irrigation:a.irrigationText || 'Damla', season:'Desen payı' })
      ];
      patterns.push({
        patternName: `${main} + ${prettyCropName(a.name)}`,
        mainCrop: main,
        secondaryCrop: prettyCropName(a.name),
        areaSplit: splitLabel(components),
        irrigation: `${baseRow.irrigationSuggestedText || baseRow.irrigationSuggested || baseRow.irrigationCurrentText || 'Damla'} / ${a.irrigationText || 'Damla'}`,
        totalWater,
        totalProfit,
        tlPerM3: totalWater > 0 ? (totalProfit/totalWater) : 0,
        peakMonth: 'Haz-Tem',
        seasonLabel: 'Bahçe + sıra arası',
        note: a.note || `${main} ana ürün korunur; ara ürün yalnız sıra arası ve kontrollü oranda değerlendirilir.`,
        components,
        score: _objectiveScorePattern(totalWater, totalProfit, scenarioKey) + safeNum(a.score,0)*0.01
      });
    });
  } else {
    const pool = _fieldCandidatePool(parcel, currentRows);
    const obj = normalizeScenarioKey(scenarioKey);
    pool.sort((a,b)=>{
      const sa = clamp(safeNum(a?.suitability?.score, 0.78), 0, 1);
      const sb = clamp(safeNum(b?.suitability?.score, 0.78), 0, 1);
      if(obj === 'max_profit' || obj === 'maks_kar') return (safeNum(b.profitPerDa)*sb)-(safeNum(a.profitPerDa)*sa);
      if(obj === 'water_saving' || obj === 'su_tasarruf') return safeNum(a.waterPerDa)-safeNum(b.waterPerDa) || (safeNum(b.profitPerDa)*sb)-(safeNum(a.profitPerDa)*sa);
      return (safeNum(b.tlPerM3)*sb)-(safeNum(a.tlPerM3)*sa) || safeNum(a.waterPerDa)-safeNum(b.waterPerDa);
    });
    const top = pool.slice(0, Math.max(10, pool.length ? 10 : 0));
    if(scenarioType === 's1'){
      top.forEach((c)=>{
        const totalWater = areaDa * n(c.waterPerDa,0);
        const totalProfit = areaDa * n(c.profitPerDa,0);
        const components = [component(c.name, 1, c, 'Ana ürün', { water:totalWater, profit:totalProfit, irrigationKey:c.irrigationKey })];
        const st = stageParamsForCrop(c.name);
        const days = stageTotalDays(st);
        patterns.push({
          patternName: `${prettyCropName(c.name)} tek ürün`,
          mainCrop: prettyCropName(c.name),
          secondaryCrop: '-',
          areaSplit: splitLabel(components),
          irrigation: irrigationLabel(c.irrigationKey),
          totalWater,
          totalProfit,
          tlPerM3: totalWater > 0 ? (totalProfit/totalWater) : 0,
          peakMonth: cropPeakMonthLabel(c.name),
          seasonLabel: inferSeasonFromCropName(c.name) || 'Tek sezon',
          note: (parcel?.parcel_type === 'orchard' || currentMain && isPerennialCropName(currentMain.name))
            ? 'Senaryo 1 tek ürün dönüşüm alternatifidir; kurulu bahçede uygulanması uzman onayı ve tesis dönüşümü gerektirir.'
            : 'Tek ürünlü parsel senaryosu',
          suitability: `${c.suitability?.label || 'Proxy'} (${Math.round(safeNum(c.suitability?.score,0)*100)}%)`,
          suitabilityBasis: c.suitability?.basis || '',
          growthDays: days,
          productionWindow: cropProductionWindowLabel(c.name),
          components,
          score: _objectiveScorePattern(totalWater, totalProfit, scenarioKey) * Math.max(0.6, n(c.suitability?.score,0.78))
        });
      });
    } else {
      const winterNames = /BUGDAY|ARPA|CAVDAR|YULAF|TRITIKALE|MERCIMEK|NOHUT|FIG|YEM|BEZELYE|SOGAN|SARIMSAK|LAHANA|MARUL|ISPANAK|TURP/;
      const summerNames = /AYCICEGI|MISIR|PANCAR|PATATES|KIMYON|DOMATES|BIBER|KABAK|HAVUC|FASULYE/;
      const first = top.filter(c=>isAnnualFieldCandidateName(c.name)).slice(0,8);
      const seconds = pool
        .filter(x=>isAnnualFieldCandidateName(x.name))
          .filter(x=>n(x.suitability?.score,0.78) >= 0.65)
        .slice(0,30);
      first.forEach((c1, idx)=>{
        const c1Key = normCropName(c1.name);
        const c1SeasonGuess = inferSeasonFromCropName(c1.name);
        const c1Winter = c1SeasonGuess === 'Kışlık' || winterNames.test(c1Key);
        const c1Summer = c1SeasonGuess === 'Yazlık' || summerNames.test(c1Key);
        const c2 = seconds.find(x=>{
          const xk = normCropName(x.name);
          if(x.family && c1.family && x.family === c1.family) return false;
          const xSeasonGuess = inferSeasonFromCropName(x.name);
          const xWinter = xSeasonGuess === 'Kışlık' || winterNames.test(xk);
          const xSummer = xSeasonGuess === 'Yazlık' || summerNames.test(xk);
          return c1Winter ? xSummer : (c1Summer ? xWinter : xWinter);
        }) || null;
        const secondShareBase = selectedObjective === 'water_saving' ? 0.30 : (selectedObjective === 'max_profit' ? 0.38 : 0.34);
        const secondShare = c2 ? clamp(secondShareBase + ((idx % 3) - 1) * 0.04, 0.25, 0.45) : 0;
        const mainShare = c2 ? (1 - secondShare) : 1;
        const totalWater = areaDa*mainShare*n(c1.waterPerDa,0) + (c2 ? areaDa*secondShare*n(c2.waterPerDa,0) : 0);
        const totalProfit = areaDa*mainShare*n(c1.profitPerDa,0) + (c2 ? areaDa*secondShare*n(c2.profitPerDa,0) : 0);
        const st1 = stageParamsForCrop(c1.name);
        const st2 = c2 ? stageParamsForCrop(c2.name) : null;
        const days1 = stageTotalDays(st1);
        const days2 = st2 ? stageTotalDays(st2) : 0;
        const suitScore = Math.min(n(c1.suitability?.score,0.78), c2 ? n(c2.suitability?.score,0.78) : 1);
        const components = c2
          ? [
              component(c1.name, mainShare, c1, 'Ana ürün', { water:areaDa*mainShare*n(c1.waterPerDa,0), profit:areaDa*mainShare*n(c1.profitPerDa,0), irrigationKey:c1.irrigationKey, season:'Desen payı' }),
              component(c2.name, secondShare, c2, '2. ürün / ara ürün', { water:areaDa*secondShare*n(c2.waterPerDa,0), profit:areaDa*secondShare*n(c2.profitPerDa,0), irrigationKey:c2.irrigationKey, season:'Desen payı' })
            ]
          : [component(c1.name, 1, c1, 'Ana ürün', { water:totalWater, profit:totalProfit, irrigationKey:c1.irrigationKey })];
        patterns.push({
          patternName: c2 ? `${prettyCropName(c1.name)} + ${prettyCropName(c2.name)}` : `${prettyCropName(c1.name)} tek ürün`,
          mainCrop: prettyCropName(c1.name),
          secondaryCrop: c2 ? prettyCropName(c2.name) : '-',
          areaSplit: splitLabel(components),
          irrigation: c2 ? `${irrigationLabel(c1.irrigationKey)} / ${irrigationLabel(c2.irrigationKey)}` : irrigationLabel(c1.irrigationKey),
          totalWater,
          totalProfit,
          tlPerM3: totalWater > 0 ? (totalProfit/totalWater) : 0,
          peakMonth: c2 ? `${cropPeakMonthLabel(c1.name)} / ${cropPeakMonthLabel(c2.name)}` : cropPeakMonthLabel(c1.name),
          seasonLabel: c2 ? 'Çift ürün / desen' : (inferSeasonFromCropName(c1.name) || 'Tek sezon'),
          note: c2 ? 'Yıllık desen olarak birlikte test edilir; 2. ürün bağımsız öneri değildir.' : 'Tek ürünlü fallback',
          suitability: `${c1.suitability?.label || 'Proxy'} / ${c2 ? (c2.suitability?.label || 'Proxy') : '-'}`,
          suitabilityBasis: [c1.suitability?.basis, c2?.suitability?.basis].filter(Boolean).join(' | '),
          growthDays: c2 ? `${days1}+${days2}` : days1,
          productionWindow: c2 ? `${cropProductionWindowLabel(c1.name)} / ${cropProductionWindowLabel(c2.name)}` : cropProductionWindowLabel(c1.name),
          components,
          score: _objectiveScorePattern(totalWater, totalProfit, scenarioKey) * Math.max(0.6, suitScore)
        });
      });
    }
  }
  let displayPatterns = patterns.map(patternWithDerived).sort((a,b)=>safeNum(b.score)-safeNum(a.score));
  if(!displayPatterns.find(p=>p.referencePattern) && currentMain && areaDa > 0){
    const refWater = n(currentMain.totalWater, areaDa * n(currentMain.waterPerDa,0));
    const refProfit = n(currentMain.totalProfit, areaDa * n(currentMain.profitPerDa,0));
    displayPatterns.push(patternWithDerived({
      referencePattern: true,
      patternName: `${prettyCropName(currentMain.name)} mevcut referans`,
      mainCrop: prettyCropName(currentMain.name),
      secondaryCrop: '-',
      areaSplit: 'Ana ürün %100',
      irrigation: currentMain.irrigationCurrentText || irrigationLabel(currentMain.irrigationCurrentKey),
      totalWater: refWater,
      totalProfit: refProfit,
      tlPerM3: refWater > 0 ? refProfit / refWater : 0,
      peakMonth: cropPeakMonthLabel(currentMain.name),
      seasonLabel: currentMain.season || inferSeasonFromCropName(currentMain.name) || 'Tek sezon',
      note: 'Mevcut desen korunursa oluşan referans sonuç; alternatifleri bununla karşılaştırın.',
      components: [component(currentMain.name, 1, currentMain, 'Ana ürün', { water:refWater, profit:refProfit })],
      score: _objectiveScorePattern(refWater, refProfit, scenarioKey) - 1
    }));
  }
  const isS1OrchardConversionView = scenarioType === 's1' && !!(parcel?.parcel_type === 'orchard' || parcel?.is_orchard || (currentMain && isPerennialCropName(currentMain.name)));
  const forceSelected = !!(selectedRecommendationPattern
    && !(scenarioType === 's2' && (!selectedRecommendationPattern.components || selectedRecommendationPattern.components.length <= 1))
    && !(isS1OrchardConversionView && isPerennialCropName(selectedRecommendationPattern.mainCrop)));
  if(forceSelected){
    const selA = normCropName(selectedRecommendationPattern.mainCrop);
    const selB = normCropName(selectedRecommendationPattern.secondaryCrop);
    displayPatterns = [
      patternWithDerived(selectedRecommendationPattern),
      ...displayPatterns.filter(p=>{
        const a = normCropName(p.mainCrop);
        const b = normCropName(p.secondaryCrop);
        if(scenarioType === 's2' && selB && selB !== normCropName('-')){
          return [a,b].sort().join('|') !== [selA,selB].sort().join('|');
        }
        return !(a === selA && b === selB);
      })
    ];
  }
  const seen = new Set();
  const ranked = displayPatterns.filter(p=>{
    const a = normCropName(p.mainCrop);
    const b = normCropName(p.secondaryCrop);
    const k = (scenarioType === 's2' && b && b !== normCropName('-')) ? [a,b].sort().join('|') : `${a}|${b}`;
    if(seen.has(k)) return false;
    seen.add(k);
    return true;
  }).slice(0,8);
  if(ranked.length && !ranked.some(p=>p.selectedRecommendation)){
    ranked[0] = { ...ranked[0], selectedRecommendation:true };
  }
  return ranked.map((p,idx)=>({ ...p, rank: idx+1, targetOrder: idx+1 }));
}

function patternComponentsToRecommendationRows(pattern, fallbackRows, parcel){
  const comps = Array.isArray(pattern?.components) ? pattern.components.filter(Boolean) : [];
  const n = (value, fallback=0)=>{ const v = Number(value); return Number.isFinite(v) ? v : fallback; };
  const areaDa = n(parcel?.area_da || parcel?.area, 0);
  if(!comps.length || !(areaDa > 0)) return Array.isArray(fallbackRows) ? fallbackRows : [];
  const fallback = Array.isArray(fallbackRows) ? fallbackRows : [];
  return comps.map((c, idx)=>{
    const crop = prettyCropName(c.crop || c.name || c.mainCrop || '-');
    const ref = fallback.find(r=>normCropName(r.name) === normCropName(crop)) || fallback[idx] || fallback[0] || {};
    const share = clamp(n(c.share, 0), 0, 1);
    const area = n(c.area, areaDa * share);
    const water = n(c.water, area * n(c.waterPerDa, n(ref.waterPerDa, 0)));
    const profit = n(c.profit, area * n(c.profitPerDa, n(ref.profitPerDa, 0)));
    const waterPerDa = area > 0 ? water / area : n(c.waterPerDa, n(ref.waterPerDa, 0));
    const profitPerDa = area > 0 ? profit / area : n(c.profitPerDa, n(ref.profitPerDa, 0));
    const cropIrr = irrigationKeysForCrop(crop);
    const suggestedKey = c.irrigationKey || ref.irrigationSuggestedKey || cropIrr.suggestedKey || ref.irrigationCurrentKey || cropIrr.currentKey;
    const currentKey = ref.irrigationCurrentKey || cropIrr.currentKey || suggestedKey;
    return {
      ...ref,
      name: crop,
      area,
      season: c.season || (pattern.components.length > 1 ? 'Desen payı' : (ref.season || inferSeasonFromCropName(crop) || 'Tek sezon')),
      irrigationCurrentKey: currentKey,
      irrigationCurrentText: ref.irrigationCurrentText || irrigationLabel(currentKey),
      irrigationSuggestedKey: suggestedKey,
      irrigationSuggestedText: c.irrigation || irrigationLabel(suggestedKey),
      irrigationSuggested: c.irrigation || irrigationLabel(suggestedKey),
      waterPerDa,
      profitPerDa,
      totalWater: water,
      totalProfit: profit,
      _baseWaterPerDa: n(ref._baseWaterPerDa, waterPerDa * Math.max(0.35, IRR_EFF[suggestedKey] || STATE.irrigEfficiency || 0.62)),
      _cropKey: (_normIrrLookupKeys(crop)[1] || String(crop || '')),
      patternShare: share,
      patternPercent: Math.round(share * 100),
    };
  });
}



function pairingForCrop(name){
  const raw = String(name||'').trim();
  const candidates = [];
  if(raw) candidates.push(raw);
  if(raw && raw.includes('_')) candidates.push(raw.replace(/_/g,' '));
  if(raw) candidates.push(prettyCropName(raw));
  if(raw && raw.includes('_')) candidates.push(prettyCropName(raw).replace(/_/g,' '));
  // direct match
  for(const c of candidates){
    if(S1_PAIRING[c]) return S1_PAIRING[c];
  }
  // case-insensitive match (space/underscore normalized)
  const target = raw.replace(/_/g,' ').toUpperCase();
  for(const k in S1_PAIRING){
    if(String(k).replace(/_/g,' ').toUpperCase()===target) return S1_PAIRING[k];
  }
  return null;
}

function runOptimization(p, scenarioKey, algoKey){
  // Defensive: async UI flows may call this before parcels are fully
  // hydrated. Make sure we never crash the whole UI.
  if(!p){
    return {
      scenarioKey,
      algoKey,
      currentRows: [],
      currentTotals: { totalWater:0, totalProfit:0, waterPerDa:0, profitPerDa:0 },
      bestRows: [],
      bestTotals: { totalWater:0, totalProfit:0, waterPerDa:0, profitPerDa:0 },
      note: 'parcel undefined'
    };
  }

  // Guarantee a baseline crop breakdown exists.
  ensureBaselineCropCurrent(p);

  if(!Array.isArray(p.cropCurrent)) p.cropCurrent = [];
  if(!p.cropCurrent.length){
    // Still nothing: return a safe empty result.
    return {
      scenarioKey,
      algoKey,
      currentRows: [],
      currentTotals: { totalWater:0, totalProfit:0, waterPerDa:0, profitPerDa:0 },
      bestRows: [],
      bestTotals: { totalWater:0, totalProfit:0, waterPerDa:0, profitPerDa:0 },
      note: 'cropCurrent missing'
    };
  }

  const currentRows = p.cropCurrent.map(c=>{
    const key = c.irrigationCurrentKey || irrKeyFromText(c.irrigationCurrentText);
    const baseWater = safeNum(c._baseWaterPerDa, safeNum(c.waterPerDa, 0));
    const grossWater = safeNum(c._officialGrossWaterPerDa, deliveredWaterPerDa(baseWater, key));
    const area = safeNum(c.area, 0);
    return ({
    name: c.name,
    area: c.area,
    season: c.season || '-',
    irrigationCurrentKey: c.irrigationCurrentKey || irrKeyFromText(c.irrigationCurrentText),
    irrigationCurrentText: c.irrigationCurrentText || '-',
    // tabloda gösterilecek su: yönteme göre teslim edilen (gross) su
    waterPerDa: deliveredWaterPerDa(c.waterPerDa, c.irrigationCurrentKey || irrKeyFromText(c.irrigationCurrentText)),
    profitPerDa: c.profitPerDa,
    totalWater: c.area*deliveredWaterPerDa(c.waterPerDa, c.irrigationCurrentKey || irrKeyFromText(c.irrigationCurrentText)),
    _baseWaterPerDa: baseWater,
    waterPerDa: grossWater,
    totalWater: area * grossWater,
    totalProfit: c.area*c.profitPerDa
  });
  });
  const currentTotals = sumMetrics(currentRows);
  const scenarioNorm = String(scenarioKey||'').trim().toLowerCase();
  if(scenarioNorm === 'mevcut' || scenarioNorm === 'current'){
    return { rows: currentRows.map(r=>({ ...r })), totals: currentTotals, baselineOnly: true };
  }
  if(!STATE.allowBrowserOptimizationFallback){
    return {
      rows: [],
      totals: { water:0, profit:0, eff:0 },
      backendUnavailable: true,
      backendOnly: true,
      decisionReason: 'Backend karar paketi olmadan frontend optimizasyon/öneri üretmez.'
    };
  }

  // Bahçe / çok yıllık parsellerde ANA ÜRÜN KORUNUR.
  // Kullanıcı S1 veya S2 seçse bile mevcut meyve ağacı / bağ / çok yıllık ürün sökülüp
  // yerine yeni bir ana ticari ürün önerilmez. İyileştirme; sulama yöntemi, kısıntı düzeyi,
  // sulama zamanı ve sıra arası örtü/yeşil gübre bitkisi üzerinden yapılır.
  const seasonSource = (document.getElementById('seasonSourceSel')?.value) || STATE.seasonSource || 's1';
  const declaredCurrent = p?.current_crop || p?.currentCrop || p?.crop || null;
  let domName = null;
  let bestCurrent = null;
  for(const r of (currentRows||[])){
    if(!bestCurrent || safeNum(r.area) > safeNum(bestCurrent.area)) bestCurrent = r;
  }
  if(declaredCurrent && isPerennialCropName(declaredCurrent)){
    domName = declaredCurrent;
  }else if(bestCurrent && bestCurrent.name){
    domName = bestCurrent.name;
  }else{
    domName = dominantCropNameForParcel(p) || declaredCurrent || null;
  }
  const orchardLocked = !!(p?.parcel_type === 'orchard' || p?.is_orchard || p?.cok_yillik_kilit === 'Evet' || (domName && isPerennialCropName(domName)));
  if(seasonSource === 's2' && orchardLocked && domName && scenarioKey !== 'mevcut'){
    const adj = s2IrrigationAdjust(scenarioKey);
    const orchardAlternatives = orchardInterrowAlternativesForMain(domName);
    const currentMain = (currentRows || []).find(r=>normCropName(r.name) === normCropName(domName)) || bestCurrent || currentRows[0] || null;
    const currentKey = currentMain?.irrigationCurrentKey || irrKeyFromText(currentMain?.irrigationCurrentText || '') || 'drip';
    const suggestedKey = irrigationKeysForCrop(domName).suggestedKey || currentKey;
    const baseNet = safeNum(currentMain?.waterPerDa, 0) * Math.max(0.35, IRR_EFF[currentKey] || STATE.irrigEfficiency || 0.62);
    const area = +(safeNum(p?.area_da, currentMain?.area || 0)).toFixed(1);
    const waterPerDa = deliveredWaterPerDa(baseNet * adj.wmul, suggestedKey);
    const profitPerDa = +(safeNum(currentMain?.profitPerDa, 0) * adj.pmul).toFixed(2);
    const rows = [{
      name: domName,
      area,
      season: currentMain?.season || 'Çok yıllık',
      irrigationCurrentKey: currentKey,
      irrigationCurrentText: currentMain?.irrigationCurrentText || irrigationLabel(currentKey),
      irrigationSuggestedKey: suggestedKey,
      irrigationSuggestedText: irrigationLabel(suggestedKey),
      irrigationSuggested: irrigationLabel(suggestedKey),
      _baseWaterPerDa: +(baseNet * adj.wmul).toFixed(3),
      waterPerDa: +waterPerDa.toFixed(3),
      profitPerDa,
      totalWater: +(area * waterPerDa).toFixed(2),
      totalProfit: +(area * profitPerDa).toFixed(2),
      orchardLocked: true,
    }];
    const totals = sumMetrics(rows);
    const orchardAlternativeMetrics = orchardAlternativeScenarioMetrics(domName, safeNum(p?.area_da, area), scenarioKey, rows[0], orchardAlternatives);
    const orchardCandidates = [{
      type: 'current_reference',
      label: 'Mevcut referans',
      rows: rows.map(r=>({ ...r, currentReference:true })),
      totals,
      metrics: planDecisionMetricsV8(p, rows, currentTotals, scenarioKey),
      c1: domName,
      c2: null,
    }];
    for(const alt of orchardAlternativeMetrics){
      const altShare = clamp(safeNum(alt.area,0) / Math.max(1, area), 0.10, 0.35);
      const mainShare = 1 - altShare;
      const comboRows = [
        {
          ...rows[0],
          area: +(area * mainShare).toFixed(1),
          totalWater: +(safeNum(rows[0].waterPerDa,0) * area * mainShare).toFixed(2),
          totalProfit: +(safeNum(rows[0].profitPerDa,0) * area * mainShare).toFixed(2),
          orchardKeepMainCrop: true,
        },
        {
          name: prettyCropName(alt.name),
          area: safeNum(alt.area, area * altShare),
          season: 'Ara ürün / sıra arası',
          irrigationCurrentKey: currentKey,
          irrigationCurrentText: irrigationLabel(currentKey),
          irrigationSuggestedKey: alt.irrigationKey || suggestedKey,
          irrigationSuggestedText: alt.irrigationText || irrigationLabel(alt.irrigationKey || suggestedKey),
          irrigationSuggested: alt.irrigationText || irrigationLabel(alt.irrigationKey || suggestedKey),
          _baseWaterPerDa: safeNum(alt.waterPerDa,0) * Math.max(0.35, IRR_EFF[alt.irrigationKey || suggestedKey] || STATE.irrigEfficiency || 0.62),
          waterPerDa: safeNum(alt.waterPerDa,0),
          profitPerDa: safeNum(alt.profitPerDa,0),
          totalWater: safeNum(alt.totalWater,0),
          totalProfit: safeNum(alt.totalProfit,0),
          orchardInterrow: true,
        }
      ];
      orchardCandidates.push({
        type: 'orchard_interrow',
        label: `${domName} + ${prettyCropName(alt.name)}`,
        rows: comboRows,
        totals: sumMetrics(comboRows),
        metrics: planDecisionMetricsV8(p, comboRows, currentTotals, scenarioKey),
        c1: domName,
        c2: alt.name,
      });
    }
    const rankedOrchardCandidates = rankPlanCandidatesV8(orchardCandidates, scenarioKey, currentTotals);
    const bestOrchard = rankedOrchardCandidates[0] || orchardCandidates[0];
    const waterSaving = safeNum(currentTotals.water) - safeNum(totals.water);
    return {
      rows: bestOrchard.rows,
      totals: bestOrchard.totals,
      cropsUsed: [bestOrchard.c1, bestOrchard.c2].filter(Boolean),
      irrigationPlan: adj.label,
      lockedCrop: domName,
      orchardKeepMainCrop: true,
      orchardAlternative: orchardAlternatives[0] || null,
      orchardAlternatives,
      orchardAlternativeMetrics,
      waterSavingM3: Math.round(waterSaving),
      profitDeltaTL: Math.round(safeNum(bestOrchard.totals?.profit, totals.profit) - safeNum(currentTotals.profit)),
      decisionMetrics: bestOrchard.metrics,
      decisionReason: decisionReasonV8(bestOrchard, scenarioKey),
      rankedCandidates: rankedOrchardCandidates.slice(0, 10)
    };
  }

  if(scenarioKey === "mevcut"){
    return { rows: currentRows.map(r=>({ ...r })), totals: currentTotals };
  }

  if(orchardLocked && domName){
    const rows = currentRows.map(r=>({
      ...r,
      currentReference: true,
      orchardLocked: true,
      orchardKeepMainCrop: true
    }));
    const totals = sumMetrics(rows);
    const metrics = planDecisionMetricsV8(p, rows, currentTotals, scenarioKey);
    const reason = 'Bu parsel çok yıllık/bahçe ürünüdür. Tek yıllık ürün önerileri doğrudan ana ürün değişimi olarak uygulanamaz; bahçe yenileme ve uzman onayı gerekir. Bu nedenle ana ürün korunmuştur.';
    const candidate = {
      type: 'current_reference',
      label: 'Mevcut referans',
      rows,
      totals,
      metrics,
      c1: domName,
      c2: null,
      rankReason: reason,
      orchardLocked: true,
      orchardKeepMainCrop: true
    };
    return {
      rows,
      totals,
      cropsUsed: [domName],
      irrigationPlan: 'Çok yıllık/bahçe parselinde ana ürün korunur; yıllık ürün geçişi uzman değerlendirmesi gerektirir.',
      lockedCrop: domName,
      orchardKeepMainCrop: true,
      decisionMetrics: metrics,
      decisionReason: reason,
      rankedCandidates: [candidate]
    };
  }

  if(!orchardLocked){
    const annualPayload = buildAnnualRecommendationPayload(p, currentRows, scenarioKey);
    return {
      rows: annualPayload.rows,
      totals: annualPayload.totals,
      cropsUsed: [annualPayload.selected?.c1, annualPayload.selected?.c2].filter(Boolean),
      irrigationPlan: annualPayload.irrigationPlan,
      decisionMetrics: annualPayload.decisionMetrics,
      decisionReason: annualPayload.decisionReason,
      rankedCandidates: annualPayload.rankedCandidates.slice(0, 10)
    };
  }

  // --- Nihai karar araması ---
  // Mevcut desen sabit baseline olarak kalır; adaylar hedefe göre su, kâr,
  // TL/m3, kota ve uygunluk metrikleriyle tek bir sıralama üzerinden seçilir.
  const parcelCandidatePool = (typeof getCandidateCropsForParcel === 'function')
    ? getCandidateCropsForParcel(p).filter(c=>c && c.parcelSpecific && normCropName(c.name) !== 'NADAS')
    : [];
  const parcelCandidateByName = new Map();
  for(const c of parcelCandidatePool){
    const k = normCropName(c.name);
    if(k && !parcelCandidateByName.has(k)) parcelCandidateByName.set(k, c);
  }
  const grossCandidateToBaseWater = (name, grossWaterPerDa)=>{
    const keys = irrigationKeysForCrop(name || '');
    const recKey = recommendedIrrKeyForCrop(name || '', keys.currentKey || 'sprinkler') || keys.suggestedKey || keys.currentKey || 'sprinkler';
    const gross = safeNum(grossWaterPerDa, 0);
    if(recKey === 'rainfed') return gross / 0.20;
    return gross * Math.max(0.35, IRR_EFF[recKey] || STATE.irrigEfficiency || 0.62);
  };

  // Robust crop meta lookup:
  // Some sources use underscores (NOHUT_KURU) while catalog keys use spaces/parentheses.
  // If we fail here, recommended rows show 0 water/profit and look "empty".
  function cropMeta(name){
    const cat = STATE.cropCatalog || {};
    const raw = String(name||'').trim();
    const variants = [];
    if(raw) variants.push(raw);
    if(raw && raw.includes('_')) variants.push(raw.replace(/_/g,' '));
    const pretty = prettyCropName(raw);
    if(pretty && pretty !== raw) variants.push(pretty);
    if(pretty && pretty.includes('_')) variants.push(pretty.replace(/_/g,' '));

    for(const v of variants){
      const local = parcelCandidateByName.get(normCropName(v));
      if(local){
        return {
          waterNet: grossCandidateToBaseWater(local.name || v, local.waterPerDa),
          profit: safeNum(local.profitPerDa, 0)
        };
      }
    }

    // Try several normalized keys (uppercased, diacritics-stripped).
    for(const v of variants){
      const k = normCropName(v);
      if(cat[k]){
        let wNet = safeNum(cat[k].waterPerDa);
        let pr = safeNum(cat[k].profitPerDa);
        // If water is missing/zero, try season-derived net water (year-specific)
        if(!(isFinite(wNet) && wNet>0)){
          const ws = getNetM3PerDaFromSeasons(STATE.selectedWaterYear, k);
          if(isFinite(ws) && ws>0) wNet = ws;
        }
        return { waterNet: wNet, profit: pr };
      }
    }
    // Last resort: scan for close match by space/underscore normalization.
    const target = normCropName(raw).replace(/_/g,' ');
    for(const k in cat){
      if(normCropName(k).replace(/_/g,' ') === target){
        let wNet = safeNum(cat[k].waterPerDa);
        let pr = safeNum(cat[k].profitPerDa);
        if(!(isFinite(wNet) && wNet>0)){
          const ws = getNetM3PerDaFromSeasons(STATE.selectedWaterYear, normCropName(k));
          if(isFinite(ws) && ws>0) wNet = ws;
        }
        return { waterNet: wNet, profit: pr };
      }
    }
    return { waterNet: 0, profit: 0 };
  }

  function buildPlanRows(c1, c2){
    const A = safeNum(p.area_da);
    const pair = pairingForCrop(c1) || {season1:'-', irr1:'-', secondary:'-', season2:'-', irr2:'-'};
    const c2Resolved = (seasonSource === 's1') ? null : (c2 || null);
    const inferredS1 = inferSeasonFromCropName(c1) || '-';
    const inferredS2 = c2Resolved ? (inferSeasonFromCropName(c2Resolved) || '-') : '-';
    const s1 = (seasonSource === 's2') ? inferredS1 : (pair.season1 || inferredS1 || '-');
    const s2 = (seasonSource === 's2') ? inferredS2 : (pair.season2 || inferredS2 || '-');

    // --- Alan kuralı ---
    // Eğer 1. ve 2. ürün farklı sezonlardaysa (rotasyon), aynı parsel alanında ardışık ekilir.
    // Bu durumda HER sezonun alan toplamı parsel alanına eşit olmalı; alanı 70/30 bölmeyiz.
    // Eğer aynı sezon (veya belirsiz) ise, çeşitlendirme varsayımı ile 70/30 bölünmüş alan kullanılabilir.
    const isRotation = c2Resolved && (String(s1).toLowerCase() !== String(s2).toLowerCase()) && s1 !== '-' && s2 !== '-';
    let a1, a2;
    if (seasonSource === 's1') {
      a1 = +A.toFixed(1);
      a2 = 0;
    } else if (isRotation) {
      a1 = +A.toFixed(1);
      a2 = +A.toFixed(1);
    } else {
      // 0.1 da hassasiyet: tabloda gösterilen alan ile toplamların tutarlı kalması için alanı burada da yuvarlıyoruz.
      const a1Raw = A * 0.7;
      const a2Raw = Math.max(0, A - a1Raw);
      a1 = +a1Raw.toFixed(1);
      a2 = +a2Raw.toFixed(1);
      // Yuvarlama sonrası küçük sapmalar olursa (ör. 40.6 yerine 40.5), toplamı tekrar A'ya oturt.
      const sumA = a1 + a2;
      if (A > 0 && sumA > 0 && Math.abs(sumA - A) > 0.05) {
        const k = A / sumA;
        a1 = +(a1 * k).toFixed(1);
        a2 = +(Math.max(0, A - a1)).toFixed(1);
      }
    }

    const m1 = cropMeta(c1);
    const m2 = c2Resolved ? cropMeta(c2Resolved) : {waterNet:0, profit:0};

    const irr1CurKey = irrKeyFromText(pair.irr1);
    const irr2CurKey = c2Resolved ? irrKeyFromText(pair.irr2) : 'rainfed';
    const irr1RecKey = recommendedIrrKeyForCrop(c1, irr1CurKey);
    const irr2RecKey = c2Resolved ? recommendedIrrKeyForCrop(c2Resolved, irr2CurKey) : 'rainfed';

    // Sulama yükseltme maliyeti (çok kaba): damlaya geçişte da başına küçük yatırım bedeli
    const upgradeCostDa = (from,to)=>{
      if(from===to) return 0;
      if(to==='drip') return 250; // damla dönüşüm
      if(to==='sprinkler' && from==='surface') return 150;
      return 50;
    };

    const p1 = m1.profit - upgradeCostDa(irr1CurKey, irr1RecKey);
    const p2 = c2Resolved ? (m2.profit - upgradeCostDa(irr2CurKey, irr2RecKey)) : 0;

    const w1 = deliveredWaterPerDa(m1.waterNet, irr1RecKey);
    const w2 = c2Resolved ? deliveredWaterPerDa(m2.waterNet, irr2RecKey) : 0;

    const rows = [];
    rows.push({
      name: prettyCropName(c1),
      season: s1,
      irrigationCurrentKey: irr1CurKey,
      irrigationCurrentText: irrigationLabel(irr1CurKey),
      irrigationSuggestedKey: irr1RecKey,
      irrigationSuggestedText: irrigationLabel(irr1RecKey),
      irrigationSuggested: irrigationLabel(irr1RecKey),
      // Keep NET (field) water requirement so the UI can compute delivered (gross) water
      // consistently based on the shown irrigation method.
      _baseWaterPerDa: safeNum(m1.waterNet, 0),
      area: +a1.toFixed(1),
      waterPerDa: +w1.toFixed(3),
      profitPerDa: +p1.toFixed(3),
      totalWater: a1*w1,
      totalProfit: a1*p1,
      orchardConversion: !!(orchardLocked && seasonSource === 's1' && domName && normCropName(c1) !== normCropName(domName)),
    });
    if(c2Resolved){
      rows.push({
        name: prettyCropName(c2Resolved),
        season: s2,
        irrigationCurrentKey: irr2CurKey,
        irrigationCurrentText: irrigationLabel(irr2CurKey),
        irrigationSuggestedKey: irr2RecKey,
        irrigationSuggestedText: irrigationLabel(irr2RecKey),
        irrigationSuggested: irrigationLabel(irr2RecKey),
        _baseWaterPerDa: safeNum(m2.waterNet, 0),
        area: +a2.toFixed(1),
        waterPerDa: +w2.toFixed(3),
        profitPerDa: +p2.toFixed(3),
        totalWater: a2*w2,
        totalProfit: a2*p2
      });
    }
    return rows;
  }

  // --- Aday havuzları (sezon veri setine göre) ---
  // Senaryo-1: 15 ana ürün + geniş 2. ürün havuzu
  // Senaryo-2: mutabık kalınan ürün listesi (meyve + tarla) ve sadece sınırlı 2. ürün
  //            (nadas gibi). Böylece "Senaryo-2 seçili ama ürünler değişmiyor" sorunu çözülür.
  let primaryCandidates = parcelCandidatePool.length
    ? parcelCandidatePool.map(c=>c.name).filter(c=>normCropName(c) !== "NADAS")
    : S1_PRIMARY_CROPS.slice().filter(c=>normCropName(c) !== "NADAS");
  if(seasonSource === 's1' && inferParcelTypeKey(p) !== 'orchard'){
    primaryCandidates = primaryCandidates.filter(c=>!isPerennialCropName(c));
  }
  if(seasonSource === 's1'){
    // Su verimliliği hedefinde yalnız mevcut S1 ana ürün listesine kilitlenmek,
    // baklagil/düşük su alternatifleri tabloya girse bile seçilememesine yol açıyordu.
    const strategicLowWater = ['NOHUT','MERCIMEK','KIMYON','ISPANAK','MARUL','TURP','LAHANA'];
    primaryCandidates = Array.from(new Set([...primaryCandidates, ...strategicLowWater]))
      .filter(c=>normCropName(c) !== "NADAS");
    if(inferParcelTypeKey(p) === 'orchard'){
      const orchardConversionPool = ['NOHUT','MERCIMEK','KIMYON','BUGDAY (DANE)','ARPA (DANE)','KABAK (ÇEREZLIK)','SOGAN (KURU)'];
      primaryCandidates = Array.from(new Set([...orchardConversionPool, ...primaryCandidates]))
        .filter(c=>normCropName(c) !== "NADAS" && !isPerennialCropName(c));
    }
  }
  let secondaryPool = Array.from(new Set([
    ...S1_SECONDARY_CROPS,
    'Buğday (Dane)','Arpa (Dane)','Silajlık Mısır','Fiğ (Yeşilot)','Yem Bezelyesi',
    'Ayçiçeği','Ayçiçeği (Yağlık)','Marul','Ispanak','Fasulye (Taze)','Kabak (Çerezlik)'
  ]));
  if(seasonSource === 's2'){
    // S2 mantığı:
    // - Bahçe / bağ parsellerinde ürün korunur (yukarıda erken dönüş var).
    // - Tarla parsellerinde ise yazlık + kışlık münavebe adayları denenir.
    primaryCandidates = S2_SUMMER_RAW.slice();
    secondaryPool = S2_WINTER_RAW.slice();

    // Tarla parselinde bahçe ürünü önerme.
    const lu = landUseCodeFromSoilUnit(p.soil_unit_code || '');
    const allowFruitVine = !!lu;
    if(allowFruitVine){
      // Çok yıllık parsel ise zaten yukarıda lock uygulanıyor; burada güvenli kal.
      primaryCandidates = primaryCandidates.slice();
    }
  }

  // Uyum kuralı: aynı familyadan kaçın
  const fam = (STATE && STATE.cropFamilyMap) ? STATE.cropFamilyMap : {};
  const sameFam = (a,b)=>{ const fa=fam[prettyCropName(a)]||fam[a]||fam[normCropName(a)]; const fb=fam[prettyCropName(b)]||fam[b]||fam[normCropName(b)]; return fa && fb && fa===fb; };

  const scorePlan = (rows)=>{
    const t = sumMetrics(rows);
    const water = safeNum(t.water, 0);
    const profit = safeNum(t.profit, 0);
    if(!Array.isArray(rows) || !rows.length || water < 0 || !(profit > 0)){
      return { ok:false, score: Number.NEGATIVE_INFINITY, totals:t, reason:'Geçerli su/kâr metriği yok' };
    }
    const metrics = planDecisionMetricsV8(p, rows, currentTotals, scenarioKey);
    return { ok:true, score: 0, totals:t, metrics };
  };

  const candidates = [];
  const currentReferenceRows = currentRows.map(r=>({
    ...r,
    irrigationSuggestedKey: r.irrigationCurrentKey || irrKeyFromText(r.irrigationCurrentText || ''),
    irrigationSuggestedText: r.irrigationCurrentText || irrigationLabel(r.irrigationCurrentKey || irrKeyFromText(r.irrigationCurrentText || '')),
    irrigationSuggested: r.irrigationCurrentText || irrigationLabel(r.irrigationCurrentKey || irrKeyFromText(r.irrigationCurrentText || '')),
    currentReference: true,
  }));
  const currentRefMetrics = planDecisionMetricsV8(p, currentReferenceRows, currentTotals, scenarioKey);
  candidates.push({
    type: 'current_reference',
    label: 'Mevcut referans',
    rows: currentReferenceRows,
    totals: sumMetrics(currentReferenceRows),
    metrics: currentRefMetrics,
    score: 0,
    c1: dominantCropNameForParcel(p) || currentReferenceRows[0]?.name || 'Mevcut referans',
    c2: null,
  });
  const seed = _hashInt(String(algoKey||'ga')) + _hashInt(p.id||'P');
  for(const c1 of primaryCandidates){
    // Ön tanımlı eşleşme (Senaryo-1 için). Senaryo-2'de geniş eşleşme
    // kurallarını kullanmıyoruz; yalnızca sınırlı 2. ürün (ör. nadas)
    // denenir.
    const defPair = (seasonSource === 's2') ? null : (S1_PAIRING[c1] ? S1_PAIRING[c1].secondary : null);
    const defOpts = [];
    if(defPair && defPair !== '-' && defPair !== '-'){
      if(defPair.includes('/')) defOpts.push(...defPair.split('/').map(x=>x.trim()).filter(Boolean));
      else defOpts.push(defPair);
    }
    const c2Candidates = (seasonSource === 's1')
      ? [null]
      : (seasonSource === 's2'
          ? [...new Set(secondaryPool)].filter(c2=>!c2 || !sameFam(c1,c2))
          : [...new Set([null, ...defOpts, ...secondaryPool])].filter(c2=>!c2 || !sameFam(c1,c2)));

    for(const c2 of c2Candidates){
      const rows = buildPlanRows(c1, c2);
      const res = scorePlan(rows);
      if(!res.ok) continue;
      candidates.push({ rows, totals: res.totals, metrics: res.metrics, score: res.score, c1, c2, seed });
    }
  }

  const rankedCandidates = rankPlanCandidatesV8(candidates, scenarioKey, currentTotals);
  let best = rankedCandidates[0] || null;
  if(!best){
    // Güvenli fallback: mevcut desen
    return { rows: currentRows.map(r=>({ ...r })), totals: currentTotals, irrigationPlan: 'Mevcut (uygulanabilir aday bulunamadı)', decisionReason: 'Bu parsel ve kısıtlar altında geçerli aday üretilemedi; mevcut desen referans olarak korunur.' };
  }

  if(normalizeScenarioKey(scenarioKey) === 'water_saving' || scenarioKey === 'su_tasarruf'){
    const curW = safeNum(currentTotals.water, 0);
    const finalW = safeNum(best?.totals?.water, 0);
    if(curW > 0 && finalW > curW + 1e-6){
      return {
        rows: currentRows.map(r=>({ ...r })),
        totals: currentTotals,
        irrigationPlan: 'Su tasarrufu: uygulanabilir adayların tamamı mevcut desenden fazla su istediği için mevcut desen korundu',
        decisionReason: 'Su tasarrufu hedefinde suyu azaltmayan aday ana öneri yapılmaz; mevcut desen sabit referans olarak bırakıldı.'
      };
    }
  }

  const irrigationPlan = 'Sulama önerisi: ' + best.rows.map(r=>`${r.name} → ${r.irrigationSuggested}`).join(' | ');
  return {
    rows: best.rows,
    totals: best.totals,
    cropsUsed: [best.c1, best.c2].filter(Boolean),
    irrigationPlan,
    decisionMetrics: best.metrics,
    decisionReason: decisionReasonV8(best, scenarioKey),
    rankedCandidates: rankedCandidates.slice(0, 10)
  };
}

function getOptimizationResult(parcelId, scenarioKey, algoKey){
  optimizationCache[parcelId] ??= {};
  const p = parcelData.find(x=>x.id===parcelId);
  const cropSig = (p?.cropCurrent || []).map(r=>`${normCropName(r.name)}:${safeNum(r.area,0)}:${safeNum(r.waterPerDa,0)}:${safeNum(r.profitPerDa,0)}:${r.irrigationCurrentKey || irrKeyFromText(r.irrigationCurrentText || '')}`).join(',');
  const contextKey = `${basinCacheKey(scenarioKey, algoKey)}|P${parcelId}|C${cropSig || normCropName(p?.current_crop || p?.currentCrop || p?.crop || '')}|DV${STATE.dataVersion || STATE.selectedWaterYear || ''}`;
  optimizationCache[parcelId][contextKey] ??= {};
  if(!optimizationCache[parcelId][contextKey][algoKey]){
    optimizationCache[parcelId][contextKey][algoKey] = {
      rows: [],
      totals: { water:0, profit:0, eff:0 },
      backendUnavailable: true,
      backendOnly: true,
      decisionReason: 'Backend sonucu cache içinde yok; tarayıcı içi karar motoru devre dışı.'
    };
  }
  return optimizationCache[parcelId][contextKey][algoKey];
}


function computeCropData(p, scenarioKey, algoKey) {
  // Mevcut desen: her zaman runOptimization içindeki su/da (sulama randımanı dahil) ile hesapla
  const curRes = runOptimization(p, 'mevcut', algoKey);
  const current = (curRes.rows || []).map(r=>({ ...r, irrigationSuggested: undefined }));
  const currentTotals = sumMetrics(current);
  const dominantCurrent = Array.isArray(current) && current.length
    ? [...current].sort((a,b)=>safeNum(b.area,0)-safeNum(a.area,0))[0]
    : null;
  const isPlaceholderCropName = (name)=>{
    const raw = String(name||'').trim();
    const nk = normCropName(raw).replace(/[^A-ZÇĞİÖŞÜ0-9]/g,'');
    return !raw || raw === '-' || raw === '-' || raw === 'null' || raw === 'undefined' || ['URUN','ÜRÜN','NA','N/A'].includes(nk);
  };
  const currentRowForName = (name)=>{
    const nn = normCropName(name||'');
    return (current||[]).find(x=>normCropName(x.name||'') === nn) || dominantCurrent || null;
  };

  // Referans görünümünde sağdaki tablo/özet mevcut deseni aynen yansıtmalı.
  // Bu modda optimizasyon sonucu, placeholder ürün adı veya farklı sulama etiketi gösterilmez.
  if(String(scenarioKey||'').trim().toLowerCase() === 'mevcut'){
    const rec = (current || []).map(r=>({
      ...r,
      irrigationSuggestedKey: r.irrigationCurrentKey || irrKeyFromText(r.irrigationCurrentText),
      irrigationSuggestedText: r.irrigationCurrentText || irrigationLabel(r.irrigationCurrentKey || irrKeyFromText(r.irrigationCurrentText)),
      irrigationSuggested: r.irrigationCurrentText || irrigationLabel(r.irrigationCurrentKey || irrKeyFromText(r.irrigationCurrentText)),
    }));
    return {
      current,
      currentTotals,
      rec,
      recTotals: {
        water: currentTotals.water,
        profit: currentTotals.profit,
        water_eff: currentTotals.water > 0 ? (currentTotals.profit / currentTotals.water) : 0,
        water_current_irrig: currentTotals.water,
        water_saving_m3: 0,
        water_saving_pct: 0,
      },
      recMeta: { referenceMode: true, irrigationPlan: 'Referans görünüm: mevcut ürün ve mevcut sulama yöntemi aynen gösterilir.' },
    };
  }

  // Önerilen: küresel su bütçesi uygulanmış havza planından çek
  const basin = computeBasinPlan(scenarioKey, algoKey);
  const opt = basin.plan[p.id] || getOptimizationResult(p.id, scenarioKey, algoKey);
  if(opt?.backendUnavailable){
    return {
      current,
      currentTotals,
      rec: [],
      recTotals: { water:0, profit:0, water_eff:0, water_current_irrig:0, water_saving_m3:0, water_saving_pct:0 },
      recMeta: {
        backendUnavailable: true,
        backendOnly: true,
        decisionReason: opt.decisionReason || 'Backend sonucu yok; frontend karar üretmedi.',
        alternativePatterns: [],
        interrowAlternatives: [],
        conversionWarnings: Array.isArray(opt.conversionWarnings) ? opt.conversionWarnings : ['Backend sonucu yok; frontend karar üretmedi.']
      }
    };
  }
  if(opt?.backendOnly || opt?.backendResult){
    const recommendedForUi = Array.isArray(opt.rows) ? opt.rows.map(r=>({ ...r })) : [];
    const recTotalsAdj = opt.totals || sumMetrics(recommendedForUi);
    const recWaterCurrentIrr = recommendedForUi.reduce((acc, rr) => {
      const w = deliveredWaterPerDa(safeNum(rr._baseWaterPerDa, rr.waterPerDa), rr.irrigationCurrentKey);
      return acc + safeNum(rr.area,0) * w;
    }, 0);
    return {
      current,
      currentTotals,
      rec: recommendedForUi,
      recTotals: {
        water: safeNum(recTotalsAdj.water, 0),
        profit: safeNum(recTotalsAdj.profit, 0),
        water_eff: safeNum(recTotalsAdj.water, 0) > 0 ? safeNum(recTotalsAdj.profit, 0) / safeNum(recTotalsAdj.water, 0) : 0,
        water_current_irrig: recWaterCurrentIrr,
        water_saving_m3: Math.max(0, recWaterCurrentIrr - safeNum(recTotalsAdj.water, 0)),
        water_saving_pct: recWaterCurrentIrr > 0 ? (Math.max(0, recWaterCurrentIrr - safeNum(recTotalsAdj.water, 0)) / recWaterCurrentIrr) : 0,
      },
      recMeta: {
        backendOnly: true,
        irrigationPlan: opt.irrigationPlan || null,
        decisionReason: opt.decisionReason || recommendedForUi[0]?.rankReason || recommendedForUi[0]?.decisionNote || null,
        rankedCandidates: null,
        alternativePatterns: Array.isArray(opt.alternativePatterns) ? opt.alternativePatterns : [],
        interrowAlternatives: Array.isArray(opt.interrowAlternatives) ? opt.interrowAlternatives : [],
        conversionWarnings: Array.isArray(opt.conversionWarnings) ? opt.conversionWarnings : [],
        backendResult: opt.backendResult || null,
        selectedPlan: opt.backendDecisionPackage?.selected_plan || opt.backendResult?.selected_plan || null,
        noFeasibleTwoCrop: !!opt.noFeasibleTwoCrop,
        orchardKeepMainCrop: !!(recommendedForUi[0]?.orchardLocked || p?.parcel_type === 'orchard' || p?.is_orchard),
      }
    };
  }
  const optRankedCandidates = validateRecommendationResultV8(
    Array.isArray(opt.rankedCandidates) ? opt.rankedCandidates : [],
    scenarioKey,
    { parcel:p, baselineTotals:currentTotals }
  );
  const optSelectedRows = Array.isArray(optRankedCandidates?.[0]?.rows) && optRankedCandidates[0].rows.length
    ? optRankedCandidates[0].rows
    : (opt.rows || []);

  const recommended = (optSelectedRows || []).map((r) => {
    const fallbackCurrent = currentRowForName(r.name);
    const rawName = isPlaceholderCropName(r.name)
      ? (fallbackCurrent?.name || p?.current_crop || p?.currentCrop || p?.crop || '-')
      : String(r.name||'').trim();
    const name = rawName;
    const area = safeNum(r.area, safeNum(fallbackCurrent?.area, 0));
    // Some producers already store delivered (gross) water in r.waterPerDa.
    // Prefer explicit NET base water if available to avoid double-adjusting.
    const hasExplicitBase = r._baseWaterPerDa != null || r.baseWaterPerDa != null;
    const grossFromTotal = area > 0 && Number.isFinite(safeNum(r.totalWater, NaN)) ? (safeNum(r.totalWater, 0) / area) : NaN;
    const baseWaterPerDa = hasExplicitBase
      ? safeNum((r._baseWaterPerDa ?? r.baseWaterPerDa), safeNum(fallbackCurrent?._baseWaterPerDa ?? fallbackCurrent?.waterPerDa, 0))
      : safeNum(r.waterPerDa, safeNum(grossFromTotal, safeNum(fallbackCurrent?.waterPerDa, 0)));
    const profitPerDa = safeNum(r.profitPerDa, safeNum(fallbackCurrent?.profitPerDa, 0));
    const fallbackCurrentKey = fallbackCurrent?.irrigationCurrentKey || irrKeyFromText(fallbackCurrent?.irrigationCurrentText || '');
    const keyBlock = irrigationKeysForCrop(name);
    const currentKey = r.irrigationCurrentKey || r.irrigationCurrent || fallbackCurrentKey || keyBlock.currentKey;
    const suggestedKey = r.irrigationSuggestedKey || r.irrigationRecommended || keyBlock.suggestedKey || currentKey;
    const cropKey = (_normIrrLookupKeys(name)[1] || String(name||''));

    // UI shows gross water (m3/da). Rows with explicit base store net field water;
    // legacy/cached rows without it are already gross and must not be adjusted twice.
    const waterPerDa = hasExplicitBase
      ? deliveredWaterPerDa(baseWaterPerDa, suggestedKey)
      : safeNum(grossFromTotal, baseWaterPerDa);
    const totalWater = area * waterPerDa;
    const totalProfit = area * profitPerDa;

    // Season may be missing for some sources.
    const sameAsCurrentCrop = fallbackCurrent && normCropName(fallbackCurrent.name) === normCropName(name);
    let season = String(r.season||'').trim();
    if(!season || season === '-' || (r.orchardConversion && /çok yıllık|bahçe/i.test(season))){
      season = inferSeasonFromCropName(name) || '';
    }
    if((!season || season === '-') && sameAsCurrentCrop){
      season = String(fallbackCurrent?.season||'').trim();
    }
    if(!season || season === '-'){
      const pair = pairingForCrop(name);
      if(pair && pair.season1) season = pair.season1;
      if((!season || season === '-')){
        const nn = normCropName(name).replace(/_/g,' ');
        if(nn.includes('NOHUT')) season = 'Yazlık';
        else if(nn.includes('BUGDAY') || nn.includes('ARPA') || nn.includes('CAVDAR')) season = 'Kışlık';
        else if(isPerennialCropName(name)) season = 'Çok yıllık / bahçe';
        else season = 'Tek sezon';
      }
    }

    return {
      name,
      area,
      season,
      irrigationCurrentKey: currentKey,
      irrigationCurrentText: fallbackCurrent?.irrigationCurrentText || irrigationLabel(currentKey),
      irrigationSuggestedKey: suggestedKey,
      irrigationSuggestedText: irrigationLabel(suggestedKey),
      irrigationSuggested: irrigationLabel(suggestedKey),
      _baseWaterPerDa: hasExplicitBase ? baseWaterPerDa : safeNum(baseWaterPerDa * Math.max(0.35, IRR_EFF[suggestedKey] || STATE.irrigEfficiency || 0.62), baseWaterPerDa),
      waterPerDa,
      profitPerDa,
      totalWater,
      totalProfit,
      _cropKey: cropKey,
    };
  });

  // Çok yıllık/bahçe parsellerinde ana ürün ekranda hiçbir koşulda tarla ürünüyle yer değiştirmemeli.
  // Özellikle tarayıcıda eski yerel düzeltme kayıtları kaldığında "mevcut=Kayısı, öneri=Mercimek"
  // gibi çelişkili görünüm oluşabiliyordu. Bu blok, UI tarafında tek kaynaktan tutarlı sonuç üretir.
  const orchardMainCurrent = (dominantCurrent && isPerennialCropName(dominantCurrent.name)) ? dominantCurrent : null;
  const orchardForcedUi = _seasonModeKey() === 's2' && !!(p?.parcel_type === 'orchard' || p?.is_orchard || orchardMainCurrent);
  let recommendedForUi = recommended;
  if(orchardForcedUi && orchardMainCurrent){
    const adj = s2IrrigationAdjust(scenarioKey);
    const currentKey = orchardMainCurrent.irrigationCurrentKey || irrKeyFromText(orchardMainCurrent.irrigationCurrentText || '') || 'drip';
    const suggestedKey = irrigationKeysForCrop(orchardMainCurrent.name).suggestedKey || currentKey;
    const baseNet = isFinite(safeNum(orchardMainCurrent._baseWaterPerDa, NaN))
      ? safeNum(orchardMainCurrent._baseWaterPerDa, 0)
      : safeNum(orchardMainCurrent.waterPerDa, 0) * Math.max(0.35, IRR_EFF[currentKey] || STATE.irrigEfficiency || 0.62);
    const forcedArea = +(safeNum(p?.area_da, orchardMainCurrent.area || 0)).toFixed(1);
    const forcedBaseNet = +(baseNet * adj.wmul).toFixed(3);
    const forcedWaterPerDa = deliveredWaterPerDa(forcedBaseNet, suggestedKey);
    const forcedProfitPerDa = +(safeNum(orchardMainCurrent.profitPerDa, 0) * adj.pmul).toFixed(2);
    recommendedForUi = [{
      name: orchardMainCurrent.name,
      area: forcedArea,
      season: orchardMainCurrent.season || 'Bahçe (çok yıllık)',
      irrigationCurrentKey: currentKey,
      irrigationCurrentText: orchardMainCurrent.irrigationCurrentText || irrigationLabel(currentKey),
      irrigationSuggestedKey: suggestedKey,
      irrigationSuggestedText: irrigationLabel(suggestedKey),
      irrigationSuggested: irrigationLabel(suggestedKey),
      _baseWaterPerDa: forcedBaseNet,
      waterPerDa: +forcedWaterPerDa.toFixed(3),
      profitPerDa: forcedProfitPerDa,
      totalWater: +(forcedArea * forcedWaterPerDa).toFixed(2),
      totalProfit: +(forcedArea * forcedProfitPerDa).toFixed(2),
      _cropKey: (_normIrrLookupKeys(orchardMainCurrent.name)[1] || String(orchardMainCurrent.name||'')),
      orchardLocked: true,
    }];
    const orchardAltMetrics = orchardAlternativeScenarioMetrics(orchardMainCurrent.name, safeNum(p?.area_da, forcedArea), scenarioKey, recommendedForUi[0], null);
    opt.orchardAlternativeMetrics = orchardAltMetrics;
    opt.orchardAlternatives = orchardAltMetrics;
  }

  const altMetaForUi = { orchardKeepMainCrop: !!(opt.orchardKeepMainCrop || orchardForcedUi), orchardAlternative: opt.orchardAlternative || null, orchardAlternatives: Array.isArray(opt.orchardAlternatives) ? opt.orchardAlternatives : null, orchardAlternativeMetrics: Array.isArray(opt.orchardAlternativeMetrics) ? opt.orchardAlternativeMetrics : null };
  const rankedPatternsForUi = rankedCandidatesToUiPatternsV8(p, current, optRankedCandidates, scenarioKey);
  let alternativePatternsForUi = rankedPatternsForUi.length ? rankedPatternsForUi : buildUiAlternativePatterns(p, current, recommendedForUi, altMetaForUi, scenarioKey);
  if(alternativePatternsForUi.length){
    recommendedForUi = patternComponentsToRecommendationRows(alternativePatternsForUi[0], recommendedForUi, p);
  }
  const seasonModeForUi = _seasonModeKey();
  if(!alternativePatternsForUi.length && !rankedPatternsForUi.length && seasonModeForUi === 's1'){
    const topPatternForUi = (alternativePatternsForUi || []).find(x=>x?.selectedRecommendation) || (alternativePatternsForUi || [])[0];
    if(topPatternForUi && Array.isArray(topPatternForUi.components) && topPatternForUi.components.length){
      recommendedForUi = patternComponentsToRecommendationRows(topPatternForUi, recommendedForUi, p).slice(0,1);
    }else if(Array.isArray(recommendedForUi) && recommendedForUi.length > 1){
      recommendedForUi = [recommendedForUi[0]];
    }
    alternativePatternsForUi = buildUiAlternativePatterns(p, current, recommendedForUi, altMetaForUi, scenarioKey);
  }else if(!alternativePatternsForUi.length && !rankedPatternsForUi.length && seasonModeForUi === 's2'){
    const topPatternForUi = (alternativePatternsForUi || []).find(x=>x?.selectedRecommendation) || (alternativePatternsForUi || [])[0];
    if(topPatternForUi && Array.isArray(topPatternForUi.components) && topPatternForUi.components.length > 1){
      recommendedForUi = patternComponentsToRecommendationRows(topPatternForUi, recommendedForUi, p);
    }
  }

  const recTotalsAdj = sumMetrics(recommendedForUi);
  const recWaterCurrentIrr = recommendedForUi.reduce((acc, rr) => {
    const w = deliveredWaterPerDa(safeNum(rr._baseWaterPerDa, rr.waterPerDa), rr.irrigationCurrentKey);
    return acc + safeNum(rr.area,0) * w;
  }, 0);
  const topPatternReasonForUi = alternativePatternsForUi?.[0]?.rankReason || alternativePatternsForUi?.[0]?.note || null;

  return {
    current,
    currentTotals,
    rec: recommendedForUi,
    recTotals: {
      water: recTotalsAdj.water,
      profit: recTotalsAdj.profit,
      water_eff: recTotalsAdj.water > 0 ? (recTotalsAdj.profit / recTotalsAdj.water) : 0,
      water_current_irrig: recWaterCurrentIrr,
      water_saving_m3: Math.max(0, recWaterCurrentIrr - recTotalsAdj.water),
      water_saving_pct: recWaterCurrentIrr > 0 ? (Math.max(0, recWaterCurrentIrr - recTotalsAdj.water) / recWaterCurrentIrr) : 0,
    },
    recMeta: {
      irrigationPlan: opt.irrigationPlan || null,
      lockedCrop: opt.lockedCrop || null,
      decisionMetrics: optRankedCandidates[0]?.metrics || opt.decisionMetrics || null,
      decisionReason: topPatternReasonForUi || (optRankedCandidates[0] ? decisionReasonV8(optRankedCandidates[0], scenarioKey) : (opt.decisionReason || null)),
      rankedCandidates: optRankedCandidates.length ? optRankedCandidates : (Array.isArray(opt.rankedCandidates) ? opt.rankedCandidates : null),
      ...altMetaForUi,
      alternativePatterns: alternativePatternsForUi
    },
  };
}


