function orchardAlternativeListFallback(currentRows, recRows, recMeta){
  if(Array.isArray(recMeta?.orchardAlternatives) && recMeta.orchardAlternatives.length) return recMeta.orchardAlternatives;
  const curMain = Array.isArray(currentRows) && currentRows.length ? [...currentRows].sort((a,b)=>safeNum(b.area)-safeNum(a.area))[0] : null;
  const mainName = curMain?.name || (Array.isArray(recRows) && recRows[0]?.name) || '';
  return orchardInterrowAlternativesForMain(mainName);
}

function orchardAlternativeFallback(currentRows, recRows, recMeta){
  if(recMeta?.orchardAlternative) return recMeta.orchardAlternative;
  const list = orchardAlternativeListFallback(currentRows, recRows, recMeta);
  if(Array.isArray(list) && list.length) return list[0];
  const curMain = Array.isArray(currentRows) && currentRows.length ? [...currentRows].sort((a,b)=>safeNum(b.area)-safeNum(a.area))[0] : null;
  const recAlt = Array.isArray(recRows) ? recRows.find(r=>curMain && normCropName(r.name)!==normCropName(curMain.name)) : null;
  if(recAlt){
    return { name: recAlt.name, kind: 'Sıra arası / örtü bitkisi', note: `${prettyCropName(recAlt.name)} ana ürün yerine değil, sıra arası/toprak iyileştirme amacıyla düşünülmelidir.` };
  }
  return null;
}

function alternativePatternPanelHtmlV94(patterns, metaLabel, scenLabel){
  const rows = (Array.isArray(patterns) ? patterns : []).slice(0, 8);
  if(!rows.length){
    return `<div class="pattern-panel-empty">Alternatif desen üretilemedi.</div>`;
  }
  const cards = rows.map(x=>{
    window.__patternPickStoreV102 = window.__patternPickStoreV102 || {};
    const pickId = `PAT-${Date.now()}-${Math.random().toString(36).slice(2,8)}`;
    window.__patternPickStoreV102[pickId] = x;
    const water = Math.round(safeNum(x.totalWater,0)).toLocaleString('tr-TR');
    const profit = Math.round(safeNum(x.totalProfit,0)).toLocaleString('tr-TR');
    const eff = safeNum(x.tlPerM3,0).toFixed(2);
    const rank = safeNum(x.rank,0) || '';
    const targetOrder = safeNum(x.targetOrder, rank) || rank;
    const split = x.areaSplit || (x.secondaryCrop && x.secondaryCrop !== '-' ? 'Aynı parselde yıllık desen olarak değerlendirilir' : 'Ana ürün %100');
    const dw = Math.round(safeNum(x.deltaWater,0));
    const dp = Math.round(safeNum(x.deltaProfit,0));
    const selectedBadge = x.selectedRecommendation ? '<span class="pattern-selected-badge">Seçilen öneri</span>' : '';
    const isSelectable = x.selectable !== false && x.feasible !== false && !x.quotaExceeded;
    const quotaBadge = x.quotaExceeded || x.feasible === false ? '<span class="pattern-risk-badge">Kota aşımı riski / uzman onayı gerekir</span>' : '<span class="pattern-selected-badge">Kota uygun</span>';
    const scenarioTypeLabel = Array.isArray(x.components) && x.components.length > 1 ? 'Kombinasyon / yüzde dağılımı' : 'Tek ürün';
    const components = Array.isArray(x.components) && x.components.length
      ? `<div class="pattern-component-list">${x.components.map(c=>`<span>${escapeHtml(c.role || 'Ürün')}: <b>${escapeHtml(c.crop || '-')}</b> %${Math.round(safeNum(c.share,0)*100)}</span>`).join('')}</div>`
      : '';
    return `<article class="pattern-card-v94${x.selectedRecommendation ? ' pattern-card-selected-v149' : ''}">
      <div class="pattern-card-top">
        <span class="pattern-rank">#${escapeHtml(rank)}</span>
        <strong>${escapeHtml(x.patternName || '')}</strong>
        ${selectedBadge}${quotaBadge}
      </div>
      <div class="pattern-target-order">Hedef sırası: ${escapeHtml(targetOrder)} • ${escapeHtml(metaLabel || 'Seçili hedef')} • ${escapeHtml(scenarioTypeLabel)}</div>
      <div class="pattern-card-crops">
        <span>${escapeHtml(x.mainCrop || '-')}</span>
        <span>${escapeHtml(x.secondaryCrop || '-')}</span>
      </div>
      <div class="pattern-card-metrics">
        <div><span>Su</span><b>${water} m³</b></div>
        <div><span>Net kâr</span><b>${profit} TL</b></div>
        <div><span>TL/m³</span><b>${eff}</b></div>
      </div>
      <div class="pattern-card-deltas">
        <span>Δ su <b>${dw>=0?'+':''}${dw.toLocaleString('tr-TR')} m³</b></span>
        <span>Δ kâr <b>${dp>=0?'+':''}${dp.toLocaleString('tr-TR')} TL</b></span>
      </div>
      <p>${escapeHtml(split)}</p>
      ${components}
      <small>Sulama: ${escapeHtml(x.irrigation || '-')}</small>
      <small>${escapeHtml(x.productionWindow || x.growthDays || 'Takvim kontrolü')} • ${escapeHtml(x.peakMonth || 'Pik ay kontrolü')} • ${escapeHtml(x.suitability || 'Uygunluk kontrolü')}</small>
      <div class="pattern-card-actions-v102">
        <button class="btn-link" type="button" data-alt-crop-v101="${escapeHtml(x.patternName || `${x.mainCrop || ''} + ${x.secondaryCrop || ''}`)}">Detay</button>
        <button class="btn-link" type="button" data-select-pattern-v102="${escapeHtml(pickId)}" ${isSelectable ? '' : 'disabled aria-disabled="true"'}>${isSelectable ? 'Seç' : 'Seçilemez'}</button>
      </div>
      <div class="small muted">${escapeHtml(x.note || 'Su, kâr, TL/m³ ve parsel uygunluğu birlikte değerlendirildi.')}</div>
    </article>`;
  }).join('');
  return `<details class="pattern-panel-v94">
    <summary>
      <span><strong>${escapeHtml(metaLabel)}</strong> • ${escapeHtml(scenLabel)}</span>
      <em>İlk ${rows.length} alternatifi aç</em>
    </summary>
    <div class="pattern-panel-note">Desenler su kotası, kâr, TL/m³, dönem-gün sayısı, pik ay, familya/rotasyon ve parsel uygunluğu birlikte okunarak sıralanır. Senaryo 2'de 2. ürün tek başına bağımsız öneri değil, ana ürünle birlikte yıllık desen olarak değerlendirilir.</div>
    <div class="pattern-card-grid-v94">${cards}</div>
  </details>`;
}

function renderTables() {
  let p = (parcelData || []).find((x) => String(x?.id) === String(selectedParcelId));
  if(!p){
    p = (parcelData || []).find(x=>x && x.id);
    if(p){
      selectedParcelId = String(p.id);
      try{ const sel=document.getElementById('parcelSelect'); if(sel) sel.value=selectedParcelId; }catch(_e){}
    }else{
      console.warn('renderTables: seçili parsel bulunamadı ve parcelData boş.');
      return;
    }
  }
  const seasonSource = (document.getElementById('seasonSourceSel')?.value) || STATE.seasonSource || 's1';
  let { current, currentTotals, rec, recTotals, recMeta } = computeCropData(p, selectedScenario, selectedAlgo);
  current = sanitizePlanRows(current, p);
  rec = sanitizePlanRows(rec, p);
  currentTotals = sumMetrics(current);
  if(Array.isArray(rec) && rec.length) recTotals = sumMetrics(rec);
  const orchardLockedUi = !!(recMeta?.orchardKeepMainCrop || p?.parcel_type === 'orchard' || p?.is_orchard || (current && current[0] && isPerennialCropName(current[0].name)));
  const orchardAlternativeUi = orchardLockedUi ? orchardAlternativeFallback(current, rec, recMeta) : null;
  try{ STATE.lastRecMeta = recMeta || null; }catch(_e){}
  try{
    const recTitle = Array.from(document.querySelectorAll('.card-subtitle')).find(x => String(x.textContent || '').includes('Önerilen Ürün Deseni'));
    if(recTitle){
      recTitle.textContent = recMeta?.noFeasibleTwoCrop
        ? 'Senaryo-2 için uygulanabilir iki ürünlü/desenli plan bulunamadı'
        : 'Önerilen Ürün Deseni (Senaryo + Algoritma)';
    }
  }catch(_e){}

  // --- SEZON / ROTASYON ALAN TUTARLILIĞI ---
  // Rotasyon (örn. Yazlık + Kışlık) aynı parsel alanında ardışık yapılır.
  // Bu durumda her sezonun toplam alanı parsel alanına eşit olmalıdır (yıllık toplam alana bölünmez).
  // Daha önceki sürümlerde öneri/mecut satır alanları tüm satırlar toplamı parsel alanına eşitlenecek
  // şekilde ölçekleniyordu; bu da rotasyonda "alan bölünmüş" gibi yanlış bir görüntü oluşturuyordu.
  const targetAreaDa = safeNum(p && p.area_da, 0);
  const scaleAreasToParcelBySeason = (rows) => {
    if (!Array.isArray(rows) || !rows.length || !(targetAreaDa > 0)) return rows;
    const groups = new Map(); // season -> rows
    for (const r of rows) {
      const s = String(r.season || '-');
      if (!groups.has(s)) groups.set(s, []);
      groups.get(s).push(r);
    }
    // Eğer tek sezon varsa eski davranışı koru (çeşitlendirme / aynı sezonda iki ürün).
    if (groups.size <= 1) return rows;

    const out = rows.map((r) => ({ ...r }));
    // index by object identity position
    const idxMap = new Map();
    rows.forEach((r, i) => idxMap.set(r, i));

    for (const [season, rs] of groups.entries()) {
      const sumA = rs.reduce((a, x) => a + safeNum(x.area, 0), 0);
      if (!(sumA > 0)) continue;
      const relDiff = Math.abs(sumA - targetAreaDa) / Math.max(targetAreaDa, 1e-9);
      // Sezon toplamı parsel alanından sapıyorsa, o sezon satırlarını parsel alanına ölçekle
      if (relDiff > 0.005) {
        const k = targetAreaDa / sumA;
        for (const r of rs) {
          const i = idxMap.get(r);
          if (i == null) continue;
          const area = safeNum(r.area, 0) * k;
          const waterPerDa = safeNum(r.waterPerDa, 0);
          const profitPerDa = safeNum(r.profitPerDa, 0);
          out[i].area = area;
          out[i].totalWater = waterPerDa * area;
          out[i].totalProfit = profitPerDa * area;
        }
      }
    }
    return out;
  };

  // Uygula: Hem mevcut hem öneri satırlarında sezon bazlı alan ölçekleme
  if (targetAreaDa > 0) {
    current = scaleAreasToParcelBySeason(current);
    currentTotals = sumMetrics(current);
    if (Array.isArray(rec) && rec.length) {
      rec = scaleAreasToParcelBySeason(rec);
      if (recTotals) {
        const recWater = rec.reduce((a, r) => a + safeNum(r.totalWater, 0), 0);
        const recProfit = rec.reduce((a, r) => a + safeNum(r.totalProfit, 0), 0);
        // Baseline: recommended crops under CURRENT irrigation methods
        const recWaterCurIrr = rec.reduce((acc, rr) => {
          const w = deliveredWaterPerDa(safeNum(rr._baseWaterPerDa, rr.waterPerDa), rr.irrigationCurrentKey);
          return acc + safeNum(rr.area, 0) * w;
        }, 0);
        recTotals = {
          ...recTotals,
          water: recWater,
          profit: recProfit,
          water_eff: recWater > 0 ? (recProfit / recWater) : 0,
          water_current_irrig: recWaterCurIrr,
          water_saving_m3: Math.max(0, recWaterCurIrr - recWater),
          water_saving_pct: recWaterCurIrr > 0 ? (Math.max(0, recWaterCurIrr - recWater) / recWaterCurIrr) : 0,
        };
      }
    }
  }

  // --- v57b: Önerilen desen alanlarını sezonsal mantıkla parsel alanına normalize et ---
  // Bazı algoritma çıktılarında (özellikle GA/ABC/ACO) alanlar yanlış ölçeklenebiliyor (örn. 5.8 da parselde 40.6 da).
  // Çiftçi arayüzünde bunu asla göstermemeliyiz; her sezon parsel alanı kadar kullanılır.
  if (Array.isArray(rec) && rec.length && targetAreaDa > 0) {
    rec = normalizeRowsBySeasonToParcelArea(targetAreaDa, rec);
    const recWater = rec.reduce((a, r) => a + safeNum(r.totalWater, 0), 0);
    const recProfit = rec.reduce((a, r) => a + safeNum(r.totalProfit, 0), 0);
    recTotals = { ...(recTotals || {}), water: recWater, profit: recProfit, water_eff: recWater > 0 ? recProfit / recWater : 0 };
    recMeta = { ...(recMeta || {}), area_normalized_to_parcel: true };
  }

  // --- Alan tutarlılığı (gösterim + toplamlar) ---
  // Not: Rotasyonlu planlarda alanlar sezon bazında ölçeklenir (yukarıda). Bu nedenle
  // burada "tüm satırlar toplamını" parsel alanına zorla eşitlemiyoruz.
  // Tek sezonlu (aynı sezonda çeşitlendirme) durumda alanlar zaten parsel alanına yakın olmalıdır.
  // Eğer çok küçük yuvarlama sapmaları varsa, tek sezon durumunda hafif ölçekle.
  if (Array.isArray(rec) && rec.length && targetAreaDa > 0) {
    const seasons = new Set(rec.map(r => String(r.season || '-')));
    if (seasons.size <= 1) {
      const sumRec = rec.reduce((a, r) => a + safeNum(r.area, 0), 0);
      if (sumRec > 0) {
        const relDiff = Math.abs(sumRec - targetAreaDa) / Math.max(targetAreaDa, 1e-9);
        if (relDiff > 0.005 && sumRec > targetAreaDa) {
          const k = targetAreaDa / sumRec;
          rec = rec.map((r) => {
            const area = safeNum(r.area, 0) * k;
            const waterPerDa = safeNum(r.waterPerDa, 0);
            const profitPerDa = safeNum(r.profitPerDa, 0);
            return {
              ...r,
              area,
              totalWater: waterPerDa * area,
              totalProfit: profitPerDa * area,
            };
          });
          const recWater = rec.reduce((a, r) => a + safeNum(r.totalWater, 0), 0);
          const recProfit = rec.reduce((a, r) => a + safeNum(r.totalProfit, 0), 0);
          recTotals = {
            ...(recTotals || {}),
            water: recWater,
            profit: recProfit,
            water_eff: recWater > 0 ? recProfit / recWater : 0,
          };
          recMeta = { ...(recMeta || {}), area_scaled: true, area_scale_factor: k };
        }
      }
    }
  }

  // Kullanıcı "Optimizasyonu Çalıştır" demeden, önceki parsel/senaryodan kalan
  // öneri desenini göstermeyelim.
  const canShowOpt = (selectedScenario === "mevcut") || canShowOptimizedForCurrentSelection();
  if (!canShowOpt) {
    rec = [];
    recTotals = null;
  }

  const tbodyCur = document.querySelector("#tblCurrent tbody");
  const tbodyRec = document.querySelector("#tblRecommended tbody");
  tbodyCur.innerHTML = "";
  tbodyRec.innerHTML = "";

  if (!canShowOpt) {
    tbodyRec.innerHTML = `
      <tr>
        <td colspan="8" style="text-align:center; padding:14px; color:#6b7280;">
          Bu parsel için önerilen deseni görmek için <b>Optimizasyonu Çalıştır</b> butonuna basın.
        </td>
      </tr>
    `;
  }

  const makeRow = (r, mode) => {
    const cropIrr = irrigationKeysForCrop(r.name || '');
    const irr = (mode==='cur')
      ? displayIrrigationText(r.irrigationCurrentText || r.irrigationCurrent, r.irrigationCurrentKey || cropIrr.currentKey)
      : null;

    const irrCell = (mode==='cur')
      ? irr
      : (()=>{
          const cropIrr = irrigationKeysForCrop(r.name || '');
          const curK = String(r.irrigationCurrentKey || cropIrr.currentKey || '');
          const sugK = String(r.irrigationSuggestedKey || cropIrr.suggestedKey || '');
          const sugLbl = displayIrrigationText(r.irrigationSuggestedText || r.irrigationSuggested, sugK || curK || cropIrr.suggestedKey || cropIrr.currentKey || '');
          const curLbl = displayIrrigationText(r.irrigationCurrentText || r.irrigationCurrent, curK || cropIrr.currentKey || '');
          if(!sugK || sugK === curK){
            return `<div class="irr-cell"><div>${escapeHtml(sugLbl)}</div></div>`;
          }
          return `<div class="irr-cell"><div>${escapeHtml(sugLbl)}</div><div class="irr-hint">Mevcut: ${escapeHtml(curLbl)}</div></div>`;
        })();
    const rawSeason = !isBlankSeasonLabel(r.season) ? String(r.season) : inferSeasonLabelFromCrop(r.name || '', p?.parcel_type || '');
    const areaShareForRow = safeNum(r.area_share_pct, 0) > 0
      ? Math.round(safeNum(r.area_share_pct, 0))
      : Math.round((safeNum(r.area,0) / Math.max(1, targetAreaDa || safeNum(p?.area_da,0) || safeNum(r.area,0))) * 100);
    const displaySeason = (mode === 'rec' && /desen\s*pay/i.test(rawSeason))
      ? `Oran %${areaShareForRow}`
      : rawSeason;
    return `
    <tr>
      <td>${escapeHtml(prettyCropName(r.name || '-'))}</td>
      <td>${escapeHtml(displaySeason)}</td>
      <td>${irrCell}</td>
      <td>${safeNum(r.area,0).toFixed(1)}</td>
      <td>${safeNum(r.waterPerDa,0).toLocaleString("tr-TR")}</td>
      <td>${Math.round(safeNum(r.totalWater,0)).toLocaleString("tr-TR")}</td>
      <td>${safeNum(r.profitPerDa,0).toLocaleString("tr-TR")}</td>
      <td>${Math.round(safeNum(r.totalProfit,0)).toLocaleString("tr-TR")}</td>
    </tr>
  `;
  };

  current.forEach((r) => (tbodyCur.innerHTML += makeRow(r,'cur')));
  if (canShowOpt) {
    rec.forEach((r) => (tbodyRec.innerHTML += makeRow(r,'rec')));
  }

  const footerCur = document.getElementById("tblCurrentFooter");
  const footerRec = document.getElementById("tblRecommendedFooter");

  const effCur = currentTotals.profit / Math.max(1e-9, currentTotals.water);
  // Not: Optimizasyon çalıştırılmadıysa recTotals null olabilir.
  // Bu durumda öneri tablosu/özetleri kırmadan "Optimizasyonu çalıştırın" uyarısı gösterilir.
  const effRec = (recTotals && recTotals.water != null && recTotals.profit != null)
    ? (recTotals.profit / Math.max(1e-9, recTotals.water))
    : 0;
  const fmtEff = (v)=>{
    if(!isFinite(v)) return "0";
    if(v < 0) return v.toFixed(2);
    if(v < 1) return v.toFixed(3);
    return v.toFixed(1);
  };

  // Başlık: kapsamı kullanıcıya net göster
  const titleEl = document.getElementById('metricsTitle');
  if(titleEl){
    titleEl.textContent = metricsTitleForCurrentRole(selectedParcelId);
    if(selectedParcelId !== '__ALL__' && STATE.currentUser?.role !== 'farmer'){
      titleEl.textContent = `Parsel Karar Özeti (${selectedParcelId})`;
    }
  }

  footerCur.textContent = `Mevcut toplam su: ${Math.round(
    currentTotals.water
  ).toLocaleString("tr-TR")} m³ | Mevcut toplam net kâr: ${Math.round(
    currentTotals.profit
  ).toLocaleString("tr-TR")} TL | Su verimliliği: ${fmtEff(effCur)} TL/m³`;

  if (canShowOpt && recMeta?.noFeasibleTwoCrop) {
    tbodyRec.innerHTML = `
      <tr>
        <td colspan="8" style="text-align:center; padding:14px; color:#92400e;">
          Senaryo-2 için uygulanabilir iki ürünlü/desenli plan bulunamadı. Uygulanamaz desenler yalnız uzman onayıyla incelenebilir.
        </td>
      </tr>
    `;
    const uiAlternativePatterns = Array.isArray(recMeta?.alternativePatterns) ? recMeta.alternativePatterns : [];
    const altPanelHtml = uiAlternativePatterns.length
      ? alternativePatternPanelHtmlV94(uiAlternativePatterns, getScenarioDisplayMeta(selectedScenario).label, 'En yakın uygulanamaz alternatifler / uzman onayı gerekir')
      : '';
    if (footerRec) {
      footerRec.innerHTML = `<div class="small" style="margin-top:8px; padding:8px 10px; border:1px solid #fde68a; border-radius:10px; background:#fffbeb;"><strong>Uygun plan yok:</strong> ${escapeHtml(recMeta.decisionReason || 'Seçili parsel ve su kotası altında uygulanabilir iki ürünlü/desenli plan bulunamadı.')}</div>${altPanelHtml}`;
    }
    const explainBox = document.getElementById("explainBox");
    if (explainBox) {
      explainBox.innerHTML = `<div><strong>Senaryo-2 sonucu:</strong> uygulanabilir iki ürünlü/desenli plan bulunamadı.</div><div style="margin-top:6px;">Backend, kotayı aşan veya takvim/uygunluk riski taşıyan desenleri ana öneri olarak seçilebilir göstermedi.</div>`;
    }
    return;
  }

  // Öneri footer ve açıklanabilirlik kutuları sadece optimizasyon sonucu varsa hesaplanmalı.
  if (!canShowOpt || !recTotals) {
    if (footerRec) {
      footerRec.textContent = "Bu parsel için önerilen deseni görmek için 'Optimizasyonu Çalıştır' butonuna basın.";
    }
    const explainBox = document.getElementById("explainBox");
    if (explainBox) {
      explainBox.innerHTML = `<div style="opacity:.9">Öneriler ve kısıt değerlendirmesi, optimizasyon çalıştırıldıktan sonra gösterilir.</div>`;
    }
    // Diğer kutular da boş kalmasın
    const deliveryBox = document.getElementById("deliveryBox");
    if (deliveryBox) {
      deliveryBox.innerHTML = `<div style="opacity:.9">Aylık kapasite kontrolü için önce optimizasyon sonucunu üretin.</div>`;
    }
    const irrigPlanBox = document.getElementById("irrigPlanBox");
    if (irrigPlanBox) {
      irrigPlanBox.innerHTML = `<div style="opacity:.9">Sulama planı, önerilen desen oluştuğunda hesaplanır.</div>`;
    }
    const rotationBox = document.getElementById("rotationBox");
    if (rotationBox) {
      rotationBox.innerHTML = `<div style="opacity:.9">Rotasyon / 2. ürün önerisi, optimizasyon sonucuna göre güncellenir.</div>`;
    }
    const irrigationCompareBox = document.getElementById('irrigationCompareBox');
    if(irrigationCompareBox){ irrigationCompareBox.innerHTML = `<div style="opacity:.9">Sulama yöntemi karşılaştırması için önce optimizasyon sonucunu üretin.</div>`; }
    const businessMetricsBox = document.getElementById('businessMetricsBox');
    if(businessMetricsBox){ businessMetricsBox.innerHTML = `<div style="opacity:.9">Ekonomik dayanak tablosu, öneri sonucu oluştuğunda fiyat/verim/gider kırılımıyla doldurulur.</div>`; }
    // Opt sonuç yokken aşağıdaki hesaplara girmeyelim
    return;
  }

  let recFooter = `Senaryo toplam su: ${Math.round(
    recTotals.water
  ).toLocaleString("tr-TR")} m³ | Senaryo toplam net kâr: ${Math.round(
    recTotals.profit
  ).toLocaleString("tr-TR")} TL | Su verimliliği: ${fmtEff(effRec)} TL/m³`;

  // Irrigation-method savings within the recommended plan (current->selected)
  if(isFinite(recTotals.water_saving_m3) && recTotals.water_saving_m3 > 0){
    recFooter += ` | Sulama yöntemi tasarrufu: ${Math.round(recTotals.water_saving_m3).toLocaleString("tr-TR")} m³ (${(recTotals.water_saving_pct*100).toFixed(1)}%)`;
  }

  if(recMeta && recMeta.irrigationPlan){
    recFooter += ` | Sulama planı: ${recMeta.irrigationPlan}`;
  }

  if (footerRec) {
    const uiAlternativePatterns = Array.isArray(recMeta?.alternativePatterns) && recMeta.alternativePatterns.length
      ? recMeta.alternativePatterns
      : (recMeta?.backendOnly ? [] : buildUiAlternativePatterns(p, current, rec, recMeta || {}, selectedScenario));
    const metaLabel = getScenarioDisplayMeta(selectedScenario).label;
    const scenLabel = (_seasonModeKey()==='s2') ? 'Senaryo 2 - Çift ürün / desen' : 'Senaryo 1 - Tek ürün';
    const altPanelHtml = uiAlternativePatterns.length ? alternativePatternPanelHtmlV94(uiAlternativePatterns, metaLabel, scenLabel) : '';
    const orchardInfo = orchardLockedUi ? `<div class="small" style="margin-top:8px; padding:8px 10px; border:1px solid #dbeafe; border-radius:10px; background:#f8fbff;"><strong>Bahçe kuralı:</strong> Ana ürün korunur. Aşağıdaki alternatifler ürün sökümü değil; sıra arası / örtü bitkisi ve yönetim desenidir.</div>` : '';
    const planFeasibleForWarning = recMeta?.selectedPlan?.feasible !== false && recMeta?.selectedPlan?.selectable !== false && recMeta?.backendDecisionPackage?.selected_plan?.feasible !== false;
    const conversionWarnings = Array.isArray(recMeta?.conversionWarnings)
      ? recMeta.conversionWarnings.filter(x=>!(planFeasibleForWarning && isInfeasiblePlanWarningText(x)))
      : [];
    const warningHtml = conversionWarnings.length
      ? `<div class="small" style="margin-top:8px; padding:8px 10px; border:1px solid #fde68a; border-radius:10px; background:#fffbeb;"><strong>Dönüşüm / uygunluk uyarısı:</strong><ul style="margin:6px 0 0 18px; padding:0;">${conversionWarnings.map(x=>`<li>${escapeHtml(x)}</li>`).join('')}</ul></div>`
      : '';
    const diversityHtml = diversityWarningHtml(
      recMeta?.diversity || recMeta?.selectedPlan?.diversity || recMeta?.backendDecisionPackage?.diversity,
      recMeta?.recommendationStatus || recMeta?.selectedPlan?.recommendation_status || recMeta?.backendDecisionPackage?.recommendation_status,
      !!(recMeta?.diversityRepairApplied || recMeta?.selectedPlan?.diversity_repair_applied),
      {
        feasible: recMeta?.selectedPlan?.feasible !== false && recMeta?.backendDecisionPackage?.selected_plan?.feasible !== false,
        selectable: recMeta?.selectedPlan?.selectable !== false && recMeta?.backendDecisionPackage?.selected_plan?.selectable !== false
      }
    );
    const agronomicRiskBlock = agronomicRiskHtml(
      recMeta?.agronomicRisk || recMeta?.selectedPlan?.agronomic_risk || recMeta?.backendDecisionPackage?.agronomic_risk
    );
    const interrowHtml = Array.isArray(recMeta?.interrowAlternatives) && recMeta.interrowAlternatives.length
      ? `<div class="small" style="margin-top:8px; padding:8px 10px; border:1px dashed #cbd5e1; border-radius:10px; background:#f8fafc;"><strong>Sıra arası / uzman alternatifi:</strong><ul style="margin:6px 0 0 18px; padding:0;">${recMeta.interrowAlternatives.slice(0,5).map(x=>`<li><b>${escapeHtml(x.name || x.cropName || '-')}</b> - ${escapeHtml(x.kind || x.cropCategoryLabel || 'Uzman değerlendirmesi')} ${x.decisionNote || x.note ? `: ${escapeHtml(x.decisionNote || x.note)}` : ''}</li>`).join('')}</ul></div>`
      : '';
    const recLead = Array.isArray(rec) && rec.length ? rec[0] : null;
    const whyList = recLead ? [
      ...(Array.isArray(recLead.reasonDetails) ? recLead.reasonDetails : []),
      ...(Array.isArray(recLead.cautionDetails) ? recLead.cautionDetails.slice(0,2).map(x=>`Dikkat: ${x}`) : [])
    ].slice(0,5) : [];
    const reasonLead = recMeta?.decisionReason || recLead?.decisionNote || 'Su kotası, mevsim ve parsel uygunluğu birlikte değerlendirildi.';
    const whyHtml = recLead ? `<div class="small" style="margin-top:8px; padding:8px 10px; border:1px solid #e6f4ea; border-radius:10px; background:#fbfffc;"><strong>Neden bu ürün önerildi?</strong><ul style="margin:6px 0 0 18px; padding:0;">${whyList.length ? whyList.map(x=>`<li>${escapeHtml(x)}</li>`).join('') : `<li>${escapeHtml(reasonLead)}</li>`}</ul><div class="muted" style="margin-top:6px;">Not: Sistem şu an su kotası, mevsim, ürün familyası/rotasyon, parsel tipi, toprak sınıfı ve sulama yöntemini modelliyor. Ayrıntılı hastalık analizi ve laboratuvar mineral verisi yüklenirse daha da güçlenir.</div></div>` : '';
    const autoDecision = STATE.autoAlgoDecisionV7;
    const autoHtml = autoDecision?.selected
      ? `<div class="small" style="margin-top:8px; padding:8px 10px; border:1px solid #dbeafe; border-radius:10px; background:#f8fbff;"><strong>Otomatik algoritma seçimi:</strong> ${escapeHtml(String(autoDecision.selected).toUpperCase())} seçildi. GA, ACO ve ABC aynı hedef/senaryo koşulunda su kotası, net kâr, TL/m³ ve hedef skoruyla kıyaslandı.</div>`
      : '';
    footerRec.innerHTML = `<div class="rec-footer-kpi-v94">${recFooter}</div>${warningHtml}${diversityHtml}${agronomicRiskBlock}${autoHtml}${orchardInfo}${whyHtml}${interrowHtml}${altPanelHtml}`;
  }

  // --- Açıklanabilirlik kutusu (seçili parsel) ---
  const explainBox = document.getElementById("explainBox");
  if(explainBox){
    const basin = computeBasinPlan(selectedScenario, selectedAlgo);
    const pBudget = parcelWaterBudget(p.area_da, p);
    const margin = pBudget - recTotals.water;
    const risk = clamp(STATE.droughtRisk ?? 0, 0, 1);
    const role = STATE.currentUser?.role || 'institution';
    const patternWhy = summarizePlanShift(current, rec, seasonSource, selectedScenario);
    const curMethod = current.map(r=>r.irrigationCurrentText || irrigationLabel(r.irrigationCurrentKey)).filter(Boolean).join(' / ') || '-';
    const recMethod = rec.map(r=>r.irrigationSuggested || irrigationLabel(r.irrigationSuggestedKey || r.irrigationCurrentKey)).filter(Boolean).join(' / ') || '-';
    if(role === 'farmer'){
      const status = margin >= 0 ? 'Güvenli aralıkta' : 'Su açığı var';
      const action = margin >= 0 ? 'Bu öneri mevcut su sınırını aşmadan üretimi sürdürmeye uygundur.' : 'Bu parsel deseni mevcut su sınırını aşıyor; daha az su isteyen ürün veya daha verimli sulama gerekir.';
      explainBox.innerHTML = `<div><strong>Bu yıl parseliniz için karar özeti</strong></div><div>Yaklaşık güvenli su sınırı: <strong>${Math.round(pBudget).toLocaleString("tr-TR")} m³</strong></div><div>Önerilen desen su ihtiyacı: <strong>${Math.round(recTotals.water).toLocaleString("tr-TR")} m³</strong> • Net kâr etkisi: <strong>${Math.round(recTotals.profit).toLocaleString('tr-TR')} TL</strong></div><div>Durum: <strong>${status}</strong>${margin < 0 ? ` • Açık: ${Math.round(Math.abs(margin)).toLocaleString("tr-TR")} m³` : ` • Kalan pay: ${Math.round(margin).toLocaleString("tr-TR")} m³`}</div><div>Kuraklık baskısı: <strong>${risk < 0.33 ? 'Düşük' : (risk < 0.66 ? 'Orta' : 'Yüksek')}</strong> • Mevcut yöntem: <strong>${escapeHtml(curMethod)}</strong> • Önerilen yöntem: <strong>${escapeHtml(recMethod)}</strong></div><div style="margin-top:8px;"><strong>Neden desen değişti?</strong> ${patternWhy}</div><div style="margin-top:8px; opacity:0.92;">${action}</div>`;
    }else{
      explainBox.innerHTML = `<div><strong>Küresel su bütçesi:</strong> <strong>${Math.round(basin.budget).toLocaleString("tr-TR")} m³</strong> (seçili yıl: ${STATE.selectedWaterYear}, projeksiyon: ${STATE.selectedProjScenario})</div><div><strong>Seçili parsel için ayrılan yaklaşık güvenli pay:</strong> ${Math.round(pBudget).toLocaleString("tr-TR")} m³</div><div><strong>Seçili parsel kullanımı:</strong> ${Math.round(recTotals.water).toLocaleString("tr-TR")} m³ • <strong>Durum:</strong> ${margin>=0 ? "Uygun" : "Aşım"} (${Math.round(Math.abs(margin)).toLocaleString("tr-TR")} m³)</div><div><strong>Kuraklık riski (0-1):</strong> ${risk.toFixed(2)} • <strong>Varsayılan randıman:</strong> ${Math.round((STATE.irrigEfficiency ?? 0.62)*100)}% • <strong>Desen nedeni:</strong> ${patternWhy}</div><div style="margin-top:6px; opacity:0.9;">Aşım varsa sistem havza genelinde su yoğun ürünlerden daha düşük su yoğun ürünlere ve daha verimli sulama yöntemlerine geçerek bütçeyi sağlamaya çalışır. Greedy düzeltme / onarım iterasyonu: ${basin.iterations}.</div>`;
    }
  }

  // Parsel seviyesinde (alan dağılımı / sulama planı) kullanılacak satırlar:
  // - "Mevcut desen" seçiliyken (selectedScenario='mevcut') öneri boş olabileceği için mevcut desene düş.
  // - Öneri boş dönerse yine mevcut desen.
  const rowsUsed = (String(selectedScenario).toLowerCase() === 'mevcut' || !rec || rec.length === 0) ? current : rec;

  // --- Aylık su yükü ve kritik dönemler (v14 güven etiketi + kullanım oranı) ---
  try{ renderDeliveryBoxV14(p, rowsUsed); }
  catch(err){
    console.warn('renderDeliveryBoxV14 hata:', err);
    const deliveryBox = document.getElementById('deliveryBox');
    if(deliveryBox) deliveryBox.innerHTML = '<div class="callout callout-warn">Aylık su yükü tablosu üretilemedi.</div>';
  }

  // --- Rotasyon / 2. ürün önerisi ---
  const rotationBox = document.getElementById("rotationBox");
  if(rotationBox){
    const main = [...rowsUsed].sort((a,b)=>b.area-a.area)[0]?.name;
    const rot = makeRotationSuggestions(main);
    const orchardAlternativeListUi = orchardLockedUi ? orchardAlternativeListFallback(current, rec, recMeta) : [];
    const orchardAlternativeMetricsUi = orchardLockedUi ? (Array.isArray(recMeta?.orchardAlternativeMetrics) && recMeta.orchardAlternativeMetrics.length ? recMeta.orchardAlternativeMetrics : orchardAlternativeScenarioMetrics(main, safeNum(p?.area_da, 0), selectedScenario, rec[0] || current[0], orchardAlternativeListUi)) : [];
    const altHtml = orchardLockedUi && orchardAlternativeMetricsUi.length ? `<div class="small" style="margin:8px 0 0 0; padding:8px 10px; border:1px dashed #cbd5e1; border-radius:10px; background:#f8fafc;"><strong>Sıra arası alternatifler (ana ürün yerine değil):</strong><table class="data-table" style="margin-top:8px; font-size:12px;"><thead><tr><th>Ürün</th><th>Rol</th><th>Alan</th><th>Su</th><th>Kâr</th><th>TL/m³</th></tr></thead><tbody>${orchardAlternativeMetricsUi.slice(0,4).map(x=>`<tr><td><b>${escapeHtml(prettyCropName(x.name))}</b></td><td>${escapeHtml(x.kind || 'Sıra arası')}</td><td>${safeNum(x.area,0).toFixed(1)} da</td><td>${Math.round(safeNum(x.totalWater,0)).toLocaleString('tr-TR')} m³</td><td>${Math.round(safeNum(x.totalProfit,0)).toLocaleString('tr-TR')} TL</td><td>${safeNum(x.tlPerM3,0).toFixed(2)}</td></tr><tr><td colspan="6" class="muted" style="padding-top:0;">${escapeHtml(x.note || '')}</td></tr>`).join('')}</tbody></table></div>` : '';
    const s2Note = (_seasonModeKey()==='s2')
      ? '<div class="small" style="margin:8px 0; padding:8px 10px; border:1px solid #dbeafe; border-radius:10px; background:#f8fbff;"><strong>2. ürün okuması:</strong> Buradaki 2. ürün ayrı bağımsız öneri değildir; aynı parsel için ana ürünle birlikte yıllık desen/rotasyon olarak test edilir. Uygunluk; dönem-gün sayısı, su kotası, pik ay, ürün familyası ve mevcut toprak sınıfı/proxy verisiyle birlikte değerlendirilir.</div>'
      : '<div class="small" style="margin:8px 0; padding:8px 10px; border:1px solid #e5e7eb; border-radius:10px; background:#fff;"><strong>Tek ürün modu:</strong> Bu modda ana karar tek ürün desenidir; 2. ürün yalnızca literatür/rotasyon notu olarak gösterilir, optimizasyon deseni değildir.</div>';
    rotationBox.innerHTML = `<div><strong>${rot.title}:</strong></div>${s2Note}<ul style="margin:6px 0 0 18px;">${rot.items.map(x=>`<li>${x}</li>`).join("")}</ul>${altHtml}`;
  }
  renderIrrigationCompare(current, rec, p, selectedScenario);
  renderBusinessMetrics(current, rec, p, selectedScenario);

  // --- Sulama planı (ETo×Kc) ---
  renderIrrigationPlan(p, rowsUsed);
}

// Senaryo özet metrikleri (seçili kapsam / 5 köy parselleri toplamı - hesaplanan)
function renderMetrics() {
  renderAllScenarioSummaries();
}


function totalsAllParcels(scenarioKey, algoKey){
  // IMPORTANT:
  // The "Senaryo Özeti (seçili kapsam)" box must compare metrics that are computed
  // with the SAME accounting model (same crop water/profit intensities and the same
  // per-parcel composition logic). Otherwise, a backend-provided baseline (often built
  // from legacy summaries) can be in different units/assumptions than the frontend
  // optimization model, which incorrectly makes "Su tasarrufu" appear as a water increase.
  //
  // Therefore we ALWAYS compute totals via computeBasinPlan() for consistency.
  // If the app is running without enough data to compute a basin plan, computeBasinPlan
  // will throw and the caller can show diagnostics.
  const basin = computeBasinPlan(scenarioKey, algoKey);
  return { ...basin.totals, budget: basin.budget, feasible: basin.feasible, iterations: basin.iterations };
}

function getScenarioDisplayMeta(scenarioKey){
  const s = String(scenarioKey || '').toLowerCase().trim();
  if(s === 'mevcut' || s === 'current') return { key:'mevcut', label:'Mevcut desen', shortLabel:'Mevcut', icon:'\u{1F4CC}' };
  if(s === 'su_tasarruf' || s === 'su tasarruf' || s === 'water_saving' || s === 'tasarruf') return { key:'su_tasarruf', label:'Su tasarrufu', shortLabel:'Su tasarrufu', icon:'\u{1F4A7}' };
  if(s === 'maks_kar' || s === 'maks kar' || s === 'max_profit') return { key:'maks_kar', label:'Kâr odaklı', shortLabel:'Kâr odaklı', icon:'\u{1F4B0}' };
  if(s === 'su_etkin' || s === 'water_efficiency' || s === 'balanced' || s === 'onerilen' || s === 'recommended' || s === 'denge') return { key:'su_etkin', label:'Su etkin kullanım', shortLabel:'Su etkin', icon:'\u2696\uFE0F' };
  return { key:s || 'su_etkin', label:'Seçili hedef', shortLabel:'Seçili hedef', icon:'\u{1F3AF}' };
}

function renderIrrigationCompare(currentRows, recRows, parcel, objectiveKey){
  const box = document.getElementById('irrigationCompareBox');
  if(!box) return;
  const current = Array.isArray(currentRows) ? currentRows : [];
  const rec = Array.isArray(recRows) ? recRows : [];
  if(!current.length){
    box.innerHTML = '<div class="small muted">Sulama yöntemi karşılaştırması için seçili parselde ürün satırı bulunamadı.</div>';
    return;
  }
  const methods = [
    {key:'surface', label:'Karık / salma'},
    {key:'sprinkler', label:'Yağmurlama'},
    {key:'drip', label:'Damla'},
  ];

  const normalizeRowsForMethod = (rows, defaultMode)=> (rows||[]).map(r=>{
    const cropIrr = irrigationKeysForCrop(r.name || '');
    const currentKey = r.irrigationCurrentKey || cropIrr.currentKey || 'sprinkler';
    const suggestedKey = r.irrigationSuggestedKey || cropIrr.suggestedKey || currentKey;
    const refKey = (defaultMode==='current' ? currentKey : suggestedKey);
    const baseWater = safeNum(r._baseWaterPerDa, 0) || (safeNum(r.waterPerDa, 0) * Math.max(.35, IRR_EFF[refKey] || STATE.irrigEfficiency || .62));
    return { ...r, irrigationCurrentKey: currentKey, irrigationSuggestedKey: suggestedKey, _baseWaterPerDa: baseWater };
  });
  const curRows = normalizeRowsForMethod(current, 'current');
  const recRowsNorm = normalizeRowsForMethod(rec.length ? rec : current, 'recommended');

  const computeMethodTotals = (rows, methodKey, mode='recommended')=>{
    const econRows = rows.map(r=>computeRowEconomics(r, parcel, methodKey, mode==='current' ? (r.irrigationCurrentKey || irrigationKeysForCrop(r.name).currentKey) : (r.irrigationSuggestedKey || irrigationKeysForCrop(r.name).suggestedKey)));
    return econRows.reduce((acc, r)=>{
      acc.water += r.totalWaterM3;
      acc.net += r.totalNetProfitTl;
      acc.irrigCost += (r.breakdown.find(x=>x.label==='Sulama işletme')?.amount || 0);
      return acc;
    }, { water:0, net:0, irrigCost:0 });
  };

  const baselineRecommended = computeMethodTotals(recRowsNorm, recRowsNorm[0]?.irrigationSuggestedKey || curRows[0]?.irrigationCurrentKey || 'sprinkler', 'recommended');

  const tableRows = methods.map(m=>{
    const currentTotals = computeMethodTotals(curRows, m.key, 'current');
    const recTotals = computeMethodTotals(recRowsNorm, m.key, 'recommended');
    return {
      ...m,
      current: currentTotals,
      recommended: recTotals,
      diffRecommendedVsBase: recTotals.water - baselineRecommended.water,
      effRecommended: recTotals.net / Math.max(1, recTotals.water)
    };
  });
  const best = [...tableRows].sort((a,b)=>a.recommended.water-b.recommended.water)[0];
  const currentMethodLabel = irrigationLabel(curRows[0]?.irrigationCurrentKey || 'sprinkler');
  const recommendedMethodLabel = irrigationLabel(recRowsNorm[0]?.irrigationSuggestedKey || curRows[0]?.irrigationCurrentKey || 'sprinkler');

  box.innerHTML = `
    <div class="irrig-compare-head"><strong>Sulama yöntemi karşılaştırması</strong><span class="pill-soft">${escapeHtml(getScenarioDisplayMeta(objectiveKey).label)}</span></div>
    <div class="small muted" style="margin-bottom:10px;">Seçici kutular kaldırıldı. Aşağıdaki tablo aynı ürün deseni korunurken sulama yönteminin etkisini otomatik karşılaştırır; böylece yöntem farkı daha açık okunur.</div>
    <div class="small" style="margin-bottom:10px;">Mevcut kayıtlı yöntem: <strong>${escapeHtml(currentMethodLabel)}</strong> • Optimizasyonun önerdiği yöntem: <strong>${escapeHtml(recommendedMethodLabel)}</strong> • En düşük su isteyen seçenek: <strong>${escapeHtml(best.label)}</strong></div>
    <div class="business-table-wrap">
      <table class="data-table business-table">
        <thead><tr><th>Yöntem</th><th>Mevcut desen su (m³)</th><th>Mevcut desen net kâr</th><th>Önerilen desen su (m³)</th><th>Önerilen desen net kâr</th><th>Önerilen Δ su</th><th>Önerilen sulama gideri</th><th>Önerilen TL/m³</th><th>Yorum</th></tr></thead>
        <tbody>${tableRows.map(r=>`<tr><td><strong>${escapeHtml(r.label)}</strong></td><td>${Math.round(r.current.water).toLocaleString('tr-TR')}</td><td>${Math.round(r.current.net).toLocaleString('tr-TR')} TL</td><td>${Math.round(r.recommended.water).toLocaleString('tr-TR')}</td><td>${Math.round(r.recommended.net).toLocaleString('tr-TR')} TL</td><td>${(r.diffRecommendedVsBase>=0?'+':'') + Math.round(r.diffRecommendedVsBase).toLocaleString('tr-TR')} m³</td><td>${Math.round(r.recommended.irrigCost).toLocaleString('tr-TR')} TL</td><td>${r.effRecommended.toFixed(2)}</td><td>${r.key===best.key ? '<span class="metric-note-strong">En düşük su</span>' : (r.key==='surface' ? 'Su kaybı yüksek' : (r.key==='sprinkler' ? 'Dengeli geçiş' : 'Yüksek verimlilik'))}</td></tr>`).join('')}</tbody>
      </table>
    </div>
    <div class="small" style="margin-top:8px; padding:8px 10px; border:1px solid #eef2f7; border-radius:10px; background:#fbfcfe;">
      <strong>Okuma notu:</strong> İlk iki veri sütunu mevcut ürünü sabit tutar, sonraki sütunlar ise önerilen ürünü aynı sulama yöntemi altında test eder. Böylece ürün farkı ile sulama yöntemi farkı birbirine karışmaz.
    </div>`;
}

function buildDecisionRationaleByObjective(objectiveKey, dWater, dProfit, dEff){ const o=getScenarioDisplayMeta(objectiveKey).key; const betterWater=dWater<=0; const betterProfit=dProfit>=0; const waterTxt=`${dWater < 0 ? 'yaklaşık ' + Math.round(Math.abs(dWater)).toLocaleString('tr-TR') + ' m³ daha az' : 'yaklaşık ' + Math.round(Math.abs(dWater)).toLocaleString('tr-TR') + ' m³ daha fazla'} su`; const profitTxt=`${dProfit >= 0 ? '+' : '-'}${Math.round(Math.abs(dProfit)).toLocaleString('tr-TR')} TL net kâr etkisi`; const effTxt=`${dEff >= 0 ? '+' : ''}${dEff.toFixed(2)} TL/m³ su verimliliği farkı`; if(o==='mevcut') return {title:'Karar Gerekçesi (Referans görünüm)',msg:'Bu ekran optimizasyon sonucu değil, mevcut kayıtların referans görünümüdür. Aşağıdaki tüm öneriler bu başlangıç durumuna göre fark olarak hesaplanır.',note:'Yeni öneri üretmek için hedef modunu seçip optimizasyonu çalıştırın.'}; if(o==='su_tasarruf'){ if(betterWater && betterProfit) return {title:'Karar Gerekçesi (Su verimliliği hedefi)',msg:`Öneri ${waterTxt} kullanırken ${profitTxt} da sağlıyor. Bu, su daralırken geliri koruyan güçlü bir sonuçtur.`,note:`${effTxt}. Sistem suyu fazla isteyen ürünü veya yöntemi geri çekip daha verimli kombinasyona yönelmiştir.`}; if(betterWater && !betterProfit) return {title:'Karar Gerekçesi (Su verimliliği hedefi)',msg:`Öneri ${waterTxt} kullanıyor; bunun karşılığında ${profitTxt} görülüyor. Kurak yıllarda bu ödünleşme yönetilebilir olabilir; kritik karar su açığını önlemektir.`,note:`${effTxt}. Çiftçiye bu fark özellikle aylık sulama takvimiyle birlikte anlatılmalıdır.`}; if(!betterWater && betterProfit) return {title:'Karar Gerekçesi (Su verimliliği hedefi)',msg:`Gelir tarafında ${profitTxt} görülse de öneri ${waterTxt} istiyor. Hedef su tasarrufu olduğu için bu sonuç güçlü kabul edilmez.`,note:`${effTxt}. Ürün havuzu veya sulama yöntemi yeniden değerlendirilmelidir.`}; return {title:'Karar Gerekçesi (Su verimliliği hedefi)',msg:`Öneri hem ${waterTxt} istiyor hem de ${profitTxt} yaratıyor. Su kısıtı açısından savunulamaz bir kombinasyon oluşmuştur.`,note:`${effTxt}. Bu tip sonuçların elenmesi gerekir.`}; } if(o==='maks_kar'){ if(betterProfit && betterWater) return {title:'Karar Gerekçesi (Kâr hedefi)',msg:`Öneri ${profitTxt} sağlarken aynı anda ${waterTxt} kullanıyor. Gelir artışı, daha yüksek su baskısı oluşturmadan elde edilmiş.`,note:`${effTxt}. Kurum açısından öncelikli, çiftçi açısından uygulanabilir bir sonuçtur.`}; if(betterProfit && !betterWater) return {title:'Karar Gerekçesi (Kâr hedefi)',msg:`Öneri ${profitTxt} sağlıyor; ancak bunun karşılığında ${waterTxt} talep ediyor. Kâr hedefi açısından makul olabilir fakat su daralırsa risk artar.`,note:`${effTxt}. Bu nedenle yöntem önerisi ve kritik ay yönetimi birlikte değerlendirilmelidir.`}; if(!betterProfit && betterWater) return {title:'Karar Gerekçesi (Kâr hedefi)',msg:`Öneri ${waterTxt} kullanıyor fakat ${profitTxt} oluşuyor. Kâr hedefi seçiliyken bu sonuç zayıf kalır; gelir tarafında daha güçlü alternatif aranmalıdır.`,note:`${effTxt}. Su tasarrufu iyi olsa da amaç çiftçi gelirini korumaktır.`}; return {title:'Karar Gerekçesi (Kâr hedefi)',msg:`Öneri hem ${waterTxt} talep ediyor hem de ${profitTxt} oluşturuyor. Kâr hedefiyle bile savunulamayacak bir tablo var.`,note:`${effTxt}. Parametreler veya ürün havuzu tekrar gözden geçirilmelidir.`}; } return {title:'Karar Gerekçesi (Su etkin kullanım)',msg:`Öneri için temel farklar: ${waterTxt}, ${profitTxt}.`,note:`${effTxt}. Nihai yorum su, kâr ve uygulanabilirlik birlikte değerlendirilerek yapılmalıdır.`}; }

function summarizePlanShift(currentRows, recRows, seasonSource, objectiveKey){
  const curMain = Array.isArray(currentRows)&&currentRows.length ? [...currentRows].sort((a,b)=>safeNum(b.area)-safeNum(a.area))[0] : null;
  const recMain = Array.isArray(recRows)&&recRows.length ? [...recRows].sort((a,b)=>safeNum(b.area)-safeNum(a.area))[0] : null;
  if(!curMain || !recMain) return 'Desen farkı, seçilen hedefe göre hesaplanan su-kâr puanından kaynaklanır.';
  const sameMain = normCropName(curMain.name) === normCropName(recMain.name);
  const orchardLike = !!(curMain && isPerennialCropName(curMain.name));
  const obj = getScenarioDisplayMeta(objectiveKey).label;
  if((seasonSource||'s1') === 's1'){
    if(orchardLike && !sameMain) return `S1 tek ürün dönüşüm modunda kurulu bahçe ürünü (${prettyCropName(curMain.name)}) yerine ${prettyCropName(recMain.name)} tek ürün alternatifi hesaplanmıştır; bu sonuç uygulamada tesis dönüşümü ve uzman onayı gerektirir.`;
    if(orchardLike) return 'Çok yıllık/bahçe parsellerinde ana ürün korunur; fark sulama yöntemi, kota ve zamanlama üzerinden hesaplanır.';
    if(sameMain) return `${prettyCropName(curMain.name)} tekrar önerildi çünkü veri setindeki uygun adaylar içinde seçili hedef (${obj}) altında daha az su veya daha yüksek net kâr sağlayan alternatif eşik değeri aşamadı. Bu durum raporda "mevcut ürün korunuyor" diye açıklanır, gizlenmez.`;
    return `S1 tek ürün modunda sistem ${prettyCropName(curMain.name)} yerine ${prettyCropName(recMain.name)} seçmiştir; karar su kotası, TL/m³, dönem-gün sayısı, pik ay ve parsel/toprak uygunluğunun birlikte puanlanmasıyla verilir.`;
  }
  const recSecond = Array.isArray(recRows) ? recRows.find(r=>normCropName(r.name)!==normCropName(recMain.name)) : null;
  if(recSecond) return `S2 deseninde ${prettyCropName(recMain.name)} ve ${prettyCropName(recSecond.name)} ayni yillik planin parcalari olarak okunur; ekim penceresi cakisirsa alan yuzdesi, farkli donemlerdeyse ardisik sezon mantigi uygulanir.`;
  return sameMain ? 'S2 modunda ikinci urun uygun aday kosullarini gecmedigi icin ana urun korunmustur; sebep kota, donem cakismasi, familya/rotasyon ve toprak uygunlugu kisitlaridir.' : 'S2 modunda yazlik-kislik veya ardisik sezon kombinasyonlari denenir; secilen desen hedef fonksiyonunda en iyi puana yaklasmistir.';
}

function renderAllScenarioSummaries(){
  // seçili kapsam / 5 köy parselleri toplamı (gerçek hesap: her parseldeki tablo toplamlarından)
  // UI seçimleri değişmiş olsa bile, yeni optimizasyon bitene kadar son geçerli sonucu göster.
  const viewCtx = (
    (!STATE.isOptimizing && canShowOptimizedForCurrentSelection())
      ? { scenario: selectedScenario, algo: selectedAlgo }
      : (lastOptimizeContext ? { scenario: lastOptimizeContext.scenario, algo: lastOptimizeContext.algo } : { scenario: selectedScenario, algo: selectedAlgo })
  );

  // --- v73: Kapsamı doğru hesapla (parsel vs havza) ---
  // Not: Kullanıcı tek parsel seçtiğinde seçili kapsam / 5 köy parselleri toplamını göstermek, "0" ve aşırı büyük
  // değerler üreterek yanıltıyordu. Artık metrikler seçili kapsama göre hesaplanır.
  function totalsForScope(scenarioKey, algoKey){
    if(selectedParcelId === '__ALL__'){
      return totalsAllParcels(scenarioKey, algoKey);
    }
    const pid = String(selectedParcelId || '').trim();
    const p = parcelData.find(x=>String(x.id)===pid);
    if(!p){
      return { water:0, profit:0, eff:0, budget:0, feasible:true, iterations:0 };
    }
    if(String(scenarioKey).toLowerCase() === 'mevcut'){
      const cur = runOptimization(p, 'mevcut', algoKey);
      const t = cur?.totals || { water:0, profit:0 };
      return { ...t, budget: computeGlobalBudgetM3(), feasible:true, iterations:0, eff: (t.water>0 ? (t.profit/t.water) : 0) };
    }
    // Senaryo: küresel su bütçesi uygulanmış havza planından parsel payını çek
    const basin = computeBasinPlan(scenarioKey, algoKey);
    const pt = basin?.plan?.[pid]?.totals || { water:0, profit:0, area: safeNum(p.area_da,0) };
    return { ...pt, budget: basin.budget, feasible: basin.feasible, iterations: basin.iterations, eff: (pt.water>0 ? (pt.profit/pt.water) : 0) };
  }

  const base = totalsForScope('mevcut', viewCtx.algo);
  const scen = totalsForScope(viewCtx.scenario, viewCtx.algo);
  const basinBase = totalsAllParcels('mevcut', viewCtx.algo);
  const basinScen = totalsAllParcels(viewCtx.scenario, viewCtx.algo);

  // Küresel su bütçesi rozetleri
  const globalBudgetBadge = document.getElementById("globalBudgetBadge");
  const globalBudgetStatus = document.getElementById("globalBudgetStatus");
  const globalBudgetView = basinScen || scen;
  if(globalBudgetBadge){
    globalBudgetBadge.textContent = `Küresel su bütçesi: ${Math.round(globalBudgetView.budget).toLocaleString("tr-TR")} m³`;
  }
  if(globalBudgetStatus){
    const over = globalBudgetView.water - globalBudgetView.budget;
    if(globalBudgetView.feasible === false){
      globalBudgetStatus.textContent = `bütçe durumu: UYGUN DEĞİL (aşım: ${Math.round(Math.max(0,over)).toLocaleString("tr-TR")} m³)`;
      globalBudgetStatus.className = "badge badge-warn";
    } else if(over <= 0){
      globalBudgetStatus.textContent = `bütçe durumu: UYGUN (${Math.round(Math.abs(over)).toLocaleString("tr-TR")} m³ boş)`;
      globalBudgetStatus.className = "badge badge-ok";
    } else {
      globalBudgetStatus.textContent = `bütçe durumu: AŞIM (${Math.round(over).toLocaleString("tr-TR")} m³)`;
      globalBudgetStatus.className = "badge badge-warn";
    }
  }

  const fmt = (v) => Math.round(v).toLocaleString("tr-TR");
  const baseEff = safeNum(base.eff, (base.water>0 ? (base.profit/base.water) : 0));
  const scenEff = safeNum(scen.eff, (scen.water>0 ? (scen.profit/scen.water) : 0));
  const fmtEff = (v)=>{
    if(!isFinite(v)) return "0";
    if(v < 0) return v.toFixed(2);
    if(v < 1) return v.toFixed(3);
    return v.toFixed(1);
  };

  // Başlık: kapsamı kullanıcıya net göster
  const titleEl = document.getElementById('metricsTitle');
  if(titleEl){
    titleEl.textContent = metricsTitleForCurrentRole(selectedParcelId);
    if(selectedParcelId !== '__ALL__' && STATE.currentUser?.role !== 'farmer'){
      titleEl.textContent = `Parsel Karar Özeti (${selectedParcelId})`;
    }
  }
  const activeObjectiveBadge = document.getElementById('activeObjectiveBadge');
  if(activeObjectiveBadge){
    const objectiveMeta = getScenarioDisplayMeta(viewCtx.scenario);
    activeObjectiveBadge.textContent = `Aktif hedef: ${objectiveMeta.label}`;
    activeObjectiveBadge.className = 'badge ' + (objectiveMeta.key === 'maks_kar' ? 'badge-profit' : (objectiveMeta.key === 'su_tasarruf' ? 'badge-info' : (objectiveMeta.key === 'balanced' ? 'badge-ok' : 'badge-info')));
  }

  const parcelSummaryTitle = document.getElementById("parcelSummaryTitle");
  const parcelSummaryNote = document.getElementById("parcelSummaryNote");
  if(parcelSummaryTitle){
    parcelSummaryTitle.textContent = (selectedParcelId === '__ALL__') ? 'Seçili Kapsam Özeti' : `Parsel Bazlı Özet (${selectedParcelId})`;
  }
  if(parcelSummaryTitle && selectedParcelId !== '__ALL__'){
    parcelSummaryTitle.textContent = `Parsel Su-Kâr Metrikleri (${selectedParcelId})`;
  }
  if(parcelSummaryNote){
    parcelSummaryNote.textContent = (selectedParcelId === '__ALL__')
      ? 'Şu anda tüm görünür parseller birlikte gösteriliyor.'
      : 'Aşağıdaki kartlar yalnızca seçili parselin değerlerini gösterir.';
  }

  const basinSummaryBlock = document.getElementById("basinSummaryBlock");
  if(basinSummaryBlock){
    basinSummaryBlock.style.display = (selectedParcelId === '__ALL__') ? '' : 'none';
  }
  const basinSummaryNote = document.getElementById("basinSummaryNote");
  if(basinSummaryNote){
    const remaining = safeNum(basinScen.budget, 0) - safeNum(basinScen.water, 0);
    basinSummaryNote.textContent = `Akkaya Sulama Alanı toplamı • ${remaining >= 0 ? 'Boş bütçe' : 'Aşım'}: ${fmt(Math.abs(remaining))} m³`;
  }

  const bWaterCurrent = document.getElementById("bWaterCurrent");
  const bWaterScenario = document.getElementById("bWaterScenario");
  const bProfitCurrent = document.getElementById("bProfitCurrent");
  const bProfitScenario = document.getElementById("bProfitScenario");
  const bEffCurrent = document.getElementById("bEffCurrent");
  const bEffScenario = document.getElementById("bEffScenario");

  const mWaterCurrent = document.getElementById("mWaterCurrent");
  const mWaterScenario = document.getElementById("mWaterScenario");
  const mProfitCurrent = document.getElementById("mProfitCurrent");
  const mProfitScenario = document.getElementById("mProfitScenario");
  const mEffCurrent = document.getElementById("mEffCurrent");
  const mEffScenario = document.getElementById("mEffScenario");

  if(bWaterCurrent) bWaterCurrent.textContent = fmt(basinBase.water);
  if(bWaterScenario) bWaterScenario.textContent = fmt(basinScen.water);
  if(bProfitCurrent) bProfitCurrent.textContent = fmt(basinBase.profit);
  if(bProfitScenario) bProfitScenario.textContent = fmt(basinScen.profit);
  if(bEffCurrent) bEffCurrent.textContent = fmtEff(safeNum(basinBase.eff, (basinBase.water>0 ? (basinBase.profit/basinBase.water) : 0)));
  if(bEffScenario) bEffScenario.textContent = fmtEff(safeNum(basinScen.eff, (basinScen.water>0 ? (basinScen.profit/basinScen.water) : 0)));

  if(mWaterCurrent) mWaterCurrent.textContent = fmt(base.water);
  if(mWaterScenario) mWaterScenario.textContent = fmt(scen.water);
  if(mProfitCurrent) mProfitCurrent.textContent = fmt(base.profit);
  if(mProfitScenario) mProfitScenario.textContent = fmt(scen.profit);
  if(mEffCurrent) mEffCurrent.textContent = fmtEff(baseEff);
  if(mEffScenario) mEffScenario.textContent = fmtEff(scenEff);

  const basinWaterDiffEl = document.getElementById("bWaterDiff");
  const basinProfitDiffEl = document.getElementById("bProfitDiff");
  const basinEffDiffEl = document.getElementById("bEffDiff");
  const waterDiffEl = document.getElementById("mWaterDiff");
  const profitDiffEl = document.getElementById("mProfitDiff");
  const effDiffEl = document.getElementById("mEffDiff");

  const fmtSigned = (n)=>{
    const s = (n>=0?'+':'');
    return s + Math.round(n).toLocaleString("tr-TR");
  };

  const dWater = scen.water - base.water;
  const dProfit = scen.profit - base.profit;
  const dEff = scenEff - baseEff;
  const basinBaseEff = safeNum(basinBase.eff, (basinBase.water>0 ? (basinBase.profit/basinBase.water) : 0));
  const basinScenEff = safeNum(basinScen.eff, (basinScen.water>0 ? (basinScen.profit/basinScen.water) : 0));
  const basinDWater = basinScen.water - basinBase.water;
  const basinDProfit = basinScen.profit - basinBase.profit;
  const basinDEff = basinScenEff - basinBaseEff;

  // Yüzde gösterimi sadece anlamlı olduğunda (payda > 0) kullan
  const pct = (num, den)=> (den>0 ? (num/den)*100 : NaN);
  const fmtPct = (x)=> `${x>=0?'+':''}${x.toFixed(1)} %`;

  // Hedefe göre (su tasarrufu / maks kâr) doğru yönde mi? rozetle
  const objective = String(viewCtx.scenario || '').toLowerCase();
  const waterIsGood = (objective === 'su_tasarruf') ? (dWater <= 0) : true;
  const basinWaterIsGood = (objective === 'su_tasarruf') ? (basinDWater <= 0) : true;

  if(basinWaterDiffEl){
    const pw = pct(basinDWater, basinBase.water);
    basinWaterDiffEl.textContent = isFinite(pw) ? fmtPct(pw) : (`Δ ${fmtSigned(basinDWater)} m³`);
    basinWaterDiffEl.className = 'badge ' + (basinWaterIsGood ? 'badge-ok' : 'badge-warn');
  }
  if(basinProfitDiffEl){
    const pp = pct(basinDProfit, basinBase.profit);
    basinProfitDiffEl.textContent = isFinite(pp) ? fmtPct(pp) : (`Δ ${fmtSigned(basinDProfit)} TL`);
  }
  if(basinEffDiffEl){
    const pe = pct(basinDEff, basinBaseEff);
    basinEffDiffEl.textContent = isFinite(pe) ? fmtPct(pe) : (`Δ ${basinDEff>=0?'+':''}${basinDEff.toFixed(1)} TL/m³`);
  }

  if(waterDiffEl){
    const pw = pct(dWater, base.water);
    waterDiffEl.textContent = isFinite(pw) ? fmtPct(pw) : (`Δ ${fmtSigned(dWater)} m³`);
    waterDiffEl.className = 'badge ' + (waterIsGood ? 'badge-ok' : 'badge-warn');
  }
  if(profitDiffEl){
    const pp = pct(dProfit, base.profit);
    profitDiffEl.textContent = isFinite(pp) ? fmtPct(pp) : (`Δ ${fmtSigned(dProfit)} TL`);
  }
  if(effDiffEl){
    const pe = pct(dEff, baseEff);
    effDiffEl.textContent = isFinite(pe) ? fmtPct(pe) : (`Δ ${dEff>=0?'+':''}${dEff.toFixed(1)} TL/m³`);
  }

  // Seçim değiştiğinde özetler canlı hesaplanır; bu rozet yalnız bütçe durumunu göstermeli.

  // v72: Çalışma meta bilgisi + karar gerekçesi
  try{
    const metaEl = document.getElementById('runMetaBox');
    const riskBox = document.getElementById('riskSeparationBox');
    const ratEl = document.getElementById('decisionRationale');
    const key = basinCacheKey(viewCtx.scenario, viewCtx.algo);
    const cached = basinPlanCache[key] || null;
    const rp = (cached && cached.meta && (cached.meta.run_params || cached.meta.runParams)) ? (cached.meta.run_params || cached.meta.runParams) : null;
    const seed = (rp && (rp.seed !== undefined)) ? rp.seed : (cached && cached.meta ? cached.meta.seed : 42);
    const year = (cached && cached.year) ? cached.year : (STATE.selectedWaterYear || '-');
    const scope = (selectedParcelId === '__ALL__') ? 'Havza (tüm parseller)' : `Parsel ${selectedParcelId}`;
    const algoName2 = viewCtx.algo === 'ga' ? 'GA' : (viewCtx.algo === 'abc' ? 'ABC' : 'ACO');

    if(metaEl){
      if(!cached){
        metaEl.style.display = 'none';
        metaEl.innerHTML = '';
      }else{
        metaEl.style.display = 'block';

        const DEFAULT_RUN_PARAMS = {
          ga:  { stop: 'İyileşme durunca', iterations: 120, generations: 120, pop: 60 },
          abc: { stop: 'İyileşme durunca', iterations: 200, colony: 40 },
          aco: { stop: 'İyileşme durunca', iterations: 200, ants: 40 }
        };

        const def = DEFAULT_RUN_PARAMS[viewCtx.algo] || DEFAULT_RUN_PARAMS.ga;
        const iterVal = (rp && (rp.iterations ?? rp.cycles ?? rp.maxIter)) ?? def.iterations;
        const genVal  = (rp && (rp.generations ?? rp.maxGen)) ?? def.generations;
        const popVal  = (rp && (rp.popSize ?? rp.population ?? rp.nPop)) ?? def.pop;
        const antsVal = (rp && (rp.ants ?? rp.antCount)) ?? def.ants;
        const colonyVal = (rp && (rp.colonySize ?? rp.beeCount ?? rp.bees)) ?? def.colony;
        const stopVal = (rp && (rp.stopEarly !== undefined ? (rp.stopEarly ? 'İyileşme durunca' : 'Sabit iterasyon') : null)) || def.stop;
        const policy = cached?.optimizationRunPolicy || cached?.backendDecisionPackage?.optimization_run_policy || cached?.backendResult?.optimization_run_policy || null;
        const completedRuns = Number(policy?.completed_runs || 0);
        const requestedRuns = Number(policy?.requested_runs || policy?.selected_repeat_count || 0);
        const policyPartial = String(policy?.completion_status_kind || '').toLowerCase() === 'partial' || (requestedRuns > 0 && completedRuns < requestedRuns);
        const policyText = policy && requestedRuns > 0
          ? (policyPartial
            ? `Kısmi optimizasyon: ${String(policy.algorithm || algoName2)} algoritması ${completedRuns}/${requestedRuns} koşu tamamladı; sonuç ön değerlendirme niteliğindedir.`
            : `Optimizasyon tamamlandı: ${String(policy.algorithm || algoName2)} algoritması ${completedRuns}/${requestedRuns} bağımsız koşu ile çalıştırıldı. Ana öneri, uygulanabilir çözümler arasından hedef fonksiyonuna göre seçildi.`)
          : '';

        // Seed'i adil karşılaştırma rozetinde göster (kullanıcı "seed=..." bilgisini arada kaybetmesin)
        const reproducible = `Rastgelelik sabit (Seed: ${seed})`;
        const objectiveMeta = getScenarioDisplayMeta(viewCtx.scenario);

        const kv = [];
        kv.push({k:'Durdurma', v: stopVal});

        // Algoritma bazlı, anlamlı parametreleri göster; "-" satırı üretme
        if(viewCtx.algo === 'ga'){
          kv.push({k:'Nesil', v: genVal});
          kv.push({k:'Popülasyon', v: popVal});
          kv.push({k:'Iterasyon', v: iterVal});
        }else if(viewCtx.algo === 'abc'){
          kv.push({k:'Iterasyon', v: iterVal});
          kv.push({k:'Koloni (arı) sayısı', v: colonyVal});
        }else if(viewCtx.algo === 'aco'){
          kv.push({k:'Iterasyon', v: iterVal});
          kv.push({k:'Karınca sayısı', v: antsVal});
        }else{
          kv.push({k:'Iterasyon', v: iterVal});
        }

        metaEl.innerHTML = `
          <div class="runmeta-title">Koşullar (Adil Karşılaştırma)</div>
          <div class="runmeta-tags">
            <span class="runmeta-tag"><span class="runmeta-ic">&#128205;</span><b>${scope}</b></span>
            <span class="runmeta-tag"><span class="runmeta-ic">&#129302;</span><b>${algoName2}</b></span>
            <span class="runmeta-tag"><span class="runmeta-ic">${objectiveMeta.icon}</span><b>${objectiveMeta.label}</b></span>
            <span class="runmeta-tag"><span class="runmeta-ic">&#128197;</span><b>${year}</b></span>
            <span class="runmeta-tag"><span class="runmeta-ic">&#9878;&#65039;</span><b>${reproducible}</b></span>
            ${policy && requestedRuns > 0 ? `<span class="runmeta-tag"><span class="runmeta-ic">&#128257;</span><b>${escapeHtml(String(policy.algorithm || algoName2))}: ${completedRuns}/${requestedRuns} koşu</b></span>` : ''}
          </div>
          ${policyText ? `<div class="benchmark-note" style="margin-top:8px;">${escapeHtml(policyText)}</div>` : ''}

          <details class="runmeta-details">
            <summary>Optimizasyon parametreleri</summary>
            <div class="runmeta-kv">
              ${kv.map(x=>`<div><span class="k">${escapeHtml(String(x.k))}</span><span class="v">${escapeHtml(String(x.v))}</span></div>`).join('')}
            </div>
            <div class="small muted" style="margin-top:8px;">Not: Seed, rastgele başlangıcı sabitleyerek aynı koşullarda aynı sonuçların üretilebilmesini sağlar.</div>
          </details>
        `;
      }
    }

    if(riskBox){
      if(!cached){
        riskBox.style.display = 'none';
        riskBox.innerHTML = '';
      }else{
        const labels = cached?.diagnostics?.risk_labels || {};
        const droughtFromState = (() => {
          const r = clamp(STATE.droughtRisk ?? 0, 0, 1);
          if(r >= 0.66) return 'Yüksek';
          if(r >= 0.33) return 'Orta';
          return 'Düşük';
        })();
        const planRisk = labels.plan_feasibility_risk || (cached?.selectedPlan?.feasible === false ? 'Yüksek' : 'Düşük');
        const quotaStatus = labels.parcel_quota_status || (cached?.selectedPlan?.feasible === false ? 'Kota/uygunluk riski var' : 'Uygun');
        const calendarStatus = labels.calendar_rotation_status || ((cached?.selectedPlan?.warnings || []).some(w=>/takvim|rotasyon|desen/i.test(String(w))) ? 'Kontrol gerekli' : 'Uygun');
        const damRisk = labels.dam_drought_risk && labels.dam_drought_risk !== 'Veri yok' ? labels.dam_drought_risk : droughtFromState;
        const chip = (title, value, kind)=>{
          const cls = /yüksek|asiyor|aş|risk|kontrol|uygun değil/i.test(String(value)) ? 'badge-warn' : (/orta/i.test(String(value)) ? 'badge-info' : 'badge-ok');
          return `<span class="runmeta-tag"><span class="runmeta-ic">${kind}</span><b>${escapeHtml(title)}:</b> <span class="badge ${cls}">${escapeHtml(String(value || '-'))}</span></span>`;
        };
        riskBox.style.display = 'block';
        riskBox.innerHTML = `
          <div class="runmeta-title">Risk ve kota etiketleri ayrı okunur</div>
          <div class="runmeta-tags">
            ${chip('Baraj / kuraklık riski', damRisk, '&#127754;')}
            ${chip('Plan uygulanabilirlik riski', planRisk, '&#9878;&#65039;')}
            ${chip('Parsel su kotası durumu', quotaStatus, '&#128167;')}
            ${chip('Takvim / rotasyon uygunluğu', calendarStatus, '&#128197;')}
          </div>
          <div class="small muted" style="margin-top:8px;">Baraj riski hidrolojik bağlamdır; plan riski, kota ve takvim uygunluğu backend karar paketinden ayrı izlenir.</div>
        `;
      }
    }

    if(ratEl){
      ratEl.style.display = cached ? 'block' : 'none';
      if(!cached){ ratEl.innerHTML = ''; }
      const objectiveMeta = getScenarioDisplayMeta(viewCtx.scenario);
      const rationale = buildDecisionRationaleByObjective(objectiveMeta.key, dWater, dProfit, dEff);
      // v73: Aynı sayfada zaten sayısal KPI kartları var. Burada tekrar etmek yerine
      // sadece "neden" kısmını kısa ve anlaşılır şekilde söylüyoruz.
      ratEl.innerHTML = `
        <div class="rationale-title">${rationale.title}</div>
        <div class="rationale-target"><span class="runmeta-tag"><span class="runmeta-ic">${objectiveMeta.icon}</span><b>Aktif hedef: ${objectiveMeta.label}</b></span></div>
        <div class="rationale-text">${rationale.msg}</div>
        <div class="small muted" style="margin-top:6px;">${rationale.note}</div>
      `;
    }
  }catch(_e){ /* noop */ }

  // Bar chart güncelle
  // ÖNEMLİ: Grafikler, üstteki metrik kartlarıyla AYNI kapsamı (seçili parsel veya havza)
  // ve AYNI birimleri (m³ / TL) kullanmalı. Aksi hâlde kullanıcıya tutarsız görünür.
  const chartColors = ['rgba(73,126,230,.72)','rgba(40,191,170,.72)','rgba(255,175,91,.78)','rgba(126,92,245,.72)'];
  const cachedForCharts = basinPlanCache[basinCacheKey(viewCtx.scenario, viewCtx.algo)] || null;
  const backendWaterChart = cachedForCharts?.charts?.target_mode_water || null;
  const backendProfitChart = cachedForCharts?.charts?.target_mode_profit || null;
  const rowsFromBackend = (chart)=> Array.isArray(chart?.rows) ? chart.rows.filter(r=>r && String(r.label||'').trim()) : [];
  const setChartTitle = (chartObj, fallback)=>{
    try{
      const canvas = chartObj?.canvas || null;
      const title = canvas?.closest?.('.small-chart-card')?.querySelector?.('.card-subtitle');
      if(title) title.textContent = fallback;
    }catch(_e){}
  };
  const waterRows = rowsFromBackend(backendWaterChart);
  const profitRows = rowsFromBackend(backendProfitChart);

  if(waterChart){
    const labels = waterRows.length ? waterRows.map(r=>backendChartLabelTr(r.label)) : [];
    waterChart.data.labels = labels;
    waterChart.data.datasets[0].data = waterRows.length ? waterRows.map(r=>safeNum(r.value,0)) : [];
    waterChart.data.datasets[0].backgroundColor = labels.map((_,i)=>chartColors[i % chartColors.length]);
    waterChart.data.datasets[0].borderColor = waterChart.data.datasets[0].backgroundColor.map(c=>c.replace('.72','1').replace('.78','1'));
    setChartTitle(waterChart, backendWaterChart?.title || 'Hedef Modlarına Göre Toplam Su Kullanımı');
    waterChart.update();
  }
  if(profitChart){
    // Negatif net kârı da gösterebilmek için kırpma YOK.
    const labels = profitRows.length ? profitRows.map(r=>backendChartLabelTr(r.label)) : [];
    profitChart.data.labels = labels;
    profitChart.data.datasets[0].data = profitRows.length ? profitRows.map(r=>safeNum(r.value,0)) : [];
    profitChart.data.datasets[0].backgroundColor = labels.map((_,i)=>chartColors[i % chartColors.length]);
    profitChart.data.datasets[0].borderColor = profitChart.data.datasets[0].backgroundColor.map(c=>c.replace('.72','1').replace('.78','1'));
    setChartTitle(profitChart, backendProfitChart?.title || 'Hedef Modlarına Göre Toplam Net Kâr');
    profitChart.update();
  }
}

