function normalizeScenarioKey(v){
  const raw = String(v ?? "").trim().toLowerCase();
  if(!raw) return "";
  // Turkish-specific normalization
  const trMap = { "ı":"i", "ğ":"g", "ü":"u", "ş":"s", "ö":"o", "ç":"c" };
  const norm = raw.replace(/[ığüşöç]/g, ch=>trMap[ch]||ch)
                  .replace(/\s+/g," ")
                  .replace(/[-\s]+/g,"_");
  // Map common labels to canonical keys used in charts
  if(norm.includes("mevcut")) return "mevcut";
  if(norm.includes("iyi") && norm.includes("adapt")) return "iyi_adaptasyon";
  if(norm.includes("kotu") && norm.includes("kurak")) return "kotu_kuraklik";
  return norm;
}

// Chart.js grafikleri
let waterChart, profitChart; // areaChart removed (replaced by product cards)
let districtAreaChart, districtIrrigChart, provinceShareChart;
let storageHistoryChart, storageScenarioChart;
let benchmarkProfitChart, benchmarkWaterChart, benchmarkEffChart, benchmarkRuntimeChart;

function makeVerticalBarGradient(ctx,c1='rgba(82,156,255,.92)',c2='rgba(157,205,255,.55)'){ const g=ctx.createLinearGradient(0,0,0,220); g.addColorStop(0,c1); g.addColorStop(1,c2); return g; }

function initCharts() {
  const waterCtx = document.getElementById("waterChart").getContext("2d");
  const profitCtx = document.getElementById("profitChart").getContext("2d");

  waterChart = new Chart(waterCtx, {
    type: "bar",
    data: {
      labels: ["Mevcut", "Su tasarrufu", "Kâr odaklı", "Su etkin kullanım"],
      datasets: [
        {
          label: "Su kullanımı (m³)",
          data: [0, 0, 0, 0],
          backgroundColor: [
            makeVerticalBarGradient(waterCtx,'rgba(68,138,255,.95)','rgba(149,208,255,.55)'),
            makeVerticalBarGradient(waterCtx,'rgba(24,184,166,.92)','rgba(167,240,233,.55)'),
            makeVerticalBarGradient(waterCtx,'rgba(255,175,91,.92)','rgba(255,224,178,.55)'),
            makeVerticalBarGradient(waterCtx,'rgba(126,92,245,.92)','rgba(196,181,253,.55)')
          ],
          borderRadius: 10, borderSkipped: false, maxBarThickness: 58,
        },
      ],
    },
    options: chartBarOptions("m³"),
  });

  profitChart = new Chart(profitCtx, {
    type: "bar",
    data: {
      labels: ["Mevcut", "Su tasarrufu", "Kâr odaklı", "Su etkin kullanım"],
      datasets: [
        {
          label: "Net kâr (TL)",
          data: [0, 0, 0, 0],
          backgroundColor: [
            makeVerticalBarGradient(profitCtx,'rgba(76,110,245,.95)','rgba(167,184,255,.55)'),
            makeVerticalBarGradient(profitCtx,'rgba(24,184,166,.92)','rgba(167,240,233,.55)'),
            makeVerticalBarGradient(profitCtx,'rgba(255,159,67,.92)','rgba(255,214,163,.55)'),
            makeVerticalBarGradient(profitCtx,'rgba(126,92,245,.92)','rgba(196,181,253,.55)')
          ],
          borderRadius: 10, borderSkipped: false, maxBarThickness: 58,
        },
      ],
    },
    options: chartBarOptions("TL"),
  });

  // areaChart removed (donut yerine ürün kartları)

  // İlçe / köy düzeyi grafikler (seçili kapsamdan dinamik hesap)
  const dAreaCanvas = document.getElementById("districtAreaChart");
  const dIrrigCanvas = document.getElementById("districtIrrigChart");
  const provCanvas = document.getElementById("provinceShareChart");
  const dAreaCtx = dAreaCanvas ? dAreaCanvas.getContext("2d") : null;
  const dIrrigCtx = dIrrigCanvas ? dIrrigCanvas.getContext("2d") : null;
  const provCtx = provCanvas ? provCanvas.getContext("2d") : null;

  const districtBarOptions = (yLabel)=>({
    responsive:true,
    maintainAspectRatio:false,
    interaction:{ mode:'index', intersect:false },
    plugins:{ legend:{ display:true, position:'bottom', labels:{ boxWidth:10, usePointStyle:true, font:{ size:11, weight:'600' } } } },
    scales:{
      x:{ ticks:{ font:{ size:11, weight:'600' }, color:'#5b6474' }, grid:{ display:false } },
      y:{ beginAtZero:true, ticks:{ font:{ size:10 }, color:'#7a8496' }, border:{ display:false }, grid:{ color:'rgba(210,223,246,.8)' }, title:{ display:true, text:yLabel, font:{ size:10, weight:'600' }, color:'#60708a' } }
    }
  });

  if(dAreaCtx){
    districtAreaChart = new Chart(dAreaCtx, {
      type: "bar",
      data: { labels: [], datasets: [
        { label: "Toplam alan (da)", data: [], backgroundColor: 'rgba(59,130,246,.82)', borderRadius: 12, borderSkipped:false }
      ] },
      options: Object.assign(districtBarOptions('da'), { indexAxis:'y' })
    });
  }

  if(dIrrigCtx){
    districtIrrigChart = new Chart(dIrrigCtx, {
      type: "bar",
      data: { labels: [], datasets: [
        { label: "Mevcut su (m³)", data: [], backgroundColor: 'rgba(125,211,252,.9)', borderRadius: 10, borderSkipped:false },
        { label: "Önerilen su (m³)", data: [], backgroundColor: 'rgba(20,184,166,.85)', borderRadius: 10, borderSkipped:false }
      ] },
      options: districtBarOptions('m³')
    });
  }

  if(provCtx){
    provinceShareChart = new Chart(provCtx, {
      type: "bar",
      data: { labels: [], datasets: [
        { label: "Mevcut net kâr (TL)", data: [], backgroundColor: 'rgba(147,197,253,.9)', borderRadius:10, borderSkipped:false },
        { label: "Önerilen net kâr (TL)", data: [], backgroundColor: 'rgba(249,115,22,.82)', borderRadius:10, borderSkipped:false }
      ] },
      options: districtBarOptions('TL')
    });
  }

  // Su bütçesi grafikleri
  const histCanvas = document.getElementById("storageHistoryChart");
  const scenCanvas = document.getElementById("storageScenarioChart");
  const histCtx = histCanvas ? histCanvas.getContext("2d") : null;
  const scenCtx = scenCanvas ? scenCanvas.getContext("2d") : null;

  // 2000-2025: veri paketinden (clean CSV)
  const histYears = (STATE.barajSeries||[]).map(r=>r.yil);
  const histSeries = (STATE.barajSeries||[]).map(r=>r.doluluk);
  // New (optional): average & minimum fullness (%) from updated table
  const histAvg = (STATE.barajSeries||[]).map(r=>isFinite(+r.ortalama_pct) ? +r.ortalama_pct : null);
  const histMin = (STATE.barajSeries||[]).map(r=>isFinite(+r.min_pct) ? +r.min_pct : null);
  const hasAvg = histAvg.some(v=>v!==null);
  const hasMin = histMin.some(v=>v!==null);


  // --- Görsel vurgu: kritik eşik çizgileri ve min/max etiketleri (Chart.js plugin) ---
  const thresholdLinesPlugin = {
    id: "thresholdLinesPlugin",
    afterDraw(chart, args, pluginOptions){
      const opts = pluginOptions || {};
      const ys = Array.isArray(opts.levels) ? opts.levels : [10, 20];
      const yScale = chart.scales.y;
      const xScale = chart.scales.x;
      if(!yScale || !xScale) return;
      const ctx = chart.ctx;
      ctx.save();
      ctx.setLineDash([6, 4]);
      ctx.lineWidth = 1;
      ctx.globalAlpha = 0.6;
      for(const v of ys){
        if(!isFinite(v)) continue;
        const y = yScale.getPixelForValue(v);
        ctx.beginPath();
        ctx.moveTo(xScale.left, y);
        ctx.lineTo(xScale.right, y);
        ctx.stroke();
        // label
        ctx.setLineDash([]);
        ctx.globalAlpha = 0.75;
        ctx.font = "12px system-ui, -apple-system, Segoe UI, Roboto, Arial";
        ctx.fillText(`%${v} eşik`, xScale.left + 6, y - 4);
        ctx.setLineDash([6, 4]);
        ctx.globalAlpha = 0.6;
      }
      ctx.restore();
    }
  };

  const extremaLabelsPlugin = {
    id: "extremaLabelsPlugin",
    afterDatasetsDraw(chart, args, pluginOptions){
      const opts = pluginOptions || {};
      const only = Array.isArray(opts.onlyLabels) ? opts.onlyLabels : ["Yıl içi minimum doluluk (%)", "Yıllık ortalama doluluk (%)"];
      const ctx = chart.ctx;
      ctx.save();
      ctx.font = "12px system-ui, -apple-system, Segoe UI, Roboto, Arial";
      ctx.globalAlpha = 0.9;

      chart.data.datasets.forEach((ds, dsIndex)=>{
        if(!ds || !only.includes(ds.label)) return;
        const meta = chart.getDatasetMeta(dsIndex);
        if(!meta || meta.hidden) return;
        const data = (ds.data||[]).map(v => (isFinite(v) ? +v : null));
        const points = meta.data || [];
        if(!data.length || !points.length) return;

        let minVal=Infinity, maxVal=-Infinity, minI=-1, maxI=-1;
        for(let i=0;i<data.length;i++){
          const v=data[i];
          if(v===null) continue;
          if(v<minVal){ minVal=v; minI=i; }
          if(v>maxVal){ maxVal=v; maxI=i; }
        }
        const drawLabel=(i,val,tag)=>{
          if(i<0 || !points[i]) return;
          const pt=points[i];
          const x=pt.x, y=pt.y;
          const text=`${tag}: ${val.toFixed(1)}%`;
          // background pill
          const padX=6, padY=4;
          const w=ctx.measureText(text).width + padX*2;
          const h=18;
          const bx=x - w/2;
          const by=y - h - 8;
          ctx.globalAlpha = 0.85;
          ctx.fillRect(bx, by, w, h);
          ctx.globalAlpha = 0.95;
          ctx.fillStyle = "#fff";
          ctx.fillText(text, bx+padX, by+13);
          ctx.fillStyle = "#000";
        };
        // Use dark overlay background for visibility
        ctx.fillStyle = "rgba(0,0,0,0.55)";
        drawLabel(minI, minVal, "Min");
        drawLabel(maxI, maxVal, "Maks");
      });
      ctx.restore();
    }
  };

  // Not: Bu grafikte değerler hover/tooltip ile zaten görülebildiği için
  // okunurluğu bozabilecek kalıcı yazı/etiket eklentilerini KAPATIYORUZ.
  if(histCtx){
  storageHistoryChart = new Chart(histCtx, {
    type: "line",
    data: {
      labels: histYears.length ? histYears : Array.from({length:25},(_,i)=>2000+i),
      datasets: [
        {
          label: "Tarımsal stres endeksi (0-100)",
          data: histYears.length ? histSeries : Array.from({length:25},(_,i)=>75-i*0.3),
          tension: 0.2,
        },
        ...(hasAvg ? [{
          label: "Yıllık ortalama doluluk (%)",
          data: histYears.length ? histAvg : Array.from({length:25},(_,i)=>60-i*0.2),
          tension: 0.2,
        }] : []),
        ...(hasMin ? [{
          label: "Yıl içi minimum doluluk (%)",
          data: histYears.length ? histMin : Array.from({length:25},(_,i)=>20-i*0.1),
          tension: 0.2,
        }] : []),
      ],
    },
    // Kalıcı yazı/etiket çizimleri kaldırıldı.
    plugins: [],
    options: (() => {
      const o = chartLineOptions("Göstergeler (endeks / %)");
      // Eğer eski ayarlardan plugin opsiyonları kaldıysa temizle
      if(o.plugins){
        delete o.plugins.thresholdLinesPlugin;
        delete o.plugins.extremaLabelsPlugin;
      }
      return o;
    })(),
  });
  }

  // Su bütçesi projeksiyonu kaldırıldı; senaryo grafiği oluşturulmuyor.
  const scenYears = Array.from({ length: 26 }, (_, i) => 2025 + i);

  function buildFallbackProjection(){
    const hs = (STATE.barajSeries||[]).map(r=>+r.doluluk).filter(x=>isFinite(x));
    if(!hs.length) return null;
    const last = hs[hs.length-1];
    const back = hs.length>11 ? hs[hs.length-11] : hs[0];
    const slope = (last - back) / (hs.length>11 ? 10 : Math.max(1, hs.length-1));
    const clamp = (v)=>Math.max(0, Math.min(100, v));
    const years = scenYears;
    const make = (mult, uplift)=>years.map((y,i)=>{
      const v = last + slope*mult*(i+1) + uplift;
      return +clamp(v).toFixed(1);
    });
    return {
      mevcut: make(1.0, 0),
      iyi_adaptasyon: make(0.6, 3),
      kotu_kuraklik: make(1.4, -3),
    };
  }

  const fallbackProj = (!STATE.projSeries || !STATE.projSeries.length) ? buildFallbackProjection() : null;

  const seriesFor = (sen)=>{
    if(fallbackProj && fallbackProj[sen]) return fallbackProj[sen];
    return scenYears.map(y=>{
      const r = (STATE.projSeries||[]).find(x=>x.yil===y && x.senaryo===sen);
      return r ? r.doluluk : null;
    });
  };

  if(scenCtx){
  storageScenarioChart = new Chart(scenCtx, {
    type: "line",
    data: {
      labels: scenYears,
      datasets: [
        { label: "Mevcut gidişat", data: seriesFor("mevcut"), tension: 0.2 },
        { label: "İyi adaptasyon", data: seriesFor("iyi_adaptasyon"), tension: 0.2 },
        { label: "Kötü kuraklık", data: seriesFor("kotu_kuraklik"), tension: 0.2 },
      ],
    },
    options: chartLineOptions("Göstergeler (endeks / %)"),
  });
  }
}

function initBenchmarkCharts() {
  const pEl = document.getElementById("benchmarkProfitChart");
  const wEl = document.getElementById("benchmarkWaterChart");
  const eEl = document.getElementById("benchmarkEffChart");
  const rEl = document.getElementById("benchmarkRuntimeChart");
  if (!pEl || !wEl || !eEl || !rEl) return;

  const pCtx = pEl.getContext("2d");
  const wCtx = wEl.getContext("2d");
  const eCtx = eEl.getContext("2d");
  const rCtx = rEl.getContext("2d");
  const benchmarkPalette = {
    min: 'rgba(203,213,225,.72)',
    mean: 'rgba(37,99,235,.70)',
    max: 'rgba(15,23,42,.72)',
    waterMin: 'rgba(186,230,253,.70)',
    waterMean: 'rgba(20,184,166,.68)',
    waterMax: 'rgba(15,118,110,.70)',
    amber: 'rgba(245,158,11,.68)',
    line: '#2563eb',
    line2: '#0f766e'
  };

  const comboOptions = (yLabel, secondAxisLabel='')=>({
    responsive:true,
    maintainAspectRatio:false,
    interaction:{ mode:'index', intersect:false },
    animation:{ duration:650, easing:'easeOutQuart' },
    plugins:{
      legend:{ display:true, position:'bottom', labels:{ boxWidth:10, usePointStyle:true, font:{ size:11, weight:'600' } } },
      tooltip:{ enabled:true, backgroundColor:'rgba(30,41,59,.94)', titleColor:'#fff', bodyColor:'#fff', padding:10, cornerRadius:10 }
    },
    scales:{
      x:{ ticks:{ font:{ size:11, weight:'600' }, color:'#5b6474' }, grid:{ display:false } },
      y:{ beginAtZero:true, ticks:{ font:{ size:10 }, color:'#7a8496' }, border:{ display:false }, grid:{ color:'rgba(210,223,246,.8)' }, title:{ display:true, text:yLabel, font:{ size:10, weight:'600' }, color:'#60708a' } },
      y1:{ beginAtZero:true, position:'right', display:!!secondAxisLabel, ticks:{ font:{ size:10 }, color:'#7a8496' }, grid:{ drawOnChartArea:false }, title:{ display:!!secondAxisLabel, text:secondAxisLabel, font:{ size:10, weight:'600' }, color:'#60708a' } }
    }
  });

  benchmarkProfitChart = new Chart(pCtx, {
    type: "bar",
    data: { labels: [], datasets: [
      { label:'Min', data:[], backgroundColor:benchmarkPalette.min, borderColor:'rgba(148,163,184,.55)', borderWidth:1, borderRadius:5, borderSkipped:false, barPercentage:.72, categoryPercentage:.66 },
      { label:'Ortalama', data:[], backgroundColor:benchmarkPalette.mean, borderColor:'rgba(37,99,235,.55)', borderWidth:1, borderRadius:5, borderSkipped:false, barPercentage:.72, categoryPercentage:.66 },
      { label:'Maks', data:[], backgroundColor:benchmarkPalette.max, borderColor:'rgba(15,23,42,.35)', borderWidth:1, borderRadius:5, borderSkipped:false, barPercentage:.72, categoryPercentage:.66 }
    ] },
    options: comboOptions('TL')
  });
  benchmarkWaterChart = new Chart(wCtx, {
    type: "bar",
    data: { labels: [], datasets: [
      { label:'Min', data:[], backgroundColor:benchmarkPalette.waterMin, borderColor:'rgba(125,211,252,.5)', borderWidth:1, borderRadius:5, borderSkipped:false, barPercentage:.72, categoryPercentage:.66 },
      { label:'Ortalama', data:[], backgroundColor:benchmarkPalette.waterMean, borderColor:'rgba(20,184,166,.55)', borderWidth:1, borderRadius:5, borderSkipped:false, barPercentage:.72, categoryPercentage:.66 },
      { label:'Maks', data:[], backgroundColor:benchmarkPalette.waterMax, borderColor:'rgba(15,118,110,.5)', borderWidth:1, borderRadius:5, borderSkipped:false, barPercentage:.72, categoryPercentage:.66 }
    ] },
    options: comboOptions('m³')
  });
  benchmarkEffChart = new Chart(eCtx, {
    type: 'bar',
    data: { labels: [], datasets: [
      { label:'TL/m³ (ort)', data:[], backgroundColor:benchmarkPalette.amber, borderColor:'rgba(245,158,11,.55)', borderWidth:1, borderRadius:5, borderSkipped:false, yAxisID:'y', barPercentage:.62, categoryPercentage:.58 },
      { label:'Uygulanabilir çözüm (%)', data:[], type:'line', borderColor:benchmarkPalette.line2, backgroundColor:'rgba(15,118,110,.10)', pointRadius:3, pointHoverRadius:5, tension:.22, yAxisID:'y1' }
    ] },
    options: comboOptions('TL/m³', '%')
  });
  benchmarkRuntimeChart = new Chart(rCtx, {
    type:'bar',
    data:{ labels:[], datasets:[
      { label:'Süre (sn)', data:[], backgroundColor:'rgba(148,163,184,.58)', borderColor:'rgba(100,116,139,.45)', borderWidth:1, borderRadius:5, borderSkipped:false, yAxisID:'y', barPercentage:.62, categoryPercentage:.58 },
      { label:'Desen çeşitliliği', data:[], type:'line', borderColor:benchmarkPalette.line, backgroundColor:'rgba(37,99,235,.10)', pointRadius:3, tension:.22, yAxisID:'y1' }
    ] },
    options: comboOptions('sn', 'adet')
  });
}

function chartBarOptions(yLabel) {
  return {
    responsive:true,
    maintainAspectRatio:false,
    resizeDelay:120,
    interaction:{ mode:'index', intersect:false },
    animation:{ duration:420, easing:'easeOutQuart' },
    layout:{ padding:{ top:4, right:8, bottom:2, left:4 } },
    plugins:{
      legend:{ display:false },
      tooltip:{
        enabled:true,
        backgroundColor:'rgba(30,41,59,.94)',
        titleColor:'#fff',
        bodyColor:'#fff',
        padding:10,
        cornerRadius:10,
        callbacks:{
          label:(ctx)=>{
            const v=(ctx&&ctx.parsed&&typeof ctx.parsed.y!=='undefined')?ctx.parsed.y:(ctx.raw||0);
            const name=(ctx.dataset&&ctx.dataset.label)?ctx.dataset.label:'';
            return (name?(name+': '):'')+fmtNum(v,2);
          }
        }
      }
    },
    scales:{
      x:{
        ticks:{
          autoSkip:false,
          maxRotation:0,
          minRotation:0,
          font:{ size:10, weight:'700' },
          color:'#4b5563',
          callback:function(value){
            const label = this.getLabelForValue(value);
            return String(label || '').replace('Su etkin kullanım','Su etkin').replace('Su tasarrufu','Su tasarruf');
          }
        },
        grid:{ display:false }
      },
      y:{
        beginAtZero:true,
        ticks:{ font:{ size:10 }, color:'#7a8496', callback:(v)=>fmtNum(v,0) },
        border:{ display:false },
        grid:{ color:'rgba(210,223,246,.8)' },
        title:{ display:!!yLabel, text:yLabel, font:{ size:10, weight:'600' }, color:'#60708a' }
      }
    }
  };
}

function chartLineOptions(yLabel) {
  return {
    responsive: true,
    maintainAspectRatio: false,
    interaction: { mode: 'index', intersect: false },
    plugins: {
      legend: { position: "bottom", labels: { font: { size: 11 } } },
      tooltip: {
        enabled: true,
        callbacks: {
          label: (ctx) => {
            const v = (ctx && ctx.parsed && typeof ctx.parsed.y !== 'undefined') ? ctx.parsed.y : (ctx.raw||0);
            const ds = ctx.dataset ? (ctx.dataset.label||'') : '';
            return (ds ? (ds+': ') : '') + fmtNum(v, 2);
          }
        }
      }
    },
    scales: {
      x: { ticks: { font: { size: 9 }, maxRotation: 60, minRotation: 0, autoSkip: true }, grid: { display: false } },
      y: {
        ticks: { font: { size: 9 } },
        grid: { color: "#edf2ff" },
        title: { display: !!yLabel, text: yLabel, font: { size: 10 } },
      },
    },
  };
}

function cropInfoCardHtmlV93(row, idx=0){
  const name = prettyCropName(row?.name || '');
  const meta = cropMetaByName(row?.name || '') || (STATE.cropCatalog || {})[normCropName(row?.name || '')] || {};
  const area = safeNum(row?.area, 0);
  const waterDa = safeNum(row?.waterPerDa, meta.waterPerDa || 0);
  const profitDa = safeNum(row?.profitPerDa, meta.profitPerDa || 0);
  const totalWater = safeNum(row?.totalWater, area * waterDa);
  const totalProfit = safeNum(row?.totalProfit, area * profitDa);
  const rawSeason = String(row?.season || '').trim();
  const season = (!rawSeason || rawSeason === '-' || /desen|pay|oran/i.test(rawSeason) ? '' : rawSeason) || inferSeasonFromCropName(row?.name || '') || 'Dönem verisi yok';
  const days = cropGrowthDays(row?.name || '', season);
  const peak = cropPeakMonthLabel(row?.name || '', season);
  const price = safeNum(meta.price_tl_kg ?? meta.priceTlPerKg, NaN);
  const yieldKg = safeNum(meta.yield_kg_da ?? meta.yieldKgPerDa, NaN);
  const family = escapeHtml(cropFamilyLabel(normCropName(row?.name || '')) || 'Ürün grubu bilgisi yok');
  const isS2 = _seasonModeKey()==='s2';
  const role = idx === 0 ? 'Ana ürün' : '2. ürün / tamamlayıcı';
  const disease = cropRiskAdviceV93(row?.name || '');
  const why = isS2
    ? `${role}; dönem, su kotası, pik ay, ürün familyası ve toprak uyumu birlikte kontrol edilir. Aynı parsele ikinci ürün giriyorsa iki ürün yıllık desen olarak okunur, bağımsız iki ayrı öneri değildir.`
    : 'Tek ürün modunda bu ürün su-kâr hedefi, parsel kotası ve uygulanabilirlik puanıyla karşılaştırılmıştır.';
  return `
    <details class="crop-detail-card">
      <summary>
        <span><strong>${escapeHtml(name)}</strong><small>${escapeHtml(role)} • ${escapeHtml(season)}</small></span>
        <span class="crop-detail-metrics"><b>${waterDa.toFixed(1)}</b> m³/da <b>${profitDa.toFixed(0)}</b> TL/da</span>
      </summary>
      <div class="crop-detail-grid">
        <div><span>Toplam alan</span><strong>${area.toLocaleString('tr-TR', {maximumFractionDigits:1})} da</strong></div>
        <div><span>Toplam su</span><strong>${Math.round(totalWater).toLocaleString('tr-TR')} m³</strong></div>
        <div><span>Net kâr</span><strong>${Math.round(totalProfit).toLocaleString('tr-TR')} TL</strong></div>
        <div><span>TL/m³</span><strong>${(totalProfit/Math.max(1,totalWater)).toFixed(2)}</strong></div>
        <div><span>Yetişme süresi</span><strong>${days ? `${days} gün` : 'Takvim kontrolü'}</strong></div>
        <div><span>Pik dönem</span><strong>${escapeHtml(peak || 'Aylık plana bak')}</strong></div>
        <div><span>2024 fiyatı</span><strong>${Number.isFinite(price) ? `${price.toFixed(2)} TL/kg` : 'Veri yok'}</strong></div>
        <div><span>Verim</span><strong>${Number.isFinite(yieldKg) ? `${Math.round(yieldKg).toLocaleString('tr-TR')} kg/da` : 'Veri yok'}</strong></div>
      </div>
      <div class="crop-detail-note"><strong>Neden okunmalı?</strong> ${escapeHtml(why)}</div>
      <div class="crop-detail-note"><strong>Toprak / rotasyon:</strong> ${family}. Aynı familyadan arka arkaya ekim hastalık ve besin baskısı yaratabileceği için alternatifler bu kural ile süzülür.</div>
      <div class="crop-detail-note"><strong>Bakım özeti:</strong> ${escapeHtml(disease)}</div>
    </details>`;
}

function cropFamilyLabel(key){
  const fam = (CROP_FAMILY_S1 && CROP_FAMILY_S1[key]) || '';
  const labels = {
    cereal:'Tahıl',
    legume:'Baklagil',
    solanaceae:'Patlıcangiller',
    brassica:'Lahanagiller',
    cucurbit:'Kabakgiller',
    orchard:'Meyve / çok yıllık',
    allium:'Soğan-sarımsak grubu',
    forage:'Yem bitkisi'
  };
  return labels[fam] || fam || '';
}

function cropGrowthDays(cropName, season=''){
  const n = normCropName(cropName);
  const rule = (STATE.backendMeta?.s1_crop_rules || {})[cropName] || (STATE.backendMeta?.s1_crop_rules || {})[prettyCropName(cropName)] || null;
  const d = safeNum(rule?.growth_days || rule?.days, NaN);
  if(Number.isFinite(d) && d > 0) return Math.round(d);
  if(n.includes('BUGDAY') || n.includes('ARPA') || n.includes('CAVDAR') || n.includes('TRITIKALE')) return 150;
  if(n.includes('LAHANA')) return 120;
  if(n.includes('DOMATES') || n.includes('BIBER')) return 120;
  if(n.includes('MERCIMEK') || n.includes('NOHUT')) return 110;
  if(n.includes('MARUL') || n.includes('ISPANAK') || n.includes('TURP')) return 60;
  return 100;
}

function cropRiskAdviceV93(cropName){
  const n = normCropName(cropName);
  if(n.includes('LAHANA')) return 'Fide hazırlığı, dikim sonrası can suyu, düzenli damla sulama, yabancı ot kontrolü ve baş bağlama döneminde dengeli gübreleme gerekir. Kök çürüklüğü, yaprak biti ve tırtıl riski için erken gözlem ve uygun entegre mücadele önerilir.';
  if(n.includes('BUGDAY') || n.includes('ARPA')) return 'Toprak hazırlığı ve ekim derinliği önemlidir. Kardeşlenme ve başaklanma döneminde su stresi verimi düşürür. Pas, septorya ve yabancı ot takibi yapılmalıdır.';
  if(n.includes('MERCIMEK') || n.includes('NOHUT')) return 'Baklagil olduğu için toprağa azot katkısı sağlar ve tahıl sonrası iyi rotasyon oluşturur. Aşırı sulamadan kaçınılmalı; antraknoz/kök hastalıkları için temiz tohum ve münavebe izlenmelidir.';
  if(n.includes('DOMATES') || n.includes('BIBER')) return 'Fide, dikim, çiçeklenme ve meyve tutumu dönemleri kritik sulama ister. Mildiyö, külleme, yaprak biti ve kırmızı örümcek için erken izleme gerekir.';
  return 'Toprak hazırlığı, ekim/dikim zamanı, sulama aralığı, yabancı ot ve hastalık-zararlı kontrolü yerel teknik danışmanla birlikte netleştirilmelidir.';
}

