/* ===== v50: Sol kolon yüksekliğini sağ ana içerikle senkronla ===== */
(function(){
  function clampHeight(value){
    const n = Number(value) || 0;
    // Sağ içerik çok kısa kalırsa sol panel kullanılabilir yükseklikte dursun; çok uzunsa sağ içerik kadar uzasın.
    return Math.max(620, Math.ceil(n));
  }

  function syncLeftColumnToRightV50(){
    const left = document.querySelector('.left-col');
    const right = document.querySelector('.right-col');
    if(!left || !right) return;

    // Dar ekranda tek kolon doğal akış korunur.
    if(window.innerWidth <= 1050){
      document.documentElement.style.removeProperty('--synced-left-height');
      left.style.removeProperty('height');
      left.style.removeProperty('max-height');
      left.style.removeProperty('overflow-y');
      return;
    }

    // Sağ kolonun gerçek içerik yüksekliğini esas al. Böylece sol kolon sağ içerik bittiği noktada biter.
    const rectHeight = right.getBoundingClientRect().height || 0;
    const scrollHeight = right.scrollHeight || 0;
    const target = clampHeight(Math.max(rectHeight, scrollHeight));
    document.documentElement.style.setProperty('--synced-left-height', target + 'px');

    // Önceki sürümlerde JS ile verilen inline stilleri güvenli şekilde ez.
    left.style.setProperty('height', target + 'px', 'important');
    left.style.setProperty('max-height', target + 'px', 'important');
    left.style.setProperty('overflow-y', 'auto', 'important');
    left.style.setProperty('overflow-x', 'hidden', 'important');
    left.style.setProperty('position', 'relative', 'important');
  }

  function initV50(){
    document.body.classList.remove('sidebar-collapsed','sidebar-resizing');
    syncLeftColumnToRightV50();
    setTimeout(syncLeftColumnToRightV50, 250);
    setTimeout(syncLeftColumnToRightV50, 900);
    setTimeout(syncLeftColumnToRightV50, 1800);

    window.addEventListener('resize', syncLeftColumnToRightV50);
    window.addEventListener('load', syncLeftColumnToRightV50);

    document.querySelectorAll('.left-col details.sidebar-group').forEach(el=>{
      el.addEventListener('toggle', ()=>setTimeout(syncLeftColumnToRightV50, 50));
    });

    if('ResizeObserver' in window){
      const right = document.querySelector('.right-col');
      if(right){
        const ro = new ResizeObserver(()=>syncLeftColumnToRightV50());
        ro.observe(right);
      }
    }
  }

  if(document.readyState === 'loading') document.addEventListener('DOMContentLoaded', initV50);
  else initV50();
})();



/* ============================================================
   v55 çiftçi görünümü sadeleştirme
   - Çiftçi ekranında çizim/veri yükleme/parsel atama/kullanıcı yönetimi gizlenir.
   - Kurum/uzman ataması çiftçiye sade "uzman önerisi" kartı olarak gösterilir.
   - Teknik "optimizasyon" dili çiftçi tarafında "öneri" diliyle değiştirilir.
   ============================================================ */
(function(){
  const ASSIGNMENT_STORAGE_KEY_V55 = 'akkayaParcelAssignmentsV16';

  function escV55(v){
    try{ return (typeof escapeHtml === 'function') ? escapeHtml(String(v ?? '')) : String(v ?? '').replace(/[&<>"']/g, m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m])); }
    catch(_e){ return String(v ?? ''); }
  }
  function numV55(v, fb=0){
    const n = Number(String(v ?? '').replace(',','.'));
    return Number.isFinite(n) ? n : fb;
  }
  function statusLabelV55(k){
    const s=String(k||'').toLowerCase();
    if(s==='farmer_selected') return 'Tercih iletildi';
    if(s==='technical_review') return 'Uzman incelemesinde';
    if(s==='approved') return 'Uzman onaylı';
    if(s==='in_progress') return 'Uygulamada';
    if(s==='draft') return 'Taslak öneri';
    if(s==='geometry_ready') return 'Parsel sınırı hazır';
    return s ? s : 'Atama yok';
  }
  function statusToneV55(k){
    const s=String(k||'').toLowerCase();
    if(s==='approved' || s==='in_progress') return 'ok';
    if(s==='technical_review' || s==='farmer_selected') return 'warn';
    return 'muted';
  }
  function currentParcelV55(){
    try{ return (parcelData || []).find(p=>String(p?.id || '') === String(selectedParcelId || '')) || null; }
    catch(_e){ return null; }
  }
  function loadAssignmentsV55(){
    try{ return JSON.parse(localStorage.getItem(ASSIGNMENT_STORAGE_KEY_V55) || '{}') || {}; }
    catch(_e){ return {}; }
  }
  function getAssignmentV55(parcel){
    if(!parcel) return null;
    const saved = loadAssignmentsV55()[String(parcel.id)] || null;
    const fromParcel = (parcel.assigned_alternative_id || parcel.assigned_farmer_name || parcel.assignment_status || parcel.assigned_pattern) ? {
      parcel_id: String(parcel.id || ''),
      farmer_username: parcel.assigned_farmer_username || '',
      farmer_name: parcel.assigned_farmer_name || parcel.farmer || parcel.farmer_name || '',
      alternative_id: parcel.assigned_alternative_id || '',
      alternative_label: parcel.assigned_alternative_label || '',
      pattern: parcel.assigned_pattern || '',
      water_m3: numV55(parcel.assigned_water_m3, 0),
      profit_tl: numV55(parcel.assigned_profit_tl, 0),
      tl_per_m3: numV55(parcel.assigned_tl_per_m3, 0),
      status: parcel.assignment_status || '',
      note: parcel.assignment_note || '',
      assigned_at: parcel.assigned_at || '',
      assigned_by: parcel.assigned_by || ''
    } : null;
    return saved || fromParcel;
  }
  function isFarmerV55(){
    try{ return STATE?.currentUser?.role === 'farmer'; }catch(_e){ return false; }
  }
  function syncFarmerTextLabelsV55(){
    const runBtn = document.getElementById('runOptBtn');
    if(runBtn){
      if(!runBtn.dataset.institutionLabel) runBtn.dataset.institutionLabel = runBtn.textContent || 'Optimizasyonu Çalıştır';
      runBtn.textContent = isFarmerV55() ? 'Öneri üret' : runBtn.dataset.institutionLabel;
      runBtn.title = isFarmerV55() ? 'Seçili hedef, senaryo ve algoritmaya göre öneriyi üretir.' : (runBtn.title || '');
    }
    const setupTitle = document.querySelector('#setupGroup .card-title');
    if(setupTitle){
      if(!setupTitle.dataset.institutionLabel) setupTitle.dataset.institutionLabel = setupTitle.textContent || 'Parsel seç';
      setupTitle.textContent = isFarmerV55() ? 'Kendi parselim' : setupTitle.dataset.institutionLabel;
    }
    const parcelTab = document.querySelector('.tab[data-tab="parcel"]');
    if(parcelTab){
      if(!parcelTab.dataset.institutionLabel) parcelTab.dataset.institutionLabel = parcelTab.textContent || 'Parsel düzeyi desen';
      parcelTab.textContent = isFarmerV55() ? 'Parsel düzeyi desen' : parcelTab.dataset.institutionLabel;
    }
    document.querySelectorAll('#tab-parcel h3.card-subtitle').forEach(h=>{
      if(!h.dataset.institutionLabel) h.dataset.institutionLabel = h.textContent || '';
      if(isFarmerV55()){
        if(h.dataset.institutionLabel.includes('Önerilen Ürün Deseni')) h.textContent = 'Uzman / sistem önerisi';
        if(h.dataset.institutionLabel.includes('Karar açıklaması')) h.textContent = 'Önerinin gerekçesi';
        if(h.dataset.institutionLabel.includes('Rotasyon')) h.textContent = 'Uygulanabilir ek ürün / rotasyon notu';
        if(h.dataset.institutionLabel.includes('Sulama yöntemi')) h.textContent = 'Sulama yöntemi önerisi';
        if(h.dataset.institutionLabel.includes('Ekonomik dayanak')) h.textContent = 'Gelir ve gider özeti';
        if(h.dataset.institutionLabel.includes('Aylık su kapasitesi')) h.textContent = 'Aylık su ihtiyacı ve dikkat edilecek aylar';
        if(h.dataset.institutionLabel.includes('sulama planı')) h.textContent = 'Pratik sulama rehberi';
      }else{
        h.textContent = h.dataset.institutionLabel;
      }
    });
  }
  function renderFarmerAssignmentSummaryV55(){
    const box = document.getElementById('farmerAssignmentSummary');
    if(!box) return;
    if(!isFarmerV55()){
      box.innerHTML = '<div class="small muted">Bu kart yalnızca çiftçi görünümünde kullanılır.</div>';
      return;
    }
    const user = STATE?.currentUser || {};
    const p = currentParcelV55();
    if(!p){
      box.innerHTML = '<div class="farmer-summary-note">Size atanmış görünür bir parsel bulunamadı. Kurum parsel ataması yaptığında burada yalnızca sizin parseliniz görünecek.</div>';
      return;
    }
    const ass = getAssignmentV55(p);
    const status = statusLabelV55(ass?.status);
    const tone = statusToneV55(ass?.status);
    const pattern = ass?.pattern || ass?.alternative_label || 'Uzman tarafından özel desen atanmadı';
    const note = ass?.note || (ass ? 'Uzman ataması panelinize aktarılmıştır. Uygulamadan önce kurum/uzman notunu dikkate alın.' : 'Bu parsel için henüz kurum/uzman tarafından özel atama yapılmamış. Aşağıdaki sonuçlar sistemin genel öneri ekranından izlenebilir.');
    const activeTarget = (typeof getScenarioDisplayMeta === 'function')
      ? getScenarioDisplayMeta(selectedScenario === 'mevcut' ? 'su_tasarruf' : (selectedScenario || 'su_etkin')).shortLabel
      : 'Su tasarrufu';
    const activeSeason = (STATE.farmerSeasonSourceV102 || STATE.seasonSource || document.getElementById('seasonSourceSel')?.value || 's1') === 's2'
      ? 'Senaryo 2 - ürün kombinasyonu / desen'
      : 'Senaryo 1 - tek ürün';
    const activeAlgo = STATE.farmerAlgoModeV7 === 'auto'
      ? 'Otomatik en iyi algoritma'
      : String(selectedAlgo || 'GA').toUpperCase();
    const threadId = (typeof parcelThreadKeyFor === 'function') ? parcelThreadKeyFor(p, user.username || '') : '';
    const msgCount = threadId && typeof getParcelThread === 'function' ? getParcelThread(threadId).length : 0;
    const noticeCount = typeof notificationsForCurrentUser === 'function'
      ? notificationsForCurrentUser().filter(n=>String(n.parcel_id||'')===String(p.id||'')).length
      : 0;
    box.innerHTML = `
      <div class="farmer-summary-hero">
        <div class="farmer-summary-top">
          <div>
            <strong>${escV55(p.id || p.name || 'Parsel')} - ${escV55(p.village || user.village || 'Köy bilgisi yok')}</strong>
            <span>${escV55(user.displayName || user.username || 'Çiftçi')} hesabına tanımlı parsel özeti</span>
          </div>
          <span class="farmer-status-pill ${tone}">${escV55(status)}</span>
        </div>
        <div class="farmer-summary-grid">
          <div class="farmer-kv"><span>Parsel kodu</span><strong>${escV55(p.id || '-')}</strong></div>
          <div class="farmer-kv"><span>Çiftçi / hesap</span><strong>${escV55(user.displayName || user.username || '-')}</strong></div>
          <div class="farmer-kv"><span>Mevcut ürün</span><strong>${escV55(p.current_crop || 'Belirtilmedi')}</strong></div>
          <div class="farmer-kv"><span>Aktif hedef</span><strong>${escV55(activeTarget)}</strong></div>
          <div class="farmer-kv"><span>Aktif senaryo</span><strong>${escV55(activeSeason)}</strong></div>
          <div class="farmer-kv"><span>Aktif algoritma</span><strong>${escV55(activeAlgo)}</strong></div>
          <div class="farmer-kv"><span>Talep / mesaj</span><strong>${escV55(status)} • ${msgCount} mesaj • ${noticeCount} bildirim</strong></div>
          <div class="farmer-kv"><span>Uzman / sistem önerisi</span><strong>${escV55(pattern)}</strong></div>
        </div>
        <div class="farmer-message-actions-v100" style="margin-top:10px;">
          <button class="btn-secondary" type="button" data-farmer-summary-action-v7="run">Öneri üret</button>
          <button class="btn-secondary" type="button" data-farmer-summary-action-v7="request">Uzmana gönder / mesajlaş</button>
        </div>
        <div class="farmer-summary-note" style="margin-top:10px;"><strong>Not:</strong> ${escV55(note)}</div>
      </div>`;
    box.querySelectorAll('[data-farmer-summary-action-v7]').forEach(btn=>btn.addEventListener('click', ()=>{
      const action = btn.getAttribute('data-farmer-summary-action-v7') || '';
      if(action === 'run'){
        const runBtn = document.getElementById('runOptBtn');
        if(runBtn) runBtn.click();
        else try{ refreshUI(); }catch(_e){}
      }else{
        try{ if(typeof openFarmerCommunicationTabV7 === 'function') openFarmerCommunicationTabV7(); else if(typeof switchTabByKey === 'function') switchTabByKey('farmer-communication'); }catch(_e){}
        try{ if(typeof renderFarmerComms102 === 'function') renderFarmerComms102(); }catch(_e){}
        const target = document.getElementById('farmerUserRequestThreadV100');
        if(target) target.scrollIntoView({behavior:'smooth', block:'start'});
        if(action === 'request') document.getElementById('farmerRequestSelectedV102')?.click();
      }
    }));
  }
  function bindFarmerRefreshButtonV55(){
    const btn = document.getElementById('farmerRefreshRecommendationBtn');
    if(!btn || btn.dataset.boundV55) return;
    btn.dataset.boundV55 = '1';
    btn.addEventListener('click', ()=>{
      const runBtn = document.getElementById('runOptBtn');
      if(runBtn && !runBtn.disabled) runBtn.click();
      else {
        try{ refreshUI(); }catch(_e){}
      }
      setTimeout(()=>{ renderFarmerAssignmentSummaryV55(); syncFarmerTextLabelsV55(); }, 80);
    });
  }
  function syncFarmerPanelV55(){
    syncFarmerTextLabelsV55();
    renderFarmerAssignmentSummaryV55();
    bindFarmerRefreshButtonV55();
  }

  if(typeof refreshUI === 'function'){
    const originalRefreshUIV55 = refreshUI;
    refreshUI = function(){
      const res = originalRefreshUIV55.apply(this, arguments);
      try{ syncFarmerPanelV55(); }catch(_e){}
      return res;
    };
  }
  if(typeof setAuthenticatedUser === 'function'){
    const originalSetAuthenticatedUserV55 = setAuthenticatedUser;
    setAuthenticatedUser = function(user, opts={}){
      const res = originalSetAuthenticatedUserV55.apply(this, arguments);
      bootAwareTimeout(()=>{ try{ syncFarmerPanelV55(); }catch(_e){} }, 90);
      return res;
    };
  }

  window.addEventListener('DOMContentLoaded', ()=>{
    bootAwareTimeout(()=>{
      try{ syncFarmerPanelV55(); }catch(_e){}
      document.getElementById('parcelSelect')?.addEventListener('change', ()=>setTimeout(()=>{ try{ syncFarmerPanelV55(); }catch(_e){} }, 80));
    }, 800);
  });
})();


/* ============================================================
   v56 çiftçi paneli - Betül Demir için yalnızca 3 örnek parsel
   - Çiftçi dropdown'ında yalnızca 3 parsel görünür.
   - Parseller farklı köylerden seçilir: bir meyve, bir sebze, bir tarla ürünü.
   - Çiftçi görünümünde başka çiftçi isimleri gösterilmez.
   ============================================================ */
(function(){
  const BETUL_DEMO_PARCELS_V56 = ['P23','P149','P158']; // Sazlıca sebze, Kemerhisar meyve, Kaynarca tarla ürünü

  function normalizeCropLabelV56(v){
    return String(v || '').replace(/\s+/g,' ').trim();
  }
  function parcelCropForV56(p){
    return normalizeCropLabelV56(
      p?.current_crop || p?.main_crop_current || p?.crop || p?.crop_name || p?.main_crop || ''
    );
  }
  function parcelTypeLabelV56(p){
    const crop = parcelCropForV56(p).toUpperCase('tr-TR');
    const has = (...xs)=> xs.some(x => crop.includes(String(x).toUpperCase('tr-TR')));
    if(has('ELMA','ARMUT','ERİK','KAYSI','KİRAZ','NEKTAR','ŞEFTALİ','VİŞNE','BADEM','CEVİZ','ÇİLEK','AYVA','BAĞ')) return 'Meyve';
    if(has('PATATES','DOMATES','BİBER','SOĞAN','SARIMSAK','HIYAR','KABAK','KARPUZ','KAVUN','LAHANA','FASULYE (TAZE)','BARBUNYA')) return 'Sebze';
    return 'Tarla ürünü';
  }
  function ensureBetulDemoPortfolioV56(){
    try{
      if(typeof getAuthUserByUsername !== 'function' || typeof saveAuthUser !== 'function') return;
      const user = getAuthUserByUsername('betul.demir');
      if(!user) return;
      const current = Array.isArray(user.allowedParcelIds) ? user.allowedParcelIds.map(x=>String(x||'').trim()).filter(Boolean) : [];
      const same = current.length === BETUL_DEMO_PARCELS_V56.length && BETUL_DEMO_PARCELS_V56.every((id, i)=> current[i] === id);
      if(!same || String(user.village||'') !== '3 Köy Demo'){
        const saved = saveAuthUser({
          ...user,
          allowedParcelIds: BETUL_DEMO_PARCELS_V56.slice(),
          village: '3 Köy Demo',
          district: 'Akkaya Sulama Alanı',
          notes: 'Demo çiftçi hesabı için üç örnek parsel tanımlandı: Sazlıca’da sebze, Kemerhisar’da meyve, Kaynarca’da tarla ürünü.'
        });
        try{
          if(STATE?.currentUser && STATE.currentUser.username === 'betul.demir'){
            STATE.currentUser = saved;
          }
        }catch(_e){}
      }
    }catch(_e){}
  }

  if(typeof refreshParcelSelect === 'function'){
    const originalRefreshParcelSelectV56 = refreshParcelSelect;
    refreshParcelSelect = function(){
      const res = originalRefreshParcelSelectV56.apply(this, arguments);
      try{
        const user = STATE?.currentUser || null;
        if(user?.role !== 'farmer') return res;
        const sel = document.getElementById('parcelSelect');
        if(!sel) return res;
        Array.from(sel.options).forEach(opt=>{
          const pid = String(opt.value || '').trim();
          if(!pid) return;
          const p = (parcelData || []).find(x => String(x?.id || x?.parcel_id || '').trim() === pid);
          if(!p) return;
          const village = String(p.village || p.district || '').trim();
          const crop = parcelCropForV56(p);
          const typeLabel = parcelTypeLabelV56(p);
          const parts = [pid];
          if(village) parts.push(village);
          if(crop) parts.push(`${typeLabel} (${crop})`);
          else if(typeLabel) parts.push(typeLabel);
          opt.textContent = parts.join(' - ');
        });
      }catch(_e){}
      return res;
    };
  }

  if(typeof setAuthenticatedUser === 'function'){
    const originalSetAuthenticatedUserV56 = setAuthenticatedUser;
    setAuthenticatedUser = function(user, opts={}){
      ensureBetulDemoPortfolioV56();
      const res = originalSetAuthenticatedUserV56.apply(this, arguments);
      bootAwareTimeout(()=>{
        try{
          if(STATE?.currentUser?.username === 'betul.demir'){
            ensureBetulDemoPortfolioV56();
            if(typeof refreshParcelSelect === 'function') refreshParcelSelect();
            if(typeof selectedParcelId !== 'undefined'){
              selectedParcelId = BETUL_DEMO_PARCELS_V56[0];
              const sel = document.getElementById('parcelSelect');
              if(sel && Array.from(sel.options).some(opt => String(opt.value) === selectedParcelId)){
                sel.value = selectedParcelId;
                sel.dispatchEvent(new Event('change', { bubbles:true }));
              }
            }
            if(typeof refreshUI === 'function') refreshUI();
          }
        }catch(_e){}
      }, 60);
      return res;
    };
  }

  window.addEventListener('DOMContentLoaded', ()=>{
    bootAwareTimeout(()=>{
      try{ ensureBetulDemoPortfolioV56(); }catch(_e){}
      try{
        const help = document.querySelector('#farmerDecisionCard .card-help.small');
        if(help){
          help.textContent = 'Bu demoda çiftçi hesabında yalnızca size tanımlı 3 örnek parsel gösterilir: bir sebze, bir meyve ve bir tarla ürünü. Diğer çiftçilere ait isimler ve teknik yönetim alanları gizlenmiştir.';
        }
      }catch(_e){}
      try{
        if(STATE?.currentUser?.username === 'betul.demir'){
          if(typeof refreshParcelSelect === 'function') refreshParcelSelect();
          if(typeof refreshUI === 'function') refreshUI();
        }
      }catch(_e){}
    }, 250);
  });
})();

/* ============================================================
   v57 çiftçi sahiplik senkronu
   - Betül Demir'e tanımlı 3 demo parsel, diğer panel ve harita
     özetlerinde de Betül Demir hesabına ait görünür.
   - Eski kaynak çiftçi adları çiftçi görünümünde taşınmaz.
   ============================================================ */
(function(){
  const BETUL_OWNER_PARCELS_V57 = new Set(['P23','P149','P158']);
  const BETUL_OWNER_NAME_V57 = 'Betül Demir';
  const BETUL_OWNER_USERNAME_V57 = 'betul.demir';
  const BETUL_OWNER_ID_V57 = 'C-BETUL';

  function setOwnerV57(p){
    if(!p) return;
    const pid = String(p.id || p.parcel_id || p.pid || '').trim();
    if(!BETUL_OWNER_PARCELS_V57.has(pid)) return;
    p.owner_username = BETUL_OWNER_USERNAME_V57;
    p.assigned_farmer_username = BETUL_OWNER_USERNAME_V57;
    p.farmer_id = BETUL_OWNER_ID_V57;
    p.farmer = BETUL_OWNER_NAME_V57;
    p.farmer_name = BETUL_OWNER_NAME_V57;
    p.assigned_farmer_name = BETUL_OWNER_NAME_V57;
    p.farmer_display = `${BETUL_OWNER_ID_V57} • ${BETUL_OWNER_NAME_V57}`;
    if(p.feature && p.feature.properties){
      p.feature.properties.owner_username = BETUL_OWNER_USERNAME_V57;
      p.feature.properties.assigned_farmer_username = BETUL_OWNER_USERNAME_V57;
      p.feature.properties.farmer_id = BETUL_OWNER_ID_V57;
      p.feature.properties.farmer = BETUL_OWNER_NAME_V57;
      p.feature.properties.farmer_name = BETUL_OWNER_NAME_V57;
      p.feature.properties.assigned_farmer_name = BETUL_OWNER_NAME_V57;
      p.feature.properties.farmer_display = `${BETUL_OWNER_ID_V57} • ${BETUL_OWNER_NAME_V57}`;
    }
  }
  function syncBetulOwnershipV57(){
    try{
      (parcelData || []).forEach(setOwnerV57);
    }catch(_e){}
  }
  if(typeof refreshUI === 'function'){
    const originalRefreshUIV57 = refreshUI;
    refreshUI = function(){
      syncBetulOwnershipV57();
      return originalRefreshUIV57.apply(this, arguments);
    };
  }
  if(typeof refreshParcelSelect === 'function'){
    const originalRefreshParcelSelectV57 = refreshParcelSelect;
    refreshParcelSelect = function(){
      syncBetulOwnershipV57();
      return originalRefreshParcelSelectV57.apply(this, arguments);
    };
  }
  window.addEventListener('DOMContentLoaded', ()=>{
    bootAwareTimeout(()=>{
      try{
        syncBetulOwnershipV57();
        if(typeof refreshParcelSelect === 'function') refreshParcelSelect();
        if(typeof refreshUI === 'function') refreshUI();
      }catch(_e){}
    }, 500);
  });
})();

/* ============================================================
   v99 son katman senkronu
   - v55/v57 gibi eski rol yamalari calistiktan sonra ciftci ve
     benchmark duzenlemelerini tekrar uygular.
   ============================================================ */
(function(){
  function applyFinalRoleSyncV99(){
    try{ if(typeof window.syncFarmerLabelsV98 === 'function') window.syncFarmerLabelsV98(); }catch(_e){}
    try{ if(typeof window.ensureBenchmarkMethodologyV98 === 'function') window.ensureBenchmarkMethodologyV98(); }catch(_e){}
  }
  if(typeof refreshUI === 'function' && !refreshUI.__v99Wrapped){
    const originalRefreshUIV99 = refreshUI;
    refreshUI = function(){
      const res = originalRefreshUIV99.apply(this, arguments);
      bootAwareTimeout(applyFinalRoleSyncV99, 0);
      return res;
    };
    refreshUI.__v99Wrapped = true;
  }
  if(typeof setAuthenticatedUser === 'function' && !setAuthenticatedUser.__v99Wrapped){
    const originalSetAuthenticatedUserV99 = setAuthenticatedUser;
    setAuthenticatedUser = function(){
      const res = originalSetAuthenticatedUserV99.apply(this, arguments);
      bootAwareTimeout(applyFinalRoleSyncV99, 80);
      return res;
    };
    setAuthenticatedUser.__v99Wrapped = true;
  }
  window.addEventListener('DOMContentLoaded', ()=>bootAwareTimeout(applyFinalRoleSyncV99, 1200));
})();

/* v102b - final DOM activation after older farmer wrappers */
(function(){
  function esc102(v){ return (typeof escapeHtml === 'function') ? escapeHtml(v) : String(v ?? '').replace(/[&<>"']/g, s=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[s])); }
  function fmt102(v){ return Math.round(Number(v)||0).toLocaleString('tr-TR'); }
  function scen102(v){
    const raw = String(v || '').toLowerCase().replace(/ı/g,'i').replace(/ğ/g,'g').replace(/ü/g,'u').replace(/ş/g,'s').replace(/ö/g,'o').replace(/ç/g,'c');
    if(raw.includes('tasarruf') || raw.includes('water_saving')) return 'su_tasarruf';
    if(raw.includes('kar') || raw.includes('profit') || raw.includes('maks')) return 'maks_kar';
    if(raw.includes('mevcut') || raw.includes('current')) return 'mevcut';
    if(raw.includes('etkin') || raw.includes('verim') || raw.includes('water_efficiency') || raw.includes('balanced') || raw.includes('denge')) return 'su_etkin';
    return 'su_etkin';
  }
  function scenarioLabel102(k){
    const s = scen102(k);
    if(s === 'su_tasarruf') return 'Su tasarrufu';
    if(s === 'maks_kar') return 'Kâr odaklı';
    if(s === 'mevcut') return 'Mevcut';
    return 'Su etkin kullanım';
  }
  function currentFarmerParcel102(){
    return (parcelData||[]).find(p=>String(p?.id||p?.parcel_id||'')===String(selectedParcelId)) || null;
  }
  function farmerTargetHtml102(){
    const target = scen102(selectedScenario === 'mevcut' ? 'su_tasarruf' : selectedScenario);
    const season = (document.getElementById('seasonSourceSel')?.value) || STATE.seasonSource || 's1';
    return `<div class="farmer-target-card-v100 farmer-target-card-v102">
      <div class="farmer-target-title-v100"><strong>Karar hedefi</strong><span>Hedef, senaryo ve algoritma değişince öneriler yeniden hesaplanır.</span></div>
      <div class="farmer-target-controls-v100 farmer-target-controls-v102">
        <label><span>Hedefim</span><select class="select-input" id="farmerObjectiveSelectV102">
          <option value="su_tasarruf">Su tasarrufu</option>
          <option value="maks_kar">Kâr odaklı</option>
          <option value="su_etkin">Su etkin kullanım</option>
        </select></label>
        <label><span>Senaryo</span><select class="select-input" id="farmerSeasonSourceSelectV102">
          <option value="s1">Senaryo 1 - tek ürün</option>
          <option value="s2">Senaryo 2 - ürün kombinasyonu / desen</option>
        </select></label>
        <label><span>Öneri ürün grubu</span><select class="select-input" id="farmerCropCategoryModeV102">${cropCategoryModeOptionsHtml()}</select></label>
        <label><span>Algoritma</span><select class="select-input" id="farmerAlgoSelectV102">
          <option value="auto">Otomatik en iyi algoritma</option>
          <option value="ga">GA</option>
          <option value="aco">ACO</option>
          <option value="abc">ABC</option>
        </select></label>
        <button class="btn-primary" id="farmerRunDecisionV102" type="button">Bu hedefle öneriyi çalıştır</button>
      </div>
      <div class="farmer-target-note-v100">Çiftçi mevcut atanan deseni korur; istediği S1/S2 alternatifini seçip uzmana onay talebi gönderebilir.</div>
    </div>`;
  }
  function patchFarmerControls102(){
    if(STATE?.currentUser?.role !== 'farmer') return;
    let mount = document.getElementById('farmerTargetMountV100');
    if(!mount){
      const oldControl = document.getElementById('farmerObjectiveSelectV98')?.closest?.('.farmer-decision-controls-v100');
      if(oldControl){
        mount = document.createElement('div');
        mount.id = 'farmerTargetMountV100';
        oldControl.replaceWith(mount);
      }
    }
    if(!mount || mount.dataset.v102 === '1') return;
    mount.dataset.v102 = '1';
    mount.innerHTML = farmerTargetHtml102();
    const os = document.getElementById('farmerObjectiveSelectV102');
    const ss = document.getElementById('farmerSeasonSourceSelectV102');
    const cs = document.getElementById('farmerCropCategoryModeV102');
    const as = document.getElementById('farmerAlgoSelectV102');
    if(os) os.value = scen102(selectedScenario === 'mevcut' ? 'su_tasarruf' : selectedScenario);
    if(ss) ss.value = (document.getElementById('seasonSourceSel')?.value) || STATE.seasonSource || 's1';
    if(cs) cs.value = normalizeCropCategoryMode(STATE.cropCategoryMode || 'same_category');
    if(as) as.value = STATE.farmerAlgoModeV7 || selectedAlgo || 'auto';
    const sync = ()=>{
      if(os) selectedScenario = os.value;
      if(as){
        STATE.farmerAlgoModeV7 = as.value || STATE.farmerAlgoModeV7 || 'auto';
        selectedAlgo = STATE.farmerAlgoModeV7 === 'auto' ? (STATE.benchmarkLeader?.algo || 'ga') : STATE.farmerAlgoModeV7;
      }
      if(cs) setCropCategoryMode(cs.value);
      const globalAlgo = document.getElementById('algoSelect');
      if(globalAlgo && as) globalAlgo.value = selectedAlgo;
      const globalSeason = document.getElementById('seasonSourceSel');
      if(globalSeason && ss){ globalSeason.value = ss.value; STATE.seasonSource = ss.value; }
      document.querySelectorAll('input[name="scenario"]').forEach(r=>{ r.checked = String(r.value) === String(selectedScenario); });
    };
    os?.addEventListener('change', ()=>{ sync(); refreshUI(); });
    ss?.addEventListener('change', ()=>{ sync(); refreshUI(); });
    cs?.addEventListener('change', ()=>{ sync(); try{ Object.keys(optimizationCache || {}).forEach(k=>delete optimizationCache[k]); Object.keys(basinPlanCache || {}).forEach(k=>delete basinPlanCache[k]); }catch(_e){} refreshUI(); });
    as?.addEventListener('change', ()=>{ sync(); refreshUI(); });
    document.getElementById('farmerRunDecisionV102')?.addEventListener('click', ()=>{
      sync();
      const runBtn = document.getElementById('runOptBtn');
      if(runBtn) runBtn.click(); else refreshUI();
    });
  }
  function threadKey102(p,user){
    try{ return parcelThreadKeyFor(p, user.username || ''); }catch(_e){ return `THREAD-${p?.id||selectedParcelId}-${user.username||'farmer'}`; }
  }
  function loadThread102(threadId){ try{ return getParcelThread(threadId) || []; }catch(_e){ return []; } }
  function saveDeletedMsg102(threadId,msgId){
    try{
      const store = loadParcelThreads();
      const list = Array.isArray(store[threadId]) ? store[threadId] : [];
      store[threadId] = list.filter(m=>String(m.id)!==String(msgId));
      saveParcelThreads(store);
      updateNotificationBell(); renderNotificationCenter(); renderInstitutionRequestInbox();
    }catch(_e){}
  }
  function postThread102(threadId,text,meta){
    try{ postParcelThreadMessage(threadId,text,meta); return; }catch(_e){}
  }
  function renderFarmerComms102(){
    if(STATE?.currentUser?.role !== 'farmer') return;
    const card = document.getElementById('farmerCommunicationMountV7') || document.getElementById('farmerDecisionCard');
    if(!card) return;
    let root = document.getElementById('farmerUserRequestThreadV100');
    if(!root){
      root = document.createElement('div');
      root.id = 'farmerUserRequestThreadV100';
      root.className = 'farmer-message-card-v100';
      card.appendChild(root);
    }
    if(root.parentElement !== card) card.appendChild(root);
    const user = STATE.currentUser || {};
    const p = currentFarmerParcel102();
    if(!p){ root.innerHTML = '<div class="request-thread-head"><strong>Uzman / yönetici iletişim</strong></div><div class="small muted">Parsel seçilince mesaj alanı açılır.</div>'; return; }
    const threadId = threadKey102(p,user);
    const thread = loadThread102(threadId);
    const related = (typeof notificationsForCurrentUser === 'function') ? notificationsForCurrentUser().filter(n=>String(n.parcel_id||'')===String(p.id||'')) : [];
    const selected = STATE.selectedFarmerAlternativeV102 || null;
    const rows = thread.slice(-6).map(m=>{
      const mine = m.actor_role === 'farmer';
      const status = mine ? (m.read_at ? 'Okundu' : 'Gönderildi') : 'Uzman/kurum';
      const action = mine ? `<button class="btn-link" type="button" data-farmer-msg-delete-v102="${esc102(m.id)}" data-thread-id-v102="${esc102(threadId)}">${m.read_at ? 'Sil' : 'Geri al'}</button>` : '';
      return `<div class="request-msg-item ${mine?'mine':''}"><div class="request-msg-meta">${esc102(m.actor_name || m.actor_username || 'Kullanıcı')} <span class="msg-status-v102">${status}</span>${action}</div><div class="request-msg-text">${esc102(m.text||'')}</div></div>`;
    }).join('');
    root.innerHTML = `<div class="request-thread-head"><strong>Uzman / yönetici iletişim</strong><span class="pill-soft">${related.length} bildirim - ${thread.length} mesaj</span></div>
      ${selected ? `<div class="selected-alt-v102"><b>Seçilen alternatif:</b> ${esc102(selected.patternName||'')}<span>${fmt102(selected.totalWater)} m³ su - ${fmt102(selected.totalProfit)} TL net kâr</span></div>` : ''}
      <div class="farmer-message-list-v100">${rows || '<div class="small muted">Mesaj geçmişi yok. Alternatif kartındaki Seç butonu mesajı otomatik hazırlar.</div>'}</div>
      <textarea class="text-input" id="farmerMessageInputV100" placeholder="Örn. Bu öneriyi uygulamak istiyorum, uzman onayı rica ederim."></textarea>
      <div class="farmer-message-actions-v100"><button class="btn-primary" id="farmerSendMessageV102" type="button">Mesaj gönder</button><button class="btn-secondary" id="farmerRequestSelectedV102" type="button">Seçili öneriyi talep et</button></div>`;
    root.querySelectorAll('[data-farmer-msg-delete-v102]').forEach(btn=>btn.addEventListener('click', ()=>{
      saveDeletedMsg102(btn.getAttribute('data-thread-id-v102'), btn.getAttribute('data-farmer-msg-delete-v102'));
      renderFarmerComms102();
    }));
    const send = (request=false)=>{
      const input = document.getElementById('farmerMessageInputV100');
      let val = String(input?.value || '').trim();
      const alt = STATE.selectedFarmerAlternativeV102 || null;
      if(request){
        val = alt
          ? `${alt.patternName} alternatifini talep ediyorum. Hedef: ${scenarioLabel102(selectedScenario)}. Algoritma: ${String(selectedAlgo||'GA').toUpperCase()}. Su: ${fmt102(alt.totalWater)} m³, net kâr: ${fmt102(alt.totalProfit)} TL. Uzman onayı ve parselime tanımlama rica ederim.`
          : `${scenarioLabel102(selectedScenario)} hedefindeki ${String(selectedAlgo||'GA').toUpperCase()} algoritma önerisi için uzman incelemesi ve parselime tanımlama talep ediyorum.`;
      }
      if(!val) return;
      postThread102(threadId,val,{actor_role:'farmer', actor_username:user.username||'', actor_name:user.displayName||user.username||'Çiftçi', parcel_id:String(p.id||''), selected_pattern:alt});
      try{
        pushParcelNotification({
          target_role:'institution',
          target_usernames:['kurum.nigde','uzman.nigde'],
          actor_username:user.username||'',
          text:`${user.displayName || user.username || 'Çiftçi'} ${p.id} parseli için ${request ? 'alternatif talebi' : 'mesaj'} gönderdi.`,
          parcel_id:String(p.id||''),
          thread_id:threadId,
          kind: request ? 'alternative_request' : 'message'
        });
      }catch(_e){}
      if(input) input.value = '';
      renderFarmerComms102();
      try{ updateNotificationBell(); renderNotificationCenter(); renderInstitutionRequestInbox(); }catch(_e){}
    };
    document.getElementById('farmerSendMessageV102')?.addEventListener('click', ()=>send(false));
    document.getElementById('farmerRequestSelectedV102')?.addEventListener('click', ()=>send(true));
  }
  function patchScenarioLabels102(){
    document.querySelectorAll('input[name="scenario"]').forEach(r=>{
      const label = r.closest('label');
      if(!label) return;
      if(r.value === 'su_tasarruf') label.childNodes[label.childNodes.length-1].textContent = ' Su tasarrufu hedefi';
      if(r.value === 'maks_kar') label.childNodes[label.childNodes.length-1].textContent = ' Kâr odaklı hedef';
      if(r.value === 'balanced'){
        r.checked = false;
        label.style.display = 'none';
      }
      if(r.value === 'su_etkin') label.childNodes[label.childNodes.length-1].textContent = ' Su etkin kullanım hedefi';
    });
  }
  document.addEventListener('click', (ev)=>{
    const pick = ev.target?.closest?.('[data-select-pattern-v102]');
    if(pick){
      const pat = window.__patternPickStoreV102?.[pick.getAttribute('data-select-pattern-v102')];
      if(pick.disabled || pat?.selectable === false || pat?.feasible === false || pat?.quotaExceeded){
        ev.preventDefault();
        return;
      }
      if(pat){
        STATE.selectedFarmerAlternativeV102 = pat;
        renderFarmerComms102();
        const input = document.getElementById('farmerMessageInputV100');
        if(input) input.value = `${pat.patternName} alternatifini seçmek istiyorum. Su: ${fmt102(pat.totalWater)} m³, net kâr: ${fmt102(pat.totalProfit)} TL. Uzman onayı rica ederim.`;
        document.getElementById('farmerUserRequestThreadV100')?.scrollIntoView({behavior:'smooth', block:'center'});
      }
    }
  }, true);
  function apply102b(){
    patchScenarioLabels102();
    patchFarmerControls102();
    renderFarmerComms102();
  }
  if(typeof refreshUI === 'function' && !refreshUI.__v102bWrapped){
    const prev = refreshUI;
    refreshUI = function(){
      const res = prev.apply(this, arguments);
      bootAwareTimeout(apply102b, 20);
      return res;
    };
    refreshUI.__v102bWrapped = true;
  }
  window.addEventListener('DOMContentLoaded', ()=>bootAwareTimeout(apply102b, 1400));
})();

/* v102c - keep farmer target selectors stable until the user runs the recommendation */
(function(){
  function syncFarmerSelectorsV102c(){
    const os = document.getElementById('farmerObjectiveSelectV102');
    const ss = document.getElementById('farmerSeasonSourceSelectV102');
    const as = document.getElementById('farmerAlgoSelectV102');
    if(os){
      selectedScenario = os.value;
      document.querySelectorAll('input[name="scenario"]').forEach(r=>{ r.checked = String(r.value) === String(os.value); });
    }
    if(ss){
      const gs = document.getElementById('seasonSourceSel');
      if(gs) gs.value = ss.value;
      STATE.seasonSource = ss.value;
      STATE.farmerSeasonSourceV102 = ss.value;
    }
    if(as){
      STATE.farmerAlgoModeV7 = as.value || STATE.farmerAlgoModeV7 || 'auto';
      selectedAlgo = STATE.farmerAlgoModeV7 === 'auto' ? (STATE.benchmarkLeader?.algo || 'ga') : STATE.farmerAlgoModeV7;
      const ga = document.getElementById('algoSelect');
      if(ga) ga.value = selectedAlgo;
    }
  }
  document.addEventListener('change', (ev)=>{
    const id = ev.target?.id || '';
    if(id === 'farmerObjectiveSelectV102' || id === 'farmerSeasonSourceSelectV102' || id === 'farmerAlgoSelectV102'){
      syncFarmerSelectorsV102c();
    }
  }, true);
  document.addEventListener('click', (ev)=>{
    if(ev.target?.id === 'farmerRunDecisionV102'){
      ev.preventDefault();
      syncFarmerSelectorsV102c();
      const runBtn = document.getElementById('runOptBtn');
      if(runBtn) runBtn.click();
      else if(typeof refreshUI === 'function') refreshUI();
    }
  }, true);
})();

/* v102d - force farmer S1/S2 mode inside recommendation builders */
(function(){
  function forcedSeasonV102d(){
    return (STATE?.currentUser?.role === 'farmer' && STATE.farmerSeasonSourceV102) ? STATE.farmerSeasonSourceV102 : '';
  }
  try{
    const prevSeasonModeKeyV102d = _seasonModeKey;
    _seasonModeKey = function(){
      const forced = forcedSeasonV102d();
      if(forced) return String(forced).toLowerCase() === 's2' ? 's2' : 's1';
      return prevSeasonModeKeyV102d.apply(this, arguments);
    };
  }catch(_e){}
  try{
    const prevGetCandidateCropsForParcelV102d = getCandidateCropsForParcel;
    getCandidateCropsForParcel = function(p){
      const forced = forcedSeasonV102d();
      const sel = document.getElementById('seasonSourceSel');
      const oldValue = sel ? sel.value : '';
      const oldState = STATE.seasonSource;
      if(forced){
        if(sel) sel.value = forced;
        STATE.seasonSource = forced;
      }
      const res = prevGetCandidateCropsForParcelV102d.apply(this, arguments);
      if(forced){
        if(sel) sel.value = forced;
        STATE.seasonSource = forced;
      }else{
        if(sel && oldValue) sel.value = oldValue;
        STATE.seasonSource = oldState;
      }
      return res;
    };
  }catch(_e){}
})();

